#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CIs 1000

typedef struct {
    unsigned int timestamp;
    unsigned int ci;
    int power_level;
} TX_POWER_LEVEL_STATS;

TX_POWER_LEVEL_STATS *stats[MAX_CIs];
int stats_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int add_entry(unsigned int ci, int power_level) {
    pthread_mutex_lock(&mutex);
    if (stats_count >= MAX_CIs) {
        log_error("Maximum number of CIs reached");
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    stats[stats_count] = malloc(sizeof(TX_POWER_LEVEL_STATS));
    if (!stats[stats_count]) {
        log_error("Memory allocation failed");
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    stats[stats_count]->timestamp = time(NULL);
    stats[stats_count]->ci = ci;
    stats[stats_count]->power_level = power_level;
    stats_count++;
    pthread_mutex_unlock(&mutex);
    return 0;
}

int update_entry(unsigned int ci, int new_power_level) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < stats_count; i++) {
        if (stats[i]->ci == ci) {
            stats[i]->power_level = new_power_level;
            stats[i]->timestamp = time(NULL);
            pthread_mutex_unlock(&mutex);
            return 0;
        }
    }
    log_error("CI not found");
    pthread_mutex_unlock(&mutex);
    return -1;
}

TX_POWER_LEVEL_STATS *get_latest_stats(unsigned int ci) {
    pthread_mutex_lock(&mutex);
    for (int i = stats_count - 1; i >= 0; i--) {
        if (stats[i]->ci == ci) {
            TX_POWER_LEVEL_STATS *result = malloc(sizeof(TX_POWER_LEVEL_STATS));
            if (!result) {
                log_error("Memory allocation failed");
                pthread_mutex_unlock(&mutex);
                return NULL;
            }
            memcpy(result, stats[i], sizeof(TX_POWER_LEVEL_STATS));
            pthread_mutex_unlock(&mutex);
            return result;
        }
    }
    log_error("CI not found");
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void cleanup() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < stats_count; i++) {
        free(stats[i]);
    }
    stats_count = 0;
    pthread_mutex_unlock(&mutex);
}
```

