#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <libpq-fe.h>

#define TABLE_SIZE 100

typedef struct record {
    int key;
    char data[256];
} Record;

typedef struct node {
    Record data;
    struct node* next;
} Node;

Node* hash_table[TABLE_SIZE];

pthread_mutex_t mutexes[TABLE_SIZE];

void init_hash_table() {
    for (int i = 0; i < TABLE_SIZE; i++) {
        hash_table[i] = NULL;
        pthread_mutex_init(&mutexes[i], NULL);
    }
}

unsigned int hash_function(int key) {
    return abs(key % TABLE_SIZE);
}

void insert_record(int key, char* data) {
    unsigned int index = hash_function(key);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->data.key = key;
    strncpy(new_node->data.data, data, sizeof(new_node->data.data));
    new_node->next = hash_table[index];
    hash_table[index] = new_node;

    // Insert into database
    PGconn* conn = PQconnectdb("host=localhost user=username dbname=database");
    if (PQstatus(conn) != CONNECTION_OK) {
        fprintf(stderr, "Connection to database failed: %s", PQerrorMessage(conn));
        PQfinish(conn);
        exit(EXIT_FAILURE);
    }
    char query[256];
    snprintf(query, sizeof(query), "INSERT INTO records (key, data) VALUES (%d, '%s')", key, data);
    PGresult* res = PQexec(conn, query);
    if (PQresultStatus(res) != PGRES_COMMAND_OK) {
        fprintf(stderr, "Database insert failed: %s", PQerrorMessage(conn));
    }
    PQclear(res);
    PQfinish(conn);
}

void delete_record(int key) {
    unsigned int index = hash_function(key);
    Node* current = hash_table[index];
    Node* previous = NULL;

    while (current != NULL && current->data.key != key) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        return; // Key not found
    }

    if (previous == NULL) {
        hash_table[index] = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);

    // Delete from database
    PGconn* conn = PQconnectdb("host=localhost user=username dbname=database");
    if (PQstatus(conn) != CONNECTION_OK) {
        fprintf(stderr, "Connection to database failed: %s", PQerrorMessage(conn));
        PQfinish(conn);
        exit(EXIT_FAILURE);
    }
    char query[256];
    snprintf(query, sizeof(query), "DELETE FROM records WHERE key = %d", key);
    PGresult* res = PQexec(conn, query);
    if (PQresultStatus(res) != PGRES_COMMAND_OK) {
        fprintf(stderr, "Database delete failed: %s", PQerrorMessage(conn));
    }
    PQclear(res);
    PQfinish(conn);
}

void search_record(int key) {
    unsigned int index = hash_function(key);
    Node* current = hash_table[index];
    while (current != NULL && current->data.key != key) {
        current = current->next;
    }

    if (current == NULL) {
        printf("Record not found\n");
    } else {
        printf("Key: %d, Data: %s\n", current->data.key, current->data.data);
    }
}

int main() {
    init_hash_table();
    insert_record(1, "Data 1");
    search_record(1);
    delete_record(1);
    return 0;
}
