    curl_multi_add_handle(multi_handle, easy_handle2);
    // Set URL and write callback for chunk2

    // Main loop to handle multiple data chunks
    int still_running;
    do {
        curl_multi_perform(multi_handle, &still_running);
        pthread_mutex_lock(&mutex);
        if (curl_multi_wait(multi_handle, NULL, 0, 1000, NULL) != CURLM_OK) {
            fprintf(stderr, "Error waiting for handles\n");
        }
        pthread_mutex_unlock(&mutex);
    } while (still_running);

    // Clean up
    curl_multi_cleanup(multi_handle);
    free(chunk1.buffer);
    free(chunk2.buffer);

    return EXIT_SUCCESS;
}

size_t write_data(void* ptr, size_t size, size_t nmemb, void* userdata) {
    DataChunk* chunk = (DataChunk*)userdata;
    size_t total_size = size * nmemb;

    if ((chunk->buffer == NULL) || (chunk->size + total_size > MAX_CHUNK_SIZE)) {
        fprintf(stderr, "Buffer overflow\n");
        return 0;
    }

    memcpy(chunk->buffer + chunk->size, ptr, total_size);
    chunk->size += total_size;

    return total_size;
}

void* process_chunk(void* arg) {
    DataChunk* chunk = (DataChunk*)arg;
    // Process data chunk logic here
    return NULL;
}

int parse_command_line(int argc, char** argv, int* chunk_size, char** output_file) {
    int opt;

    while ((opt = getopt_long(argc, argv, "hmc:o:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'h':
                printf("Usage: %s --cs <chunk_size> --o <output_file>\n", argv[0]);
                exit(EXIT_SUCCESS);
            case 'm':
                // Display man page
                exit(EXIT_SUCCESS);
            case 'c':
                *chunk_size = atoi(optarg);
                break;
            case 'o':
                *output_file = optarg;
                break;
            default:
                fprintf(stderr, "Invalid option: %c\n", optopt);
                return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}
