public class VulnerabilityReportService {
    private final ExecutorService executor = Executors.newFixedThreadPool(10);
    private ExternalApi client;

    public VulnerabilityReportService() {
        this.client = new ExternalApi();
    }

    public void generateReports(Pokemon[] pokemons) {
        for (Pokemon pokemon : pokemons) {
            executor.submit(() -> processPokemon(pokemon));
        }
    }

    private void processPokemon(Pokemon pokemon) {
        try {
            TypeEffectiveness data = client.getTypeEffectivenessData(pokemon.getType(), pokemon.getSubtype());
            String report = createReport(pokemon, data);
            System.out.println(report);
        } catch (IOException e) {
            handleException(e, pokemon);
        }
    }

    private String createReport(Pokemon pokemon, TypeEffectiveness data) {
        // Generate detailed vulnerability report
        return "Vulnerability Report for " + pokemon.getName() + ": " + data.getDetails();
    }

    private void handleException(Exception e, Pokemon pokemon) {
        // Log error and provide fallback or recommendation
        System.err.println("Error processing Pokémon: " + pokemon.getName() + ", Error: " + e.getMessage());
    }
}

