#define MAX_KEY_LENGTH 256

typedef struct {
    const EVP_CIPHER *cipher;
    int key_length;
} EncryptionMode;

typedef struct {
    char *key;
    char *salt;
} KeyData;

KeyData get_key_from_config_db() {
    // Placeholder function to retrieve key and salt from the external configuration database
    KeyData key_data = {NULL, NULL};
    // Assume secure retrieval logic here
    return key_data;
}

EncryptionMode get_mode_from_config_db() {
    // Placeholder function to retrieve encryption mode from the external configuration database
    EncryptionMode mode = {EVP_aes_256_cbc(), MAX_KEY_LENGTH};
    // Assume secure retrieval logic here
    return mode;
}

int encrypt(const char *plaintext, KeyData key_data, EncryptionMode mode, unsigned char **ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len, ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_EncryptInit_ex(ctx, mode.cipher, NULL, key_data.key, key_data.salt))
        goto err;

    if (1 != EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, strlen(plaintext)))
        goto err;
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, (*ciphertext) + len, &len))
        goto err;
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;

err:
    EVP_CIPHER_CTX_free(ctx);
    return -1;
}

int decrypt(const unsigned char *ciphertext, int ciphertext_len, KeyData key_data, EncryptionMode mode, char **plaintext) {
    EVP_CIPHER_CTX *ctx;
    int len, plaintext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_DecryptInit_ex(ctx, mode.cipher, NULL, key_data.key, key_data.salt))
        goto err;

    if (1 != EVP_DecryptUpdate(ctx, *plaintext, &len, ciphertext, ciphertext_len))
        goto err;
    plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, (*plaintext) + len, &len))
        goto err;
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;

err:
    EVP_CIPHER_CTX_free(ctx);
    return -1;
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <mode> <plaintext> <output>\n", argv[0]);
        return 1;
    }

    EncryptionMode mode = get_mode_from_config_db();
    KeyData key_data = get_key_from_config_db();

    const char *plaintext = argv[2];
    unsigned char *ciphertext = malloc(strlen(plaintext) + EVP_CIPHER_block_size(mode.cipher));
    if (!ciphertext)
        return 1;

    int ciphertext_len = encrypt(plaintext, key_data, mode, &ciphertext);
    if (ciphertext_len <= 0) {
        free(ciphertext);
        return 1;
    }

    char *decrypted_text = malloc(strlen(plaintext) + 1);
    if (!decrypted_text) {
        free(ciphertext);
        return 1;
    }

    int decrypted_len = decrypt(ciphertext, ciphertext_len, key_data, mode, &decrypted_text);
    if (decrypted_len <= 0) {
        free(ciphertext);
        free(decrypted_text);
        return 1;
    }
    decrypted_text[decrypted_len] = '\0';

    printf("Decrypted: %s\n", decrypted_text);

    free(ciphertext);
    free(decrypted_text);
    return 0;
}
