#include <iostream>
#include <forward_list>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <stdexcept>

class Logger {
public:
    void log(const std::string& message) {
        // Simulate logging with a timestamp and error handling
        std::cout << "LOG: " << message << std::endl;
    }
};

std::forward_list<std::string> list;
Logger logger;

void asyncLog(const std::string& message) {
    std::thread([message]() { logger.log(message); }).detach();
}

void insertAfterOrAppend(const std::string& target, const std::string& value) {
    static std::mutex mtx;
    static std::condition_variable cv;
    static std::atomic<bool> running(true);

    auto insert = [&value](auto it) {
        if (it == list.end()) {
            list.push_back(value);
        } else {
            list.insert_after(it, value);
        }
    };

    std::unique_lock<std::mutex> lock(mtx);
    while (!running.load() && !list.empty()) {
        cv.wait(lock);
    }

    auto it = std::find(list.begin(), list.end(), target);
    if (it != list.end()) {
        insert(++it); // Insert after the found target
    } else {
        insert(list.end()); // Append to the end if target not found
    }

    lock.unlock();
    asyncLog("Insert operation completed");
}

int main() {
    try {
        insertAfterOrAppend("target", "new_value");
    } catch (const std::exception& e) {
        logger.log(e.what());
    }
    return 0;
}
