#include <functional>
#include <memory>
#include <random>
#include <chrono>

class RNG {
public:
    RNG() : rng(std::random_device{}()), distribution(0, 1.0) {}

    double generate() {
        return distribution(rng);
    }

private:
    std::mt19937 rng;
    std::uniform_real_distribution<> distribution;
};

class RNGService {
public:
    RNGService(int numInstances)
        : instances(numInstances), stop(false), serviceThread(&RNGService::run, this) {}

    ~RNGService() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        cv.notify_all();
        serviceThread.join();
    }

    RNG* getInstance(int id) {
        if (id >= 0 && id < instances.size()) {
            return &instances[id];
        }
        return nullptr;
    }

private:
    void run() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return stop || !workQueue.empty(); });
            if (stop && workQueue.empty()) break;

            auto task = std::move(workQueue.front());
            workQueue.pop();
            lock.unlock();

            task();
        }
    }

    std::vector<RNG> instances;
    bool stop;
    std::mutex mutex;
    std::condition_variable cv;
    std::queue<std::function<void()>> workQueue;
};

int main() {
    RNGService rngService(10);

    for (int i = 0; i < 5; ++i) {
        if (RNG* rng = rngService.getInstance(i)) {
            std::thread([&rng] { for (int j = 0; j < 1000; ++j) std::cout << rng->generate() << std::endl; }).detach();
        }
    }

    std::this_thread::sleep_for(std::chrono::seconds(5));
    return 0;
}
