public async Task<IDataReader> ExecuteSecureCommandAsync(ExecuteSecureCommandRequest request)
{
    if (string.IsNullOrEmpty(request.Password))
    {
        LogError("Password cannot be null or empty.");
        return new ErrorDataReader(ErrorCodes.InvalidInput);
    }

    if (!request.Connection.IsOpen())
    {
        LogError("Database connection is not open.");
        return new ErrorDataReader(ErrorCodes.ConnectionFailed);
    }

    if (request.Callback == null)
    {
        LogError("Callback function cannot be null.");
        return new ErrorDataReader(ErrorCodes.InvalidInput);
    }

    try
    {
        using (var command = request.Connection.CreateCommand())
        {
            command.CommandText = request.SqlCommand;
            command.Parameters.AddRange(request.Parameters.ToArray());

            await request.Connection.OpenAsync();

            var reader = await command.ExecuteReaderAsync(CommandBehavior.Default);

            request.Callback(reader);

            return reader;
        }
    }
    catch (SqlException sqlEx)
    {
        LogError($"SQL Error: {sqlEx.Message}");
        return new ErrorDataReader(ErrorCodes.DatabaseError);
    }
    catch (ApiException apiEx)
    {
        LogError($"API Error: {apiEx.Message}");
        return new ErrorDataReader(ErrorCodes.ApiError);
    }
    catch (Exception ex)
    {
        LogError($"General Error: {ex.Message}");
        return new ErrorDataReader(ErrorCodes.GeneralError);
    }
}
