    {
        var cacheKey = $"weather:{location}";
        var cachedWeather = await _cache.StringGetAsync(cacheKey);

        if (!cachedWeather.IsNullOrEmpty)
        {
            return JsonConvert.DeserializeObject<WeatherData>(cachedWeather);
