        try
        {
            var apiResponse = await _httpClient.GetAsync($"https://api.weather.com/data/{location}");
            var weatherData = await apiResponse.Content.ReadAsStringAsync();
            var parsedWeatherData = ParseWeatherData(weatherData);

            await _cache.StringSetAsync(cacheKey, JsonConvert.SerializeObject(parsedWeatherData), TimeSpan.FromMinutes(15));
            return parsedWeatherData;
        }
        catch (Exception ex)
        {
            // Log the error and handle fallback mechanism
