    {
        _connectionString = connectionString;
    }

    public async Task ParseDocumentAsync(Stream xmlStream)
    {
        using (var reader = XmlReader.Create(xmlStream))
        {
            while (await reader.ReadAsync())
            {
                if (reader.NodeType == XmlNodeType.Element)
                {
                    // Process each element as needed
                    _log.Info($"Processing element: {reader.Name}");
                }
            }
        }
    }

    public XmlElement GetFirstElementByName(string xpathQuery)
    {
        try
        {
            var document = new XmlDocument();
            using (var streamReader = new StreamReader(_xmlFilePath))
            {
                document.Load(streamReader);
            }
            return document.SelectSingleNode(xpathQuery) as XmlElement;
        }
        catch (XmlException ex)
        {
            _log.Error($"Invalid XPath query: {xpathQuery}", ex);
            return null;
        }
    }

    public async Task IntegrateDataWithDatabaseAsync(Action<XmlElement> callback)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            using (var transaction = connection.BeginTransaction())
            {
                try
                {
                    foreach (var element in GetElementsByXPath("//element"))
                    {
                        callback(element);
                        // Perform database operations here
                    }
                    transaction.Commit();
                }
                catch (Exception ex)
                {
                    _log.Error("Database integration failed", ex);
                    transaction.Rollback();
                }
            }
        }
    }

    public void Dispose()
    {
        // Implement resource disposal if necessary
    }

    private static XmlElement[] GetElementsByXPath(string xpathQuery)
    {
        var document = new XmlDocument();
        using (var streamReader = new StreamReader(_xmlFilePath))
        {
            document.Load(streamReader);
        }
        return document.SelectNodes(xpathQuery)?.Cast<XmlElement>().ToArray() ?? new XmlElement[0];
    }

    private static string _xmlFilePath = "path_to_xml_file.xml";
}

