import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.TimeUnit;

@RestController
@RequestMapping("/resources")
public class ResourceController {

    @Autowired
    private ResourceService resourceService;

    @PutMapping("/{id}")
    public ResponseEntity<String> updateResource(@PathVariable String id, @RequestBody ResourceData data) {
        try {
            return ResponseEntity.ok(resourceService.updateResource(id, data));
        } catch (Exception e) {
            return handleException(e);
        }
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<String> deleteResource(@PathVariable String id) {
        try {
            resourceService.deleteResource(id);
            return ResponseEntity.ok("Resource deleted successfully");
        } catch (Exception e) {
            return handleException(e);
        }
    }

    private ResponseEntity<String> handleException(Exception e) {
        // Log the exception details for debugging
        e.printStackTrace();
        if (e instanceof ResourceNotFoundException) {
            return ResponseEntity.notFound().build();
        } else if (e instanceof InvalidDataException) {
            return ResponseEntity.badRequest().body("Invalid data provided");
        }
        return ResponseEntity.status(500).body("Internal server error");
    }

    private String computeMD5(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        BigInteger no = new BigInteger(1, messageDigest);
        StringBuilder hashtext = new StringBuilder(no.toString(16));
        while (hashtext.length() < 32) {
            hashtext.insert(0, "0");
        }
        return hashtext.toString();
    }

    private static class ResourceNotFoundException extends RuntimeException {}
    private static class InvalidDataException extends RuntimeException {}

    // Simulated service methods
    public static class ResourceService {
        public String updateResource(String id, ResourceData data) throws Exception {
            // Simulate resource update logic with retries for transient failures
            int attempts = 0;
            while (attempts < 3) {
                try {
                    // Validate unique identifier and MD5 hash
                    if (!isValidIdentifier(id)) throw new InvalidDataException();
                    if (!isValidMD5Hash(data, computeMD5(data.getData()))) throw new InvalidDataException();

                    // Simulate database operation with optimistic locking
                    return simulateDatabaseUpdate(id, data);
                } catch (TransientFailureException e) {
                    TimeUnit.SECONDS.sleep(1); // Wait before retrying
                    attempts++;
                }
            }
            throw new RuntimeException("Max retry attempts reached");
        }

        public void deleteResource(String id) throws Exception {
            int attempts = 0;
            while (attempts < 3) {
                try {
                    if (!isValidIdentifier(id)) throw new ResourceNotFoundException();
                    simulateDatabaseDelete(id);
                    return;
                } catch (TransientFailureException e) {
                    TimeUnit.SECONDS.sleep(1); // Wait before retrying
                    attempts++;
                }
            }
            throw new RuntimeException("Max retry attempts reached");
        }

        private String simulateDatabaseUpdate(String id, ResourceData data) throws TransientFailureException {
            // Simulate database operation logic with potential transient failures
            if (Math.random() < 0.3) throw new TransientFailureException();
            return "Resource updated successfully";
        }

        private void simulateDatabaseDelete(String id) throws TransientFailureException {
            // Simulate database operation logic with potential transient failures
            if (Math.random() < 0.3) throw new TransientFailureException();
        }

        private boolean isValidIdentifier(String id) {
            // Validate resource identifier logic
            return id != null && !id.isEmpty();
        }

        private boolean isValidMD5Hash(ResourceData data, String expectedMd5) {
            try {
                return expectedMd5.equals(computeMD5(data.getData()));
            } catch (NoSuchAlgorithmException e) {
                throw new RuntimeException("Failed to compute MD5 hash", e);
            }
        }
    }

    public static class ResourceData {
        private String data;

        // Getters and setters
        public String getData() {
            return data;
        }

        public void setData(String data) {
            this.data = data;
        }
    }

    public static class TransientFailureException extends RuntimeException {}
}
