<?php

namespace UserAccountKit;

use PDO;
use Monolog\Logger;
use Monolog\Handler\StreamHandler;
use Monolog\Formatter\JsonFormatter;
use GuzzleHttp\Client as HttpClient;
use GuzzleHttp\Exception\RequestException;

class UserAccountKit {
    private $db;
    private $logger;
    private $httpClient;

    public function __construct(PDO $db, Logger $logger, HttpClient $httpClient) {
        $this->db = $db;
        $this->logger = $logger;
        $this->httpClient = $httpClient;
    }

    public function handleRequest($request) {
        $data = json_decode($request, true);
        if (json_last_error() !== JSON_ERROR_NONE) {
            return $this->errorResponse('Invalid JSON payload', 400);
        }

        $action = $data['action'] ?? '';
        switch ($action) {
            case 'create':
                return $this->createUser($data);
            case 'update':
                return $this->updateUser($data);
            case 'delete':
                return $this->deleteUser($data);
            case 'fetch':
                return $this->fetchUser($data);
            default:
                return $this->errorResponse('Invalid action', 400);
        }
    }

    private function createUser($data) {
        // Validate input and create user logic here
        $stmt = $this->db->prepare("INSERT INTO users (name, email, password) VALUES (:name, :email, :password)");
        $stmt->execute([
            ':name' => $data['name'],
            ':email' => $data['email'],
            ':password' => password_hash($data['password'], PASSWORD_DEFAULT)
        ]);

        return $this->successResponse('User created');
    }

    private function updateUser($data) {
        // Validate input and update user logic here
        $stmt = $this->db->prepare("UPDATE users SET name = :name, email = :email WHERE id = :id");
        $stmt->execute([
            ':id' => $data['id'],
            ':name' => $data['name'],
            ':email' => $data['email']
        ]);

        return $this->successResponse('User updated');
    }

    private function deleteUser($data) {
        // Validate input and delete user logic here
        $stmt = $this->db->prepare("DELETE FROM users WHERE id = :id");
        $stmt->execute([
            ':id' => $data['id']
        ]);

        return $this->successResponse('User deleted');
    }

    private function fetchUser($data) {
        // Validate input and fetch user logic here
        $stmt = $this->db->prepare("SELECT * FROM users WHERE id = :id");
        $stmt->execute([
            ':id' => $data['id']
        ]);
        $user = $stmt->fetch(PDO::FETCH_ASSOC);

        return $this->successResponse($user);
    }

    private function errorResponse($message, $code) {
        $this->logger->error($message);
        return json_encode(['error' => $message]), $code;
    }

    private function successResponse($data) {
        $this->logger->info('Success: ' . print_r($data, true));
        return json_encode($data), 200;
    }
}
?>
