using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;

[ApiController]
[Route("api/[controller]")]
public class PageServiceController : ControllerBase
{
    private readonly IDistributedDatabase _database;
    private readonly ILogger<PageServiceController> _logger;
    private static readonly ConcurrentDictionary<string, object> _lockObjects = new();

    public PageServiceController(IDistributedDatabase database, ILogger<PageServiceController> logger)
    {
        _database = database;
        _logger = logger;
    }

    [HttpPost("{pageSectionId}/{elementId}")]
    public async Task<IActionResult> UpdateElementAsync(string pageSectionId, string elementId, [FromBody] HtmlContentDto content)
    {
        var lockKey = $"{pageSectionId}_{elementId}";
        if (!_lockObjects.TryAdd(lockKey, new object()))
            return StatusCode(503, "Service unavailable");

        try
        {
            await _retryHelper.RetryAsync(async () => 
                await _database.UpdateElementAsync(pageSectionId, elementId, content.Html, content.Version));

            return Ok(new { Refresh = true });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating element");
            return StatusCode(500, "Internal server error");
        }
        finally
        {
            _lockObjects.TryRemove(lockKey, out _);
        }
    }

    private static readonly RetryHelper _retryHelper = new RetryHelper(maxRetries: 3, delay: TimeSpan.FromSeconds(1));

    public class HtmlContentDto
    {
        public string Html { get; set; }
        public int Version { get; set; }
    }

    public interface IDistributedDatabase
    {
        Task<bool> UpdateElementAsync(string pageSectionId, string elementId, string newHtml, int expectedVersion);
    }

    public class RetryHelper
    {
        private readonly int _maxRetries;
        private readonly TimeSpan _delay;

        public RetryHelper(int maxRetries, TimeSpan delay)
        {
            _maxRetries = maxRetries;
            _delay = delay;
        }

        public async Task<T> RetryAsync<T>(Func<Task<T>> action)
        {
            for (int retry = 0; retry <= _maxRetries; retry++)
            {
                try
                {
                    return await action();
                }
                catch when (retry < _maxRetries)
                {
                    await Task.Delay(_delay);
                }
            }

            throw new Exception("Max retries reached");
        }
    }
}
```

