const fs = require('fs').promises;
const path = require('path');
const axios = require('axios');

class FileProcessor {
  constructor(maxConcurrentFiles) {
    this.maxConcurrentFiles = maxConcurrentFiles || 10;
    this.processQueue = [];
    this.inProgressCount = 0;
  }

  async processDirectory(directoryPath, fileExtensions, maxTimePerFile) {
    try {
      const files = await fs.readdir(directoryPath);
      for (const file of files) {
        const filePath = path.join(directoryPath, file);
        if (this.isFileOfInterest(file, fileExtensions)) {
          this.processQueue.push({ filePath, maxTimePerFile });
        }
      }

      while (this.processQueue.length > 0 || this.inProgressCount > 0) {
        await this.processNextFile();
      }
    } catch (error) {
      console.error('Error processing directory:', error);
    }
  }

  isFileOfInterest(fileName, fileExtensions) {
    return fileExtensions.includes(path.extname(fileName).toLowerCase());
  }

  async processNextFile() {
    if (this.inProgressCount >= this.maxConcurrentFiles) {
      await new Promise(resolve => setTimeout(resolve, 100));
      return this.processNextFile();
    }

    const { filePath, maxTimePerFile } = this.processQueue.shift();
    this.inProgressCount++;

    try {
      console.log(`Processing file: ${filePath}`);
      const startTime = Date.now();
      await this.validateMetadata(filePath);
      await this.processFile(filePath);

      if (Date.now() - startTime > maxTimePerFile) {
        console.warn(`Warning: Processing time exceeded for ${filePath}`);
      } else {
        console.log(`Successfully processed file: ${filePath}`);
      }
    } catch (error) {
      console.error(`Error processing file ${filePath}:`, error);
    } finally {
      this.inProgressCount--;
      this.processNextFile();
    }
  }

  async validateMetadata(filePath) {
    try {
      const response = await axios.get('https://metadata-service.com/validate', { params: { filePath } });
      if (!response.data.valid) {
        throw new Error('Invalid metadata');
      }
    } catch (error) {
      console.error('Error validating metadata:', error);
      throw error;
    }
  }

  async processFile(filePath) {
    // Placeholder for file processing logic
    await fs.readFile(filePath, 'utf8');
  }
}

// Usage example:
(async () => {
  const processor = new FileProcessor(20);
  await processor.processDirectory('/path/to/directory', ['.txt', '.md'], 5000);
})();
```"]

