function renderFooterScripts(scriptConfigs) {
    const allowedDomains = ['https://example.com', 'https://api.example.com'];
    const cache = {};

    function validateScriptConfig(config) {
        if (!config || !config.key || !config.src) {
            console.warn('Invalid script config:', config);
            return false;
        }
        if (!allowedDomains.includes(new URL(config.src).origin)) {
            console.warn(`Unauthorized domain: ${config.src}`);
            return false;
        }
        return true;
    }

    function loadScript(config, retries = 0) {
        return new Promise((resolve, reject) => {
            const script = document.createElement('script');
            script.async = true;
            script.src = config.src;

            script.onload = () => {
                console.log(`Loaded script: ${config.key}`);
                resolve(script);
            };

            script.onerror = (error) => {
                if (retries < 3) {
                    console.warn(`Failed to load script ${config.key}, retrying...`);
                    setTimeout(() => loadScript(config, retries + 1).then(resolve), 1000);
                } else {
                    console.error(`Failed to load script ${config.key}`);
                    reject(error);
                }
            };

            document.body.appendChild(script);
        });
    }

    function fetchMetadata(src) {
        return fetch('https://api.example.com/metadata', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ src })
        }).then(response => response.json());
    }

    async function renderScripts() {
        const validConfigs = scriptConfigs.filter(validateScriptConfig);
        for (const config of validConfigs) {
            if (cache[config.key] && cache[config.key].status === 'loaded') {
                console.log(`Using cached script: ${config.key}`);
                continue;
            }
            try {
                const metadata = await fetchMetadata(config.src);
                // Update config with metadata
                const loadedScript = await loadScript(config);
                cache[config.key] = { status: 'loaded', script: loadedScript };
            } catch (error) {
                console.error(`Failed to render script ${config.key}:`, error);
            }
        }
    }

    async function main() {
        try {
            await renderScripts();
        } catch (error) {
            console.error('Error rendering footer scripts:', error);
        }
    }

    return main();
}
