class ThemeCache {
  constructor(defaultDir) {
    this.defaultDir = defaultDir;
    this.cache = {};
    this.paused = false;
    this.queue = [];
  }

  async fetchTheme(themeId) {
    if (this.paused) return new Promise(() => {});

    if (this.cache[themeId]) return this.cache[themeId];

    const response = await fetch(`${process.env.IMAGE_PROCESSING_SERVICE}/${themeId}.png`);
    if (!response.ok) throw new Error('Failed to fetch theme');

    const blob = await response.blob();
    const url = URL.createObjectURL(blob);
    this.cache[themeId] = { url, blob };

    return url;
  }

  async processStream(stream) {
    for await (const chunk of stream) {
      if (this.paused) continue;

      try {
        const themeData = await this.fetchTheme(chunk.themeId);
        // Process theme data...
      } catch (error) {
        console.error('Error processing theme:', error);
      }
    }
  }

  pause() {
    this.paused = true;
  }

  resume() {
    this.paused = false;
    this.processQueue();
  }

  async processQueue() {
    while (this.queue.length && !this.paused) {
      const item = this.queue.shift();
      try {
        await item.promise;
      } catch (error) {
        console.error('Error processing queue:', error);
      }
    }
  }

  addImageToCache(themeId, blob) {
    if (!this.cache[themeId]) {
      URL.revokeObjectURL(this.cache[themeId].url);
    }
    this.cache[themeId] = { url: URL.createObjectURL(blob), blob };
  }

  removeThemeFromCache(themeId) {
    URL.revokeObjectURL(this.cache[themeId].url);
    delete this.cache[themeId];
  }

  async withRetries(fn, retries = 5, delay = 1000) {
    for (let i = 0; i <= retries; i++) {
      try {
        return await fn();
      } catch (error) {
        if (i === retries) throw error;
        await new Promise(resolve => setTimeout(resolve, delay * Math.pow(2, i)));
      }
    }
  }
}

// Example usage
const themeCache = new ThemeCache('/default/themes');
themeCache.processStream(myInputStream);
