const express = require('express');
const axios = require('axios');
const fs = require('fs');
const path = require('path');
const cluster = require('cluster');
const numCPUs = require('os').cpus().length;

const app = express();
const port = 3000;

if (cluster.isMaster) {
  console.log(`Master ${process.pid} is running`);

  // Fork workers.
  for (let i = 0; i < numCPUs; i++) {
    cluster.fork();
  }

  cluster.on('exit', (worker, code, signal) => {
    console.log(`worker ${worker.process.pid} died`);
  });
} else {
  console.log(`Worker ${process.pid} started`);

  // Load modules
  const loadModules = async () => {
    try {
      const moduleFiles = fs.readdirSync(path.join(__dirname, 'modules'));
      for (const file of moduleFiles) {
        if (path.extname(file) === '.js') {
          await require('./modules/' + file);
        }
      }
    } catch (error) {
      console.error('Error loading modules:', error);
    }
  };

  // Connect to API and handle data streams
  const connectToAPI = async () => {
    try {
      const response = await axios.get('https://api.example.com/data', { timeout: 5000 });
      const data = response.data;
      // Process data
    } catch (error) {
      console.error('Error connecting to API:', error);
    }
  };

  setInterval(connectToAPI, 1000);

  app.get('/', async (req, res) => {
    try {
      await loadModules();
      res.send('Modules loaded successfully');
    } catch (error) {
      res.status(500).send('Failed to load modules');
    }
  });

  app.listen(port, () => {
    console.log(`Worker ${process.pid} listening at http://localhost:${port}`);
  });
}
