        if key in self.cache:
            self.cache[key]['access_time'] = time.time()
            return self.cache[key]['value']
        return None

    def put(self, key, value):
        if len(self.cache) >= self.max_size:
            least_used_key = min(self.cache, key=lambda k: (self.cache[k]['access_time'], -k))
            del self.cache[least_used_key]
        self.cache[key] = {'value': value, 'access_time': time.time()}

    def remove(self, key):
        if key in self.cache:
            del self.cache[key]

class ImageProcessingAPI:
    def apply_filter(self, image_url, filter_type):
        try:
            response = requests.get(image_url)
            response.raise_for_status()
            # Apply filter logic here
            return f"Processed {filter_type} on {image_url}"
        except requests.RequestException as e:
            logging.error(f"Failed to process image: {e}")
            return None

class ImageRequestHandler(ABC):
    @abstractmethod
    def handle_request(self, image_id):
        pass

class CacheImageRequestHandler(ImageRequestHandler):
    def __init__(self, cache, api):
        self.cache = cache
        self.api = api

    def handle_request(self, image_id):
        image_url = f"https://example.com/images/{image_id}"
        cached_image = self.cache.get(image_id)
        if cached_image:
            return cached_image
        else:
            processed_image = self.api.apply_filter(image_url, "blur")
            if processed_image:
                self.cache.put(image_id, processed_image)
            return processed_image

class ImageLoaderModule:
    def __init__(self, cache_size):
        self.cache = ImageCache(cache_size)
        self.api = ImageProcessingAPI()
        self.handlers = {}
        self.lock = threading.Lock()

    def add_handler(self, user_region, handler):
        with self.lock:
            if user_region not in self.handlers:
                self.handlers[user_region] = []
            self.handlers[user_region].append(handler)

    def process_request(self, image_id, user_region):
        handler = self.get_appropriate_handler(user_region)
        if handler:
            return handler.handle_request(image_id)
        else:
            return "No handler available for this region"

    def get_appropriate_handler(self, user_region):
        with self.lock:
            if user_region in self.handlers and self.handlers[user_region]:
                return self.handlers[user_region][0]
        return None

# Example usage
cache_size = 100
image_loader = ImageLoaderModule(cache_size)
cache_handler = CacheImageRequestHandler(image_loader.cache, image_loader.api)
image_loader.add_handler("US", cache_handler)

user_requests = [
    ("image1", "US"),
    ("image2", "EU"),
    ("image3", "US")
]

for request in user_requests:
    result = image_loader.process_request(request[0], request[1])
    print(result)
