// Circuit breaker implementation
public class CircuitBreaker {
    private boolean isOpen = false;

    public void openCircuit() {
        isOpen = true;
    }

    public void closeCircuit() {
        isOpen = false;
    }

    public boolean isClosed() {
        return !isOpen;
    }
}

// Background task service
public class BackgroundTaskService implements Runnable {
    private ExternalAPIService[] apis;
    private CircuitBreaker circuitBreaker;

    public BackgroundTaskService(ExternalAPIService[] apis) {
        this.apis = apis;
        this.circuitBreaker = new CircuitBreaker();
    }

    @Override
    public void run() {
        while (true) {
            try {
                if (circuitBreaker.isClosed()) {
                    for (ExternalAPIService api : apis) {
                        api.fetchData();
                    }
                } else {
                    // Handle circuit breaker open state
                }
            } catch (Exception e) {
                // Log and handle exceptions, possibly opening the circuit breaker
            }

            try {
                Thread.sleep(60000); // Check every minute
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }
}

// Main class to run the background task service
public class TaskRunner {
    public static void main(String[] args) {
        ExternalAPIService[] apis = new ExternalAPIService[]{
            new API1Service(),
            new API2Service(),
            new API3Service()
        };

        BackgroundTaskService service = new BackgroundTaskService(apis);
        Thread taskThread = new Thread(service);
        taskThread.start();
    }
}
