// Define an HTTP client library in Rust that supports both synchronous and asynchronous request handling
use reqwest::{Client, Error};
use tokio::sync::Mutex;
use oauth2::{ClientId, ClientSecret, AccessToken, RefreshToken, AuthUrl, TokenUrl, Scope};

struct HttpClient {
    client: Client,
    auth_client: Mutex<oauth2::StandardClient>,
}

impl HttpClient {
    fn new(client_id: &str, client_secret: &str, token_url: &str) -> Self {
        let auth_client = oauth2::StandardClient::new(
            ClientId::new(client_id.to_string()),
            Some(ClientSecret::new(client_secret.to_string())),
            AuthUrl::new("https://example.com/oauth/authorize".to_string()).unwrap(),
            Some(TokenUrl::new(token_url.to_string()).unwrap()),
        )
        .set_auth_type(oauth2::AuthType::RequestBody)
        .add_scope(Scope::new("read".to_string()))
        .add_scope(Scope::new("write".to_string()));

        Self {
            client: Client::new(),
            auth_client: Mutex::new(auth_client),
        }
    }

    async fn refresh_token(&self) -> Result<(), Error> {
        let mut auth_client = self.auth_client.lock().await;
        if let Some(refresh_token) = auth_client.refresh_token() {
            let token_response = auth_client.exchange_refresh_token(refresh_token).await?;
            auth_client = &mut *auth_client; // Reassign mutable reference
            auth_client.set_access_token(token_response.access_token());
        } else {
            // Handle the case where no refresh token is available
        }
        Ok(())
    }

    async fn make_request(&self, url: &str) -> Result<String, Error> {
        let token = self.auth_client.lock().await.get_access_token();
        let mut headers = reqwest::header::HeaderMap::new();
        headers.insert(
            "Authorization",
            format!("Bearer {}", token.secret()).parse().unwrap(),
        );
        let response = self.client.get(url).headers(headers).send().await?;
        if response.status().is_success() {
            Ok(response.text().await?)
        } else {
            Err(Error::from_response(response).map_err(|e| e.into_inner())?)
        }
    }
}
