use std::collections::HashMap;
use std::fs::{File, OpenOptions};
use std::io::{Read, Write};
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use tokio::sync::RwLock;
use actix_web::{web, App, HttpResponse, HttpServer, Responder};
use serde::{Deserialize, Serialize};
use chrono::Local;

#[derive(Deserialize)]
struct ResourceBundle {
    items: Vec<String>,
}

#[derive(Serialize)]
struct HealthCheckResponse {
    status: String,
    last_compilation_time: Option<String>,
    memory_usage: u32,
}

enum ResourceBundleFormat {
    Json,
    Toml,
}

struct ServiceState {
    resource_bundle_cache: Arc<RwLock<HashMap<ResourceBundleFormat, Vec<String>>>>,
    cache_last_modified: Arc<Mutex<HashMap<ResourceBundleFormat, chrono::DateTime<Local>>>>,
}

impl ServiceState {
    fn new() -> Self {
        ServiceState {
            resource_bundle_cache: Arc::new(RwLock::new(HashMap::new())),
            cache_last_modified: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    async fn compile_c_program(&self) -> Result<(), String> {
        // Simulate C program compilation
        let output = std::process::Command::new("gcc")
            .arg("-o")
            .arg("output")
            .arg("main.c")
            .output()
            .map_err(|e| format!("Failed to compile C program: {}", e))?;

        if !output.status.success() {
            return Err(format!("C program compilation failed: {:?}", output.stderr));
        }

        Ok(())
    }

    async fn load_resource_bundle(&self, path: PathBuf) -> Result<Vec<String>, String> {
        let mut file = OpenOptions::new()
            .read(true)
            .open(path)
            .map_err(|e| format!("Failed to open resource bundle file: {}", e))?;

        let mut contents = String::new();
        file.read_to_string(&mut contents)
            .map_err(|e| format!("Failed to read resource bundle file: {}", e))?;

        match ResourceBundleFormat::from_path(&path) {
            ResourceBundleFormat::Json => {
                serde_json::from_str::<ResourceBundle>(&contents)
                    .map(|bundle| bundle.items)
                    .map_err(|e| format!("Invalid JSON format in resource bundle: {}", e))
            }
            ResourceBundleFormat::Toml => {
                toml::from_str::<ResourceBundle>(&contents)
                    .map(|bundle| bundle.items)
                    .map_err(|e| format!("Invalid TOML format in resource bundle: {}", e))
            }
        }
    }

    async fn get_resource_bundle(&self, format: ResourceBundleFormat) -> Result<Vec<String>, String> {
        let cache = self.resource_bundle_cache.read().await;
        if let Some(items) = cache.get(&format) {
            return Ok(items.clone());
        }

        drop(cache);
        let new_items = self.load_resource_bundle(format.into_path()).await?;
        self.resource_bundle_cache.write().await.insert(format, new_items.clone());

        Ok(new_items)
    }
}

#[actix_web::get("/health")]
async fn health_check(state: web::Data<ServiceState>) -> impl Responder {
    let compile_time = state.cache_last_modified.lock().unwrap().get(&ResourceBundleFormat::Json);
    let memory_usage = 123; // Simulated memory usage

    HttpResponse::Ok().json(HealthCheckResponse {
        status: "OK".to_string(),
        last_compilation_time: compile_time.cloned().map(|t| t.to_rfc3339()),
        memory_usage,
    })
}

#[actix_web::post("/compile")]
async fn compile(state: web::Data<ServiceState>) -> impl Responder {
    match state.compile_c_program().await {
        Ok(_) => HttpResponse::Ok().body("C program compiled successfully"),
        Err(e) => HttpResponse::InternalServerError().body(format!("Compilation failed: {}", e)),
    }
}

#[actix_web::get("/bundle")]
async fn get_bundle(state: web::Data<ServiceState>, format: web::Query<ResourceBundleFormat>) -> impl Responder {
    match state.get_resource_bundle(*format).await {
        Ok(items) => HttpResponse::Ok().json(items),
        Err(e) => HttpResponse::InternalServerError().body(format!("Failed to load resource bundle: {}", e)),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let state = web::Data::new(ServiceState::new());

    HttpServer::new(move || {
        App::new()
            .app_data(state.clone())
            .service(health_check)
            .service(compile)
            .service(get_bundle)
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}

impl From<ResourceBundleFormat> for PathBuf {
    fn from(format: ResourceBundleFormat) -> Self {
        match format {
            ResourceBundleFormat::Json => "data.json".into(),
            ResourceBundleFormat::Toml => "data.toml".into(),
        }
    }
}

impl From<PathBuf> for ResourceBundleFormat {
    fn from(path: PathBuf) -> Self {
        if path.extension().unwrap() == "json" {
            ResourceBundleFormat::Json
        } else if path.extension().unwrap() == "toml" {
            ResourceBundleFormat::Toml
        } else {
            panic!("Unsupported resource bundle format");
        }
    }
}

enum CacheInvalidationStrategy {
    TimeBased,
    SizeBased,
}

fn invalidate_cache(state: &ServiceState, strategy: CacheInvalidationStrategy) {
    match strategy {
        CacheInvalidationStrategy::TimeBased => {
            let now = Local::now();
            let mut cache_last_modified = state.cache_last_modified.lock().unwrap();
            for (format, last_modified) in cache_last_modified.iter_mut() {
                if now.signed_duration_since(*last_modified).num_minutes() > 60 {
                    cache_last_modified.remove(format);
                }
            }
        }
        CacheInvalidationStrategy::SizeBased => {
            // Implement size-based invalidation logic here
        }
    }
}
