CREATE PROCEDURE GetEmployeeDetails (
    @SupervisorID INT,
    @DepartmentID INT,
    @PageNumber INT,
    @PageSize INT,
    @Async BIT = 0
)
AS
BEGIN
    DECLARE @SQL NVARCHAR(MAX),
            @APIEndpoint NVARCHAR(256),
            @CachingKey NVARCHAR(256),
            @Response NVARCHAR(MAX),
            @ErrorText NVARCHAR(MAX);

    SET @CachingKey = 'EmployeeDetails_' + CAST(@SupervisorID AS NVARCHAR) + '_' + CAST(@DepartmentID AS NVARCHAR) + '_' + CAST(@PageNumber AS NVARCHAR) + '_' + CAST(@PageSize AS NVARCHAR);
    SET @APIEndpoint = 'https://api.example.com/employee/metadata';

    IF EXISTS(SELECT * FROM sys.dm_exec_cached_plans WHERE plan_handle IN (SELECT plan_handle FROM sys.sql_handle WHERE text LIKE '%GetEmployeeDetails%'))
        BEGIN
            -- Cached result exists, return it immediately
            SELECT * FROM EmployeeDetailsCache WHERE CacheKey = @CachingKey;
        END
    ELSE
        BEGIN
            IF @Async = 0
                BEGIN
                    SET @SQL = N'
                        SELECT e.EmployeeID, e.Name, e.City, e.Address
                        FROM Employees e WITH (INDEX(EmployeeIX))
                        WHERE e.SupervisorID = @SupervisorID AND e.DepartmentID = @DepartmentID
                        ORDER BY e.EmployeeID OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;

                        DECLARE @EmployeeIDs TABLE (EmployeeID INT);

                        INSERT INTO @EmployeeIDs (EmployeeID)
                        SELECT EmployeeID FROM Employees WHERE SupervisorID = @SupervisorID AND DepartmentID = @DepartmentID
                        ORDER BY EmployeeID OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;

                        DECLARE @Metadata NVARCHAR(MAX);
                        SET @Metadata = N'';

                        DECLARE @EmployeeID INT;
                        DECLARE emp_cursor CURSOR FOR SELECT EmployeeID FROM @EmployeeIDs;
                        OPEN emp_cursor;
                        FETCH NEXT FROM emp_cursor INTO @EmployeeID;

                        WHILE @@FETCH_STATUS = 0
                            BEGIN
                                SET @Response = (SELECT * FROM OPENJSON(GET_JSON(@APIEndpoint + ''?employeeID='' + CAST(@EmployeeID AS NVARCHAR)))
                                    WITH (
                                        MetaData NVARCHAR(MAX)
                                    )
                                FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);

                                IF @Response IS NULL OR LEN(@Response) = 0
                                    BEGIN
                                        SET @ErrorText = ''Error retrieving metadata for employee ID: '' + CAST(@EmployeeID AS NVARCHAR);
                                        RAISERROR (@ErrorText, 16, 1);
                                    END
                                ELSE
                                    BEGIN
                                        SET @Metadata = @Metadata + @Response;
                                    END

                                FETCH NEXT FROM emp_cursor INTO @EmployeeID;
                            END

                        CLOSE emp_cursor;
                        DEALLOCATE emp_cursor;

                        SELECT * FROM OPENJSON(@Metadata) WITH (
                            MetaData NVARCHAR(MAX)
                        )
                        FOR JSON PATH;
                    ';

                    EXEC sp_executesql @SQL, N'@SupervisorID INT, @DepartmentID INT, @PageNumber INT, @PageSize INT', @SupervisorID, @DepartmentID, @PageNumber, @PageSize;

                    -- Cache the result
                    INSERT INTO EmployeeDetailsCache (CacheKey, CacheData)
                    SELECT @CachingKey, CAST(@SQL AS NVARCHAR(MAX));
                END
            ELSE
                BEGIN
                    -- Asynchronous processing logic goes here
                    RAISERROR ('Asynchronous processing is not implemented yet.', 16, 1);
                END
        END
END
