<?php

class SecureAuthManager {
    private $apiUrl;
    private $apiKey;

    public function __construct($apiUrl, $apiKey) {
        $this->apiUrl = $apiUrl;
        $this->apiKey = $apiKey;
    }

    public function generateSalt() {
        return bin2hex(random_bytes(32));
    }

    public function hashPassword($password, $salt) {
        return password_hash($password . $salt, PASSWORD_ARGON2I);
    }

    public function verifyHash($password, $hash, $salt) {
        return password_verify($password . $salt, $hash);
    }

    public function generateSecureString($length = 32) {
        return bin2hex(random_bytes($length / 2));
    }

    public function authenticateUser($username, $password) {
        try {
            $ch = curl_init();
            curl_setopt($ch, CURLOPT_URL, $this->apiUrl . '/login');
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
            curl_setopt($ch, CURLOPT_POST, true);
            curl_setopt($ch, CURLOPT_POSTFIELDS, [
                'username' => $username,
                'password' => $password
            ]);
            curl_setopt($ch, CURLOPT_HTTPHEADER, [
                'Authorization: Bearer ' . $this->apiKey
            ]);

            $response = curl_exec($ch);

            if (curl_errno($ch)) {
                throw new Exception('Network error: ' . curl_error($ch));
            }

            $data = json_decode($response, true);
            curl_close($ch);

            return $data['token'];
        } catch (Exception $e) {
            // Handle error, e.g., log it and return a failure response
            return false;
        }
    }

    public function extendSession($token) {
        try {
            $ch = curl_init();
            curl_setopt($ch, CURLOPT_URL, $this->apiUrl . '/session/extend');
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
            curl_setopt($ch, CURLOPT_POST, true);
            curl_setopt($ch, CURLOPT_POSTFIELDS, [
                'token' => $token
            ]);
            curl_setopt($ch, CURLOPT_HTTPHEADER, [
                'Authorization: Bearer ' . $this->apiKey
            ]);

            $response = curl_exec($ch);

            if (curl_errno($ch)) {
                throw new Exception('Network error: ' . curl_error($ch));
            }

            $data = json_decode($response, true);
            curl_close($ch);

            return $data['token'];
        } catch (Exception $e) {
            // Handle error, e.g., log it and return a failure response
            return false;
        }
    }
}

// Example usage:
$authManager = new SecureAuthManager('https://api.example.com/auth', 'your_api_key_here');
$salt = $authManager->generateSalt();
$passwordHash = $authManager->hashPassword('user_password', $salt);
$userToken = $authManager->authenticateUser('username', 'user_password');

if ($userToken) {
    // Use the token for further authenticated requests
}
?>
