use tokio::sync::Mutex;
use std::collections::HashMap;
use reqwest::Client;
use chrono::{Utc, Duration};

#[derive(Clone)]
struct KMS {
    client: Client,
}

impl KMS {
    async fn fetch_cert(&self, token: &str) -> Result<(String, String), String> {
        // Simulate fetching cert and key from KMS
        Ok(("cert".to_string(), "key".to_string()))
    }
}

struct CertificateService {
    kms: KMS,
    cache: Mutex<HashMap<String, (String, Utc)>>,
}

impl CertificateService {
    async fn new() -> Self {
        CertificateService {
            kms: KMS::new(),
            cache: Mutex::new(HashMap::new()),
        }
    }

    async fn generate_cert(&self, token: &str) -> Result<String, String> {
        let mut cache = self.cache.lock().await;
        if let Some((cert, expires_at)) = cache.get(token) {
            if expires_at > &Utc::now() {
                return Ok(cert.clone());
            }
        }

        let (cert, key) = self.kms.fetch_cert(token).await?;
        let pem = format!("-----BEGIN CERTIFICATE-----\n{}\n-----END CERTIFICATE-----", cert);
        cache.insert(token.to_string(), (pem.clone(), Utc::now() + Duration::hours(1)));
        Ok(pem)
    }
}

async fn generate_cert_handler(service: web::Data<CertificateService>, token: web::Path<String>) -> impl Responder {
    match service.generate_cert(&token).await {
        Ok(cert) => web::HttpResponse::Ok().body(cert),
        Err(e) => web::HttpResponse::InternalServerError().body(e),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let service = CertificateService::new().await;
    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(service.clone()))
            .route("/cert/{token}", web::get().to(generate_cert_handler))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
