import json
import threading
from queue import Queue, Empty
import logging

class DynamicLineProcessor:
    _registry = {}

    @classmethod
    def register(cls, factory_id, factory_function):
        cls._registry[factory_id] = factory_function

    def __init__(self, max_workers=5):
        self.max_workers = max_workers
        self.log_queue = Queue()
        self.processors = [threading.Thread(target=self._process_logs) for _ in range(max_workers)]

        for processor in self.processors:
            processor.start()

    @staticmethod
    def parse_log_line(line):
        try:
            return json.loads(line)
        except json.JSONDecodeError:
            logging.error(f"Failed to decode JSON: {line}")
            return None

    def process_logs(self, lines):
        for line in lines:
            log_data = self.parse_log_line(line)
            if log_data and 'sequence_number' not in log_data:
                log_data['sequence_number'] = 0  # Default value or generate sequence number
            self.log_queue.put(log_data)

    def _process_logs(self):
        while True:
            try:
                log_data = self.log_queue.get(timeout=1)
                if log_data:
                    logging.info(f"Processing log: {log_data}")
                    # Integrate with external services for validation and enrichment here
                    # Example: validate_log(log_data)
            except Empty:
                break

    def add_source(self, source_id, data_lines):
        self.process_logs(data_lines)

    def stop(self):
        for _ in range(self.max_workers):
            self.log_queue.put(None)
        for processor in self.processors:
            processor.join()

# Example usage
DynamicLineProcessor.register('json', lambda line: json.loads(line))
dLP = DynamicLineProcessor()
dLP.add_source('source1', ['{"level": "info", "message": "Test message 1"}', '{"level": "error", "message": "Test message 2"}'])
# Add more sources and data as needed
```

