State** create_state_list(int* states, int count, FSA* fsa, State** last_state) {
    if (states == NULL || count <= 0 || fsa == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    State** state_list = malloc(count * sizeof(State*));
    if (state_list == NULL) {
        perror("Failed to allocate memory for state list");
        return NULL;
    }

    pthread_mutex_t lock;
    if (pthread_mutex_init(&lock, NULL) != 0) {
        perror("Failed to initialize mutex");
        free(state_list);
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        State* state = create_state(states[i], NULL); // Placeholder metadata
        if (state == NULL) {
            pthread_mutex_destroy(&lock);
            for (int j = 0; j < i; j++) {
                free(state_list[j]->metadata);
                free(state_list[j]);
            }
            free(state_list);
            return NULL;
        }
        state_list[i] = state;
    }

    if (*last_state != NULL) {
        *last_state->next = state_list[0];
    } else {
        *last_state = state_list[0];
    }

    pthread_mutex_destroy(&lock);
    return state_list;
}

void free_state_list(State** state_list, int count) {
    for (int i = 0; i < count; i++) {
        free(state_list[i]->metadata);
        free(state_list[i]);
    }
    free(state_list);
}
