#include <chrono>

class Attack {
public:
    std::string name;
    int powerLevel;
    int cooldown;
    int cost;
};

class CombatStrategyManager {
private:
    std::vector<Attack> attacks;
    std::map<std::string, int> cooldowns;
    std::map<std::string, int> resources;
    std::mutex mutex;
    std::condition_variable cv;
    std::shared_ptr<Database> db;

public:
    CombatStrategyManager(std::shared_ptr<Database> db) : db(db) {}

    void addAttack(const Attack& attack) {
        std::lock_guard<std::mutex> lock(mutex);
        attacks.push_back(attack);
        cooldowns[attack.name] = 0;
        resources[attack.name] = attack.cost;
    }

    void updateResource(std::string attackName, int amount) {
        std::lock_guard<std::mutex> lock(mutex);
        resources[attackName] += amount;
    }

    void executeAttack(std::string attackName) {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this, &attackName]() {
            return cooldowns[attackName] == 0 && resources[attackName] >= attacks.front().cost;
        });

        // Simulate attack execution
        Attack& attack = attacks.front();
        std::cout << "Executing: " << attack.name << ", Power: " << attack.powerLevel << ", Cost: " << attack.cost << std::endl;

        // Update cooldown and resources
        cooldowns[attackName] = attack.cooldown;
        resources[attackName] -= attack.cost;

        // Log to database
        db->logAttack(attack.name, attack.powerLevel, attack.cost);

        cv.notify_all();
    }

    void selectAndExecuteNext() {
        std::unique_lock<std::mutex> lock(mutex);
        while (true) {
            if (!attacks.empty()) {
                executeAttack(attacks.front().name);
                attacks.erase(attacks.begin());
            } else {
                cv.wait(lock);
            }
        }
    }

    // Configuration interface methods
    void setResourceLimit(std::string attackName, int limit) {
        std::lock_guard<std::mutex> lock(mutex);
        resources[attackName] = limit;
    }

    // Add more configuration methods as needed

private:
    struct Database {
        void logAttack(const std::string& name, int powerLevel, int cost) {
            // Log attack details to the database
            std::cout << "Logging: " << name << ", Power: " << powerLevel << ", Cost: " << cost << std::endl;
        }
    };
};

int main() {
    auto db = std::make_shared<CombatStrategyManager::Database>();
    CombatStrategyManager manager(db);

    Attack attack1{"Fireball", 50, 10, 20};
    Attack attack2{"Ice Lance", 40, 8, 15};
    Attack attack3{"Thunder Strike", 60, 12, 25};

    manager.addAttack(attack1);
    manager.addAttack(attack2);
    manager.addAttack(attack3);

    std::thread t(&CombatStrategyManager::selectAndExecuteNext, &manager);
    t.join();

    return 0;
}
