using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading.Tasks;

public class RandomValueService
{
    private readonly ConcurrentDictionary<string, Random> _randomGenerators = new ConcurrentDictionary<string, Random>();
    private readonly ConcurrentDictionary<string, CacheItem<object>> _cache = new ConcurrentDictionary<string, CacheItem<object>>();
    private readonly ConfigService _configService;
    private readonly ILogger _logger;

    public RandomValueService(ConfigService configService, ILogger logger)
    {
        _configService = configService ?? throw new ArgumentNullException(nameof(configService));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));

        Initialize();
    }

    public int GetRandomInt(string key, int min, int max)
    {
        if (min > max) throw new ArgumentException("Min must be less than or equal to max.");

        var randomGenerator = GetRandomGenerator(key);
        lock (randomGenerator)
        {
            return randomGenerator.Next(min, max + 1);
        }
    }

    public float GetRandomFloat(string key, float min, float max)
    {
        if (min > max) throw new ArgumentException("Min must be less than or equal to max.");

        var randomGenerator = GetRandomGenerator(key);
        lock (randomGenerator)
        {
            return (float)(randomGenerator.NextDouble() * (max - min)) + min;
        }
    }

    private Random GetRandomGenerator(string key)
    {
        if (!_randomGenerators.TryGetValue(key, out var random))
        {
            random = new Random(GetSeed(key));
            _randomGenerators[key] = random;
        }
        return random;
    }

    private int GetSeed(string key)
    {
        try
        {
            var seed = _configService.GetSeed(key);
            if (seed != null) return seed.Value;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to get seed for key: {Key}", key);
        }

        // Fallback mechanism
        return DateTime.Now.Ticks.GetHashCode();
    }

    private void Initialize()
    {
        try
        {
            var config = _configService.GetConfig();
            if (config != null)
            {
                _cache.TryAdd("MinInt", new CacheItem<object> { Value = config.MinInt, ExpirationTime = DateTime.MaxValue });
                _cache.TryAdd("MaxInt", new CacheItem<object> { Value = config.MaxInt, ExpirationTime = DateTime.MaxValue });
                _cache.TryAdd("MinFloat", new CacheItem<object> { Value = config.MinFloat, ExpirationTime = DateTime.MaxValue });
                _cache.TryAdd("MaxFloat", new CacheItem<object> { Value = config.MaxFloat, ExpirationTime = DateTime.MaxValue });
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to initialize configuration.");
        }
    }

    private class CacheItem<T>
    {
        public T Value { get; set; }
        public DateTime ExpirationTime { get; set; }
    }

    // Implement IConfigService and ILogger interfaces or use existing libraries for these purposes.
}
