// Callback function type definition
typedef void (*OnExceedCallback)(const char* input, const char* message);

// Function prototype for processString
char* processString(const char* input, int sizeLimit, OnExceedCallback onExceed);

// Implementation of processString
char* processString(const char* input, int sizeLimit, OnExceedCallback onExceed) {
    if (input == NULL || sizeLimit < 0) {
        if (onExceed != NULL) {
            onExceed(input, "Invalid input or size limit");
        }
        return NULL;
    }

    size_t len = strlen(input);
    if (len + 1 <= (size_t)sizeLimit) {
        char* result = (char*)realloc((void*)input, len + 2); // Allocate space for the new character and null terminator
        if (result != NULL) {
            result[len] = '/';
            result[len + 1] = '\0';
            return result;
        } else {
            if (onExceed != NULL) {
                onExceed(input, "Memory allocation failed");
            }
            return NULL;
        }
    } else {
        if (onExceed != NULL) {
            onExceed(input, "String exceeds size limit");
        }
        // Optionally log the event or trigger external monitoring systems
        return (char*)input; // Return the original string without modification
    }
}

// Example usage of processString
int main() {
    const char* input = "example";
    int sizeLimit = 10;

    OnExceedCallback onExceed = [](const char* input, const char* message) {
        printf("Error: %s\n", message);
    };

    char* result = processString(input, sizeLimit, onExceed);
    if (result != NULL) {
        printf("Processed string: %s\n", result);
    }

    // Free the memory allocated by processString
    free((void*)result);

    return 0;
}
