#define MAX_THREADS 10

typedef struct {
    char *endpoint;
    char *auth_token;
} Config;

typedef struct {
    double value;
    int random_num;
} ProcessedData;

size_t write_data(void *ptr, size_t size, size_t nmemb, void *userdata) {
    // Implement the logic to parse JSON data here
    return size * nmemb;
}

void* process_data(void *arg) {
    Config *config = (Config *) arg;
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Authorization: Bearer ");
        headers = curl_slist_append(headers, config->auth_token);

        curl_easy_setopt(curl, CURLOPT_URL, config->endpoint);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    return NULL;
}

int main() {
    FILE *config_file = fopen("config.txt", "r");
    if (!config_file) {
        perror("Failed to open config file");
        return EXIT_FAILURE;
    }

    Config configs[MAX_THREADS];
    int thread_count = 0;

    char line[1024];
    while (fgets(line, sizeof(line), config_file)) {
        // Parse configuration lines here
        if (thread_count < MAX_THREADS) {
            configs[thread_count].endpoint = strtok(line, ",");
            configs[thread_count].auth_token = strtok(NULL, ",");
            pthread_t thread;
            pthread_create(&thread, NULL, process_data, &configs[thread_count]);
            pthread_detach(thread);
            thread_count++;
        }
    }

    fclose(config_file);

    return EXIT_SUCCESS;
}
