        return NULL;
    }

    TIFFGetField(metadata->tif, TIFFTAG_BITSPERSAMPLE, &metadata->bitsPerSample);
    TIFFGetField(metadata->tif, TIFFTAG_SAMPLESPERPIXEL, &metadata->samplesPerPixel);
    TIFFGetField(metadata->tif, TIFFTAG_COMPRESSION, &metadata->compressionType);

    // Process metadata and error handling here

    TIFFClose(metadata->tif);
    free(imageData);
    return metadata;
}

int main() {
    ImageData* imageFiles = malloc(10000 * sizeof(ImageData));
    pthread_t threads[10000];
    int i, status;

    // Populate imageFiles with actual file paths

    for (i = 0; i < 10000; i++) {
        if (pthread_create(&threads[i], NULL, extractMetadata, &imageFiles[i]) != 0) {
            fprintf(stderr, "Failed to create thread for image %s\n", imageFiles[i].filePath);
            // Handle error
        }
    }

    for (i = 0; i < 10000; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Failed to join thread for image %s\n", imageFiles[i].filePath);
            // Handle error
        }
    }

    free(imageFiles);
    return 0;
}
