#define RESERVED_WORDS {"tmp", "temp", "backup"}

// Define structures and types
typedef struct {
    const char** extensions;
    size_t num_extensions;
    const char* default_extension;
    pthread_mutex_t lock;
} Config;

typedef struct {
    char original_filename[MAX_FILENAME_LENGTH];
    char generated_filename[MAX_FILENAME_LENGTH];
    Config config;
} FilenameContext;

// Function declarations
int validateFilename(const char* filename, const char** reserved_words);
int isSupportedExtension(const char* extension, const char** extensions, size_t num_extensions);
char* generateUniqueIdentifier();
int generateSequenceLength(size_t main_length);
void constructNewFilename(FilenameContext* context, const char* original_filename, const char* extension, const char* identifier);

// Function definitions
int validateFilename(const char* filename, const char** reserved_words) {
    for (const char** word = reserved_words; *word != NULL; ++word) {
        if (strstr(filename, *word) != NULL) {
            return 0;
        }
    }
    return 1;
}

int isSupportedExtension(const char* extension, const char** extensions, size_t num_extensions) {
    for (size_t i = 0; i < num_extensions; ++i) {
        if (strcmp(extension, extensions[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

char* generateUniqueIdentifier() {
    // Implement logic to generate a unique identifier
    static char identifier[32];
    pthread_mutex_lock(&context->config.lock);
    time_t now = time(NULL);
    srand(now ^ getpid());
    snprintf(identifier, sizeof(identifier), "%lu_%d", (unsigned long)now, rand() % 1000);
    pthread_mutex_unlock(&context->config.lock);
    return identifier;
}

int generateSequenceLength(size_t main_length) {
    // Implement logic to determine the length of the numeric sequence
    if (main_length < 5) {
        return 4;
    } else if (main_length < 10) {
        return 3;
    } else {
        return 2;
    }
}

void constructNewFilename(FilenameContext* context, const char* original_filename, const char* extension, const char* identifier) {
    // Implement logic to construct the new filename
    size_t main_length = strlen(original_filename);
    size_t seq_length = generateSequenceLength(main_length);
    snprintf(context->generated_filename, MAX_FILENAME_LENGTH, "%.*s_%s%s", (int)(main_length - seq_length), original_filename, identifier, extension);
}

char* generateSafeUniqueFileName(const char* original_filename, const char** extensions, size_t num_extensions, Config config) {
    pthread_mutex_lock(&config.lock);
    FilenameContext context = {original_filename, "", config};

    if (!validateFilename(original_filename, RESERVED_WORDS)) {
        fprintf(stderr, "Error: Filename contains reserved words.\n");
        return "";
    }

    const char* extension = strrchr(original_filename, '.');
    if (extension == NULL || !isSupportedExtension(extension, extensions, num_extensions)) {
        extension = config.default_extension;
        fprintf(stderr, "Warning: Unsupported file extension. Using default: %s\n", extension);
    }

    char* identifier = generateUniqueIdentifier();
    constructNewFilename(&context, original_filename, extension, identifier);

    pthread_mutex_unlock(&config.lock);
    return context.generated_filename;
}
