#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_COMMANDS 100
#define BUFFER_SIZE 256

typedef struct {
    char command[BUFFER_SIZE];
    int result;
} Command;

typedef struct {
    Command commands[MAX_COMMANDS];
    int count;
    sem_t semaphore;
    pthread_mutex_t mutex;
} CommandQueue;

CommandQueue command_queue;

void init_command_queue() {
    memset(&command_queue, 0, sizeof(command_queue));
    sem_init(&command_queue.semaphore, 0, 1);
    pthread_mutex_init(&command_queue.mutex, NULL);
}

void enqueue_command(const char* command) {
    sem_wait(&command_queue.semaphore);
    pthread_mutex_lock(&command_queue.mutex);

    if (command_queue.count < MAX_COMMANDS) {
        strcpy(command_queue.commands[command_queue.count].command, command);
        command_queue.commands[command_queue.count].result = -1;
        command_queue.count++;
    }

    pthread_mutex_unlock(&command_queue.mutex);
    sem_post(&command_queue.semaphore);
}

void* execute_command(void* arg) {
    while (1) {
        sem_wait(&command_queue.semaphore);
        pthread_mutex_lock(&command_queue.mutex);

        if (command_queue.count > 0) {
            int index = command_queue.count - 1;
            char* cmd = command_queue.commands[index].command;
            // Execute the command and capture the result
            system(cmd);
            command_queue.commands[index].result = 0; // Simulated success
            command_queue.count--;
        }

        pthread_mutex_unlock(&command_queue.mutex);
        sem_post(&command_queue.semaphore);

        usleep(100000); // Delay to simulate processing time
    }
}

int main() {
    init_command_queue();

    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, execute_command, NULL);
    }

    enqueue_command("ls -l");
    enqueue_command("echo Hello World");

    // Simulate shutting down after some time
    sleep(10);

    for (int i = 0; i < 5; i++) {
        pthread_cancel(threads[i]);
    }

    sem_destroy(&command_queue.semaphore);
    pthread_mutex_destroy(&command_queue.mutex);

    return 0;
}
```

