public class UserManagementService
{
    private readonly IMailService _mailService;
    private readonly IUserRepository _userRepository;
    private readonly ILogger _logger;
    private readonly IRetryPolicy _retryPolicy;

    public UserManagementService(IMailService mailService, IUserRepository userRepository, ILogger logger, IRetryPolicy retryPolicy)
    {
        _mailService = mailService;
        _userRepository = userRepository;
        _logger = logger;
        _retryPolicy = retryPolicy;
    }

    public async Task<bool> RegisterUserAsync(string email, string password)
    {
        try
        {
            if (!IsValidEmail(email))
            {
                _logger.Log("Invalid email format.", LogLevel.Error);
                return false;
            }

            if (await IsAccountActive(email))
            {
                _logger.Log($"Account already active for email: {email}", LogLevel.Info);
                return true;
            }

            var registrationSuccessful = await _retryPolicy.ExecuteAsync(async () =>
            {
                try
                {
                    // Simulate user registration
                    await _userRepository.RegisterUserAsync(email, password);

                    // Send activation email with retry logic
                    await _mailService.SendActivationEmailAsync(email, "Your Activation Code");

                    _logger.Log($"User registered and email sent for: {email}", LogLevel.Info);
                    return true;
                }
                catch (Exception ex)
                {
                    _logger.Log($"Error during registration: {ex.Message}", LogLevel.Error);
                    throw;
                }
            });

            if (registrationSuccessful)
            {
                return true;
            }

            _logger.Log("Registration failed after retries.", LogLevel.Error);
            return false;
        }
        catch (Exception ex)
        {
            _logger.Log($"Unexpected error during registration: {ex.Message}", LogLevel.Critical);
            return false;
        }
    }

    private bool IsValidEmail(string email)
    {
        // Basic validation for an email format
        try
        {
            MailAddress.Parse(email);
            return true;
        }
        catch (FormatException)
        {
            return false;
        }
    }

    private async Task<bool> IsAccountActive(string email)
    {
        // Simulate database query with potential delay
        await Task.Delay(200); // Mocking slow database query
        return await _userRepository.IsAccountActiveAsync(email);
    }
}

public interface IMailService
{
    Task SendActivationEmailAsync(string email, string activationCode);
}

public interface IUserRepository
{
    Task RegisterUserAsync(string email, string password);
    Task<bool> IsAccountActiveAsync(string email);
}

public interface ILogger
{
    void Log(string message, LogLevel level);
}

public enum LogLevel
{
    Info,
    Error,
    Warning,
    Debug,
    Critical
}

public interface IRetryPolicy
{
    Task<T> ExecuteAsync<T>(Func<Task<T>> action);
}
