import java.io.BufferedReader;
import java.io.IOException;
import java.nio.file.*;
import java.time.Duration;
import java.time.LocalDateTime;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Stream;

public class BatchFileDeleter {

    private final Path rootDirectory;
    private final int maxFilesPerDirectory;
    private final ExecutorService executorService = Executors.newFixedThreadPool(10);
    private final Logger logger = new Logger();

    public BatchFileDeleter(Path rootDirectory, int maxFilesPerDirectory) {
        this.rootDirectory = rootDirectory;
        this.maxFilesPerDirectory = maxFilesPerDirectory;
    }

    public void start() {
        try (Stream<Path> paths = Files.walk(rootDirectory)) {
            paths.filter(Files::isRegularFile)
                 .forEach(this::deleteOldFilesAsync);
        } catch (IOException e) {
            logger.error("Error walking directory: " + rootDirectory, e);
        }
    }

    private void deleteOldFilesAsync(Path file) {
        executorService.submit(() -> {
            try {
                if (isOldAndUnmodified(file)) {
                    Files.deleteIfExists(file);
                    logger.info("Deleted file: " + file);
                }
            } catch (IOException e) {
                logger.error("Error deleting file: " + file, e);
            }
        });
    }

    private boolean isOldAndUnmodified(Path file) throws IOException {
        BasicFileAttributes attributes = Files.readAttributes(file, BasicFileAttributes.class);
        LocalDateTime lastModifiedTime = LocalDateTime.ofInstant(attributes.lastModifiedTime().toInstant(), attributes.fileStore().getZone());
        return Duration.between(lastModifiedTime, LocalDateTime.now()).toDays() > 7
                && Duration.between(lastModifiedTime, LocalDateTime.now()).toHours() <= 24;
    }

    public void stop() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    private static class Logger {
        public void info(String message) {
            System.out.println("INFO: " + message);
        }

        public void error(String message, Exception e) {
            System.err.println("ERROR: " + message);
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        Path rootDirectory = Paths.get("/path/to/your/directories");
        int maxFilesPerDirectory = 100;
        BatchFileDeleter deleter = new BatchFileDeleter(rootDirectory, maxFilesPerDirectory);
        deleter.start();
    }
}
