#include <iostream>
#include <fstream>
#include <string>
#include <thread>
#include <mutex>
#include <nlohmann/json.hpp>
#include <libxml/parser.h>

// Custom exceptions
class ValidationError : public std::exception {
public:
    ValidationError(const std::string& message) : std::exception(message.c_str()) {}
};

class RetrievalFailure : public std::exception {
public:
    RetrievalFailure(const std::string& message) : std::exception(message.c_str()) {}
};

// Logger
std::mutex logMutex;
void logError(const std::string& error) {
    std::lock_guard<std::mutex> lock(logMutex);
    std::ofstream logFile("error.log", std::ios_base::app);
    logFile << "[" << getCurrentTime() << "] " << error << std::endl;
}

// JSON parsing and validation
nlohmann::json parseAndValidateJson(const std::string& jsonStr) {
    nlohmann::json jsonObj = nlohmann::json::parse(jsonStr);

    if (!jsonObj.contains("access_token") || !jsonObj.contains("expires_in") || !jsonObj.contains("token_type")) {
        throw ValidationError("Missing required JSON fields");
    }

    if (jsonObj["token_type"] != "Bearer") {
        throw ValidationError("Invalid token type");
    }

    int expiresIn = jsonObj["expires_in"];
    if (expiresIn <= 0) {
        throw ValidationError("Expires_in must be a positive integer");
    }

    return jsonObj;
}

// XML parsing and validation
std::string parseAndValidateXml(const std::string& xmlStr) {
    xmlDocPtr doc = xmlReadMemory(xmlStr.c_str(), xmlStr.size(), "noname.xml", NULL, 0);
    if (!doc) {
        throw RetrievalFailure("Failed to parse XML");
    }

    if (xmlStrcmp(xmlGetDocElement(doc)->name, BAD_CAST "configuration") != 0) {
        xmlFreeDoc(doc);
        throw ValidationError("XML must contain exactly one root element named 'configuration'");
    }

    std::string result = xmlNodeListGetString(doc, xmlDocGetRootElement(doc), 1);
    xmlFreeDoc(doc);
    return result;
}

// Thread-safe function to handle JSON and XML parsing
std::pair<nlohmann::json, std::string> parseData(const std::string& jsonData, const std::string& xmlData) {
    nlohmann::json parsedJson = parseAndValidateJson(jsonData);
    std::string parsedXml = parseAndValidateXml(xmlData);

    return {parsedJson, parsedXml};
}

// Example usage
int main() {
    std::string jsonData = R"({"access_token": "abc123", "expires_in": 3600, "token_type": "Bearer"})";
    std::string xmlData = "<configuration></configuration>";

    try {
        auto [parsedJson, parsedXml] = parseData(jsonData, xmlData);

        // Use the parsed data
        std::cout << "Access Token: " << parsedJson["access_token"] << std::endl;
        std::cout << "XML Data: " << parsedXml << std::endl;
    } catch (const std::exception& e) {
        logError(e.what());
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
