using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;

[ApiController]
[Route("api/[controller]")]
public class SecureDataProcessor : ControllerBase
{
    private readonly ILogger<SecureDataProcessor> _logger;
    private readonly string _encryptionKey;
    private readonly string _iv;

    public SecureDataProcessor(ILogger<SecureDataProcessor> logger, IConfiguration configuration)
    {
        _logger = logger;
        _encryptionKey = configuration["EncryptionKey"];
        _iv = configuration["IV"];
    }

    [HttpPost("decrypt-max")]
    public async Task<IActionResult> DecryptMax([FromBody] DecryptionRequest request)
    {
        try
        {
            if (request == null || string.IsNullOrEmpty(request.EncryptedMessage) || !request.Integers.Any())
                return BadRequest("Invalid input");

            byte[] encryptedBytes = Convert.FromBase64String(request.EncryptedMessage);
            byte[] key = Encoding.UTF8.GetBytes(_encryptionKey);
            byte[] iv = Encoding.UTF8.GetBytes(_iv);

            using (TripleDES tdesAlg = TripleDES.Create())
            {
                tdesAlg.Key = key;
                tdesAlg.IV = iv;
                tdesAlg.Mode = CipherMode.CBC;
                tdesAlg.Padding = PaddingMode.PKCS7;

                ICryptoTransform decryptor = tdesAlg.CreateDecryptor();
                byte[] decryptedBytes = await Task.Run(() => decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length));
                string decryptedMessage = Encoding.UTF8.GetString(decryptedBytes);

                int maxInteger = request.Integers.Max();

                return Ok(new { DecryptedMessage = decryptedMessage, MaxInteger = maxInteger });
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred during decryption or processing.");
            return StatusCode(500, "Internal Server Error");
        }
    }
}

public class DecryptionRequest
{
    public string EncryptedMessage { get; set; }
    public IEnumerable<int> Integers { get; set; }
}
