import java.io.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

@Retention(RetentionPolicy.RUNTIME)
@interface Serializable {}

class SerializationException extends Exception {
    public SerializationException(String message) {
        super(message);
    }
}

public class SerializationLibrary {
    private final Map<String, Class<?>> serializableClasses = new ConcurrentHashMap<>();
    private final Map<SerializableKey, Object> cache = new ConcurrentHashMap<>();

    public void registerSerializableClass(Class<?> clazz) throws SerializationException {
        if (!clazz.isAnnotationPresent(Serializable.class)) {
            throw new SerializationException(clazz.getName() + " is not annotated with @Serializable");
        }
        serializableClasses.put(clazz.getSimpleName(), clazz);
    }

    public <T> T deserialize(byte[] data, Class<T> type) throws SerializationException {
        SerializableKey key = new SerializableKey(type);
        if (cache.containsKey(key)) {
            return (T) cache.get(key);
        }

        try (ByteArrayInputStream bis = new ByteArrayInputStream(data);
             ObjectInput ois = new ObjectInputStream(bis)) {

            T obj = (T) ois.readObject();
            cache.put(key, obj);
            return obj;
        } catch (IOException | ClassNotFoundException e) {
            throw new SerializationException("Error deserializing object", e);
        }
    }

    private static class SerializableKey implements Comparable<SerializableKey> {
        private final Class<?> type;

        public SerializableKey(Class<?> type) {
            this.type = type;
        }

        @Override
        public int hashCode() {
            return type.hashCode();
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof SerializableKey)) return false;
            SerializableKey that = (SerializableKey) o;
            return type.equals(that.type);
        }

        @Override
        public int compareTo(SerializableKey other) {
            return this.type.getSimpleName().compareTo(other.type.getSimpleName());
        }
    }

    // Unit tests and further implementation details would go here
}
