async function uploadFiles(config) {
  const { storageService, sourceURLs, fileMetadata, retrySettings } = config;

  // Validate source URL and file type
  for (let url of sourceURLs) {
    if (!isSupportedSource(url)) throw new Error('Unsupported source URL');
    const fileType = getFileType(url);
    if (!isFileTypeAllowed(fileType)) throw new Error(`Invalid file type: ${fileType}`);
  }

  // Initialize storage service client
  const client = await initializeStorageClient(storageService);

  // Set up logging and error handling
  const logger = createLogger();
  const errorHandler = setupErrorHandler(retrySettings, logger);

  // Perform concurrent uploads with chunking and encryption
  const uploadPromises = sourceURLs.map(async (url) => {
    try {
      const fileContent = await fetchFileContent(url);
      const encryptedContent = encryptContent(fileContent, url);
      const chunks = chunkFile(encryptedContent, config.chunkSize || 1024 * 1024);
      for (let i = 0; i < chunks.length; i++) {
        await client.uploadChunk({ url, chunk: chunks[i], index: i });
      }
      logger.log('Upload successful', url);
    } catch (error) {
      errorHandler.handle(error);
    }
  });

  // Wait for all uploads to complete
  await Promise.all(uploadPromises);

  // Update metadata service and log final status
  updateMetadataService(fileMetadata);
  logger.log('All files uploaded successfully');
}

