const fs = require('fs');
const util = require('util');
const execFileAsync = util.promisify(require('child_process').execFile);
const axios = require('axios');

async function encryptPassword(password) {
    try {
        const response = await axios.post('https://api.passwordservice.com/encrypt', { password });
        return response.data.encryptedPassword;
    } catch (error) {
        if (error.response) {
            console.error(`API Error: ${error.response.status} - ${error.response.data.message}`);
        } else if (error.request) {
            console.error('No API response received');
        } else {
            console.error('Error setting up the request');
        }
        throw error;
    }
}

async function replacePlaceholdersAndAppend(file, replacements, encryptedPassword) {
    try {
        await execFileAsync('sed', ['-i', '-e', `s/${replacements.placeholder}/${replacements.value}/`, file]);
        fs.appendFileSync(file, `\n${encryptedPassword}\n`);
    } catch (error) {
        console.error(`Error modifying file ${file}:`, error);
    }
}

async function processFiles(files, replacements) {
    for (const file of files) {
        try {
            const encryptedPassword = await encryptPassword(replacements.password);
            await replacePlaceholdersAndAppend(file, replacements, encryptedPassword);
        } catch (error) {
            console.error(`Error processing file ${file}:`, error);
        }
    }
}

async function main() {
    const files = ['config1.cfg', 'config2.cfg']; // List of configuration files
    const replacements = {
        placeholder: '${PASSWORD}',
        value: 'mySecretPassword',
        password: 'mySecretPassword'
    };

    await processFiles(files, replacements);
    console.log('File processing completed.');
}

main().catch(console.error);
