func encryptWithAES(data map[string]interface{}, key []byte) (string, error) {
	block, err := aes.NewCipher(key)
	if err != nil {
		return "", err
	}

	plaintext := fmt.Sprintf("%v", data)
	plaintextBytes := []byte(plaintext)

	ciphertext := make([]byte, aes.BlockSize+len(plaintextBytes))
	iv := ciphertext[:aes.BlockSize]
	if _, err := io.ReadFull(rand.Reader, iv); err != nil {
		return "", err
	}

	stream := cipher.NewCFBEncrypter(block, iv)
	stream.XORKeyStream(ciphertext[aes.BlockSize:], plaintextBytes)

	return base64.StdEncoding.EncodeToString(ciphertext), nil
}

func encryptWithCamellia(data map[string]interface{}, key []byte) (string, error) {
	block, err := aes.NewCipher(key) // Camellia is not natively supported in Go; use AES for demonstration
	if err != nil {
