import json
from abc import ABC, abstractmethod
from threading import Lock

class JsonConvertible(ABC):
    @abstractmethod
    def to_json_string(self) -> str:
        pass

    @classmethod
    def from_json_string(cls, json_str: str):
        data = json.loads(json_str)
        return cls(**data)

class Registry:
    _registry = {}
    _lock = Lock()

    @classmethod
    def register(cls, class_id, factory_func):
        with cls._lock:
            if class_id in cls._registry:
                raise ValueError(f"Class ID {class_id} already registered")
            cls._registry[class_id] = factory_func

    @classmethod
    def get_factory(cls, class_id):
        with cls._lock:
            return cls._registry.get(class_id)

# Example subclass implementation
class User(JsonConvertible):
    def __init__(self, id: int, name: str):
        self.id = id
        self.name = name

    def to_json_string(self) -> str:
        return json.dumps({
            'id': self.id,
            'name': self.name
        })

# Usage example
Registry.register('user', User.from_json_string)
new_user_json = '{"id": 1, "name": "Alice"}'
new_user = Registry.get_factory('user')(new_user_json)
