                for (ActivityData activity : response.getBody()) {
                    aggregatedActivities.merge(activity.getType(), activity, (existing, replacement) -> 
                        existing.getTimestamp().after(replacement.getTimestamp()) ? existing : replacement);
                }
            } catch (HttpClientErrorException e) {
                if (e.getStatusCode() == HttpStatus.UNAUTHORIZED) {
                    // Refresh token and retry
                    oauth2ClientContext.getAccessTokenRequest().setGrantType("refresh_token");
                    oauth2ClientContext.getAccessTokenResponse().setRefreshToken(oauth2ClientContext.getOAuth2Authentication().getOAuth2Request().getRefreshToken());
                } else {
                    throw e;
                }
            } catch (Exception e) {
                // Handle other exceptions, possibly retry or log
                log.error("Failed to fetch activities from API", e);
            }
        }

        return aggregatedActivities;
    }

    private HttpEntity<?> createOAuth2RequestEntity() {
        OAuth2AccessToken accessToken = oauth2ClientContext.getAccessToken();
        HttpHeaders headers = new HttpHeaders();
        headers.setBearerAuth(accessToken.getValue());
        return new HttpEntity<>(headers);
    }
}
