#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/time.h>

// Define the State structure
typedef struct State {
    int id;
    char* metadata;
    pthread_mutex_t lock;
    struct State* next;
} State;

// Define the LinkedList structure
typedef struct LinkedList {
    State* head;
    pthread_mutex_t list_lock;
} LinkedList;

// Function to create a new state
State* create_state(int id, const char* metadata) {
    State* state = (State*)malloc(sizeof(State));
    if (!state) return NULL;

    state->id = id;
    state->metadata = strdup(metadata);
    pthread_mutex_init(&state->lock, NULL);

    state->next = NULL;
    return state;
}

// Function to insert a new state into the linked list
void insert_state(LinkedList* list, State* new_state) {
    pthread_mutex_lock(&list->list_lock);
    if (!list->head) {
        list->head = new_state;
    } else {
        State* current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_state;
    }
    pthread_mutex_unlock(&list->list_lock);
}

// Function to fetch metadata asynchronously
void* fetch_metadata(void* arg) {
    // Asynchronous fetching logic here
    return NULL;
}

// Function to manage the linked list and integrate with external data source
LinkedList* manage_states(int* states, int count, FSA fsa, State** last_state) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    pthread_mutex_init(&list->list_lock, NULL);
    list->head = NULL;

    for (int i = 0; i < count; i++) {
        int state_id = states[i];
        char* metadata = fetch_metadata(state_id); // Asynchronous fetching
        State* new_state = create_state(state_id, metadata);
        if (!new_state) {
            free(list);
            return NULL;
        }

        insert_state(list, new_state);

        if (last_state) {
            *last_state = new_state;
        }
    }

    return list;
}

// Function to clean up the linked list and associated memory
void cleanup(LinkedList* list) {
    pthread_mutex_lock(&list->list_lock);
    State* current = list->head;
    while (current) {
        State* next = current->next;
        pthread_mutex_destroy(&current->lock);
        free(current->metadata);
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->list_lock);
    pthread_mutex_destroy(&list->list_lock);
    free(list);
}
