import java.io.FileInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;

public class StateLoader {

    public static MoSTState loadStateFromFile(String filePath) {
        ObjectInputStream ois = null;
        try (FileInputStream fis = new FileInputStream(filePath)) {
            ois = new ObjectInputStream(fis);
            Object obj = ois.readObject();
            if (obj instanceof MoSTState) {
                return (MoSTState) obj;
            }
        } catch (IOException | ClassNotFoundException e) {
            System.err.println("Failed to load state from file: " + filePath);
            e.printStackTrace();
        } finally {
            if (ois != null) {
                try {
                    ois.close();
                } catch (IOException e) {
                    System.err.println("Failed to close ObjectInputStream.");
                    e.printStackTrace();
                }
            }
        }
        return null;
    }

    public static void main(String[] args) {
        String filePath = "path/to/state/file.ser";
        MoSTState state = loadStateFromFile(filePath);
        if (state != null) {
            System.out.println("State loaded successfully.");
        } else {
            System.out.println("Failed to load state.");
        }
    }
