['```c
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct Semaphore {
    sem_t semaphore;
    unsigned int initial_value;
    unsigned long acquire_count;
    unsigned long release_count;
    // Add fields for logging and external dependencies as needed
} Semaphore;

Semaphore* create_semaphore(unsigned int initial_value) {
    Semaphore *sem = (Semaphore*)malloc(sizeof(Semaphore));
    if (sem == NULL) {
        perror("Failed to allocate memory for semaphore");
        return NULL;
    }
    sem->initial_value = initial_value;
    sem->acquire_count = 0;
    sem->release_count = 0;
    if (sem_init(&sem->semaphore, 0, initial_value) != 0) {
        perror("Failed to initialize semaphore");
        free(sem);
        return NULL;
    }
    // Initialize logging and external dependencies
    // ...
    return sem;
}

void destroy_semaphore(Semaphore *sem) {
    if (sem == NULL) {
        return;
    }
    sem_destroy(&sem->semaphore);
    // Clean up logging and external dependencies
    // ...
    free(sem);
}

int acquire_semaphore(Semaphore *sem) {
    if (sem == NULL) {
        return -1;
    }
    int result = sem_wait(&sem->semaphore);
    if (result == 0) {
        sem->acquire_count++;
        // Log acquisition event
        // ...
    } else {
        perror("Failed to acquire semaphore");
    }
    return result;
}

int release_semaphore(Semaphore *sem) {
    if (sem == NULL) {
        return -1;
    }
    int result = sem_post(&sem->semaphore);
    if (result == 0) {
        sem->release_count++;
        // Log release event
        // ...
    } else {
        perror("Failed to release semaphore");
    }
    return result;
}

// Additional functions for managing semaphore lifecycle, handling failures,
// and performing maintenance tasks can be added here.
```

