@Service
public class ResourceService {

    @Autowired
    private ResourceRepository resourceRepository;

    @Autowired
    private BCryptPasswordEncoder passwordEncoder;

    public String updateResource(String resourceId, String updatedData, int version) {
        Resource existingResource = resourceRepository.findByResourceId(resourceId);
        if (existingResource == null || existingResource.getVersion() != version) {
            throw new OptimisticLockingFailureException("Resource not found or version mismatch");
        }
        byte[] md5Hash = computeMd5Hash(updatedData);
        // Update resource with new data and hash
        Resource updatedResource = new Resource();
        updatedResource.setResourceId(resourceId);
        updatedResource.setData(updatedData);
        updatedResource.setVersion(version + 1);
        updatedResource.setHash(md5Hash);
        resourceRepository.save(updatedResource);
        return "Resource updated successfully";
    }

    public void deleteResource(String resourceId, int version) {
        Resource existingResource = resourceRepository.findByResourceId(resourceId);
        if (existingResource == null || existingResource.getVersion() != version) {
            throw new OptimisticLockingFailureException("Resource not found or version mismatch");
        }
        // Delete resource
        resourceRepository.deleteById(existingResource.getId());
    }

    private byte[] computeMd5Hash(String data) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            return md.digest(data.getBytes(StandardCharsets.UTF_8));
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Failed to compute MD5 hash", e);
        }
    }
}

@Entity
public class Resource {
