    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false)
    private String resourceId;

    @Lob
    private String data;

    @Column(nullable = false)
    private int version;

    @Lob
    private byte[] hash;

