['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int power_level;
    char timestamp[20];
} TX_POWER_LEVEL_STATS;

typedef struct dynamic_array {
    TX_POWER_LEVEL_STATS *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DYNAMIC_ARRAY;

DYNAMIC_ARRAY* create_dynamic_array() {
    DYNAMIC_ARRAY *array = (DYNAMIC_ARRAY*)malloc(sizeof(DYNAMIC_ARRAY));
    if (!array) return NULL;
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DYNAMIC_ARRAY *array) {
    if (array->data) free(array->data);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int insert_into_array(DYNAMIC_ARRAY *array, TX_POWER_LEVEL_STATS value) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t new_capacity = (array->capacity == 0) ? 1 : array->capacity * 2;
        TX_POWER_LEVEL_STATS *new_data = (TX_POWER_LEVEL_STATS*)realloc(array->data, new_capacity * sizeof(TX_POWER_LEVEL_STATS));
        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failure
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size++] = value;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

TX_POWER_LEVEL_STATS* get_from_array(DYNAMIC_ARRAY *array, size_t index) {
    if (index >= array->size) return NULL;
    pthread_mutex_lock(&array->lock);
    TX_POWER_LEVEL_STATS *value = &array->data[index];
    pthread_mutex_unlock(&array->lock);
    return value;
}

int remove_from_array(DYNAMIC_ARRAY *array, size_t index) {
    if (index >= array->size) return -1; // Index out of bounds
    pthread_mutex_lock(&array->lock);
    for (size_t i = index; i < array->size - 1; ++i) {
        array->data[i] = array->data[i + 1];
    }
    array->size--;
    pthread_mutex_unlock(&array->lock);
    return 0;
}
```

This code snippet defines a basic dynamic array module in C with thread-safe operations. The `create_dynamic_array` function initializes a new dynamic array, and the `destroy_dynamic_array` function cleans up resources. The `insert_into_array`, `get_from_array`, and `remove_from_array` functions provide thread-safe methods for inserting, retrieving, and removing elements from the array.

The module uses mutexes to ensure that concurrent operations do not interfere with each other, preventing data corruption. Error handling is performed using return values, and memory allocation failures are explicitly checked and handled by returning -1.

This modular design allows for easy integration into larger systems while providing a solid foundation for more complex functionalities such as real-time analytics, database synchronization, and multi-region support that can be added in future iterations.']

