Bucket hashtable[TABLE_SIZE];

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void init_hashtable() {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        hashtable[i].head = NULL;
    }
}

unsigned int hash_function(int key) {
    return abs(key % TABLE_SIZE);
}

Record* create_record(int key, const char* value) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    new_record->key = key;
    snprintf(new_record->value, sizeof(new_record->value), "%s", value);
    new_record->next = NULL;
    return new_record;
}

void insert(int key, const char* value) {
    unsigned int index = hash_function(key);
    pthread_mutex_lock(&lock);
    Record* new_record = create_record(key, value);
    new_record->next = hashtable[index].head;
    hashtable[index].head = new_record;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&lock);
}

Record* lookup(int key) {
    unsigned int index = hash_function(key);
    pthread_mutex_lock(&lock);
    Record* current = hashtable[index].head;
    while (current != NULL) {
        if (current->key == key) {
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
    return current;
}

void delete(int key) {
    unsigned int index = hash_function(key);
    pthread_mutex_lock(&lock);
    Record* current = hashtable[index].head;
    Record* previous = NULL;
    while (current != NULL) {
        if (current->key == key) {
            if (previous == NULL) {
                hashtable[index].head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&lock);
}

void* database_worker(void* arg) {
    PGconn* conn = (PGconn*)arg;
    while (1) {
        // Simulate database operations
        char query[256];
        snprintf(query, sizeof(query), "INSERT INTO my_table VALUES (%d, '%s')", rand(), "test");
        if (PQsendQuery(conn, query) != 1) {
            fprintf(stderr, "SendQuery() failed: %s\n", PQerrorMessage(conn));
        }
        while (!PQconsumeInput(conn)) {
            sleep(1);
        }
        PGresult* result = PQgetResult(conn);
        if (PQresultStatus(result) == PGRES_COMMAND_OK) {
            printf("Insert successful.\n");
        } else {
            fprintf(stderr, "Database operation failed: %s\n", PQerrorMessage(conn));
        }
        PQclear(result);
    }
    return NULL;
}

int main() {
    init_hashtable();
    pthread_t db_thread;
    PGconn* conn = PQconnectdb("dbname=mydb user=postgres password=mypassword");
    if (PQstatus(conn) != CONNECTION_OK) {
        fprintf(stderr, "Connection to database failed: %s\n", PQerrorMessage(conn));
        exit(1);
    }
    pthread_create(&db_thread, NULL, database_worker, conn);

    // Simulate concurrent operations
    pthread_t insert_thread;
    pthread_create(&insert_thread, NULL, (void* (*)(void*))insert, (void*)rand());
    pthread_join(insert_thread, NULL);

    return 0;
}
