#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_FILES 10
#define BUFFER_SIZE 256

typedef struct {
    int value;
    time_t timestamp;
} LogEntry;

LogEntry log_entries[MAX_FILES];
int num_files = 0;

void* process_file(void* file_name) {
    FILE* file = fopen((char*)file_name, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    int number;
    while (fscanf(file, "%d", &number) == 1) {
        // Process each number and update log
        LogEntry entry = {number, time(NULL)};
        log_entries[num_files++] = entry;
    }

    fclose(file);
    return NULL;
}

void setup_logging() {
    for (int i = 0; i < num_files; i++) {
        printf("Largest Number: %d at Timestamp: %s", 
               log_entries[i].value, ctime(&log_entries[i].timestamp));
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [file2] [...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    pthread_t threads[MAX_FILES];
    int num_threads = 0;

    for (int i = 1; i < argc; i++) {
        if (num_threads >= MAX_FILES) {
            fprintf(stderr, "Too many files. Maximum is %d\n", MAX_FILES);
            return EXIT_FAILURE;
        }
        pthread_create(&threads[num_threads], NULL, process_file, argv[i]);
        num_threads++;
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    setup_logging();

    return EXIT_SUCCESS;
}
