typedef struct EncryptionContext {
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;
} EncryptionContext;

EncryptionContext* create_encryption_context(const char *mode) {
    EncryptionContext *ctx = (EncryptionContext*)malloc(sizeof(EncryptionContext));
    ctx->ctx = EVP_CIPHER_CTX_new();

    if (strcmp(mode, "ECB") == 0) {
        ctx->cipher = EVP_aes_256_ecb();
    } else if (strcmp(mode, "CBC") == 0) {
        ctx->cipher = EVP_aes_256_cbc();
    } else if (strcmp(mode, "CFB") == 0) {
        ctx->cipher = EVP_aes_256_cfb128();
    } else if (strcmp(mode, "GCM") == 0) {
        ctx->cipher = EVP_aes_256_gcm();
    } else {
        // Fallback to null encryption for testing
        ctx->cipher = NULL;
    }

    return ctx;
}

void encrypt_data(EncryptionContext *ctx, const unsigned char *key, size_t key_len,
                 const unsigned char *iv, const unsigned char *plaintext, size_t plaintext_len,
                 unsigned char *ciphertext) {
    if (ctx->cipher == NULL) {
        // Null encryption mode
        memcpy(ciphertext, plaintext, plaintext_len);
        return;
    }

    EVP_EncryptInit_ex(ctx->ctx, ctx->cipher, NULL, key, iv);
    EVP_EncryptUpdate(ctx->ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx->ctx, ciphertext + ciphertext_len, &ciphertext_len);
}

void log_encryption_operation(const char *user_id, const char *operation_details) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    printf("[%s] User ID: %s, Operation: %s\n", asctime(tm_info), user_id, operation_details);
}

void secure_log_encryption_operation(const unsigned char *user_id, const unsigned char *operation_details) {
    // Implement secure logging logic here
}

void release_encryption_context(EncryptionContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}

int main() {
    unsigned char key[32] = {0}; // Example key
    unsigned char iv[16] = {0};  // Example IV
    unsigned char plaintext[] = "Hello, World!";
    unsigned char ciphertext[sizeof(plaintext)];

    EncryptionContext *ctx = create_encryption_context("CBC");
    encrypt_data(ctx, key, sizeof(key), iv, plaintext, sizeof(plaintext), ciphertext);
    log_encryption_operation("user123", "Encrypting data using CBC mode");

    release_encryption_context(ctx);

    return 0;
}
