DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (array == NULL) return NULL;

    array->stats = malloc(initial_capacity * sizeof(TX_POWER_LEVEL_STATS));
    if (array->stats == NULL) {
        free(array);
        return NULL;
    }

    array->length = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array != NULL) {
        free(array->stats);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

int add_stats(DynamicArray* array, TX_POWER_LEVEL_STATS new_stat) {
    pthread_mutex_lock(&array->lock);

    if (array->length >= array->capacity) {
        // Resize the array
        size_t new_capacity = array->capacity * 2;
        TX_POWER_LEVEL_STATS* new_stats = realloc(array->stats, new_capacity * sizeof(TX_POWER_LEVEL_STATS));

        if (new_stats == NULL) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }

        array->stats = new_stats;
        array->capacity = new_capacity;
    }

    array->stats[array->length++] = new_stat;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

