    virtual void log(const USER_ACTIVITY_LOG& logEntry) = 0;
};

// Implementations for different logging frameworks
class GRPCLogger : public LoggingFramework {
public:
    void log(const USER_ACTIVITY_LOG& logEntry) override {
        // Implementation using gRPC
    }
};

class AMQPLogger : public LoggingFramework {
public:
    void log(const USER_ACTIVITY_LOG& logEntry) override {
        // Implementation using AMQP
    }
};

class NATSLogger : public LoggingFramework {
public:
    void log(const USER_ACTIVITY_LOG& logEntry) override {
        // Implementation using NATS
    }
};

// Class to manage dynamic logging frameworks
class LoggingManager {
private:
    std::unordered_map<std::string, std::shared_ptr<LoggingFramework>> frameworks;
    std::mutex mutex;

public:
    void addFramework(const std::string& name, std::shared_ptr<LoggingFramework> framework) {
        std::lock_guard<std::mutex> lock(mutex);
        frameworks[name] = framework;
    }

    void removeFramework(const std::string& name) {
        std::lock_guard<std::mutex> lock(mutex);
        frameworks.erase(name);
    }

    void log(const USER_ACTIVITY_LOG& logEntry, const std::string& frameworkName) {
        std::lock_guard<std::mutex> lock(mutex);
        if (frameworks.find(frameworkName) != frameworks.end()) {
            frameworks[frameworkName]->log(logEntry);
        } else {
            // Fallback mechanism
        }
    }
};

// Class for managing user-defined plugins
class PluginManager {
public:
    virtual ~PluginManager() {}
    virtual void execute(const USER_ACTIVITY_LOG& logEntry) = 0;
};

// Example plugin implementation
class MyPlugin : public PluginManager {
public:
    void execute(const USER_ACTIVITY_LOG& logEntry) override {
        // Implementation of the plugin
    }
};

// Class to manage user-defined plugins
class PluginRegistry {
private:
    std::vector<std::shared_ptr<PluginManager>> plugins;

public:
    void registerPlugin(std::shared_ptr<PluginManager> plugin) {
        plugins.push_back(plugin);
    }

    void executePlugins(const USER_ACTIVITY_LOG& logEntry) {
        for (const auto& plugin : plugins) {
            plugin->execute(logEntry);
        }
    }
};

// Main logging library class
class UserActivityLogLib {
private:
    LoggingManager logger;
    PluginRegistry plugins;

public:
    void addLoggingFramework(const std::string& name, std::shared_ptr<LoggingFramework> framework) {
        logger.addFramework(name, framework);
    }

    void removeLoggingFramework(const std::string& name) {
        logger.removeFramework(name);
    }

    void log(const USER_ACTIVITY_LOG& logEntry, const std::string& frameworkName) {
        logger.log(logEntry, frameworkName);
        plugins.executePlugins(logEntry);
    }
};

// Example usage
