    UserActivityLogLib lib;
    auto grpcLogger = std::make_shared<GRPCLogger>();
    auto amqpLogger = std::make_shared<AMQPLogger>();

    lib.addLoggingFramework("gRPC", grpcLogger);
    lib.addLoggingFramework("AMQP", amqpLogger);

    USER_ACTIVITY_LOG logEntry = {"user123", "login", 1633072800};
    lib.log(logEntry, "gRPC");

    return 0;
}
