#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <chrono>
#include <gRPC/gRPC.h>
#include <AMQP/AMQP.h>
#include <NATS/NATS.h>

struct USER_ACTIVITY_LOG {
    int id;
    std::string data;
};

class LogProcessor {
private:
    std::vector<std::thread> threads;
    std::mutex mtx;
    std::condition_variable cv;
    std::atomic<bool> running;
    std::queue<USER_ACTIVITY_LOG> logQueue;

public:
    LogProcessor(size_t numThreads) : running(true), numThreads(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            threads.emplace_back([this]() {
                while (true) {
                    std::unique_lock<std::mutex> lock(mtx);
                    cv.wait(lock, [this] { return !running || !logQueue.empty(); });
                    if (!running && logQueue.empty()) break;
                    USER_ACTIVITY_LOG log = std::move(logQueue.front());
                    logQueue.pop();
                    lock.unlock();
                    processLog(log);
                }
            });
        }
    }

    ~LogProcessor() {
        running = false;
        cv.notify_all();
        for (auto& thread : threads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void addLog(const USER_ACTIVITY_LOG& log) {
        std::lock_guard<std::mutex> lock(mtx);
        logQueue.push(log);
        cv.notify_one();
    }

private:
    void processLog(const USER_ACTIVITY_LOG& log) {
        // Process the log entry here
        std::cout << "Processing log entry: " << log.id << ", Data: " << log.data << std::endl;
    }
};

int main() {
    LogProcessor processor(4);
    for (int i = 0; i < 1000000; ++i) {
        USER_ACTIVITY_LOG log = {i, "Log data " + std::to_string(i)};
        processor.addLog(log);
    }
    return 0;
}
