    size_t count;
    pthread_mutex_t mutex;
} NFAPI_LIST_T;

NFAPI_LIST_T* nfaapi_list_create() {
    NFAPI_LIST_T *list = (NFAPI_LIST_T*)malloc(sizeof(NFAPI_LIST_T));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_LIST_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = MAX_LIST_SIZE;
    list->count = 0;

    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void nfaapi_list_destroy(NFAPI_LIST_T *list) {
    if (list->data) free(list->data);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int nfaapi_list_add(NFAPI_LIST_T *list, RX_UE_INFORMATION_TAG ue_info, RNTI_T rnti, CRC_INDICATION_REL8_TAG crc_indication) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, list->capacity * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->data = new_data;
        list->capacity *= 2;
    }

    list->data[list->count].ue_info = ue_info;
    list->data[list->count].rnti = rnti;
    list->data[list->count].crc_indication = crc_indication;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

