// Include necessary headers
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define constants
#define TABLE_SIZE 1024

// Define record structure
typedef struct Record {
    int id;
    char data[256];
} Record;

// Define hash table structure
typedef struct HashTable {
    Record* buckets[TABLE_SIZE];
} HashTable;

// Initialize hash table
void initHashTable(HashTable* ht) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        ht->buckets[i] = NULL;
    }
}

// Hash function to get bucket index
int hashFunction(int id) {
    return id % TABLE_SIZE;
}

// Insert record into hash table
void insertRecord(HashTable* ht, Record* rec) {
    int index = hashFunction(rec->id);
    if (ht->buckets[index] != NULL) {
        // Handle collision using separate chaining
        Record* current = ht->buckets[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = rec;
    } else {
        ht->buckets[index] = rec;
    }
}

// Search record in hash table
Record* searchRecord(HashTable* ht, int id) {
    int index = hashFunction(id);
    Record* current = ht->buckets[index];
    while (current != NULL) {
        if (current->id == id) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Delete record from hash table
void deleteRecord(HashTable* ht, int id) {
    int index = hashFunction(id);
    Record* current = ht->buckets[index];
    Record* prev = NULL;
    while (current != NULL) {
        if (current->id == id) {
            if (prev == NULL) {
                ht->buckets[index] = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

// Main function
int main() {
    HashTable ht;
    initHashTable(&ht);

    // Example usage
    Record rec1 = {1, "Data1"};
    insertRecord(&ht, &rec1);

    Record* foundRec = searchRecord(&ht, 1);
    if (foundRec != NULL) {
        printf("Found record: %d %s\n", foundRec->id, foundRec->data);
    }

    deleteRecord(&ht, 1);

    return 0;
}
```

This code provides a basic implementation of a distributed hash table with separate chaining for collision resolution. It includes functions to insert, search, and delete records. The `main` function demonstrates how to use these functions.']

