typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void resize_dynamic_list(DynamicList* list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* newData = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newData == NULL) {
        // Handle memory allocation failure
        return;
    }
    list->data = newData;
    list->capacity = new_capacity;
}

void add_to_dynamic_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        resize_dynamic_list(list, list->capacity * 2);
    }
    list->data[list->size++] = pdu;
    pthread_mutex_unlock(&list->lock);
}

void remove_from_dynamic_list(DynamicList* list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->size) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    for (size_t i = index; i < list->size - 1; i++) {
        list->data[i] = list->data[i + 1];
    }
    list->size--;
    if (list->size > 0 && list->size == list->capacity / 4) {
        resize_dynamic_list(list, list->capacity / 2);
    }
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_from_dynamic_list(DynamicList* list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->size) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* pdu = &list->data[index];
    pthread_mutex_unlock(&list->lock);
    return pdu;
}
