    unsigned long timestamp;
} TX_POWER_LEVEL_STATS;

// Function to create a new dynamic array of TX_POWER_LEVEL_STATS
TX_POWER_LEVEL_STATS** create_tx_power_stats_array(int num_regions) {
    TX_POWER_LEVEL_STATS** array = (TX_POWER_LEVEL_STATS**)malloc(num_regions * sizeof(TX_POWER_LEVEL_STATS*));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    for (int i = 0; i < num_regions; i++) {
        array[i] = (TX_POWER_LEVEL_STATS*)malloc(sizeof(TX_POWER_LEVEL_STATS));
        if (array[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for region %d\n", i);
            // Clean up previously allocated memory
            for (int j = 0; j < i; j++) {
                free(array[j]);
            }
            free(array);
            return NULL;
        }
    }
    return array;
}

// Function to free the dynamic array of TX_POWER_LEVEL_STATS
void free_tx_power_stats_array(TX_POWER_LEVEL_STATS** array, int num_regions) {
    for (int i = 0; i < num_regions; i++) {
        free(array[i]);
    }
    free(array);
}

// Function to add a new entry to the dynamic array
int add_tx_power_stats_entry(TX_POWER_LEVEL_STATS** array, int region_id, double power_level, unsigned long timestamp) {
    if (array[region_id]->timestamp != 0) {
        fprintf(stderr, "Region %d already has a power level stats entry\n", region_id);
        return -1;
    }
    array[region_id]->region_id = region_id;
    array[region_id]->power_level = power_level;
    array[region_id]->timestamp = timestamp;
    return 0;
}

// Function to update an existing entry in the dynamic array
int update_tx_power_stats_entry(TX_POWER_LEVEL_STATS** array, int region_id, double power_level, unsigned long timestamp) {
    if (array[region_id]->timestamp == 0) {
        fprintf(stderr, "Region %d does not have a power level stats entry\n", region_id);
        return -1;
    }
    array[region_id]->power_level = power_level;
    array[region_id]->timestamp = timestamp;
    return 0;
}

// Function to get an existing entry from the dynamic array
int get_tx_power_stats_entry(TX_POWER_LEVEL_STATS** array, int region_id, TX_POWER_LEVEL_STATS* result) {
    if (array[region_id]->timestamp == 0) {
        fprintf(stderr, "Region %d does not have a power level stats entry\n", region_id);
        return -1;
    }
    *result = *(array[region_id]);
    return 0;
}
