void SensorDataLibrary::startProcessing() {
    std::thread([this]() {
        while (processingActive) {
            std::unique_lock<std::mutex> lock(queueMutex);
            dataReady.wait(lock, [this] { return !dataQueue.empty(); });
            auto data = dataQueue.front();
            dataQueue.pop();
            lock.unlock();

            processor->processData(data);
        }
    }).detach();
}

void SensorDataLibrary::stopProcessing() {
    processingActive = false;
    dataReady.notify_all();
}
