#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define USER_ACTIVITY_LOGS structure
typedef struct {
    int version;
    char *activity;
} USER_ACTIVITY_LOGS;

// Function to initialize USER_ACTIVITY_LOGS
USER_ACTIVITY_LOGS* init_user_activity_logs(int version, const char *activity) {
    USER_ACTIVITY_LOGS *log = (USER_ACTIVITY_LOGS*)malloc(sizeof(USER_ACTIVITY_LOGS));
    log->version = version;
    log->activity = strdup(activity);
    return log;
}

// Function to free USER_ACTIVITY_LOGS
void free_user_activity_logs(USER_ACTIVITY_LOGS *log) {
    if (log != NULL) {
        free(log->activity);
        free(log);
    }
}

// Function to clone USER_ACTIVITY_LOGS
USER_ACTIVITY_LOGS* clone_user_activity_logs(const USER_ACTIVITY_LOGS *original) {
    return init_user_activity_logs(original->version, original->activity);
}

// Function to update USER_ACTIVITY_LOGS
void update_user_activity_logs(USER_ACTIVITY_LOGS *log, const char *new_activity) {
    free(log->activity);
    log->activity = strdup(new_activity);
}

// Function to compare two USER_ACTIVITY_LOGS
int compare_user_activity_logs(const USER_ACTIVITY_LOGS *log1, const USER_ACTIVITY_LOGS *log2) {
    if (log1->version != log2->version)
        return 0;
    return strcmp(log1->activity, log2->activity) == 0;
}

// Function to get the activity description
const char* get_activity_description(const USER_ACTIVITY_LOGS *log) {
    return log->activity;
}

// Main function to demonstrate usage
int main() {
    USER_ACTIVITY_LOGS *log1 = init_user_activity_logs(1, "User logged in");
    USER_ACTIVITY_LOGS *log2 = clone_user_activity_logs(log1);

    update_user_activity_logs(log1, "User logged out");

    printf("Log 1: Version %d, Activity '%s'\n", log1->version, log1->activity);
    printf("Log 2: Version %d, Activity '%s'\n", log2->version, log2->activity);

    if (compare_user_activity_logs(log1, log2) == 0)
        printf("Logs are different.\n");
    else
        printf("Logs are the same.\n");

    free_user_activity_logs(log1);
    free_user_activity_logs(log2);

    return 0;
}
