// C code for managing a dynamic array of TX_POWER_LEVEL_STATS structures

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    int ci;
    int power_level;
} TX_POWER_LEVEL_STATS;

TX_POWER_LEVEL_STATS* array = NULL;
size_t size = 0;
size_t capacity = 16;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void resize_array() {
    capacity *= 2;
    TX_POWER_LEVEL_STATS* new_array = realloc(array, capacity * sizeof(TX_POWER_LEVEL_STATS));
    if (new_array) {
        array = new_array;
    }
}

void add_entry(time_t timestamp, int ci, int power_level) {
    pthread_mutex_lock(&mutex);
    if (size == capacity) {
        resize_array();
    }
    array[size].timestamp = timestamp;
    array[size].ci = ci;
    array[size].power_level = power_level;
    size++;
    pthread_mutex_unlock(&mutex);
}

void update_entry(int ci, int power_level) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < size; i++) {
        if (array[i].ci == ci) {
            array[i].power_level = power_level;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

TX_POWER_LEVEL_STATS* get_latest_entry(int ci) {
    TX_POWER_LEVEL_STATS* latest_entry = NULL;
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < size; i++) {
        if (array[i].ci == ci && (!latest_entry || array[i].timestamp > latest_entry->timestamp)) {
            latest_entry = &array[i];
        }
    }
    pthread_mutex_unlock(&mutex);
    return latest_entry;
}
