// Rust function to measure performance of compiling a custom Rust binary

use std::process::{Command, ExitStatus};
use rustc_driver::{self, catch_with_exit_code, early_error};

fn compile_rust_binary(logging_config: &str) -> ExitStatus {
    let mut command = Command::new("rustc");
    command.args(&["-C", &format!("debug-assertions={}", logging_config)]);

    match catch_with_exit_code(|| rustc_driver::main()) {
        Ok(status) => status,
        Err(e) => early_error(rustc_errors::emitter::ErrorGuarantee::Crash, e.to_string()).exit(),
    }
}
