// src/main.rs
use clap::{App, Arg};
use log::{info, error, set_max_level, LevelFilter};
use rayon::prelude::*;
use std::fs;
use std::path::Path;

mod lexer;
mod parser;
mod ir_generator;
mod error_handler;

fn main() {
    let matches = App::new("Code Transformation Tool")
        .version("0.1.0")
        .author("Your Name <you@example.com>")
        .about("A Rust-based code transformation tool that converts source code files into optimized LLVM IR.")
        .arg(
            Arg::with_name("input")
                .short('i')
                .long("input")
                .value_name("FILE")
                .takes_value(true)
                .help("Sets the input file path"),
        )
        .arg(
            Arg::with_name("output")
                .short('o')
                .long("output")
                .value_name("FILE")
                .takes_value(true)
                .help("Sets the output file path"),
        )
        .arg(
            Arg::with_name("log-level")
                .short('l')
                .long("log-level")
                .value_name("LEVEL")
                .takes_value(true)
                .possible_values(&["info", "error", "debug"])
                .default_value("info")
                .help("Sets the log level"),
        )
        .get_matches();

    set_max_level(match matches.value_of("log-level") {
        Some("info") => LevelFilter::Info,
        Some("error") => LevelFilter::Error,
        Some("debug") => LevelFilter::Debug,
        _ => unreachable!(),
    });

    let input_path = Path::new(matches.value_of("input").unwrap());
    let output_path = Path::new(matches.value_of("output").unwrap());

    if !input_path.exists() {
        error!("Input file does not exist");
        return;
    }

    let source_code = fs::read_to_string(input_path).expect("Unable to read input file");

    let tokens = lexer::lex(&source_code);
    let ast = parser::parse(tokens);
    let llvm_ir = ir_generator::generate_ir(ast);

    match fs::write(output_path, &llvm_ir) {
        Ok(_) => info!("Output file generated successfully"),
        Err(e) => error!("Error writing output file: {}", e),
    }
}
