#include <random>
#include <chrono>
#include <future>

// External service interface
class ExternalService {
public:
    virtual void requestReSeed() = 0;
    virtual void tuneParameters(int seed) = 0;
};

// Dummy external service implementation
class DummyExternalService : public ExternalService {
public:
    void requestReSeed() override {}
    void tuneParameters(int seed) override {}
};

// RNG engine
class RandomNumberGenerator {
private:
    std::mt19937 gen;
    std::mutex mtx;

public:
    RandomNumberGenerator(int seed) : gen(seed) {}

    int generateRandomNumber() {
        std::lock_guard<std::mutex> lock(mtx);
        return gen();
    }
};

// RNG library
class RNGLibrary {
private:
    std::vector<RandomNumberGenerator*> rngs;
    ExternalService* externalService;
    std::thread reseedThread;
    std::condition_variable cv;
    bool stop;

public:
    RNGLibrary(ExternalService* service) : externalService(service), stop(false) {
        reseedThread = std::thread(&RNGLibrary::reseedLoop, this);
    }

    ~RNGLibrary() {
        stop = true;
        cv.notify_all();
        reseedThread.join();

        for (auto rng : rngs) {
            delete rng;
        }
    }

    void addRNG(int seed) {
        std::lock_guard<std::mutex> lock(mtx);
        rngs.push_back(new RandomNumberGenerator(seed));
    }

    int generateRandomNumber() {
        std::lock_guard<std::mutex> lock(mtx);
        if (rngs.empty()) return -1;
        auto it = rngs.begin();
        advance(it, std::rand() % rngs.size());
        return (*it)->generateRandomNumber();
    }

private:
    void reseedLoop() {
        while (!stop) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this] { return stop || externalService->requestReSeed(); });

            if (stop) break;

            // Request re-seeding and parameter tuning from the external service
            externalService->requestReSeed();
            int newSeed = std::rand();  // Dummy logic for demonstration
            externalService->tuneParameters(newSeed);

            // Update all RNG instances with the new seed
            for (auto rng : rngs) {
                delete rng;
                rngs.push_back(new RandomNumberGenerator(newSeed));
            }
        }
    }

private:
    mutable std::mutex mtx;
};
```

