#include <semaphore.h>
#include <stdio.h>

sem_t* create_semaphore(int initial_value) {
    sem_t* semaphore = (sem_t*)malloc(sizeof(sem_t));
    if (sem_init(semaphore, 0, initial_value) == -1) {
        perror("Failed to initialize semaphore");
        free(semaphore);
        return NULL;
    }
    return semaphore;
}

void delete_semaphore(sem_t* semaphore) {
    if (sem_destroy(semaphore) == -1) {
        perror("Failed to destroy semaphore");
    }
    free(semaphore);
}
