const express = require('express');
const fs = require('fs').promises;
const path = require('path');
const axios = require('axios');
const os = require('os');

const app = express();
app.use(express.json());

// Configuration
const config = {
  directory: '/path/to/your/directory',
  fileExtensions: ['.txt', '.jpg'],
  concurrencyLimit: 10,
  performanceThresholds: {
    cpu: 50, // in percentage
    memory: 800 * 1024 * 1024 // 800MB in bytes
  },
  retryPolicy: {
    maxRetries: 3,
    delay: 5000 // 5 seconds
  }
};

// Middleware for rate limiting based on concurrency
const rateLimiter = (req, res, next) => {
  if (/* check if number of concurrent tasks exceeds limit */) {
    return res.status(429).send('Too many requests');
  }
  next();
};

app.use(rateLimiter);

// Route to start processing files
app.post('/start-processing', async (req, res) => {
  const { directory } = req.body;

  try {
    // List files in the specified directory
    const files = await fs.readdir(directory);
    const filteredFiles = files.filter(file => config.fileExtensions.includes(path.extname(file)));

    // Process files asynchronously
    await Promise.all(filteredFiles.map(processFile));

    res.status(200).send('Processing started');
  } catch (error) {
    console.error('Error processing files:', error);
    res.status(500).send('Failed to process files');
  }
});

// Function to process a single file
const processFile = async (file) => {
  const filePath = path.join(config.directory, file);

  try {
    // Validate file integrity with external metadata service
    await validateFileIntegrity(filePath);

    // Process the file (e.g., read content, perform operations)
    await readFileContent(filePath);
  } catch (error) {
    console.error('Error processing file:', filePath, error);
  }
};

// Function to validate file integrity
const validateFileIntegrity = async (filePath) => {
  const response = await axios.post('https://metadata-service.com/validate', { filePath });

  if (!response.data.valid) {
    throw new Error('Invalid file integrity');
  }
};

// Function to read file content
const readFileContent = async (filePath) => {
  const content = await fs.readFile(filePath, 'utf8');

  // Process the content as needed
  console.log('Processed file:', filePath);
};

// Route to get system metrics
app.get('/metrics', (req, res) => {
  const cpuUsage = os.cpus().reduce((sum, core) => sum + core.usage * 100, 0) / os.cpus().length;
  const memoryUsage = process.memoryUsage().rss;

  res.json({
    cpuUsage,
    memoryUsage
  });
});

app.listen(3000, () => {
  console.log('Service is running on port 3000');
});
```

