import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

public class DistributedLogProcessingSystem {
    private Map<String, LogSource> sources = new ConcurrentHashMap<>();
    private List<LogProcessor> processors = Collections.synchronizedList(new ArrayList<>());
    private TimeSeriesDatabase storage;
    private ExecutorService executor;

    public DistributedLogProcessingSystem(TimeSeriesDatabase storage) {
        this.storage = storage;
        this.executor = Executors.newCachedThreadPool();
    }

    public void addSource(String sourceId, LogSource source) {
        sources.put(sourceId, source);
        source.setProcessor(processor -> processLogEvents(sourceId, processor));
    }

    public void addProcessor(LogProcessor processor) {
        processors.add(processor);
    }

    public void start() {
        for (LogSource source : sources.values()) {
            executor.submit(() -> source.start());
        }
    }

    private void processLogEvents(String sourceId, Function<List<String>, List<String>> processor) {
        while (true) {
            List<String> rawLogs = sources.get(sourceId).fetchLogs();
            if (rawLogs == null || rawLogs.isEmpty()) {
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
                continue;
            }

            List<String> processedLogs = processor.apply(rawLogs);
            storage.storeLogs(processedLogs, System.currentTimeMillis());
        }
    }

    public void stop() {
        executor.shutdownNow();
        for (LogSource source : sources.values()) {
            source.stop();
        }
    }

    public static void main(String[] args) {
        TimeSeriesDatabase db = new InMemoryTimeSeriesDatabase();
        DistributedLogProcessingSystem system = new DistributedLogProcessingSystem(db);

        KafkaLogSource kafkaSource = new KafkaLogSource("kafka-broker:9092", "logs-topic");
        system.addSource("kafka-source", kafkaSource);

        HttpLogSource httpSource = new HttpLogSource("http://example.com/api/logs");
        system.addSource("http-source", httpSource);

        GrpcLogSource grpcSource = new GrpcLogSource("grpc://example.com:50051/logs-service/Logs");
        system.addSource("grpc-source", grpcSource);

        LogProcessor filterProcessor = logs -> {
            List<String> filteredLogs = new ArrayList<>();
            for (String log : logs) {
                if (log.contains("ERROR")) {
                    filteredLogs.add(log);
                }
            }
            return filteredLogs;
        };
        system.addProcessor(filterProcessor);

        system.start();

        // Simulate stopping after 60 seconds
        try {
            Thread.sleep(60000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        system.stop();
    }
}

