fn generate_llvm_ir(file_path: &str) -> String {
    let content = fs::read_to_string(file_path).expect("Failed to read file");
    let pairs = Grammar::parse(Rule::file, &content).expect("Parsing failed");

    let mut llvm_ir = String::new();

    for pair in pairs.into_inner() {
        match pair.as_rule() {
            Rule::statement => {
                // Handle statement parsing and LLVM IR generation
                println!("Parsed statement: {:?}", pair);
                llvm_ir.push_str(&generate_llvm_ir_for_statement(pair));
            }
            _ => {}
        }
    }

    llvm_ir
}

