using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class ScriptSource
{
    public string Key { get; set; }
    public string Src { get; set; }
    public string InnerHTML { get; set; }
    public List<string> Dependencies { get; set; }
}

public class FooterScriptsRenderer
{
    private static readonly HashSet<string> WhitelistedDomains = new HashSet<string> { "https://example.com" };
    private static readonly Dictionary<string, string> Cache = new Dictionary<string, string>();

    public async Task<(string Html, string Md5Hash)> renderFooterScriptsMD5(List<ScriptSource> scripts)
    {
        List<Task<string>> scriptTasks = new List<Task<string>>();
        foreach (var script in scripts)
        {
            if (!script.Src.StartsWithAny(WhitelistedDomains))
            {
                Console.WriteLine($"Warning: Script source {script.Src} is not whitelisted. Skipping.");
                continue;
            }

            if (string.IsNullOrEmpty(script.Src) || string.IsNullOrEmpty(script.InnerHTML))
            {
                Console.WriteLine("Warning: Missing src or innerHTML for a script. Using fallback values.");
                script.Src = "https://example.com/fallback.js";
                script.InnerHTML = "<script>console.log('Fallback script');</script>";
            }

            if (Cache.ContainsKey(script.Key) && Cache[script.Key] != null)
            {
                Console.WriteLine($"Using cached script for {script.Key}");
                scriptTasks.Add(Task.FromResult(Cache[script.Key]));
                continue;
            }

            scriptTasks.Add(LoadScriptAsync(script));
        }

        string concatenatedHtml = await Task.WhenAll(scriptTasks);
        string html = $"<footer>{concatenatedHtml}</footer>";
        string md5Hash = GenerateMd5Hash(html);

        return (html, md5Hash);
    }

    private async Task<string> LoadScriptAsync(ScriptSource script)
    {
        for (int attempt = 0; attempt < 3; attempt++)
        {
            try
            {
                var httpClient = new HttpClient();
                var htmlContent = await httpClient.GetStringAsync(script.Src);
                Cache[script.Key] = htmlContent;
                return htmlContent;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error loading script {script.Key} (Attempt {attempt + 1}): {ex.Message}");
                if (attempt == 2)
                    throw;
                await Task.Delay(500); // Wait before retrying
            }
        }
    }

    private string GenerateMd5Hash(string input)
    {
        using (MD5 md5 = MD5.Create())
        {
            byte[] inputBytes = Encoding.ASCII.GetBytes(input);
            byte[] hashBytes = md5.ComputeHash(inputBytes);

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < hashBytes.Length; i++)
                sb.Append(hashBytes[i].ToString("x2"));

            return sb.ToString();
        }
    }
}
