class ThemeManager {
  constructor(cacheServerUrl, imageServiceUrl) {
    this.cache = new Map();
    this.cacheServerUrl = cacheServerUrl;
    this.imageServiceUrl = imageServiceUrl;
    this.retryCount = 0;
    this.maxRetries = 5;
    this.backoffFactor = 2;
  }

  async fetchTheme(id, retries = 0) {
    try {
      const response = await fetch(`${this.cacheServerUrl}/themes/${id}`);
      if (!response.ok) throw new Error('Network response was not ok');
      return await response.json();
    } catch (error) {
      if (retries < this.maxRetries) {
        const backoffTime = Math.min(
          1000 * this.backoffFactor ** retries,
          60000
        );
        setTimeout(() => this.fetchTheme(id, retries + 1), backoffTime);
      } else {
        throw error;
      }
    }
  }

  async downloadImage(url) {
    try {
      const response = await fetch(url);
      if (!response.ok) throw new Error('Network response was not ok');
      return await response.blob();
    } catch (error) {
      this.retryCount++;
      if (this.retryCount < this.maxRetries) {
        setTimeout(() => this.downloadImage(url), 1000 * this.backoffFactor ** this.retryCount);
      } else {
        throw error;
      }
    }
  }

  async cacheTheme(id, data) {
    this.cache.set(id, data);
    await fetch(`${this.cacheServerUrl}/themes`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    });
  }

  async updateTheme(id, newData) {
    const theme = this.cache.get(id);
    if (theme) {
      Object.assign(theme, newData);
      await fetch(`${this.cacheServerUrl}/themes/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newData)
      });
    } else {
      throw new Error('Theme not found in cache');
    }
  }

  async deleteTheme(id) {
    this.cache.delete(id);
    await fetch(`${this.cacheServerUrl}/themes/${id}`, { method: 'DELETE' });
  }

  pause() {
    // Implement pause functionality
  }

  resume() {
    // Implement resume functionality
  }

  static getDefaultThemeDirectory() {
    return localStorage.getItem('defaultThemeDirectory') || '/default-themes';
  }

  static setDefaultThemeDirectory(directory) {
    localStorage.setItem('defaultThemeDirectory', directory);
  }
}

// Unit tests
describe('ThemeManager', () => {
  it('fetches theme data from cache server', async () => {
    const manager = new ThemeManager('http://cache-server', 'http://image-service');
    const themeData = await manager.fetchTheme('123');
    expect(themeData).toEqual({ id: '123', name: 'Default' });
  });

  it('downloads and caches image', async () => {
    const manager = new ThemeManager('http://cache-server', 'http://image-service');
    const imageBlob = await manager.downloadImage('http://image-url');
    expect(imageBlob).toEqual(new Blob());
  });

  it('caches theme data', async () => {
    const manager = new ThemeManager('http://cache-server', 'http://image-service');
    const themeData = { id: '123', name: 'Default' };
    await manager.cacheTheme('123', themeData);
    expect(manager.cache.get('123')).toEqual(themeData);
  });

  it('updates cached theme data', async () => {
    const manager = new ThemeManager('http://cache-server', 'http://image-service');
    const themeData = { id: '123', name: 'Default' };
    await manager.cacheTheme('123', themeData);
    const updatedData = { id: '123', name: 'Updated' };
    await manager.updateTheme('123', updatedData);
    expect(manager.cache.get('123')).toEqual(updatedData);
  });

  it('deletes cached theme data', async () => {
    const manager = new ThemeManager('http://cache-server', 'http://image-service');
    const themeData = { id: '123', name: 'Default' };
    await manager.cacheTheme('123', themeData);
    await manager.deleteTheme('123');
    expect(manager.cache.has('123')).toBe(false);
  });

  it('handles network errors during fetch', async () => {
