```javascript
// middleware/caching.js

const LRU = require('lru-cache');

const cache = new LRU({
  max: 500,
  maxAge: 1000 * 60 * 60, // 1 hour
});

const isCacheable = (url) => {
  // Define your logic to determine which URLs should be cached
  return url.includes('api.example.com');
};

module.exports = (req, res, next) => {
  const { url } = req;
  if (!isCacheable(url)) {
    return next();
  }

  const cachedData = cache.get(url);
  if (cachedData) {
    res.json(cachedData);
  } else {
    res.sendResponse = res.json;
    res.json = (data) => {
      cache.set(url, data);
      res.sendResponse(data);
    };
    next();
  }
};
```

