const fetchDataFromAPI = require('../../utils/fetchDataFromAPI');

router.get('/data', async (req, res) => {
  try {
    const data = await fetchDataFromAPI();
    res.json(data);
  } catch (error) {
    handleErrors(res, error);
  }
});

module.exports = router;
```

