# Import necessary libraries
from flask import Flask, request, jsonify
import redis
import requests
from cachetools import TTLCache, cached

app = Flask(__name__)
cache = TTLCache(maxsize=100, ttl=300)  # Simple cache with max size and TTL

# Redis client for distributed caching
redis_client = redis.StrictRedis(host='localhost', port=6379, db=0)

def get_image_from_cache(key):
    return redis_client.get(key)

def set_image_in_cache(key, value):
    redis_client.setex(key, 3600, value)  # Cache for 1 hour

@app.route('/image/<image_id>', methods=['GET'])
@cached(cache)
def get_image(image_id):
    cached_image = get_image_from_cache(image_id)
    if cached_image:
        return jsonify({'image': cached_image.decode('utf-8')})

    try:
        # Simulate external API call
        response = requests.get(f'https://api.example.com/images/{image_id}')
        response.raise_for_status()
        image_data = response.content
        set_image_in_cache(image_id, image_data)
        return jsonify({'image': image_data.decode('utf-8')})
    except requests.RequestException as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
