        using (var reader = XmlReader.Create(xmlStream)) {
            while (await reader.ReadAsync()) {
                if (reader.NodeType == XmlNodeType.Element && reader.Name == "elementName") {
                    // Process element
                    await ProcessElement(reader);
                }
            }
        }

