                    command.Parameters.AddWithValue("@Value", "someValue");
                    await command.ExecuteNonQueryAsync();
                }
            }
        } catch (Exception e) {
            HandleException(e);
        }
    }

    private async Task ProcessElement(XmlReader reader) {
