CREATE OR ALTER PROCEDURE GetEmployeeDetails
    @SupervisorID INT = NULL,
    @Department NVARCHAR(100) = NULL,
    @JobTitle NVARCHAR(100) = NULL,
    @APIKey NVARCHAR(100),
    @PageNumber INT,
    @PageSize INT = 500
AS
BEGIN
    DECLARE @SQL NVARCHAR(MAX);
    DECLARE @Error INT;

    SET @SQL = '
        SELECT TOP (@PageSize)
            E.EmployeeID, E.Name, E.City, E.Address
        FROM Employees E WITH (INDEX(IX_Employees_SupervisorID_Department_JobTitle))
        WHERE 1=1
        ';

    IF @SupervisorID IS NOT NULL
    BEGIN
        SET @SQL = @SQL + ' AND E.SupervisorID = @SupervisorID ';
    END

    IF @Department IS NOT NULL
    BEGIN
        SET @SQL = @SQL + ' AND E.Department = @Department ';
    END

    IF @JobTitle IS NOT NULL
    BEGIN
        SET @SQL = @SQL + ' AND E.JobTitle = @JobTitle ';
    END

    SET @SQL = @SQL + '
        ORDER BY E.EmployeeID OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;

        DECLARE @APIResponse NVARCHAR(MAX);
        BEGIN TRY
            EXEC sp_executesql @SQL, N''@SupervisorID INT, @Department NVARCHAR(100), @JobTitle NVARCHAR(100), @PageNumber INT, @PageSize INT'', @SupervisorID, @Department, @JobTitle, @PageNumber, @PageSize;
        END TRY
        BEGIN CATCH
            SET @Error = @@ERROR;
            -- Log error details here
        END CATCH;
    ';

    EXEC sp_executesql @SQL, N''@APIKey NVARCHAR(100), @PageNumber INT'', @APIKey, @PageNumber;
END;
