<?php

// Initialize dependencies
$paymentGateways = [
    'stripe' => new StripeGateway(),
    'paypal' => new PayPalGateway(),
    'square' => new SquareGateway(),
];
$cachingService = new CachingService();
$rateLimiter = new RateLimiter();

// Define transaction processing function
function processTransaction($gateway, $amount, $currency, $user, &$error)
{
    if (!$rateLimiter->allowRequest($gateway)) {
        $error = "Rate limit exceeded for {$gateway}.";
        return null;
    }

    try {
        $transactionId = $paymentGateways[$gateway]->createTransaction($amount, $currency, $user);
        $cachingService->set("transaction:{$transactionId}", $transactionId, 3600);

        while (true) {
            $status = $paymentGateways[$gateway]->getTransactionStatus($transactionId);
            if ($status === 'completed') {
                return $transactionId;
            }
            sleep(2); // Poll every 2 seconds
        }
    } catch (\Exception $e) {
        $error = $e->getMessage();
        return null;
    }
}

// Handle incoming transaction requests
$gateway = $_GET['gateway'] ?? 'stripe';
$amount = $_POST['amount'] ?? 0;
$currency = $_POST['currency'] ?? 'USD';
$user = $_POST['user'] ?? null;

$error = '';
$transactionId = processTransaction($gateway, $amount, $currency, $user, $error);

if ($transactionId) {
    echo json_encode(['success' => true, 'transaction_id' => $transactionId]);
} else {
    http_response_code(400);
    echo json_encode(['success' => false, 'message' => $error]);
}
```

