    argon2_config config = {
        .m = 65536, // Memory cost
        .t = 4,     // Time cost
        .p = 1      // Parallelism
    };

    if (argon2id_hash_raw(data.c_str(), data.length(), out, sizeof(out), NULL, 0, &config) != ARGON2_OK) {
        throw std::runtime_error("Failed to hash data");
    }

    return std::string(reinterpret_cast<char*>(out), sizeof(out));
}

