class TransactionQueue {
public:
    void push(const Transaction& tx) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(tx);
        cv_.notify_one();
    }

    bool try_pop(Transaction& tx, std::chrono::milliseconds timeout) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (!cv_.wait_for(lock, timeout, [this] { return !queue_.empty(); })) {
            return false;
        }
        tx = queue_.front();
        queue_.pop();
        return true;
    }

private:
    std::queue<Transaction> queue_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

class TransactionProcessor {
public:
    void processTransactionStream(TransactionQueue& queue) {
        while (true) {
            Transaction tx;
            if (queue.try_pop(tx, std::chrono::milliseconds(100))) {
                if (filterTransaction(tx)) {
