#include <pthread.h>

#define MAX_POWER_LEVELS 1000

typedef struct {
    int timestamp;
    int cell_identity;
    int power_level;
} TX_POWER_LEVEL_STATS;

TX_POWER_LEVEL_STATS power_levels[MAX_POWER_LEVELS];
int num_entries = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_power_level(int timestamp, int ci, int power_level) {
    pthread_mutex_lock(&lock);
    if (num_entries < MAX_POWER_LEVELS) {
        power_levels[num_entries].timestamp = timestamp;
        power_levels[num_entries].cell_identity = ci;
        power_levels[num_entries].power_level = power_level;
        num_entries++;
    } else {
        printf("Maximum number of entries reached\n");
    }
    pthread_mutex_unlock(&lock);
}

void update_power_level(int ci, int new_power_level) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_entries; i++) {
        if (power_levels[i].cell_identity == ci) {
            power_levels[i].power_level = new_power_level;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

TX_POWER_LEVEL_STATS* get_latest_power_level(int ci) {
    pthread_mutex_lock(&lock);
    TX_POWER_LEVEL_STATS* latest_entry = NULL;
    for (int i = 0; i < num_entries; i++) {
        if (power_levels[i].cell_identity == ci && (!latest_entry || power_levels[i].timestamp > latest_entry->timestamp)) {
            latest_entry = &power_levels[i];
        }
    }
    pthread_mutex_unlock(&lock);
    return latest_entry;
}

int main() {
    add_power_level(1633072800, 12345, -95);
    update_power_level(12345, -90);
    TX_POWER_LEVEL_STATS* entry = get_latest_power_level(12345);
    if (entry) {
        printf("Latest power level for CI 12345: %d dBm\n", entry->power_level);
    }
    return 0;
}
