#include <nlohmann/json.hpp>

namespace config_lib {

class ConfigurationManager {
public:
    using ConfigKey = std::string;
    using ConfigValue = nlohmann::json;

private:
    struct ConfigEntry {
        ConfigValue value;
        std::time_t version;
    };

    std::unordered_map<ConfigKey, ConfigEntry> configMap_;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::atomic<bool> isShuttingDown_;

public:
    ConfigurationManager(const std::vector<std::string>& file_paths)
        : isShuttingDown_(false) {
        for (const auto& path : file_paths) {
            loadConfigFile(path);
        }
    }

    ~ConfigurationManager() {
        isShuttingDown_.store(true);
        cv_.notify_all();
    }

    void updateConfig(const ConfigKey& key, const ConfigValue& value, std::time_t version) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (isShuttingDown_) return;
        configMap_[key] = {value, version};
        cv_.notify_all();
    }

    ConfigValue getConfig(const ConfigKey& key) const {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = configMap_.find(key);
        if (it != configMap_.end()) {
            return it->second.value;
        }
        throw std::runtime_error("Config not found");
    }

private:
    void loadConfigFile(const std::string& path) {
        // Implement file loading and parsing logic here
    }
};

class ConfigUpdater {
public:
    ConfigUpdater(ConfigurationManager& manager)
        : manager_(manager), service_(), strand_(service_) {}

    void start() {
        boost::asio::spawn(service_, [this](boost::system::error_code ec) {
            if (!ec) updateLoop();
        });
        service_.run();
    }

private:
    void updateLoop() {
        while (true) {
            ConfigKey key;
            ConfigValue value;
            std::time_t version;
            // Implement logic to fetch updates from centralized server
            manager_.updateConfig(key, value, version);
            cv_.wait(strand_);
        }
    }

    ConfigurationManager& manager_;
    boost::asio::io_service service_;
    boost::asio::strand strand_;
};

} // namespace config_lib

int main() {
    std::vector<std::string> file_paths = {"config1.json", "config2.json"};
    config_lib::ConfigurationManager manager(file_paths);
    config_lib::ConfigUpdater updater(manager);

    updater.start();

    return 0;
}
```

