public class UserRegistrationService
{
    private readonly ILogger<UserRegistrationService> _logger;
    private readonly IDistributedCache _cache;
    private readonly SmtpClient _smtpClient;
    private readonly RateLimiter _rateLimiter;
    private readonly RetryPolicy _retryPolicy;

    public UserRegistrationService(ILogger<UserRegistrationService> logger, IDistributedCache cache)
    {
        _logger = logger;
        _cache = cache;
        _smtpClient = new SmtpClient("smtp.example.com", 587)
        {
            EnableSsl = true,
            Credentials = new System.Net.NetworkCredential("user@example.com", "password")
        };

        _rateLimiter = new RateLimiter();
        _retryPolicy = Policy
            .Handle<Exception>()
            .WaitAndRetryAsync(5, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)))
            .WithRetryStrategy(new Polly.Retry.AsyncRetryStrategy(
                onRetry: (exception, retryCount, context) =>
                {
                    _logger.LogInformation("Retrying email sending attempt {RetryCount} for user {UserId}: {Exception}",
                        retryCount, context.State, exception);
                },
                retryThreshold: 5 * 60
            ));
    }

    public async Task RegisterUserAsync(string email)
    {
        if (!IsValidEmail(email))
        {
            _logger.LogError("Invalid email address format.");
            throw new ArgumentException("Invalid email address format.");
        }

        var userId = GenerateUserId();

        try
        {
            await _rateLimiter.EnsureRateLimitAsync(userId);

            if (await IsUserRegisteredAsync(email))
            {
                _logger.LogInformation("User already registered: {Email}", email);
                return;
            }

            var activationToken = GenerateActivationToken();

            await _cache.SetStringAsync($"Activation:{userId}", activationToken, new DistributedCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromHours(1)
            });

            await SendActivationEmailAsync(email, activationToken);

            _logger.LogInformation("User registered successfully: {Email}", email);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to register user: {Email}", email);
            throw;
        }
    }

    private bool IsValidEmail(string email)
    {
        var pattern = @"^[^@\s]+@[^@\s]+\.[^@\s]+$";
        return Regex.IsMatch(email, pattern);
    }

    private string GenerateUserId()
    {
        // Generate a unique user ID
        return Guid.NewGuid().ToString();
    }

    private string GenerateActivationToken()
    {
        // Generate a token for email activation
        return Guid.NewGuid().ToString("N");
    }

    private async Task<bool> IsUserRegisteredAsync(string email)
    {
        // Check if user is already registered in the system
        // This could involve querying the database or any other storage mechanism
        // For simplicity, assume this method returns false always
        return await _cache.GetStringAsync($"Registered:{email}") == "true";
    }

    private async Task SendActivationEmailAsync(string email, string token)
    {
