            using (var message = new MailMessage("user@example.com", email, "Activate Your Account", $"Click <a href=\"http://example.com/activate?token={token}\">here</a> to activate your account."))
            {
                await _smtpClient.SendMailAsync(message);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to send activation email to: {Email}", email);
            throw;
        }
    }
}

