import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class BatchFileDeletionManager {

    private Map<String, Integer> directoryLimits = new HashMap<>();
    private List<String> exemptedFileTypes = List.of(".log", ".tmp");
    private boolean adminApprovalRequired = true;
    private ExecutorService executorService = Executors.newFixedThreadPool(10);

    public void deleteOldFiles() {
        for (Map.Entry<String, Integer> entry : directoryLimits.entrySet()) {
            String directoryPath = entry.getKey();
            int limit = entry.getValue();

            File directory = new File(directoryPath);
            if (!directory.exists() || !directory.isDirectory()) {
                continue;
            }

            Path path = Paths.get(directoryPath);
            try (Files.Walk walk = Files.walk(path)) {
                long fileCount = 0;
                for (Path filePath : walk) {
                    if (filePath.toFile().isFile()) {
                        LocalDateTime lastModifiedTime = LocalDateTime.ofInstant(filePath.toFile().lastModified(), java.time.ZoneId.systemDefault());
                        if (ChronoUnit.DAYS.between(lastModifiedTime, LocalDateTime.now()) > 7 &&
                                !exemptedFileTypes.contains(filePath.toString())) {
                            fileCount++;
                            if (fileCount <= limit) {
                                executorService.submit(() -> deleteFileSafely(filePath));
                            } else {
                                break;
                            }
                        }
                    }
                }
            } catch (Exception e) {
                handleException(e);
            }
        }
    }

    private void deleteFileSafely(Path filePath) {
        if (!adminApprovalRequired || getAdminApproval()) {
            try {
                Files.delete(filePath);
                log("Deleted file: " + filePath.toString());
            } catch (Exception e) {
                handleException(e);
            }
        } else {
            log("Admin approval required for deletion of: " + filePath.toString());
        }
    }

    private boolean getAdminApproval() {
        // Implement logic to request admin approval
        return true;
    }

    private void handleException(Exception e) {
        log("Error occurred: " + e.getMessage());
        retry(e);
    }

    private void retry(Exception e) {
        // Implement retry logic for transient failures
    }

    private void log(String message) {
        // Implement logging mechanism with configurable output formats and destinations
        System.out.println(message);
    }

    public static void main(String[] args) {
        BatchFileDeletionManager manager = new BatchFileDeletionManager();
        manager.directoryLimits.put("C:\\directory1", 50);
        manager.directoryLimits.put("C:\\directory2", 30);
        manager.deleteOldFiles();
    }
}
