public class EncryptionModule
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, byte[]> _cache = new();
    private readonly SemaphoreSlim _lock = new(1);

    public EncryptionModule(HttpClient httpClient)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
    }

    public async Task<byte[]> DownloadAndDecryptAsync(string url)
    {
        var key = GenerateKeyFromUrl(url);
        if (_cache.TryGetValue(key, out var data))
            return data;

        try
        {
            using (var response = await _httpClient.GetAsync(url, HttpCompletionOption.ResponseHeadersRead))
            {
                response.EnsureSuccessStatusCode();
                var encryptedData = await response.Content.ReadAsByteArrayAsync();
                return Decrypt(encryptedData);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error downloading and decrypting data: {ex}");
            throw;
        }
    }

    private byte[] GenerateKeyFromUrl(string url)
    {
        // Implement a secure key generation mechanism based on the URL
        return HashAlgorithm.Create("SHA256").ComputeHash(System.Text.Encoding.UTF8.GetBytes(url));
    }

    private byte[] Decrypt(byte[] encryptedData)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = GenerateKeyFromUrl("encryption_key_url");
            aes.IV = GenerateIV();
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            using (var decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
            {
                using (var ms = new System.IO.MemoryStream(encryptedData))
                {
                    using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                    {
                        return await cs.ReadAllBytesAsync();
                    }
                }
            }
        }
    }

    private byte[] GenerateIV()
    {
        // Implement a secure IV generation mechanism
        var iv = new byte[16];
        using (var rng = RandomNumberGenerator.Create())
        {
            rng.GetBytes(iv);
        }
        return iv;
    }

