// Java Library for Serialization/Deserialization

public class DomainObjectSerializer {
    private Map<String, Class<?>> registeredClasses;
    private ConcurrentHashMap<String, Object> cache;

    public DomainObjectSerializer() {
        this.registeredClasses = new HashMap<>();
        this.cache = new ConcurrentHashMap<>();
    }

    public void registerClass(String className, Class<?> clazz) {
        registeredClasses.put(className, clazz);
    }

    public byte[] serialize(Object obj) throws IOException {
        if (!registeredClasses.containsValue(obj.getClass())) {
            throw new IllegalArgumentException("Class not registered");
        }
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(bos);
        oos.writeObject(obj);
        return bos.toByteArray();
    }

    @SuppressWarnings("unchecked")
    public <T> T deserialize(byte[] data, Class<T> clazz) throws IOException, ClassNotFoundException {
        String className = clazz.getName();
        if (!registeredClasses.containsKey(className)) {
            throw new IllegalArgumentException("Class not registered");
        }
        if (cache.containsKey(className + "-" + Arrays.hashCode(data))) {
            return (T) cache.get(className + "-" + Arrays.hashCode(data));
        }

        ByteArrayInputStream bis = new ByteArrayInputStream(data);
        ObjectInputStream ois = new ObjectInputStream(bis);
        T obj = clazz.cast(ois.readObject());
        cache.put(className + "-" + Arrays.hashCode(data), obj);
        return obj;
    }
}

