    let chunkPromises = [];
    for (let i = 0; i < chunks.length; i++) {
      chunkPromises.push(this.uploadChunk(chunks[i], file.name));
    }
    return Promise.all(chunkPromises).then(chunks => this.mergeChunks(chunks, file.name));
  }

  async uploadChunk(chunk, fileName) {
