// Import necessary modules
const express = require('express');
const bodyParser = require('body-parser');
const axios = require('axios');
const rateLimit = require('express-rate-limit');
const fs = require('fs');
const path = require('path');

// Initialize express app
const app = express();
app.use(bodyParser.json());

// Setup rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Middleware for command validation and user authentication
async function validateCommand(req, res, next) {
  const { userId, command } = req.body;

  try {
    const response = await axios.post('https://api.example.com/validate', { userId, command });

    if (response.data.isValid) {
      next();
    } else {
      res.status(403).send('Unauthorized command');
    }
  } catch (error) {
    res.status(500).send('Error during validation');
  }
}

// Middleware for logging command executions
function logCommand(req, res, next) {
  const { userId, command } = req.body;

  const logEntry = `${new Date().toISOString()} - User ${userId} executed command: ${command}\n`;
  fs.appendFile(path.join(__dirname, 'logs', 'command-executions.log'), logEntry, (err) => {
    if (err) throw err;
  });

  next();
}

// Route to execute system commands
app.post('/execute', validateCommand, logCommand, async (req, res) => {
  const { command } = req.body;

  try {
    const result = await execPromise(command);
    res.send(result);
  } catch (error) {
    res.status(500).send('Error executing command');
  }
});

// Function to safely execute system commands
function execPromise(cmd) {
  return new Promise((resolve, reject) => {
    require('child_process').exec(cmd, { maxBuffer: 1024 * 1024 }, (error, stdout, stderr) => {
      if (error) {
        reject(error);
      } else if (stderr) {
        reject(stderr);
      } else {
        resolve(stdout);
      }
    });
  });
}

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
