use tokio::net::{TcpListener, TcpStream};
use tokio::sync::mpsc;
use std::collections::HashMap;

#[tokio::main]
async fn main() {
    let listener = TcpListener::bind("0.0.0.0:8080").await.unwrap();

    // Create a channel for distributing commands to worker tasks
    let (tx, mut rx) = mpsc::channel(32);

    // Spawn multiple worker tasks
    for _ in 0..10 {
        let tx = tx.clone();
        tokio::spawn(async move {
            while let Some(command) = rx.recv().await {
                handle_command(command).await;
            }
        });
    }

    loop {
        match listener.accept().await {
            Ok((stream, addr)) => {
                println!("New connection from {}", addr);

                // Spawn a task to handle the new connection
                tokio::spawn(async move {
                    let mut buffer = [0; 1024];
                    while let Ok(n) = stream.read(&mut buffer).await {
                        if n == 0 {
                            return;
                        }

                        // Extract the command from the buffer and send it to the worker tasks
                        let command = parse_command(&buffer[..n]).unwrap();
                        tx.send(command).await.unwrap();
                    }
                });
            },
            Err(e) => eprintln!("Failed to accept connection: {}", e),
        }
    }
}

