package com.example.textprocessing;

import java.io.IOException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.ws.rs.GET;
import javax.ws.rs.POST;
import javax.ws.rs.Path;
import javax.ws.rs.Produces;
import javax.ws.rs.Consumes;
import javax.ws.rs.QueryParam;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import com.fasterxml.jackson.databind.ObjectMapper;

@Path("/api/textprocessor")
public class DynamicTextProcessorService {

    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final TransformationEngine transformationEngine;
    private final ConfigurationServer configServer;
    private final CacheManager cacheManager;

    public DynamicTextProcessorService() {
        this.transformationEngine = new TransformationEngine();
        this.configServer = new ConfigurationServer("http://config-server:8080");
        this.cacheManager = new CacheManager(1024, 60);
        loadInitialRules();
    }

    private void loadInitialRules() {
        try {
            String rules = configServer.fetchConfig("/rules.json");
            transformationEngine.loadRules(rules);
        } catch (IOException e) {
            // Load local defaults
            transformationEngine.loadDefaultRules();
        }
    }

    @GET
    @Produces(MediaType.TEXT_PLAIN)
    public Response processText(@QueryParam("text") String text, @QueryParam("operation") String operation) {
        if (text == null || operation == null) {
            return Response.status(Response.Status.BAD_REQUEST).entity("Missing parameters").build();
        }
        try {
            String result = cacheManager.get(text + "-" + operation);
            if (result != null) {
                return Response.ok(result).header("X-Cache", "HIT").build();
            }
            String transformedText = transformationEngine.applyOperation(text, operation);
            result = cacheManager.put(text + "-" + operation, transformedText);
            return Response.ok(result).header("X-Cache", "MISS").build();
        } catch (Exception e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Error processing text").build();
        }
    }

    @POST
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response processBatchText(BatchTextRequest request) {
        try {
            String[] results = executor.invokeAll(request.getTexts().stream()
                .map(text -> () -> transformationEngine.applyOperation(text, request.getOperation()))
                .collect(Collectors.toList()))
                .stream()
                .map(future -> {
                    try {
                        return future.get();
                    } catch (InterruptedException | ExecutionException e) {
                        throw new RuntimeException("Error processing text", e);
                    }
                })
                .toArray(String[]::new);
            BatchTextResponse response = new BatchTextResponse(results);
            return Response.ok(response).build();
        } catch (Exception e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Error processing batch text").build();
        }
    }

    public static void main(String[] args) {
        // Start service
    }
}
