#include <iostream>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <unordered_map>
#include <thread>
#include <atomic>

class DynamicResourceManager {
public:
    DynamicResourceManager(size_t maxResources)
        : maxResources(maxResources), availableResources(maxResources) {}

    void requestResource(const std::string& requestId, size_t resourceAmount) {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this, resourceAmount]() {
            return availableResources >= resourceAmount;
        });
        availableResources -= resourceAmount;
        resourcesInUse[requestId] += resourceAmount;
    }

    void releaseResource(const std::string& requestId, size_t resourceAmount) {
        std::unique_lock<std::mutex> lock(mutex);
        availableResources += resourceAmount;
        resourcesInUse[requestId] -= resourceAmount;
        if (resourcesInUse[requestId] == 0) {
            resourcesInUse.erase(requestId);
        }
        condition.notify_one();
    }

private:
    std::mutex mutex;
    std::condition_variable condition;
    size_t maxResources;
    size_t availableResources;
    std::unordered_map<std::string, size_t> resourcesInUse;
};

int main() {
    DynamicResourceManager manager(100);
    manager.requestResource("app1", 30);
    manager.requestResource("app2", 50);

    // Simulate resource usage
    std::thread t1([&manager]() {
        for (size_t i = 0; i < 10; ++i) {
            manager.requestResource("app1", 5);
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    });

    std::thread t2([&manager]() {
        for (size_t i = 0; i < 10; ++i) {
            manager.requestResource("app2", 10);
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
        }
    });

    t1.join();
    t2.join();

    return 0;
}
