// Function to dynamically load and register a cryptographic algorithm
void load_algorithm(const char *name, void (*init)(void), int (*is_available)(void)) {
    pthread_mutex_lock(&algorithm_lock);
    // Resize the algorithm list to accommodate new algorithms
    CryptoAlgorithm *new_list = realloc(algorithm_list, (num_algorithms + 1) * sizeof(CryptoAlgorithm));
    if (new_list == NULL) {
        perror("Failed to allocate memory for algorithm list");
        pthread_mutex_unlock(&algorithm_lock);
        return;
    }
    algorithm_list = new_list;

    // Initialize the new algorithm
    strcpy(algorithm_list[num_algorithms].name, name);
    algorithm_list[num_algorithms].init = init;
    algorithm_list[num_algorithms].is_available = is_available;

    num_algorithms++;
    pthread_mutex_unlock(&algorithm_lock);
}

// Function to modify file extension with digits and a type based on original filename characters
void modify_file_extension(char *filename, int digits, const char *extension) {
    // Find the last dot in the filename
    char *dot = strrchr(filename, '.');
    if (dot != NULL) {
        // Move past the dot and append digits and extension
        sprintf(dot + 1, "%0*d.%s", digits, (int)(filename - dot - 1), extension);
    } else {
        // If no dot is found, append to the end of the filename
        strcat(filename, "_");
        sprintf(filename + strlen(filename), "%0*d.%s", digits, num_algorithms, extension);
    }
}

