const workerpool = require('workerpool');
const fs = require('fs');
const path = require('path');

// Initialize Express app
const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Redis client setup
const redisClient = redis.createClient({
  url: 'redis://localhost:6379',
  evictionPolicy: 'allkeys-lru'
});

// Worker pool setup
const workerPool = workerpool.createPool(path.join(__dirname, 'workers.js'), {
  minWorkers: 1,
  maxWorkers: 20,
  maxTasksPerWorker: 5
});

// Middleware for error handling
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

// Route to process shell commands
app.post('/process', async (req, res) => {
  const { command, outputFile, priority } = req.body;

  try {
    // Execute command asynchronously
    const result = await workerPool.exec('executeCommand', [command]);

    // Cache the result in Redis with TTL
    redisClient.setex(outputFile, 3600, JSON.stringify(result));

    res.send({ status: 'success', data: result });
  } catch (error) {
    console.error('Error processing command:', error);
    res.status(500).send({ status: 'error', message: 'Failed to process command' });
  }
});

// Route to fetch cached result
app.get('/result/:outputFile', async (req, res) => {
  const { outputFile } = req.params;

  try {
    // Retrieve cached result from Redis
    const cacheResult = await redisClient.get(outputFile);

    if (cacheResult) {
      const result = JSON.parse(cacheResult);
      res.send({ status: 'success', data: result });
    } else {
      res.status(404).send({ status: 'error', message: 'Cached result not found' });
    }
  } catch (error) {
    console.error('Error fetching cached result:', error);
    res.status(500).send({ status: 'error', message: 'Failed to fetch cached result' });
  }
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
