from threading import Lock

class NetworkProtocolManager:
    def __init__(self):
        self.protocols = {}
        self.lock = Lock()
        self.config = self.load_config()

    def load_config(self):
        # Load external configuration file
        config_path = "network_manager_config.yaml"
        if os.path.exists(config_path):
            with open(config_path, 'r') as file:
                return yaml.safe_load(file)
        else:
            return {}

    def discover_protocols(self):
        protocols_dir = "protocols"
        for filename in os.listdir(protocols_dir):
            if filename.endswith(".py"):
                protocol_name = filename[:-3]
                try:
                    module = importlib.import_module(f"protocols.{protocol_name}")
                    protocol_class = getattr(module, f"{protocol_name}Protocol")
                    self.register_protocol(protocol_name, protocol_class)
                except (ImportError, AttributeError) as e:
                    print(f"Failed to load {protocol_name}: {e}")

    def register_protocol(self, name, protocol):
        with self.lock:
            if name in self.protocols:
                print(f"Protocol {name} already registered.")
            else:
                self.protocols[name] = protocol
                print(f"Registered protocol: {name}")

    def get_protocol(self, name):
        with self.lock:
            return self.protocols.get(name, None)

    def execute_with_fallback(self, protocol_name, method_name, *args, **kwargs):
        protocol = self.get_protocol(protocol_name)
        if protocol:
            try:
                result = getattr(protocol, method_name)(*args, **kwargs)
                return result
            except Exception as e:
                print(f"Failed to execute {method_name} using {protocol_name}: {e}")
                # Fallback logic here
                pass
        else:
            print(f"No protocol found for {protocol_name}")

    def handle_api_failure(self, api_function):
        try:
            return api_function()
        except Exception as e:
            print(f"API call failed: {e}")
            # Handle API failure gracefully

    def log_message(self, level, message):
        if self.config.get("logging", {}).get(level, False):
            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            print(f"{timestamp} [{level.upper()}]: {message}")

# Example usage
if __name__ == "__main__":
    manager = NetworkProtocolManager()
    manager.discover_protocols()
    result = manager.execute_with_fallback("TwistedProtocol", "send_data", data="Hello, World!")
    manager.log_message("INFO", "Operation completed successfully.")
