typedef struct {
    pthread_mutex_t lock;
    unsigned char value_pool[1024 * 1024]; // 1MB pool
    size_t pool_size;
} RandomValueService;

RandomValueService* create_random_value_service() {
    RandomValueService* service = (RandomValueService*)malloc(sizeof(RandomValueService));
    if (!service) return NULL;

    pthread_mutex_init(&service->lock, NULL);
    service->pool_size = 0;
    return service;
}

void destroy_random_value_service(RandomValueService* service) {
    if (service) {
        pthread_mutex_destroy(&service->lock);
        free(service);
    }
}

void* generate_random_value(void* arg) {
    RandomValueService* service = (RandomValueService*)arg;

    pthread_mutex_lock(&service->lock);
    // Simplified example: just return the next byte from the pool
    unsigned char random_value = service->value_pool[service->pool_size++];
    pthread_mutex_unlock(&service->lock);

    return (void*)(long)random_value;
}

// Other functions and structures for handling concurrent requests, caching, logging, etc.

int main() {
    RandomValueService* service = create_random_value_service();

    // Simulate concurrent requests
    pthread_t threads[MAX_CONCURRENT_REQUESTS];
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        if (pthread_create(&threads[i], NULL, generate_random_value, (void*)service) != 0) {
            perror("Failed to create thread");
            return 1;
        }
    }

    // Join threads
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_random_value_service(service);
    return 0;
}
