#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_SEMAPHORES 100

typedef struct {
    sem_t semaphore;
    int initial_value;
    char type[50];
} Semaphore;

Semaphore semaphores[MAX_SEMAPHORES];
int semaphore_count = 0;
pthread_mutex_t semaphore_lock;
FILE *log_file;

void initialize_semaphore(char *type, int initial_value) {
    pthread_mutex_lock(&semaphore_lock);
    if (semaphore_count < MAX_SEMAPHORES) {
        semaphores[semaphore_count].initial_value = initial_value;
        sem_init(&semaphores[semaphore_count].semaphore, 0, initial_value);
        strncpy(semaphores[semaphore_count].type, type, sizeof(semaphores[semaphore_count].type));
        semaphore_count++;
    }
    pthread_mutex_unlock(&semaphore_lock);
}

int acquire_semaphore(char *type) {
    for (int i = 0; i < semaphore_count; i++) {
        if (strcmp(semaphores[i].type, type) == 0) {
            sem_wait(&semaphores[i].semaphore);
            return 1;
        }
    }
    return -1;
}

void release_semaphore(char *type) {
    for (int i = 0; i < semaphore_count; i++) {
        if (strcmp(semaphores[i].type, type) == 0) {
            sem_post(&semaphores[i].semaphore);
            return;
        }
    }
}

void log_usage(char *type) {
    pthread_mutex_lock(&semaphore_lock);
    fprintf(log_file, "Semaphore %s used\n", type);
    fflush(log_file);
    pthread_mutex_unlock(&semaphore_lock);
}

void cleanup() {
    for (int i = 0; i < semaphore_count; i++) {
        sem_destroy(&semaphores[i].semaphore);
    }
    fclose(log_file);
}

void *log_thread(void *arg) {
    while (1) {
        // Log usage statistics
        sleep(10);
    }
    return NULL;
}

int main() {
    pthread_t log_tid;
    pthread_mutex_init(&semaphore_lock, NULL);

    initialize_semaphore("critical", 5);
    initialize_semaphore("non_critical", 20);

    pthread_create(&log_tid, NULL, log_thread, NULL);

    // Simulate semaphore usage
    acquire_semaphore("critical");
    release_semaphore("critical");
    log_usage("critical");

    acquire_semaphore("non_critical");
    release_semaphore("non_critical");
    log_usage("non_critical");

    cleanup();
    pthread_join(log_tid, NULL);
    return 0;
}
