// Implementation of another logging framework (e.g., AMQP)
class AmqpLoggingFramework : public ILoggingFramework {
public:
    void log(const USER_ACTIVITY_LOG& log) override {
        // Log implementation using AMQP
    }
    void registerLogger(std::shared_ptr<Logger> logger) override {
        // Register logger with AMQP framework
    }
};

// Logger class managing logging frameworks and logs
class Logger {
private:
    std::vector<std::shared_ptr<ILoggingFramework>> frameworks;
    std::mutex logQueueMutex;
    std::condition_variable logCondition;
    std::queue<USER_ACTIVITY_LOG> logQueue;

public:
    void addFramework(std::shared_ptr<ILoggingFramework> framework) {
        frameworks.push_back(framework);
        framework->registerLogger(shared_from_this());
    }

    void log(const USER_ACTIVITY_LOG& log) {
        std::lock_guard<std::mutex> lock(logQueueMutex);
        logQueue.push(log);
        logCondition.notify_one();
    }

    void run() {
        while (true) {
            std::unique_lock<std::mutex> lock(logQueueMutex);
            logCondition.wait(lock, [this] { return !logQueue.empty(); });
            USER_ACTIVITY_LOG log = logQueue.front();
            logQueue.pop();
            lock.unlock();

            for (auto& framework : frameworks) {
                framework->log(log);
            }
        }
    }

    void handleError(const std::string& error) {
        // Error handling implementation
    }
};

int main() {
    Logger logger;

    // Create and add logging frameworks
    auto grpcFramework = std::make_shared<GrpcLoggingFramework>();
    auto amqpFramework = std::make_shared<AmqpLoggingFramework>();

    logger.addFramework(grpcFramework);
    logger.addFramework(amqpFramework);

    // Start the logger thread
    std::thread loggerThread(&Logger::run, &logger);
    loggerThread.detach();

    // Example log entry
    USER_ACTIVITY_LOG exampleLog = {
        "region1",
        "user123",
        "login"
    };

    logger.log(exampleLog);

    return 0;
}
