<?php

class UserService {
    private $identityProvider;
    private $loggingService;
    private $encryptionKey;
    private $encryptionIv;

    public function __construct($identityProvider, $loggingService) {
        $this->identityProvider = $identityProvider;
        $this->loggingService = $loggingService;
        $this->encryptionKey = openssl_random_pseudo_bytes(32);
        $this->encryptionIv = openssl_random_pseudo_bytes(openssl_cipher_iv_length('aes-256-cbc'));
    }

    public function handleRequest($request) {
        $data = json_decode($request, true);

        if (isset($data['id'])) {
            return $this->updateUser($data);
        } elseif ($data['action'] == 'delete') {
            return $this->deleteUser($data['id']);
        } else {
            return $this->createUser($data);
        }
    }

    private function createUser($data) {
        // Securely compute the MD5 hash of the uploaded profile picture
        $profilePictureHash = md5(file_get_contents($data['profile_picture_url']));

        // Encrypt the profile picture using AES-256-CBC
        $encryptedProfilePicture = openssl_encrypt(
            file_get_contents($data['profile_picture_url']),
            'aes-256-cbc',
            $this->encryptionKey,
            0,
            $this->encryptionIv
        );

        // Integrate with the identity provider for authentication
        $userId = $this->identityProvider->registerUser(
            $data['name'],
            $data['email'],
            password_hash($data['password'], PASSWORD_DEFAULT),
            $profilePictureHash
        );

        if ($userId) {
            // Log the user creation
            $this->loggingService->log('User created', [
                'user_id' => $userId,
                'name' => $data['name'],
                'email' => $data['email']
            ]);

            return json_encode(['status' => 'success', 'message' => 'User created']);
        } else {
            return json_encode(['status' => 'error', 'message' => 'Failed to create user']);
        }
    }

    private function updateUser($data) {
        // Securely compute the MD5 hash of the uploaded profile picture
        $profilePictureHash = md5(file_get_contents($data['profile_picture_url']));

        // Encrypt the profile picture using AES-256-CBC
        $encryptedProfilePicture = openssl_encrypt(
            file_get_contents($data['profile_picture_url']),
            'aes-256-cbc',
            $this->encryptionKey,
            0,
            $this->encryptionIv
        );

        // Integrate with the identity provider for authentication
        $result = $this->identityProvider->updateUser(
            $data['id'],
            $data['name'],
            $data['email'],
            password_hash($data['password'], PASSWORD_DEFAULT),
            $profilePictureHash,
            $encryptedProfilePicture
        );

        if ($result) {
            // Log the user update
            $this->loggingService->log('User updated', [
                'user_id' => $data['id'],
                'name' => $data['name'],
                'email' => $data['email']
            ]);

            return json_encode(['status' => 'success', 'message' => 'User updated']);
        } else {
            return json_encode(['status' => 'error', 'message' => 'Failed to update user']);
        }
    }

    private function deleteUser($id) {
        // Integrate with the identity provider for authentication
        $result = $this->identityProvider->deleteUser($id);

        if ($result) {
            // Log the user deletion
            $this->loggingService->log('User deleted', [
                'user_id' => $id
            ]);

            return json_encode(['status' => 'success', 'message' => 'User deleted']);
        } else {
            return json_encode(['status' => 'error', 'message' => 'Failed to delete user']);
        }
    }
}

