#define CACHE_SIZE 1024

typedef struct {
    time_t timestamp;
    int cell_identity;
    int power_level;
} TX_POWER_LEVEL_STATS;

TX_POWER_LEVEL_STATS power_stats[MAX_CIS];
TX_POWER_LEVEL_STATS cache[CACHE_SIZE];

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void update_power_stats(int ci, int power_level) {
    pthread_mutex_lock(&lock);
    time_t current_time = time(NULL);
    for (int i = 0; i < MAX_CIS; i++) {
        if (power_stats[i].cell_identity == ci) {
            power_stats[i] = (TX_POWER_LEVEL_STATS){current_time, ci, power_level};
            return;
        }
    }
    // Handle non-existent CI
    printf("CI %d does not exist\n", ci);
    pthread_mutex_unlock(&lock);
}

int get_latest_power_stats(int ci) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < MAX_CIS; i++) {
        if (power_stats[i].cell_identity == ci) {
            return power_stats[i].power_level;
        }
    }
    // Handle non-existent CI
    printf("CI %d does not exist\n", ci);
    pthread_mutex_unlock(&lock);
    return -1;
}

void *cache_eviction_thread(void *arg) {
    while (1) {
        sleep(60); // Evict every minute
        for (int i = 0; i < CACHE_SIZE; i++) {
            cache[i].cell_identity = -1; // Invalidate cache entries
        }
    }
    return NULL;
}

int main() {
    pthread_t eviction_thread_id;
    pthread_create(&eviction_thread_id, NULL, cache_eviction_thread, NULL);

    update_power_stats(12345, 70);
    printf("Latest power level for CI 12345: %d\n", get_latest_power_stats(12345));

    pthread_join(eviction_thread_id, NULL);
    return 0;
}
