#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CIs 1000000

typedef struct {
    time_t timestamp;
    int ci;
    int power_level;
} TX_POWER_LEVEL_STATS;

TX_POWER_LEVEL_STATS *power_stats[MAX_CIs];
pthread_mutex_t lock;

void initialize_library() {
    pthread_mutex_init(&lock, NULL);
}

int add_power_stat(int ci, int power_level) {
    pthread_mutex_lock(&lock);
    if (ci >= MAX_CIs || power_stats[ci] == NULL) {
        TX_POWER_LEVEL_STATS *new_stat = (TX_POWER_LEVEL_STATS *)malloc(sizeof(TX_POWER_LEVEL_STATS));
        if (new_stat == NULL) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&lock);
            return -1;
        }
        new_stat->timestamp = time(NULL);
        new_stat->ci = ci;
        new_stat->power_level = power_level;
        power_stats[ci] = new_stat;
    } else {
        power_stats[ci]->timestamp = time(NULL);
        power_stats[ci]->power_level = power_level;
    }
    pthread_mutex_unlock(&lock);
    return 0;
}

int update_power_stat(int ci, int power_level) {
    pthread_mutex_lock(&lock);
    if (ci >= MAX_CIs || power_stats[ci] == NULL) {
        pthread_mutex_unlock(&lock);
        return -1;
    }
    power_stats[ci]->timestamp = time(NULL);
    power_stats[ci]->power_level = power_level;
    pthread_mutex_unlock(&lock);
    return 0;
}

int get_latest_power_stat(int ci, TX_POWER_LEVEL_STATS *stat) {
    pthread_mutex_lock(&lock);
    if (ci >= MAX_CIs || power_stats[ci] == NULL) {
        pthread_mutex_unlock(&lock);
        return -1;
    }
    memcpy(stat, power_stats[ci], sizeof(TX_POWER_LEVEL_STATS));
    pthread_mutex_unlock(&lock);
    return 0;
}

void cleanup_library() {
    for (int i = 0; i < MAX_CIs; i++) {
        if (power_stats[i] != NULL) {
            free(power_stats[i]);
            power_stats[i] = NULL;
        }
    }
    pthread_mutex_destroy(&lock);
}
