import json
from typing import Dict, Any

def process_config(file_path: str) -> Dict[str, Any]:
    with open(file_path, 'r') as file:
        config = json.load(file)

    # Validate and sanitize inputs
    if not isinstance(config, dict):
        raise ValueError("Configuration must be a dictionary")

    if "server" not in config or "port" not in config["server"]:
        raise KeyError("Server configuration is missing port")

    # Implement rollback mechanism for critical configurations
    if config.get("features", {}).get("rollback"):
        if not os.path.exists(config["features"]["rollback_path"]):
            print(f"Rollback path {config['features']['rollback_path']} does not exist. Applying default settings.")
            config = load_default_config()

    return config

def load_default_config() -> Dict[str, Any]:
    # Load and return default configuration
    default_config = {
        "server": {
            "port": 8080,
            "host": "localhost"
        },
        "features": {}
    }
    return default_config

# Example usage
config_path = 'path/to/config.json'
try:
    config = process_config(config_path)
    print("Configuration processed successfully.")
except Exception as e:
    print(f"Error processing configuration: {e}")
