    for (int i = 0; i < num_workers; i++) {
        workers[i].id = i;
        snprintf(workers[i].url, sizeof(workers[i].url), "api%d.example.com", i);
    }

    pthread_t threads[num_workers];
    int thread_ids[num_workers];

    for (int i = 0; i < num_workers; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, fetch_data, &thread_ids[i]);
    }

    for (int i = 0; i < num_workers; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("All workers finished fetching data\n");

