#include <memory>
#include <chrono>

class DataStream {
public:
    virtual ~DataStream() = default;
    virtual void fetchData(std::function<void(const std::string&)> callback) = 0;
};

class SensorDataStream : public DataStream {
public:
    void fetchData(std::function<void(const std::string&)> callback) override {
        // Simulate fetching data from a sensor
        auto data = "SensorData";
        callback(data);
    }
};

class IOTDataStream : public DataStream {
public:
    void fetchData(std::function<void(const std::string&)> callback) override {
        // Simulate fetching data from an IoT device
        auto data = "IOTData";
        callback(data);
    }
};

class DataProcessor {
private:
    std::vector<std::unique_ptr<DataStream>> streams;
    std::queue<std::string> dataQueue;
    std::mutex queueMutex;
    std::condition_variable notEmpty;
    bool running;

public:
    DataProcessor() : running(true) {
        for (int i = 0; i < 200; ++i) {
            if (i % 2 == 0) streams.emplace_back(std::make_unique<SensorDataStream>());
            else streams.emplace_back(std::make_unique<IOTDataStream>());
        }
    }

    ~DataProcessor() {
        running = false;
        notEmpty.notify_all();
    }

    void startProcessing() {
        std::thread worker([this]() {
            while (running) {
                std::string data;
                {
                    std::unique_lock<std::mutex> lock(queueMutex);
                    notEmpty.wait(lock, [this] { return !dataQueue.empty() || !running; });
                    if (!running) break;
                    data = std::move(dataQueue.front());
                    dataQueue.pop();
                }
                process(data);
            }
        });
        worker.detach();
    }

    void addData(const std::string& data) {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            dataQueue.push(data);
        }
        notEmpty.notify_one();
    }

private:
    void process(const std::string& data) {
        // Simulate processing data
        std::cout << "Processing data: " << data << std::endl;
    }
};

int main() {
    DataProcessor processor;
    processor.startProcessing();

    for (int i = 0; i < 10; ++i) {
        auto data = "Data" + std::to_string(i);
        processor.addData(data);
    }

    // Simulate running for some time
    std::this_thread::sleep_for(std::chrono::seconds(5));

    return 0;
}
