typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* items;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* dynamicListCreate(size_t initialCapacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->items = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initialCapacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initialCapacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void dynamicListDestroy(DynamicList* list) {
    free(list->items);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

bool dynamicListAdd(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* newItems = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->items, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newItems) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
        list->items = newItems;
        list->capacity = newCapacity;
    }
    list->items[list->count++] = item;
    pthread_mutex_unlock(&list->lock);
    return true;
}

