        TextTransformationRule rule = getTransformationRule(language);
        if (rule == null) {
            throw new IllegalArgumentException("Unsupported language: " + language);
        }
        try {
            String transformedText = rule.apply(input);
            monitoringSystem.logRequestLatency(System.currentTimeMillis());
            return transformedText;
        } catch (Exception e) {
            monitoringSystem.logError(e);
            throw e;
        }
    }

    private TextTransformationRule getTransformationRule(String language) {
        TextTransformationRule rule = cacheStrategy.getFromCache(language);
        if (rule == null) {
            try {
                rule = configServer.fetchTransformationRule(language);
                if (rule != null) {
                    cacheStrategy.addToCache(language, rule);
                }
            } catch (Exception e) {
                monitoringSystem.logError(e);
                // Fallback to local default rules or throw exception
            }
        }
        return rule;
    }

    public void addCustomTransformationRule(String language, TextTransformationRule rule) {
        cacheStrategy.addToCache(language, rule);
        configServer.updateTransformationRule(language, rule);
    }

