// Function signature for processing user activities
using ActivityProcessor = std::function<void(const std::string&)>;

class UserActivityFeed {
public:
    UserActivityFeed(size_t numThreads) : stop(false), threadPool(numThreads, &UserActivityFeed::worker, this) {}

    ~UserActivityFeed() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& t : threadPool) {
            if (t.joinable()) {
                t.join();
            }
        }
    }

    void addActivity(const std::string& activity) {
        {
            std::unique_lock<std::mutex> lock(mutex);
            activities.push(activity);
        }
        condition.notify_one();
    }

private:
    bool stop;
    std::vector<std::thread> threadPool;
    std::queue<std::string> activities;
    std::mutex mutex;
    std::condition_variable condition;

    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return stop || !activities.empty(); });
            if (stop && activities.empty()) {
                break;
            }
            auto activity = activities.front();
            activities.pop();
            lock.unlock();

            // Process the activity
            processActivity(activity);
        }
    }

    void processActivity(const std::string& activity) {
        // Implement your processing logic here
        std::cout << "Processing activity: " << activity << std::endl;
    }
};

int main() {
    UserActivityFeed feed(4);

    // Simulate adding activities to the feed
    for (int i = 0; i < 10; ++i) {
        feed.addActivity("Activity " + std::to_string(i));
    }

    return 0;
}
