class ResourceThrottler {
    private Map<String, Integer> resourceUsage;
    private int maxResourceLimit;

    public ResourceThrottler(int maxResourceLimit) {
        this.resourceUsage = new ConcurrentHashMap<>();
        this.maxResourceLimit = maxResourceLimit;
    }

    public synchronized void acquireResource(ResourceRequirements requirements) throws ResourceExceededException {
        if (resourceUsage.getOrDefault(requirements.getType(), 0) + requirements.getAmount() > maxResourceLimit) {
            throw new ResourceExceededException("Insufficient resources");
        }
        resourceUsage.merge(requirements.getType(), requirements.getAmount(), Integer::sum);
    }

    public synchronized void releaseResource(ResourceRequirements requirements) {
        resourceUsage.merge(requirements.getType(), -requirements.getAmount(), (a, b) -> a + b);
    }
}

