#include <netdb.h>
#include <pthread.h>

#define MAX_HOSTNAMES 100
#define CONCURRENCY_THRESHOLD 5

typedef struct {
    int value;
} record;

long* offsets = NULL;
int* keys = NULL;
record* records = NULL;
int num_records = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_record_array(int size, int min_val, int max_val) {
    num_records = size;
    records = (record*)malloc(num_records * sizeof(record));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }
}

void* resolve_dns(void* arg) {
    char** hostnames = (char**)arg;
    int hostname_count = *(int*)hostnames[0];
    for (int i = 0; i < hostname_count; i++) {
        struct addrinfo hints, *res;
        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
        hints.ai_socktype = SOCK_STREAM;

        int status = getaddrinfo(hostnames[i + 1], NULL, &hints, &res);
        if (status != 0) {
            fprintf(stderr, "DNS resolution failed for %s: %s\n", hostnames[i + 1], gai_strerror(status));
            continue;
        }

        freeaddrinfo(res); // Free the linked list
    }
    return NULL;
}

void process_hostnames(char** hostnames, int hostname_count) {
    pthread_t threads[MAX_HOSTNAMES];
    for (int i = 0; i < hostname_count / CONCURRENCY_THRESHOLD; i++) {
        int start = i * CONCURRENCY_THRESHOLD;
        int end = (i + 1) * CONCURRENCY_THRESHOLD;
        if (end > hostname_count) {
            end = hostname_count;
        }

        pthread_create(&threads[i], NULL, resolve_dns, &hostnames[start]);
    }

    for (int i = 0; i < hostname_count / CONCURRENCY_THRESHOLD; i++) {
        pthread_join(threads[i], NULL);
    }
}

void cleanup() {
    free(offsets);
    free(keys);
    free(records);
}

// Unit tests to be implemented
