#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RNTI 65535

typedef struct {
    uint16_t RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    SUCCESS,
    INVALID_INPUT,
    ALLOCATION_FAILURE,
    DATA_SOURCE_ERROR
} NFAPI_STATUS_E;

NFAPI_STATUS_E generate_NFAPI_PDUs(uint32_t N, uint32_t seed, void (*log_callback)(NFAPI_CRC_INDICATION_PDU_T*), NFAPI_CRC_INDICATION_PDU_T** PDUs) {
    if (N == 0 || seed < 0 || !PDUs) {
        return INVALID_INPUT;
    }

    srand(seed);
    NFAPI_CRC_INDICATION_PDU_T* PDU_array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!PDU_array) {
        return ALLOCATION_FAILURE;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    for (uint32_t i = 0; i < N; ++i) {
        uint16_t RNTI;
        do {
            RNTI = rand() % (MAX_RNTI + 1);
        } while (RNTI == 0); // Ensure RNTI is not zero

        PDU_array[i].RNTI = RNTI;
        PDU_array[i].CRCFLAG = (rand() % 2) ? true : false;

        if (log_callback) {
            log_callback(&PDU_array[i]);
        }
    }

    pthread_mutex_unlock(&mutex);

    *PDUs = PDU_array;
    return SUCCESS;
}

void log_PDU(NFAPI_CRC_INDICATION_PDU_T* PDU) {
    printf("RNTI: %d, CRCFLAG: %d\n", PDU->RNTI, PDU->CRCFLAG);
}

int main() {
    uint32_t N = 100;
    uint32_t seed = time(NULL);
    NFAPI_CRC_INDICATION_PDU_T* PDUs;

    NFAPI_STATUS_E status = generate_NFAPI_PDUs(N, seed, log_PDU, &PDUs);
    if (status != SUCCESS) {
        printf("Error: %d\n", status);
        return 1;
    }

    for (uint32_t i = 0; i < N; ++i) {
        printf("PDU %d - RNTI: %d, CRCFLAG: %d\n", i, PDUs[i].RNTI, PDUs[i].CRCFLAG);
    }

    free(PDUs);
    return 0;
}
