#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_ELEMENTS 5000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data;
    int ref_count;
} Element;

typedef struct {
    Element* elements;
    int size;
    int capacity;
    sem_t lock;
    pthread_mutex_t gc_lock;
} CRCList;

CRCList* create_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->elements = (Element*)calloc(MAX_ELEMENTS, sizeof(Element));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = MAX_ELEMENTS;
    sem_init(&list->lock, 0, 1);
    pthread_mutex_init(&list->gc_lock, NULL);

    return list;
}

void destroy_crc_list(CRCList* list) {
    if (!list) return;

    for (int i = 0; i < list->size; ++i) {
        free(list->elements[i].data.RX_UE_INFORMATION_TAG);
    }

    sem_destroy(&list->lock);
    pthread_mutex_destroy(&list->gc_lock);
    free(list->elements);
    free(list);
}

void add_element(CRCList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    sem_wait(&list->lock);

    if (list->size == list->capacity) {
        // Resize logic here
    }

    list->elements[list->size].data = data;
    list->elements[list->size].ref_count = 1;
    ++(list->size);

    sem_post(&list->lock);
}

void remove_element(CRCList* list, int index) {
    sem_wait(&list->lock);

    if (index < 0 || index >= list->size) return;

    free(list->elements[index].data.RX_UE_INFORMATION_TAG);
    for (int i = index; i < list->size - 1; ++i) {
        list->elements[i] = list->elements[i + 1];
    }
    --(list->size);

    sem_post(&list->lock);
}

void* crc_list_thread(void* arg) {
    CRCList* list = (CRCList*)arg;
    // Thread logic here
    return NULL;
}

int main() {
    CRCList* list = create_crc_list();
    if (!list) return -1;

    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, crc_list_thread, list);
    pthread_create(&thread2, NULL, crc_list_thread, list);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    destroy_crc_list(list);
    return 0;
}
