// Include necessary headers
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <functional>
#include <chrono>

// Define a class for the sensor data stream processor
class SensorDataStreamProcessor {
public:
    // Constructor
    SensorDataStreamProcessor(size_t maxThreads = std::thread::hardware_concurrency()) 
        : stop(false), numRunning(0) {
        for (size_t i = 0; i < maxThreads; ++i) {
            workers.emplace_back([this]() { worker(); });
        }
    }

    // Destructor
    ~SensorDataStreamProcessor() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    // Function to add a new data stream task
    void addTask(std::function<void()> task) {
        {
            std::unique_lock<std::mutex> lock(mutex);
            tasks.push(task);
        }
        condition.notify_one();
    }

    // Function to check if the processor is running
    bool isRunning() const {
        return numRunning > 0;
    }

private:
    void worker() {
        while (true) {
            std::function<void()> task;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this]() { return stop || !tasks.empty(); });
                if (stop && tasks.empty()) {
                    break;
                }
                task = std::move(tasks.front());
                tasks.pop();
                ++numRunning;
            }
            task();
            {
                std::unique_lock<std::mutex> lock(mutex);
                --numRunning;
            }
        }
    }

    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::mutex mutex;
    std::condition_variable condition;
    bool stop;
    size_t numRunning;
};

// Example usage
int main() {
    SensorDataStreamProcessor processor;

    // Add tasks to the processor
    for (size_t i = 0; i < 1000; ++i) {
        processor.addTask([i]() {
            std::cout << "Processing task " << i << std::endl;
        });
    }

    // Wait for all tasks to complete
    while (processor.isRunning()) {
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }

    return 0;
}
