typedef struct {
    time_t timestamp;
    int ci;
    float power_level;
} TX_POWER_LEVEL_STATS;

TX_POWER_LEVEL_STATS tx_power_stats[MAX_TX_POWER_LEVEL_STATS];
int stats_count = 0;
pthread_mutex_t mutex;

void init_module() {
    pthread_mutex_init(&mutex, NULL);
}

TX_POWER_LEVEL_STATS* get_tx_power_stats_by_ci(int ci) {
    for (int i = 0; i < stats_count; i++) {
        if (tx_power_stats[i].ci == ci) {
            return &tx_power_stats[i];
        }
    }
    return NULL;
}

void add_update_tx_power_stats(TX_POWER_LEVEL_STATS new_stats) {
    pthread_mutex_lock(&mutex);
    TX_POWER_LEVEL_STATS* existing_stats = get_tx_power_stats_by_ci(new_stats.ci);
    if (existing_stats != NULL) {
        *existing_stats = new_stats;
    } else {
        tx_power_stats[stats_count++] = new_stats;
    }
    pthread_mutex_unlock(&mutex);
}

char* append_slash(char* str, size_t max_len) {
    if (strlen(str) < max_len - 1) {
        strcat(str, "/");
        return str;
    }
    return NULL;
}

// Unit tests
#include <assert.h>

void test_get_tx_power_stats_by_ci() {
    TX_POWER_LEVEL_STATS stats = {time(NULL), 12345, 20.5};
    add_update_tx_power_stats(stats);
    assert(get_tx_power_stats_by_ci(12345)->ci == 12345);
}

void test_append_slash() {
    char str[] = "log_entry";
    assert(append_slash(str, sizeof(str)) != NULL && strcmp(str, "log_entry/") == 0);
    assert(append_slash(str, 7) == NULL); // No space for slash
}

int main() {
    init_module();
    test_get_tx_power_stats_by_ci();
    test_append_slash();
