package com.networklatencymanager;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;

public class NetworkLatencyManager {
    private final ConcurrentHashMap<String, Integer> bandwidthLimits = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, AtomicInteger> currentBandwidthUsage = new ConcurrentHashMap<>();

    public void setBandwidthLimit(String serviceId, int limit) {
        bandwidthLimits.put(serviceId, limit);
        currentBandwidthUsage.putIfAbsent(serviceId, new AtomicInteger(0));
    }

    public boolean allocateBandwidth(String serviceId, int amount) {
        AtomicInteger usage = currentBandwidthUsage.get(serviceId);
        if (usage == null) {
            return false;
        }
        synchronized (usage) {
            int remaining = bandwidthLimits.getOrDefault(serviceId, 0) - usage.get();
            if (remaining >= amount) {
                usage.addAndGet(amount);
                return true;
            }
        }
        return false;
    }

    public boolean releaseBandwidth(String serviceId, int amount) {
        AtomicInteger usage = currentBandwidthUsage.get(serviceId);
        if (usage == null) {
            return false;
        }
        synchronized (usage) {
            usage.addAndGet(-amount);
            if (usage.get() < 0) {
                usage.set(0); // Ensure non-negative usage
            }
        }
        return true;
    }

    public void monitorNetworkHealth(String serviceId, Consumer<String> onFailover) {
        AtomicInteger usage = currentBandwidthUsage.get(serviceId);
        if (usage == null) {
            return;
        }
        synchronized (usage) {
            int limit = bandwidthLimits.getOrDefault(serviceId, 0);
            if (limit > 0 && usage.get() >= limit) {
                onFailover.accept("Service " + serviceId + " is experiencing network latency issues. Initiating failover.");
                // Implement failover logic here
            }
        }
    }

    public void integrateWithKubernetes(String namespace, String serviceName) {
        // Integrate with Kubernetes API to manage network resources and monitor service health
    }
}
