void NetworkedImageDownloader::DownloadImageAsync(const std::string& imageUrl, const std::string& cachePath) {
    std::lock_guard<std::mutex> lock(cacheMutex);
    auto it = imageCache.find(imageUrl);

    if (it == imageCache.end()) {
        ImageCacheEntry entry;
        entry.downloadFuture = std::async(std::launch::async, &NetworkedImageDownloader::BackgroundDownload, this, imageUrl, cachePath);
        imageCache[imageUrl] = entry;
    } else {
        // Handle cache hit and possibly download again if not already cached
    }
}

