#include <curl/curl.h>

// Define constants
#define MAX_FILENAME_LENGTH 256
#define RETRY_COUNT 3

// Define error codes
typedef enum {
    FILENAME_OK,
    FILENAME_INVALID,
    NETWORK_ERROR,
    SERVICE_TIMEOUT,
    OTHER_ERROR
} ErrorCode;

// Define file type enumeration
typedef enum {
    TXT_FILE,
    LOG_FILE,
    CFG_FILE
} FileType;

// Function declarations
int validate_filename(const char *filename);
FileType determine_file_type(const char *filename);
void process_filename_thread(void *arg);

// Main function to process filename
ErrorCode process_filename(const char *filename, char **new_filename) {
    if (strlen(filename) > MAX_FILENAME_LENGTH) {
        return FILENAME_INVALID;
    }

    if (!validate_filename(filename)) {
        return FILENAME_INVALID;
    }

    FileType type = determine_file_type(filename);
    asprintf(new_filename, "%s.%s", filename, get_extension_from_type(type));
    return FILENAME_OK;
}

// Function to validate filename using external metadata service
int validate_filename(const char *filename) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        // Set URL and other options for the request
        curl_easy_setopt(curl, CURLOPT_URL, "http://metadata-service/validate");
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");
        headers = curl_slist_append(headers, "filename: ");
        headers = curl_slist_append(headers, filename);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        // Perform the request and check for errors
        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            printf("curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return 0;
        }

        // Clean up
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return 1;
}

// Function to determine file type based on filename content
FileType determine_file_type(const char *filename) {
    int contains_digit = 0, contains_alpha = 0;

    for (int i = 0; filename[i]; i++) {
        if (isdigit(filename[i])) contains_digit = 1;
        if (isalpha(filename[i])) contains_alpha = 1;
    }

    if (contains_digit && contains_alpha) return CFG_FILE;
    if (contains_digit) return TXT_FILE;
    return LOG_FILE;
}

// Function to get file extension based on type
const char* get_extension_from_type(FileType type) {
    switch(type) {
        case TXT_FILE: return "txt";
        case LOG_FILE: return "log";
        case CFG_FILE: return "cfg";
        default: return "";
    }
}

// Thread function for processing filenames concurrently
void process_filename_thread(void *arg) {
    char **filename_list = (char **)arg;
    for (int i = 0; filename_list[i] != NULL; i++) {
        char *new_filename = NULL;
        ErrorCode result = process_filename(filename_list[i], &new_filename);
        if (result == FILENAME_OK) {
            printf("Processed %s to %s\n", filename_list[i], new_filename);
            free(new_filename);
        } else {
            printf("Error processing %s\n", filename_list[i]);
        }
    }
}

// Example usage
int main() {
    char *filenames[] = {"example1.txt", "example2.log", "example3.cfg", "invalidfile", NULL};
    pthread_t thread_id;

    pthread_create(&thread_id, NULL, process_filename_thread, filenames);
    pthread_join(thread_id, NULL);

    return 0;
}
```

