#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <future>
#include <chrono>

class TransactionQueue {
    std::queue<int> transactions;
    std::mutex mtx;
    std::condition_variable cv;
    size_t max_size;

public:
    TransactionQueue(size_t size) : max_size(size) {}

    void enqueue(int transaction_id) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return transactions.size() < max_size; });
        transactions.push(transaction_id);
    }

    int dequeue() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return !transactions.empty(); });
        int transaction_id = transactions.front();
        transactions.pop();
        return transaction_id;
    }

    bool try_enqueue(int transaction_id) {
        std::unique_lock<std::mutex> lock(mtx);
        if (transactions.size() >= max_size)
            return false;
        transactions.push(transaction_id);
        cv.notify_one();
        return true;
    }
};

class FSAState {
public:
    int state_id;
    // Other state properties
};

class StateManager {
private:
    std::vector<FSAState> states;
    TransactionQueue transaction_queue;

public:
