        DEVICE_STATUS_RECORD record = {deviceId, 0.0, 0.0, 100, true};
        return record;
    }
};

// Device Manager Class
class DeviceManager {
public:
    DeviceManager(IGPSProvider* gpsProvider, ICloudStorageProvider* cloudStorage)
        : gpsProvider(gpsProvider), cloudStorage(cloudStorage) {}

    void Start() {
        // Initialize threads for handling real-time updates and storage
        updateThread = std::thread(&DeviceManager::UpdateLoop, this);
        storageThread = std::thread(&DeviceManager::StorageLoop, this);
    }

    void Stop() {
        stopFlag = true;
        updateCond.notify_all();
        storageCond.notify_all();
        if (updateThread.joinable()) updateThread.join();
        if (storageThread.joinable()) storageThread.join();
    }

private:
    std::mutex deviceMutex;
    std::map<int, DEVICE_STATUS_RECORD> deviceStatusMap;

    IGPSProvider* gpsProvider;
    ICloudStorageProvider* cloudStorage;

    std::atomic<bool> stopFlag = false;
    std::condition_variable updateCond;
    std::condition_variable storageCond;
    std::thread updateThread, storageThread;

    void UpdateLoop() {
        while (!stopFlag) {
            // Wait for new updates
            std::unique_lock<std::mutex> lock(deviceMutex);
            updateCond.wait(lock);

            // Process and save device status
            for (auto& pair : deviceStatusMap) {
                gpsservice.UpdateDeviceStatus(pair.first, pair.second);
            }
        }
    }

    void StorageLoop() {
        while (!stopFlag) {
            // Wait for storage tasks
            std::unique_lock<std::mutex> lock(deviceMutex);
            storageCond.wait(lock);

            // Save device status to cloud storage
            for (auto& pair : deviceStatusMap) {
                if (cloudStorage->SaveDeviceStatus(pair.first, pair.second)) {
                    // Update local copy with saved data
                    deviceStatusMap[pair.first] = cloudStorage->LoadDeviceStatus(pair.first);
                }
            }
        }
    }

public:
    void AddOrUpdateDeviceStatus(int deviceId, const DEVICE_STATUS_RECORD& record) {
        std::lock_guard<std::mutex> lock(deviceMutex);
        deviceStatusMap[deviceId] = record;
        updateCond.notify_one();
    }

    DEVICE_STATUS_RECORD GetDeviceStatus(int deviceId) {
        std::lock_guard<std::mutex> lock(deviceMutex);
        return deviceStatusMap[deviceId];
    }
};

// Example usage
int main() {
    GPSService gpsService;
    CloudStorage cloudStorage;
    DeviceManager deviceManager(&gpsService, &cloudStorage);

    deviceManager.Start();

    // Simulate adding/updating and retrieving device status
    DEVICE_STATUS_RECORD record = {1, 40.7128, -74.0060, 50, true};
    deviceManager.AddOrUpdateDeviceStatus(1, record);
    std::cout << "Device Status: " << deviceManager.GetDeviceStatus(1).batteryPercentage << "%" << std::endl;

    deviceManager.Stop();
    return 0;
}
