#include <iostream>
#include <fstream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <curl/curl.h>
#include "nlohmann/json.hpp"
#include "csv_parser.h"

using json = nlohmann::json;

class CSVProcessor {
public:
    CSVProcessor(const std::string& input_file, const std::string& output_file, const std::string& config_file, int verbosity)
        : input_file(input_file), output_file(output_file), config_file(config_file), verbosity(verbosity) {}

    void run() {
        // Load configuration
        load_config();

        // Initialize API client
        api_client.init(api_key, api_endpoint);

        // Create worker threads
        std::vector<std::thread> workers(num_threads);
        for (auto& thread : workers) {
            thread = std::thread(&CSVProcessor::process_files, this);
        }

        // Join worker threads
        for (auto& thread : workers) {
            if (thread.joinable()) {
                thread.join();
            }
        }

        // Write results to output file
        write_output(results);
    }

private:
    void load_config() {
        std::ifstream config(config_file);
        config >> config_data;
        api_key = config_data["api_key"];
        api_endpoint = config_data["api_endpoint"];
        num_threads = config_data["num_threads"];
        retry_attempts = config_data["retry_attempts"];
        timeout_seconds = config_data["timeout_seconds"];
        verbosity = config_data["verbosity"];
    }

    void process_files() {
        std::unique_lock<std::mutex> lock(queue_mutex);
        while (true) {
            cv.wait(lock, [this] { return !input_queue.empty() || shutdown; });
            if (shutdown && input_queue.empty()) {
                break;
            }
            std::string file_path = input_queue.front();
            input_queue.pop();
            lock.unlock();

            try {
                process_file(file_path);
            } catch (const std::exception& e) {
                if (verbosity > 0) {
                    std::cerr << "Error processing file: " << e.what() << std::endl;
                }
            }

            lock.lock();
        }
    }

    void process_file(const std::string& file_path) {
        // Parse CSV file
        CSVParser parser(file_path, schema);
        while (parser.has_next()) {
            json row = parser.next();

            // Validate against external API
            for (const auto& field : validation_fields) {
                if (!api_client.validate(row[field])) {
                    throw std::runtime_error("Validation failed for field: " + field);
                }
            }

            // Process and store results
            results.push_back(row);
        }

        if (verbosity > 1) {
            std::cout << "Processed file: " << file_path << std::endl;
        }
    }

    void write_output(const std::vector<json>& results) {
        std::ofstream output(output_file);
        output << json(results).dump(4);
        if (verbosity > 0) {
            std::cout << "Output written to: " << output_file << std::endl;
        }
    }

    std::string input_file, output_file, config_file;
