public class EventProcessor
{
    private readonly ConcurrentQueue<Event> _eventQueue = new ConcurrentQueue<Event>();
    private readonly HttpClient _httpClient;
    private readonly string _databaseConnectionString;
    private readonly int _maxConcurrencyLevel;

    public EventProcessor(HttpClient httpClient, string databaseConnectionString, int maxConcurrencyLevel)
    {
        _httpClient = httpClient;
        _databaseConnectionString = databaseConnectionString;
        _maxConcurrencyLevel = maxConcurrencyLevel;
    }

    public async Task ProcessRealtimeEventsAsync()
    {
        var tasks = new List<Task>(_maxConcurrencyLevel);

        for (int i = 0; i < _maxConcurrencyLevel; i++)
        {
            tasks.Add(ProcessEventsAsync());
        }

        await Task.WhenAll(tasks);
    }

    private async Task ProcessEventsAsync()
    {
        while (true)
        {
            if (!_eventQueue.TryDequeue(out Event @event))
                continue;

            try
            {
                await HandleEventAsync(@event);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing event: {ex.Message}");
                // Log the exception with context-specific details
            }
        }
    }

    private async Task HandleEventAsync(Event @event)
    {
        using (var connection = new SqlConnection(_databaseConnectionString))
        {
            await connection.OpenAsync();
            var commandText = "UPDATE Events SET Status = @Status WHERE Id = @Id";
            using (var command = new SqlCommand(commandText, connection))
            {
                command.Parameters.AddWithValue("@Status", @event.Status);
                command.Parameters.AddWithValue("@Id", @event.Id);
                await command.ExecuteNonQueryAsync();
            }
        }

        var response = await _httpClient.GetAsync($"https://api.example.com/events/{@event.Id}");
        if (response.IsSuccessStatusCode)
        {
            // Process API response
        }
    }
}

public class Event
{
    public int Id { get; set; }
    public string Status { get; set; }
}
