        var cachedData = await _cacheManager.GetCachedWeatherAsync(location);
        if (cachedData != null)
        {
            return cachedData;
        }

        var apiPolicy = Policy
            .Handle<HttpRequestException>()
            .Or<TaskCanceledException>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

        foreach (var api in _weatherApis.OrderBy(api => GetApiPriority(api)))
        {
            try
            {
                var data = await apiPolicy.ExecuteAsync(async () => await FetchWeatherFromApiAsync(api, location));
                if (data != null)
                {
                    _cacheManager.CacheWeatherData(data);
                    return data;
