const express = require('express');
const fs = require('fs');
const path = require('path');
const os = require('os');
const { Worker, isMainThread, parentPort } = require('worker_threads');
const axios = require('axios');
const rateLimit = require('express-rate-limit');
const Redis = require('ioredis');

const app = express();
const redisClient = new Redis();

// Configuration
const maxConcurrentFiles = 100;
const allowedFileExtensions = ['.jpg', '.png', '.txt'];
const fileSizeWhitelist = [1 * 1024 * 1024, 5 * 1024 * 1024]; // 1MB and 5MB
const rateLimitConfig = {
  windowMs: 15 * 60 * 1000,
  max: 100,
};

// Middleware
app.use(express.json());
app.use(rateLimit(rateLimitConfig));

// Routes
app.post('/process', async (req, res) => {
  const { directory } = req.body;

  if (!directory || !Array.isArray(allowedFileExtensions)) {
    return res.status(400).json({ error: 'Invalid input' });
  }

  try {
    await redisClient.set('processing_queue', JSON.stringify([]));
    const files = await fs.promises.readdir(directory);
    const filteredFiles = files.filter(file => allowedFileExtensions.includes(path.extname(file)));

    if (filteredFiles.length === 0) {
      return res.status(204).json({ message: 'No files to process' });
    }

    const queue = JSON.parse(await redisClient.get('processing_queue'));
    queue.push(...filteredFiles);
    await redisClient.set('processing_queue', JSON.stringify(queue));

    // Start workers
    for (let i = 0; i < maxConcurrentFiles && i < filteredFiles.length; i++) {
      new Worker(path.resolve(__dirname, 'worker.js'), { workerData: filteredFiles[i] });
    }

    res.status(202).json({ message: 'Processing started' });
  } catch (error) {
    console.error('Error processing files:', error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// Worker process
if (!isMainThread) {
  const file = workerData;
  try {
    const filePath = path.resolve(__dirname, `../${file}`);
    const fileSize = await fs.promises.stat(filePath).then(fileStat => fileStat.size);

    if (fileSizeWhitelist.includes(fileSize)) {
      // Perform processing
      console.log(`Processing file: ${file}`);
      await axios.get('https://metadata-service.com/check', { responseType: 'json' });
      await new Promise(resolve => setTimeout(resolve, 1000)); // Simulate processing time

      // Save processed file
      const archivePath = path.resolve(__dirname, `../processed_${file}`);
      await fs.promises.rename(filePath, archivePath);
      console.log(`Processed and archived: ${file}`);
    } else {
      console.log(`File size exceeds limit: ${file}`);
    }
  } catch (error) {
    console.error(`Error processing file ${file}:`, error);
    // Retry logic here
  }
}

// Start server
app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
```

