const processTransactionStream = async (transactions) => {
  const whitelist = ['https://trusteddomain.com', 'https://anothertrusteddomain.com'];

  const loadScript = async (src, key) => {
    return new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = src;
      script.async = true;

      script.onload = () => resolve(script);
      script.onerror = () => reject(new Error(`Failed to load script ${key}: ${src}`));

      document.body.appendChild(script);
    });
  };

  const validateTransaction = (transaction) => {
    if (!transaction || !transaction.key) {
      console.warn('Missing key in transaction');
      return false;
    }

    if (!transaction.src) {
      console.warn('Missing src in transaction');
      return false;
    }

    if (!whitelist.includes(transaction.src)) {
      console.warn(`Invalid domain ${transaction.src} for transaction key: ${transaction.key}`);
      return false;
    }

    if (!transaction.payload) {
      console.warn('Missing payload in transaction');
      transaction.payload = {}; // Fallback
    }

    return true;
  };

  const processTransactions = async () => {
    for (const transaction of transactions) {
      if (validateTransaction(transaction)) {
        try {
          await loadScript(transaction.src, transaction.key);
          console.log(`Successfully loaded script ${transaction.key}`);
        } catch (error) {
          console.error(error);
          // Retry logic here
        }
      }
    }
  };

  processTransactions();
};

// Example usage:
const transactions = [
  { key: 'script1', src: 'https://trusteddomain.com/script.js', timestamp: Date.now(), payload: {} },
  { key: 'script2', src: 'https://untrusteddomain.com/script.js', timestamp: Date.now(), payload: {} }
];

processTransactionStream(transactions);
```

