const path = require('path');

class ThemeCacheModule {
  constructor(cacheDir = './theme_cache') {
    this.cacheDir = cacheDir;
    this.cache = new Map();
    this.retryAttempts = 0;
    this.maxRetries = 5;
    this.retryDelay = 1000; // Initial delay in milliseconds
  }

  async loadTheme(url) {
    try {
      const cachedData = this.getCachedData(url);
      if (cachedData) {
        return cachedData;
      } else {
        let imageData = await axios.get(url, { responseType: 'arraybuffer' });
        imageData = Buffer.from(imageData.data, 'binary');
        this.cache.set(url, imageData);
        this.saveToCache(url, imageData);
        return imageData;
      }
    } catch (error) {
      if (this.retryAttempts < this.maxRetries) {
        await this.exponentialBackoff();
        return this.loadTheme(url);
      } else {
        throw error;
      }
    }
  }

  getCachedData(url) {
    return this.cache.get(url) || null;
  }

  saveToCache(url, data) {
    fs.writeFileSync(path.join(this.cacheDir, path.basename(url)), data);
  }

  async exponentialBackoff() {
    return new Promise(resolve => setTimeout(resolve, this.retryDelay));
  }
}

// Usage example
const themeModule = new ThemeCacheModule();
themeModule.loadTheme('https://example.com/theme.png')
  .then(imageData => console.log('Theme loaded:', imageData))
  .catch(error => console.error('Failed to load theme:', error));
