class Device(ABC):
    @abstractmethod
    def discover(self):
        pass

    @abstractmethod
    def connect(self):
        pass

    @abstractmethod
    def collect_metrics(self):
        pass

    @abstractmethod
    def send_alert(self, message):
        pass

class CiscoDevice(Device):
    def discover(self):
        # Implement discovery logic for Cisco devices
        pass

    def connect(self):
        # Implement connection logic using SSH
        client = paramiko.SSHClient()
        client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        client.connect('cisco_device_ip', username='admin', password='password')
        return client

    def collect_metrics(self, client):
        # Implement metric collection for Cisco devices
        stdin, stdout, stderr = client.exec_command('show ip interface brief')
        output = stdout.read().decode()
        metrics = parse_output(output)
        return metrics

    def send_alert(self, message):
        # Implement alert sending logic using MQTT
        client = mqtt.Client()
        client.connect("mqtt_broker_address", 1883, 60)
        client.publish("cisco/alerts", json.dumps({"timestamp": datetime.now(), "message": message}))
        client.disconnect()

