#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void generate_NFAPI_PDUs(int N, int seed, void (*callback)(NFAPI_CRC_INDICATION_PDU_T* pdu)) {
    srand(seed);
    int rntiPool[1000]; // Example pool of RNTIs
    for (int i = 0; i < 1000; i++) {
        rntiPool[i] = rand() % 1000;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    for (int i = 0; i < N; i++) {
        int rntiIndex;
        do {
            rntiIndex = rand() % 1000;
        } while (rntiPool[rntiIndex] == -1); // Ensure no duplicates

        pdus[i].RX_UE_INFORMATION_TAG = rand();
        pdus[i].RNTI = rntiPool[rntiIndex];
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
        rntiPool[rntiIndex] = -1; // Mark as used

        if (callback) {
            callback(&pdus[i]);
        }
    }

    free(pdus);
}

void logPDU(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
           pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG);
}

int main() {
    generate_NFAPI_PDUs(5, time(NULL), logPDU);
    return 0;
}
