NFAPI_CRC_INDICATION_PDU_T pdu_pool[MAX_PDUS];
int available_pdus = MAX_PDUS;
pthread_mutex_t pool_lock;

void init_pdu_pool() {
    pthread_mutex_init(&pool_lock, NULL);
}

int allocate_pdu(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&pool_lock);
    if (available_pdus > 0) {
        available_pdus--;
        NFAPI_CRC_INDICATION_PDU_T *pdu = &pdu_pool[available_pdus];
        pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
