NFAPI_CRC_INDICATION_PDU_T *pool[MAX_PDUS];
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
int next_available_index = 0;

void initialize_pool() {
    for (int i = 0; i < MAX_PDUS; i++) {
        pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pool[i]) {
            // Handle memory allocation failure
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T *allocate_pdu() {
    pthread_mutex_lock(&pool_lock);
    if (next_available_index == MAX_PDUS) {
        pthread_mutex_unlock(&pool_lock);
        return NULL; // Pool is full
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = pool[next_available_index];
    next_available_index++;
    pthread_mutex_unlock(&pool_lock);

    // Initialize the PDU with unique values and a random CRCFLAG
    pdu->RX_UE_INFORMATION_TAG = generate_unique_tag();
    pdu->RNTI = generate_rnti_value();
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG

    return pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < MAX_PDUS; i++) {
        if (pool[i] == pdu) {
            pool[i] = NULL;
            next_available_index = i + 1;
            break;
        }
    }
    pthread_mutex_unlock(&pool_lock);
}

// Helper functions to generate unique tags and RNTI values
int generate_unique_tag() {
    static int tag_counter = 0;
    return tag_counter++;
}

int generate_rnti_value() {
    static int rnti_counter = 1;
    return rnti_counter++;
