class TX_DATA_BUFFER {
public:
    uint64_t TX_STREAM_ID;
    uint32_t SEQUENCE_NUMBER;
    int TRANSMISSION_POWER_LEVEL;

    TX_DATA_BUFFER(uint64_t stream_id, uint32_t sequence_number, int power_level)
        : TX_STREAM_ID(stream_id), SEQUENCE_NUMBER(sequence_number), TRANSMISSION_POWER_LEVEL(power_level) {}
};

class BufferPool {
public:
    BufferPool(size_t capacity) : pool(capacity), next_index(0), available_buffers(capacity) {}

    std::shared_ptr<TX_DATA_BUFFER> allocate() {
        std::unique_lock<std::mutex> lock(mutex);
        if (available_buffers.empty()) {
            available_buffers.push_back(std::make_shared<TX_DATA_BUFFER>(0, 0, 0));
        }
        auto buffer = available_buffers.front();
        available_buffers.pop_front();
        return buffer;
    }

    void deallocate(const std::shared_ptr<TX_DATA_BUFFER>& buffer) {
        std::unique_lock<std::mutex> lock(mutex);
        available_buffers.push_back(buffer);
    }

private:
    std::vector<std::shared_ptr<TX_DATA_BUFFER>> pool;
    size_t next_index;
    std::queue<std::shared_ptr<TX_DATA_BUFFER>> available_buffers;
    std::mutex mutex;
};

class NMSIntegrator {
public:
    virtual void reportBufferState(const TX_DATA_BUFFER& buffer) = 0;
    virtual void controlBufferFlow(bool enable) = 0;
};

class NMSIntegratorImpl : public NMSIntegrator {
public:
    void reportBufferState(const TX_DATA_BUFFER& buffer) override {
        // Implement reporting logic
    }

    void controlBufferFlow(bool enable) override {
        // Implement flow control logic
    }
};

class BufferManager {
public:
    BufferManager(size_t capacity, std::shared_ptr<NMSIntegrator> nms)
        : pool(capacity), nms(nms), stopped(false) {}

    ~BufferManager() {
        stop();
    }

    void start() {
        for (size_t i = 0; i < num_threads; ++i) {
            workers.emplace_back(&BufferManager::worker, this);
        }
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stopped = true;
        }
        cv.notify_all();
        for (auto& worker : workers) {
            worker.join();
        }
    }

    void allocateAndReport(uint64_t stream_id, uint32_t sequence_number, int power_level) {
        auto buffer = pool.allocate();
        if (buffer) {
            (*buffer)->TX_STREAM_ID = stream_id;
            (*buffer)->SEQUENCE_NUMBER = sequence_number;
            (*buffer)->TRANSMISSION_POWER_LEVEL = power_level;
            nms->reportBufferState(*buffer);
            // Simulate a delay in buffer management
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
    }

private:
    BufferPool pool;
    std::shared_ptr<NMSIntegrator> nms;
    std::vector<std::thread> workers;
    std::mutex mutex;
    std::condition_variable cv;
    bool stopped;
    size_t num_threads = 4; // Adjust based on the number of available threads
};
