        if (curl_errno($ch)) {
            throw new Exception('API request failed: ' . curl_error($ch), curl_errno($ch));
        }

        $apiData = json_decode($response, true);
        if (!$apiData || !isset($apiData['success']) || !$apiData['success']) {
