#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the semaphore type
typedef struct {
    int value;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} Semaphore;

// Initialize a semaphore with a given initial value
void sem_init(Semaphore *sem, int init_value) {
    sem->value = init_value;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);
}

// Wait on a semaphore
void sem_wait(Semaphore *sem) {
    pthread_mutex_lock(&sem->mutex);
    while (sem->value <= 0) {
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    sem->value--;
    pthread_mutex_unlock(&sem->mutex);
}

// Post to a semaphore
void sem_post(Semaphore *sem) {
    pthread_mutex_lock(&sem->mutex);
    sem->value++;
    pthread_cond_signal(&sem->cond);
    pthread_mutex_unlock(&sem->mutex);
}

// Destroy a semaphore
void sem_destroy(Semaphore *sem) {
    pthread_mutex_destroy(&sem->mutex);
    pthread_cond_destroy(&sem->cond);
}

int main() {
    Semaphore sem;
    sem_init(&sem, 2); // Initialize with a value of 2

    pthread_t thread1, thread2;

    // Create threads
    pthread_create(&thread1, NULL, (void *)sem_wait, &sem);
    pthread_create(&thread2, NULL, (void *)sem_wait, &sem);

    // Wait for threads to finish
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    sem_post(&sem); // Post once after waiting twice
    sem_destroy(&sem); // Destroy the semaphore

    return 0;
}
