class DynamicXMLProcessor {
public:
    void UpdatePreferencesAsync(std::istream& xmlStream);
    void ValidateAndUpdate(xml_document<> doc);

private:
    std::mutex mutex_;
    std::condition_variable cv_;
    std::queue<std::streambuf*> work_queue_;
    bool stop_flag_ = false;
    std::vector<std::thread> workers_;

    void WorkerThread();
    bool ValidateXML(const std::string& xml);
    bool IsAuthorizedUser(int userId);
};

void DynamicXMLProcessor::UpdatePreferencesAsync(std::istream& xmlStream) {
    std::streambuf* sbuf = new std::streambuf(xmlStream.rdbuf());
    std::lock_guard<std::mutex> lock(mutex_);
    work_queue_.push(sbuf);
    cv_.notify_one();
}

void DynamicXMLProcessor::WorkerThread() {
    while (true) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this] { return !work_queue_.empty() || stop_flag_; });
        if (stop_flag_ && work_queue_.empty()) {
            break;
        }
        std::streambuf* sbuf = work_queue_.front();
        work_queue_.pop();
        lock.unlock();

        std::istream stream(sbuf);
        xml_document<> doc;
        try {
            doc.parse<0>(&(*sbuf)[0]);
        } catch (const parse_error& e) {
            delete sbuf;
            continue;
        }

        ValidateAndUpdate(doc);

        delete sbuf;
    }
}

