#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_CONCURRENT_REQUESTS 10
#define FALLBACK_DNS "8.8.4.4" // Google's public DNS server

typedef struct {
    int key;
    long offset;
} Entry;

int dns_query(const char *hostname, struct in_addr *ip) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // Use IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "DNS query failed for %s: %s\n", hostname, gai_strerror(status));
        return -1;
    }

    memcpy(ip, &((struct sockaddr_in *)res->ai_addr)->sin_addr, sizeof(struct in_addr));
    freeaddrinfo(res);
    return 0;
}

int resolve_hostnames(const char *filename, Entry **entries, int *num_entries) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return -1;
    }

    // Allocate initial memory for entries
    *entries = malloc(100 * sizeof(Entry));
    if (!*entries) {
        perror("Memory allocation failed");
        fclose(file);
        return -1;
    }
    *num_entries = 0;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        char hostname[128], key_str[32];
        if (sscanf(line, "%s %s", hostname, key_str) != 2) continue;

        struct in_addr ip;
        if (dns_query(hostname, &ip) == -1) continue;

        (*entries)[*num_entries].key = atoi(key_str);
        (*entries)[*num_entries].offset = (long)ip.s_addr;
        (*num_entries)++;
    }

    fclose(file);
    return 0;
}

void sort_entries(Entry *entries, int num_entries) {
    for (int i = 0; i < num_entries - 1; i++) {
        for (int j = 0; j < num_entries - i - 1; j++) {
            if (entries[j].key > entries[j + 1].key) {
                Entry temp = entries[j];
                entries[j] = entries[j + 1];
                entries[j + 1] = temp;
            }
        }
    }
}

int main() {
    Entry *entries;
    int num_entries;

    if (resolve_hostnames("config.txt", &entries, &num_entries) == -1) {
        return EXIT_FAILURE;
    }

    sort_entries(entries, num_entries);

    printf("Sequence number from the last entry: %d\n", entries[num_entries - 1].key);

    // Clean up
    free(entries);

    return EXIT_SUCCESS;
}
