from abc import ABC, abstractmethod
import threading
import queue
import time
import requests
from concurrent.futures import ThreadPoolExecutor

class LogProcessor(ABC):
    @abstractmethod
    def process(self, log_data):
        pass

class DynamicLogProcessor:
    _registry = {}

    @classmethod
    def register(cls, format_name, factory):
        cls._registry[format_name] = factory

    @classmethod
    def create_processor(cls, format_name):
        return cls._registry.get(format_name)()

    def __init__(self, max_workers=5):
        self.processors = {}
        self.executor = ThreadPoolExecutor(max_workers=max_workers)
        self.queue = queue.Queue()
        self.lock = threading.Lock()

    def add_source(self, source_id, format_name):
        processor = DynamicLogProcessor.create_processor(format_name)
        self.processors[source_id] = processor
        self.executor.submit(self._process_logs, source_id)

    def submit_log(self, log_data):
        self.queue.put(log_data)

    def _process_logs(self, source_id):
        while True:
            log_data = self.queue.get()
            if log_data is None:
                break
            processor = self.processors[source_id]
            try:
                processor.process(log_data)
            except Exception as e:
                print(f"Error processing log from source {source_id}: {e}")
            finally:
                self.queue.task_done()

    def stop(self):
        for _ in range(len(self.processors)):
            self.queue.put(None)
        self.executor.shutdown(wait=True)

# Example usage
class JSONLogProcessor(LogProcessor):
    def process(self, log_data):
        # Implement processing logic for JSON logs
        print(f"Processing JSON log: {log_data}")

DynamicLogProcessor.register("json", JSONLogProcessor)
processor = DynamicLogProcessor()
processor.add_source("source1", "json")
processor.submit_log({"event": "login", "user": "user1"})
processor.stop()
