// ConfigLoggingKit.cpp
#include "ConfigLoggingKit.h"
#include "ConfigManager.h"
#include "Logger.h"

std::shared_ptr<ConfigLoggingKit> ConfigLoggingKit::instance = nullptr;

std::shared_ptr<ConfigLoggingKit> ConfigLoggingKit::getInstance() {
    if (!instance) {
        instance = std::make_shared<ConfigLoggingKit>();
    }
    return instance;
}

ConfigLoggingKit::ConfigLoggingKit()
    : configManager(std::make_unique<ConfigManager>())
    , logger(std::make_unique<Logger>()) {
    logger->thread = std::thread(&Logger::workerThread, logger.get());
}

ConfigLoggingKit::~ConfigLoggingKit() {
    logger->logQueue.push("SHUTDOWN");
    logger->thread.join();
}

void ConfigLoggingKit::loadConfig(const std::string& configFilePath) {
    configManager->loadConfig(configFilePath);
}

void ConfigLoggingKit::updateConfig(const std::string& configJson) {
    configManager->updateConfig(configJson);
}

