// ConfigManager.cpp
#include "ConfigManager.h"
#include <fstream>
#include <nlohmann/json.hpp>

using json = nlohmann::json;

void ConfigManager::loadConfig(const std::string& filePath) {
    std::ifstream file(filePath);
    if (file.is_open()) {
        json configJson = json::parse(file);
        for (auto& item : configJson.items()) {
            config[item.key()] = item.value().get<std::string>();
        }
        file.close();
    } else {
        // Handle error
    }
}

void ConfigManager::updateConfig(const std::string& json) {
    try {
        json configJson = json::parse(json);
        for (auto& item : configJson.items()) {
            config[item.key()] = item.value().get<std::string>();
        }
    } catch (...) {
        // Handle error
    }
}

// Logger.cpp
#include "Logger.h"
#include <iostream>
#include <chrono>

void Logger::logInfo(const std::string& message) {
    logQueue.push("INFO: " + message);
}

void Logger::logWarning(const std::string& message) {
    logQueue.push("WARNING: " + message);
}

void Logger::logError(const std::string& message) {
    logQueue.push("ERROR: " + message);
}

void Logger::workerThread() {
    while (true) {
        std::string message;
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            if (logQueue.empty()) {
                break;
            }
            message = logQueue.front();
            logQueue.pop();
        }
        // Send log message to external logging service
        std::cout << message << std::endl;
    }
}
