      });
      await newUser.save();
    }
    res.status(201).send('User updated/created successfully');
  } catch (error) {
    res.status(500).send('Error updating/creating user');
  }
});

// Function to fetch user from cache or database
async function getUserFromCacheOrDB(userId) {
  try {
    const cachedUser = await cacheClient.get(userId);
    if (cachedUser) {
      return JSON.parse(cachedUser);
    } else {
      const userFromDB = await User.findOne({ id: userId });
      if (userFromDB) {
        await cacheClient.setex(userId, 3600, JSON.stringify(userFromDB)); // Cache for 1 hour
        return userFromDB;
      }
      return null;
    }
  } catch (error) {
    console.error('Error fetching user:', error);
    throw error;
  }
}

// Middleware to handle concurrent requests using Redis cache
app.use(async (req, res, next) => {
  const userId = req.body.id;
  try {
    const cachedUser = await getUserFromCacheOrDB(userId);
    if (cachedUser) {
      req.user = cachedUser;
      return next();
    } else {
      // Simulate processing time
      setTimeout(() => {
        req.user = { id: userId, name: 'John Doe', email: 'john.doe@example.com' };
        cacheClient.setex(userId, 3600, JSON.stringify(req.user)); // Cache for 1 hour
        next();
      }, 1000); // Simulate delay
    }
  } catch (error) {
    res.status(500).send('Error handling concurrent request');
  }
});

// Endpoint to fetch user profiles with caching
app.get('/users/:id', async (req, res) => {
  try {
    const user = req.user;
    if (user) {
      res.status(200).json(user);
    } else {
      res.status(404).send('User not found');
    }
  } catch (error) {
    res.status(500).send('Error fetching user profile');
  }
});

// Function to handle retries and exponential backoff
async function makeApiRequestWithRetry(url, options, maxRetries = 3, delay = 1000) {
  for (let i = 0; i <= maxRetries; i++) {
    try {
      const response = await axios.request({ ...options, url });
      return response.data;
    } catch (error) {
      if (i === maxRetries) throw error;
      await new Promise(resolve => setTimeout(resolve, delay));
      delay *= 2; // Exponential backoff
    }
  }
}

// Endpoint to integrate with external API subject to rate limits and versioning
app.get('/external-api', async (req, res) => {
  try {
    const response = await makeApiRequestWithRetry('https://api.example.com/data/v1', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${process.env.API_TOKEN}`
      }
    });
    res.status(200).json(response);
  } catch (error) {
    res.status(500).send('Error integrating with external API');
  }
});

// Start the server
app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
