        _rateLimiter = rateLimiter;
    }

    public async Task BatchProcessOrdersAsync(IEnumerable<Order> orders)
    {
        foreach (var order in orders)
        {
            if (!_rateLimiter.AllowRequest())
            {
                _logger.LogWarning("Rate limit exceeded for processing order.");
                continue;
            }

            try
            {
                var orderId = await ProcessOrderAsync(order);
                _logger.LogInformation($"Order {orderId} processed successfully.");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to process order.");
            }
        }
    }

    private async Task<string> ProcessOrderAsync(Order order)
    {
        var orderId = Guid.NewGuid().ToString();

        if (!order.IsValid())
        {
            _logger.LogWarning($"Invalid order data for order ID: {orderId}");
            throw new ArgumentException("Invalid order data");
        }

        await _retryPolicy.ExecuteAsync(() => 
        {
            return _paymentGateway.ProcessPayment(order);
        });

        await _inventoryManager.UpdateInventory(order);

        var cacheKey = $"Order_{orderId}";
        await _cache.SetStringAsync(cacheKey, orderId, new DistributedCacheEntryOptions
        {
            SlidingExpiration = TimeSpan.FromMinutes(10)
        });

        return orderId;
    }
}
```

