import java.time.temporal.ChronoUnit;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class BatchProcessingSystem {

    private static final int DELETION_QUOTA = 100; // Files per directory
    private static final String EXCLUDE_EXTENSIONS[] = {".tmp", ".log"};
    private static final String PRIMARY_SERVER = "primary.server.com";
    private static final String SECONDARY_SERVER = "secondary.server.com";

    public static void main(String[] args) {
        ExecutorService executorService = Executors.newFixedThreadPool(10);

        // List of directories to process
        Path directory1 = Paths.get("/path/to/directory1");
        Path directory2 = Paths.get("/path/to/directory2");

        executorService.submit(() -> processDirectory(directory1));
        executorService.submit(() -> processDirectory(directory2));

        executorService.shutdown();
    }

    private static void processDirectory(Path directory) {
        try (var stream = Files.list(directory)) {
            stream
                .filter(Files::isRegularFile)
                .forEach(file -> deleteOutdatedFiles(file, directory));
        } catch (Exception e) {
            handleException(e);
        }
    }

    private static void deleteOutdatedFiles(Path file, Path directory) {
        LocalDateTime now = LocalDateTime.now();
        LocalDateTime lastModified = Files.getLastModifiedTime(file).toInstant().atZone(java.time.ZoneId.systemDefault()).toLocalDateTime();

        if (ChronoUnit.DAYS.between(lastModified, now) > 7 && ChronoUnit.HOURS.between(lastModified, now) < 24) {
            String fileName = file.getFileName().toString();
            boolean isExcludedExtension = false;

            for (String extension : EXCLUDE_EXTENSIONS) {
                if (fileName.endsWith(extension)) {
                    isExcludedExtension = true;
                    break;
                }
            }

            if (!isExcludedExtension && Files.size(file) <= DELETION_QUOTA * 1024 * 1024) { // Size in bytes
                try {
                    Files.delete(file);
                    log("Deleted file: " + file.toAbsolutePath());
                } catch (Exception e) {
                    handleException(e);
                }
            }
        }
    }

    private static void handleException(Exception e) {
        log("Error processing file: " + e.getMessage());
        // Implement retry logic or escalate critical issues
    }

    private static void log(String message) {
        System.out.println(message); // Replace with actual logging system integration
    }
}
