{
    private readonly ConcurrentDictionary<string, byte[]> _keyCache;
    private readonly ConcurrentDictionary<string, byte[]> _ivCache;
    private readonly object _lockObject = new object();

    public EncryptionService()
    {
        _keyCache = new ConcurrentDictionary<string, byte[]>();
        _ivCache = new ConcurrentDictionary<string, byte[]>();
    }

    ~EncryptionService()
    {
        Dispose();
    }

    public void Dispose()
    {
        // Cleanup resources
    }

    public byte[] Encrypt(byte[] data, string keyId)
    {
        var key = GetKey(keyId);
        var iv = GenerateIV();
        using (var aesGcm = Aes.Create())
        {
            aesGcm.Key = key;
            aesGcm.IV = iv;
            aesGcm.Mode = CipherMode.CipherBlockChaining;
            aesGcm.Padding = PaddingMode.PKCS7;
            aesGcm.GenerateTag();
            return aesGcm.Encrypt(data, false);
        }
    }

    public byte[] Decrypt(byte[] data, string keyId)
    {
        var key = GetKey(keyId);
        using (var aesGcm = Aes.Create())
        {
            aesGcm.Key = key;
            aesGcm.Mode = CipherMode.CipherBlockChaining;
            aesGcm.Padding = PaddingMode.PKCS7;
            aesGcm.ValidateTag();
            return aesGcm.Decrypt(data);
        }
    }

    private byte[] GetKey(string keyId)
    {
        if (!_keyCache.TryGetValue(keyId, out var key))
        {
            lock (_lockObject)
            {
                if (!_keyCache.TryGetValue(keyId, out key))
                {
                    // Fetch and cache the key from a secure vault or environment variable
                    key = Encoding.UTF8.GetBytes("your_key_here");
                    _keyCache.TryAdd(keyId, key);
                }
            }
        }
        return key;
    }

    private byte[] GenerateIV()
    {
        using (var rng = RandomNumberGenerator.Create())
        {
            var iv = new byte[12];
            rng.GetBytes(iv);
            return iv;
        }
    }
}
