const express = require('express');
const axios = require('axios');
const fs = require('fs').promises;
const Redis = require('ioredis');
const bodyParser = require('body-parser');

const app = express();
app.use(bodyParser.json());
const redis = new Redis();

// External password encryption service URL and credentials
const ENCRYPTION_SERVICE_URL = 'https://api.example.com/encrypt';
const API_KEY = process.env.API_KEY;

// Retry logic for external API failures
async function retry(fn, retries = 3, delay = 1000) {
  try {
    return await fn();
  } catch (error) {
    if (retries === 0) throw error;
    await new Promise(resolve => setTimeout(resolve, delay));
    return retry(fn, retries - 1, delay * 2);
  }
}

// Function to fetch and encrypt password
async function fetchAndEncryptPassword(password) {
  const response = await retry(() => axios.post(ENCRYPTION_SERVICE_URL, { password }, { headers: { 'Authorization': `Bearer ${API_KEY}` } }));
  return response.data.encryptedPassword;
}

// Function to update server configuration file
async function updateConfigFile(serverId, configData) {
  const encryptedPassword = await fetchAndEncryptPassword(configData.password);
  configData.password = encryptedPassword;

  // Simulate updating the configuration file
  await fs.writeFile(`server-${serverId}.config`, JSON.stringify(configData));
}

// API endpoint to trigger configuration update
app.post('/update-config', async (req, res) => {
  const { serverIds, configData } = req.body;
  for (const serverId of serverIds) {
    try {
      await updateConfigFile(serverId, configData);
      console.log(`Configuration updated for server ${serverId}`);
    } catch (error) {
      console.error(`Failed to update configuration for server ${serverId}:`, error);
    }
  }
  res.status(200).send('Configuration updates initiated');
});

// Start the server
app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
```

