void handleRemoteConnectionAndProcessCRCIndications(const char* socket_address, int N, int timeout) {
    if (N > MAX_CONCURRENT_CONNECTIONS) {
        logMessage("Error: Requested connections exceed the maximum limit.");
        return;
    }

    struct sockaddr_in remote_addr;
    memset(&remote_addr, 0, sizeof(remote_addr));
    remote_addr.sin_family = AF_INET;
    inet_pton(AF_INET, socket_address, &remote_addr.sin_addr);
    remote_addr.sin_port = htons(12345); // Replace with the actual port number

    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        logMessage("Error: Failed to create socket.");
        return;
    }

    if (handleConnection(sockfd, remote_addr, timeout) != 0) {
        logMessage("Error: Connection failed. Unable to establish connection.");
        close(sockfd);
        return;
    }

    int connected = 1;
    while (N > 0 && connected) {
        char buffer[1024];
        int bytes_received = recv(sockfd, buffer, sizeof(buffer), 0);
        if (bytes_received < 0) {
            logMessage("Error: Failed to receive data.");
            break;
        } else if (bytes_received == 0) {
            logMessage("Info: Remote connection closed.");
            connected = 0;
        } else {
            if (processCRCPdu(buffer, bytes_received) != 0) {
                logMessage("Error: CRC PDU processing failed.");
            }
            N--;
        }
    }

    close(sockfd);
}

