// FileIntegrityVerificationService.java

import java.io.File;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class FileIntegrityVerificationService {
    private static final String MD5_ALGORITHM = "MD5";
    private final MessageDigest md5Digest;
    private final ExecutorService executorService;
    private final ConcurrentHashMap<File, HashTask> tasks;

    public FileIntegrityVerificationService() throws NoSuchAlgorithmException {
        this.md5Digest = MessageDigest.getInstance(MD5_ALGORITHM);
        this.executorService = Executors.newCachedThreadPool();
        this.tasks = new ConcurrentHashMap<>();
    }

    public void calculateHashAsync(File file) {
        if (tasks.containsKey(file)) {
            System.out.println("Hash calculation already in progress for " + file.getName());
            return;
        }
        HashTask task = new HashTask(file);
        tasks.put(file, task);
        executorService.submit(task);
    }

    public void pauseFileHashing(File file) {
        HashTask task = tasks.get(file);
        if (task != null) {
            task.pause();
        }
    }

    public void resumeFileHashing(File file) {
        HashTask task = tasks.get(file);
        if (task != null) {
            task.resume();
        }
    }

    public void cancelFileHashing(File file) {
        HashTask task = tasks.remove(file);
        if (task != null) {
            task.cancel();
        }
    }

    public String getHashForFile(File file) throws IOException {
        HashTask task = tasks.get(file);
        if (task == null || !task.isDone()) {
            throw new IOException("Hash calculation not yet completed for " + file.getName());
        }
        return task.getResult();
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    private class HashTask implements Runnable {
        private final File file;
        private boolean paused = false;
        private boolean cancelled = false;
        private String hash;

        public HashTask(File file) {
            this.file = file;
        }

        @Override
        public void run() {
            try {
                while (!cancelled) {
                    if (paused) {
                        synchronized (this) {
                            wait();
                        }
                    } else {
                        hash = calculateMD5(file);
                        break;
                    }
                }
            } catch (IOException | InterruptedException e) {
                System.err.println("Error calculating hash for " + file.getName() + ": " + e.getMessage());
            }
        }

        private String calculateMD5(File file) throws IOException {
            md5Digest.reset();
            byte[] buffer = new byte[8192];
            int bytesRead;
            try (java.io.FileInputStream fis = new java.io.FileInputStream(file)) {
                while ((bytesRead = fis.read(buffer)) != -1) {
                    md5Digest.update(buffer, 0, bytesRead);
                }
            }
            return bytesToHex(md5Digest.digest());
        }

        private String bytesToHex(byte[] bytes) {
            StringBuilder sb = new StringBuilder();
            for (byte b : bytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        }

        public synchronized void pause() {
            paused = true;
        }

        public synchronized void resume() {
            paused = false;
            notifyAll();
        }

        public boolean isDone() {
            return hash != null;
        }

        public String getResult() {
            return hash;
        }

        public synchronized void cancel() {
            cancelled = true;
        }
    }

    // Example usage
    public static void main(String[] args) throws Exception {
        FileIntegrityVerificationService service = new FileIntegrityVerificationService();
        File file = new File("path/to/file.txt");
        service.calculateHashAsync(file);

        // Wait for hash calculation to complete
        while (!service.isHashCompletedForFile(file)) {
            Thread.sleep(100);
        }

        String hash = service.getHashForFile(file);
        System.out.println("MD5 Hash: " + hash);

        service.shutdown();
    }
}
