public class CommandExecutor {
    public static void main(String[] args) {
        String command = "your_command_here";
        File directory = new File("/path/to/directory");

        try {
            deleteFileIfExists(directory, "file_to_delete.txt");
            Process process = Runtime.getRuntime().exec(command, null, directory);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            while ((line = errorReader.readLine()) != null) {
                System.err.println(line);
            }

            int exitCode = process.waitFor();
            System.out.println("Command exited with code " + exitCode);
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    private static void deleteFileIfExists(File directory, String fileName) {
        File fileToDelete = new File(directory, fileName);
        if (fileToDelete.exists()) {
            fileToDelete.delete();
        }
    }
}
