use tokio::net::TcpStream;
use tokio::time::{Duration, Instant};
use std::error::Error;

// Define the HTTP client configuration struct
pub struct HttpClientConfig {
    pub base_url: String,
    pub timeout: Duration,
    pub max_connections: u32,
    pub enable_certificate_validation: bool,
}

// Implement the HTTP client struct
pub struct HttpClient {
    config: HttpClientConfig,
    client: Client<HttpsConnector<TcpStream>>,
}

// Implement methods for the HTTP client
impl HttpClient {
    // Create a new HTTP client instance
    pub fn new(config: HttpClientConfig) -> Result<Self, Box<dyn Error>> {
        let https_connector = HttpsConnector::new();
        Ok(HttpClient {
            config,
            client: Client::builder()
                .timeout(config.timeout)
                .build::<_, hyper::Body>(https_connector),
        })
    }

    // Send a GET request to the specified path
    pub async fn get(&self, path: &str) -> Result<hyper::Response<hyper::Body>, Box<dyn Error>> {
        let url = format!("{}{}", self.config.base_url, path);
        let uri = Uri::from_str(&url)?;
        self.client.get(uri).await
    }

    // Send a POST request with JSON body to the specified path
    pub async fn post_json<T>(&self, path: &str, json: T) -> Result<hyper::Response<hyper::Body>, Box<dyn Error>>
    where
        T: serde::Serialize,
    {
        let url = format!("{}{}", self.config.base_url, path);
        let uri = Uri::from_str(&url)?;
        let body = hyper::body::Body::from(serde_json::to_vec(&json)?);
        self.client.post(uri).header("Content-Type", "application/json").body(body).await
    }

    // Send a PUT request with JSON body to the specified path
    pub async fn put_json<T>(&self, path: &str, json: T) -> Result<hyper::Response<hyper::Body>, Box<dyn Error>>
    where
        T: serde::Serialize,
    {
        let url = format!("{}{}", self.config.base_url, path);
        let uri = Uri::from_str(&url)?;
        let body = hyper::body::Body::from(serde_json::to_vec(&json)?);
        self.client.put(uri).header("Content-Type", "application/json").body(body).await
    }

    // Send a DELETE request to the specified path
    pub async fn delete(&self, path: &str) -> Result<hyper::Response<hyper::Body>, Box<dyn Error>> {
        let url = format!("{}{}", self.config.base_url, path);
        let uri = Uri::from_str(&url)?;
        self.client.delete(uri).await
    }
}

// Example usage of the HTTP client
#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    let config = HttpClientConfig {
        base_url: "https://api.example.com".to_string(),
        timeout: Duration::from_secs(5),
        max_connections: 10,
        enable_certificate_validation: true,
    };

    let client = HttpClient::new(config)?;
    let response = client.get("/data").await?;
    println!("Response status: {}", response.status());

    Ok(())
}
