const express = require('express');
const jwt = require('jsonwebtoken');
const axios = require('axios');
const { CircuitBreaker } = require('opossum');

// Initialize Express app
const app = express();
app.use(express.json());

// Middleware for JWT token verification
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (token == null) return res.sendStatus(401);

  jwt.verify(token, 'your-secret-key', (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
}

// Circuit breaker for backend services
const backendServiceBreaker = new CircuitBreaker(() => axios.get('https://backend-service.com/data'), {
  timeout: 5000,
  errorThresholdPercentage: 50,
  resetTimeout: 10000,
});

// Route to fetch data from backend service
app.get('/data', authenticateToken, async (req, res) => {
  try {
    const response = await backendServiceBreaker.fire();
    res.json(response.data);
  } catch (error) {
    if (backendServiceBreaker.isOpen()) {
      res.status(503).send('Backend service is temporarily unavailable');
    } else {
      res.status(500).send('Error fetching data from backend service');
    }
  }
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`API Gateway running on port ${PORT}`);
});
