// Function to modify the file extension of a given filename by appending a number of digits and a file type.
std::string ModifyFileExtension(const std::string& filename, int numDigits, const std::string& fileType) {
    size_t dotPos = filename.find_last_of(".");
    if (dotPos != std::string::npos) {
        return filename.substr(0, dotPos + 1) + std::to_string(numDigits) + "." + fileType;
    }
    return filename + "_" + std::to_string(numDigits) + "." + fileType;
}

// Function to run a given command in the background using fork and wait system calls.
int RunCommandInBackground(const std::string& command) {
    pid_t pid = fork();
    if (pid == -1) {
        // Fork failed
        return 0;
    } else if (pid == 0) {
        // Child process
        execlp(command.c_str(), command.c_str(), nullptr);
        exit(1); // Exit if execlp fails
    } else {
        // Parent process
        wait(pid);
        return 1;
    }
}

// Main function to demonstrate the usage of the above functions.
int main() {
    std::string originalFilename = "example.txt";
    int numDigits = 5;
    std::string fileType = "log";

    std::string modifiedFilename = ModifyFileExtension(originalFilename, numDigits, fileType);
    std::cout << "Modified Filename: " << modifiedFilename << std::endl;

    const char* command = "ls -l";
    if (RunCommandInBackground(command)) {
        std::cout << "Command executed successfully." << std::endl;
    } else {
        std::cerr << "Failed to execute command." << std::endl;
    }

    return 0;
}
