use hyper::{
    Client,
    Request,
    Body,
    Uri,
};
use hyper_tls::HttpsConnector;
use std::time::Duration;

#[derive(Debug, Clone)]
pub struct HttpClient {
    client: Client<HttpsConnector>,
}

impl HttpClient {
    pub fn new() -> Self {
        let https = HttpsConnector::new();
        let client = Client::builder()
            .timeout(Duration::from_secs(10))
            .build::<_, hyper::Body>(https);
        Self { client }
    }

    pub async fn get(&self, url: &str) -> Result<hyper::Response<hyper::Body>, Box<dyn std::error::Error>> {
        let uri = Uri::parse(url)?;
        self.client.get(uri).await
    }

    pub async fn post(
        &self,
        url: &str,
        body: hyper::Body,
    ) -> Result<hyper::Response<hyper::Body>, Box<dyn std::error::Error>> {
        let uri = Uri::parse(url)?;
        let request = Request::post(uri).body(body)?;
        self.client.request(request).await
    }

    pub async fn put(
        &self,
        url: &str,
        body: hyper::Body,
    ) -> Result<hyper::Response<hyper::Body>, Box<dyn std::error::Error>> {
        let uri = Uri::parse(url)?;
        let request = Request::put(uri).body(body)?;
        self.client.request(request).await
    }

    pub async fn delete(
        &self,
        url: &str,
    ) -> Result<hyper::Response<hyper::Body>, Box<dyn std::error::Error>> {
        let uri = Uri::parse(url)?;
        let request = Request::delete(uri);
        self.client.request(request).await
    }
}
