// LoggingFramework.h

#pragma once

#include <iostream>
#include <string>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>

class LogEntry {
public:
    std::string timestamp;
    int priority;
    std::string message;

    LogEntry(std::string ts, int prio, std::string msg) : timestamp(ts), priority(prio), message(msg) {}
};

class LoggingFramework {
private:
    std::queue<LogEntry> logQueue;
    std::mutex queueMutex;
    std::condition_variable cv;
    bool stopProcessing;
    std::thread processingThread;

public:
    LoggingFramework() : stopProcessing(false) {
        processingThread = std::thread(&LoggingFramework::processLogs, this);
    }

    ~LoggingFramework() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stopProcessing = true;
        }
        cv.notify_all();
        if (processingThread.joinable()) {
            processingThread.join();
        }
    }

    void log(const LogEntry& entry) {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            logQueue.push(entry);
        }
        cv.notify_one();
    }

private:
    void processLogs() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            cv.wait(lock, [this] { return !logQueue.empty() || stopProcessing; });
            if (stopProcessing && logQueue.empty()) {
                break;
            }
            LogEntry entry = logQueue.front();
            logQueue.pop();
            lock.unlock();

            // Process the log entry
            processLogEntry(entry);
        }
    }

    void processLogEntry(const LogEntry& entry) {
        // Implement log processing logic here
        std::cout << "Processing log: " << entry.message << std::endl;
    }
};

int main() {
    LoggingFramework framework;

    // Simulate logging entries
    for (int i = 0; i < 100; ++i) {
        LogEntry entry(std::to_string(i), i % 5, "Log message " + std::to_string(i));
        framework.log(entry);
    }

    return 0;
}
