import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class FlexibleCommandOrchestrator {
    private ConcurrentHashMap<String, Task> taskMap = new ConcurrentHashMap<>();
    private AtomicInteger taskIdGenerator = new AtomicInteger(0);

    public int submitTask(Runnable command) {
        String taskId = "task-" + taskIdGenerator.incrementAndGet();
        taskMap.put(taskId, new Task(command));
        CompletableFuture.runAsync(() -> executeTask(taskId));
        return Integer.parseInt(taskId.split("-")[1]);
    }

    private void executeTask(String taskId) {
        Task task = taskMap.get(taskId);
        try {
            task.getCommand().run();
            updateStatus(taskId, "Completed");
        } catch (Exception e) {
            updateStatus(taskId, "Failed: " + e.getMessage());
        }
    }

    public String getStatus(int taskId) {
        return taskMap.get("task-" + taskId).getStatus();
    }

    public void cancelTask(int taskId) {
        String taskIdStr = "task-" + taskId;
        Task task = taskMap.get(taskIdStr);
        if (task != null) {
            task.cancel();
        }
        updateStatus(taskIdStr, "Cancelled");
    }

    private void updateStatus(String taskId, String status) {
        taskMap.computeIfPresent(taskId, (k, v) -> { v.setStatus(status); return v; });
    }

    private static class Task {
        private final Runnable command;
        private volatile boolean cancelled = false;
        private String status;

        public Task(Runnable command) {
            this.command = command;
        }

        public void run() {
            if (cancelled) {
                return;
            }
            command.run();
        }

        public void cancel() {
            this.cancelled = true;
        }

        public Runnable getCommand() {
            return command;
        }

        public String getStatus() {
            return status;
        }

        public void setStatus(String status) {
            this.status = status;
        }
    }
}
