#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_POWER_LEVEL 100
#define CI_LENGTH 12

typedef struct {
    time_t timestamp;
    char ci[CI_LENGTH];
    int power_level;
} TX_POWER_LEVEL_STATS;

typedef struct {
    TX_POWER_LEVEL_STATS *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

void init_dynamic_array(DynamicArray *array, size_t initial_capacity) {
    array->data = (TX_POWER_LEVEL_STATS *)malloc(initial_capacity * sizeof(TX_POWER_LEVEL_STATS));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void resize_dynamic_array(DynamicArray *array) {
    size_t new_capacity = array->capacity * 2;
    TX_POWER_LEVEL_STATS *new_data = (TX_POWER_LEVEL_STATS *)realloc(array->data, new_capacity * sizeof(TX_POWER_LEVEL_STATS));
    if (new_data) {
        array->data = new_data;
        array->capacity = new_capacity;
    }
}

void add_or_update_entry(DynamicArray *array, const TX_POWER_LEVEL_STATS *entry) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (strcmp(array->data[i].ci, entry->ci) == 0) {
            array->data[i] = *entry;
            pthread_mutex_unlock(&array->mutex);
            return;
        }
    }
    if (array->size >= array->capacity) {
        resize_dynamic_array(array);
    }
    array->data[array->size++] = *entry;
    pthread_mutex_unlock(&array->mutex);
}

TX_POWER_LEVEL_STATS* get_latest_entry(DynamicArray *array, const char *ci) {
    pthread_mutex_lock(&array->mutex);
    for (int i = array->size - 1; i >= 0; --i) {
        if (strcmp(array->data[i].ci, ci) == 0) {
            pthread_mutex_unlock(&array->mutex);
            return &array->data[i];
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return NULL;
}

char* append_slash_if_needed(char *str, size_t max_length) {
    if (strlen(str) < max_length - 1) {
        str[strcspn(str, "\0")] = '/';
        str[strcspn(str, "\0")] = '\0';
    } else {
        return NULL;
    }
    return str;
}

