class UserActivityProcessor {
public:
    UserActivityProcessor(const std::string& configFilePath, int verbosity)
        : m_configFilePath(configFilePath), m_verbosity(verbosity) {}

    void ProcessFiles(const std::vector<std::string>& inputFiles, const std::string& outputJsonPath) {
        // Initialize configuration
        LoadConfig(m_configFilePath);

        // Create threads for file processing
        std::vector<std::thread> workerThreads;
        for (size_t i = 0; i < m_numThreads; ++i) {
            workerThreads.emplace_back(&UserActivityProcessor::ProcessFileQueue, this);
        }

        // Add files to the queue
        for (const auto& file : inputFiles) {
            std::lock_guard<std::mutex> lock(m_queueMutex);
            m_fileQueue.push(file);
        }
        m_stopProcessing.store(true);

        // Join all worker threads
        for (auto& thread : workerThreads) {
            thread.join();
        }

        // Generate and save output JSON
        SaveOutputToJson(outputJsonPath);
    }

private:
    void LoadConfig(const std::string& configFilePath) {
        std::ifstream configFile(configFilePath);
        configFile >> m_config;
        m_numThreads = m_config["num_threads"].asInt();
    }

    void ProcessFileQueue() {
        while (true) {
            std::string file;
            {
                std::unique_lock<std::mutex> lock(m_queueMutex);
                m_condition.wait(lock, [this] { return !m_fileQueue.empty() || m_stopProcessing.load(); });
                if (m_fileQueue.empty() && m_stopProcessing.load()) break;
                file = m_fileQueue.front();
                m_fileQueue.pop();
            }

            ProcessFile(file);
        }
    }

    void ProcessFile(const std::string& filePath) {
        // Simulate processing logic
        std::ifstream file(filePath);
        if (file.is_open()) {
            std::string line;
            while (std::getline(file, line)) {
                ParseRow(line);
            }
        } else {
            HandleError("Failed to open file: " + filePath);
        }
    }

    void ParseRow(const std::string& row) {
        // Simulate parsing logic
        Json::Value entry;
        try {
            // Parse the row into JSON format based on config
            entry = Json::parse(row);
            // Validate and process data using external API
            ValidateAndProcess(entry);
        } catch (const std::exception& e) {
            HandleError("Failed to parse row: " + std::string(e.what()));
        }
    }

    void ValidateAndProcess(const Json::Value& entry) {
        // Simulate validation and processing logic
        CURL* curl;
        CURLcode res;
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if(curl) {
            // Make API call with retry mechanism
            int retries = m_config["retry_limit"].asInt();
            while (retries-- > 0) {
                curl_easy_setopt(curl, CURLOPT_URL, "http://example.com/api");
                res = curl_easy_perform(curl);
                if(res != CURLE_OK) {
                    std::cerr << "cURL error: " << curl_easy_strerror(res) << std::endl;
                    continue;
                }
                break; // Success
            }
            curl_easy_cleanup(curl);
        }
    }

    void SaveOutputToJson(const std::string& outputJsonPath) {
        // Simulate saving to JSON file
        Json::StreamWriterBuilder wbuilder;
        std::unique_ptr<Json::StreamWriter> writer(wbuilder.newStreamWriter());
        std::ofstream outputFile(outputJsonPath, std::ios::out | std::ios::binary);
        writer->write(m_outputRoot.toStyledString(), &outputFile);
    }

    void HandleError(const std::string& error) {
        // Simulate error handling based on verbosity
        if (m_verbosity >= 1) {
            std::cerr << "Error: " << error << std::endl;
        }
    }

private:
    std::string m_configFilePath;
    int m_verbosity;
    Json::Value m_config;
    size_t m_numThreads = 4;
    std::queue<std::string> m_fileQueue;
    std::mutex m_queueMutex;
    std::condition_variable m_condition;
