// Define a struct to handle directory creation and environment variable setting
struct DirectoryHandler {
    env_var_name: String,
}

impl DirectoryHandler {
    // Create a new instance of DirectoryHandler with the given environment variable name
    fn new(env_var_name: String) -> Self {
        DirectoryHandler { env_var_name }
    }

    // Function to create a directory and set an environment variable
    fn create_and_set_dir(&self, dir_name: &str) -> Result<(), std::io::Error> {
        let env_value = env::var_os(&self.env_var_name);
        if let Some(value) = env_value {
            // If the environment variable is already set, use its value
            println!("Using existing directory path: {:?}", value);
        } else {
            // Create a new directory and set the environment variable
            let dir_path = Path::new(dir_name);
            fs::create_dir_all(&dir_path)?;
            env::set_var(&self.env_var_name, &dir_path);
            println!("Created new directory at: {:?}", dir_path);
        }
        Ok(())
    }
}

fn main() {
    // Create an instance of DirectoryHandler with the environment variable name
    let handler = DirectoryHandler::new("MY_DIRECTORY".to_string());

    // Call the function to create a directory and set the environment variable
    if let Err(e) = handler.create_and_set_dir("my_new_directory") {
        eprintln!("Failed to create directory: {:?}", e);
    }
}
