            }
            cells[cell_info.CELL_ID] = cell_info;
        }
    }

private:
    void resize() {
        std::lock_guard<std::mutex> lock(mutex);
        size_t new_capacity = capacity * 2;
        if (new_capacity > max_elements) throw std::runtime_error("Max elements exceeded");
        capacity = new_capacity;
        cells.reserve(capacity);
