#include <pthread.h>
#include <stdlib.h>
#include <string.h>

#define MAX_UE_INFO 1000

typedef struct {
    int rnti;
    char tag[256];
} RX_UE_INFORMATION_T;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_T ue_info;
    // other fields...
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_nfapi_array(int n) {
    if (n > MAX_UE_INFO) {
        fprintf(stderr, "Error: Too many elements requested.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Populate the array with unique RX UE information
    for (int i = 0; i < n; ++i) {
        array[i].ue_info.rnti = i + 1;
        snprintf(array[i].ue_info.tag, sizeof(array[i].ue_info.tag), "RX_UE_TAG_%d", i);
    }

    return array;
}

void* populate_nfaip_array(void* arg) {
    int* n_ptr = (int*)arg;
    NFAPI_CRC_INDICATION_PDU_T** array_ptr = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array_ptr) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_exit(NULL);
    }

    *array_ptr = create_nfaip_array(*n_ptr);
    if (*array_ptr == NULL) {
        free(array_ptr);
        pthread_exit(NULL);
    }

    pthread_exit((void*)array_ptr);
}

int main() {
    int n = 1000;
    pthread_t thread;
    NFAPI_CRC_INDICATION_PDU_T** array_ptr;

    if (pthread_create(&thread, NULL, populate_nfaip_array, &n) != 0) {
        fprintf(stderr, "Thread creation failed.\n");
        return 1;
    }

    if (pthread_join(thread, (void**)&array_ptr) != 0) {
        fprintf(stderr, "Thread join failed.\n");
        return 1;
    }

    // Use the array...

    free(array_ptr[0]);
    free(array_ptr);

    return 0;
}
```

