// Define the structure for CRC Indication PDU
struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRCFLAG;

    NFAPI_CRC_INDICATION_PDU_T() : RX_UE_INFORMATION_TAG(0), RNTI(0), CRCFLAG(false) {}
};

// Function to generate random boolean value
bool generateRandomCRCFlag() {
    static std::random_device rd;
    static std::mt19937 gen(rd());
    static std::uniform_int_distribution<> dis(0, 1);
    return dis(gen) == 1;
}

// Function to manage dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void manageCRCIndicationPDUs(std::vector<NFAPI_CRC_INDICATION_PDU_T>& pdus, size_t maxSize) {
    if (pdus.size() >= maxSize) return;

    pdus.emplace_back();
    auto& pdu = pdus.back();
    pdu.RX_UE_INFORMATION_TAG = static_cast<uint32_t>(std::chrono::system_clock::now().time_since_epoch().count()) % 10000;
    pdu.RNTI = static_cast<uint16_t>(pdu.RX_UE_INFORMATION_TAG);
    pdu.CRCFLAG = generateRandomCRCFlag();
}

int main() {
    const size_t maxSize = 10000;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pdus;

    // Simulate dynamic addition of PDUs
    for (size_t i = 0; i < maxSize * 2; ++i) {
        manageCRCIndicationPDUs(pdus, maxSize);
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }

    std::cout << "Number of PDUs managed: " << pdus.size() << std::endl;

    return 0;
}
```

