#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define SEMAPHORE_TYPE_A 0
#define SEMAPHORE_TYPE_B 1

typedef struct {
    sem_t semaphore;
    int type;
} Semaphore;

Semaphore semaphores[2];

void initialize_semaphore(int type, int initial_value) {
    if (type == SEMAPHORE_TYPE_A || type == SEMAPHORE_TYPE_B) {
        sem_init(&semaphores[type].semaphore, 0, initial_value);
        semaphores[type].type = type;
    }
}

void acquire_semaphore(int type) {
    if (type == SEMAPHORE_TYPE_A || type == SEMAPHORE_TYPE_B) {
        sem_wait(&semaphores[type].semaphore);
    }
}

void release_semaphore(int type) {
    if (type == SEMAPHORE_TYPE_A || type == SEMAPHORE_TYPE_B) {
        sem_post(&semaphores[type].semaphore);
    }
}

void* semaphore_thread(void* arg) {
    int thread_id = *(int*)arg;
    for (int i = 0; i < 10; i++) {
        acquire_semaphore(SEMAPHORE_TYPE_A);
        printf("Thread %d acquired Semaphore A\n", thread_id);
        release_semaphore(SEMAPHORE_TYPE_A);

        acquire_semaphore(SEMAPHORE_TYPE_B);
        printf("Thread %d acquired Semaphore B\n", thread_id);
        release_semaphore(SEMAPHORE_TYPE_B);
    }
    pthread_exit(NULL);
}

int main() {
    initialize_semaphore(SEMAPHORE_TYPE_A, 5);
    initialize_semaphore(SEMAPHORE_TYPE_B, 3);

    pthread_t threads[10];
    int thread_ids[10];

    for (int i = 0; i < 10; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, semaphore_thread, &thread_ids[i]);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&semaphores[SEMAPHORE_TYPE_A].semaphore);
    sem_destroy(&semaphores[SEMAPHORE_TYPE_B].semaphore);

    return 0;
}
