API_KEYS = {'key1': 'secret1', 'key2': 'secret2'}
POLL_INTERVALS = {'api1': 60, 'api2': 30}
CACHE = OrderedDict()

def fetch_data(api_name):
    url = f'https://api.example.com/{api_name}'
    headers = {'Authorization': API_KEYS[api_name]}
    try:
        response = requests.get(url, headers=headers)
        response.raise_for_status()
        data = response.json()
        return api_name, data
    except requests.RequestException as e:
        app.logger.error(f"Error fetching data from {api_name}: {e}")
        return None

def poll_api(api_name):
    while True:
        executor.submit(fetch_data, api_name)

@app.route('/admin/config', methods=['POST'])
def update_config():
    config = request.json
    for key, value in config.items():
        if key == 'api_keys':
            API_KEYS.update(value)
        elif key == 'poll_intervals':
            POLL_INTERVALS.update(value)
    return jsonify({'status': 'success'})

@app.route('/admin/api_keys', methods=['GET'])
def get_api_keys():
    return jsonify(API_KEYS)

if __name__ == '__main__':
    for api_name in API_KEYS.keys():
        executor.submit(poll_api, api_name)
    app.run(host='0.0.0.0', port=5000)
