class IoTTelemetryProcessor {
public:
    IoTTelemetryProcessor(size_t numThreads) : stop(false), threadCount(numThreads) {}

    void start() {
        for (size_t i = 0; i < threadCount; ++i) {
            workers.emplace_back([this] { worker(); });
        }
    }

    void stopProcessing() {
        std::unique_lock<std::mutex> lock(mutex);
        stop = true;
        condition.notify_all();
        lock.unlock();

        for (std::thread& w : workers) {
            if (w.joinable()) {
                w.join();
            }
        }
    }

    void addTelemetry(const TelemetryPacket& packet) {
        std::unique_lock<std::mutex> lock(mutex);
        queue.push(packet);
        condition.notify_one();
    }

private:
    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return stop || !queue.empty(); });
            if (stop && queue.empty()) {
                break;
            }
            TelemetryPacket packet = queue.front();
            queue.pop();
            lock.unlock();

            try {
                processTelemetry(packet);
                ExternalSystem::getInstance()->storeData(packet);
                ExternalSystem::getInstance()->sendNotification(packet);
            } catch (const std::exception& e) {
                std::cerr << "Error processing telemetry: " << e.what() << std::endl;
                // Log error and handle fallback strategy
