```c
// dynamic_array.c
#include "dynamic_array.h"
#include <stdlib.h>

#define INITIAL_CAPACITY 10

DYNAMIC_ARRAY* create_dynamic_array() {
    DYNAMIC_ARRAY* array = (DYNAMIC_ARRAY*)malloc(sizeof(DYNAMIC_ARRAY));
    if (array == NULL) {
        return NULL;
    }
    array->array = (TX_POWER_LEVEL_STATS**)malloc(INITIAL_CAPACITY * sizeof(TX_POWER_LEVEL_STATS*));
    if (array->array == NULL) {
        free(array);
        return NULL;
    }
    array->size = 0;
    array->capacity = INITIAL_CAPACITY;
    return array;
}

void destroy_dynamic_array(DYNAMIC_ARRAY* array) {
    if (array != NULL) {
        for (size_t i = 0; i < array->size; ++i) {
            free_tx_power_level_stats(array->array[i]);
        }
        free(array->array);
        free(array);
    }
}

int add_to_dynamic_array(DYNAMIC_ARRAY* array, TX_POWER_LEVEL_STATS* stats) {
    if (array == NULL || stats == NULL) {
        return -1;
    }

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        TX_POWER_LEVEL_STATS** new_array = (TX_POWER_LEVEL_STATS**)realloc(array->array, new_capacity * sizeof(TX_POWER_LEVEL_STATS*));
        if (new_array == NULL) {
            return -1;
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }

    array->array[array->size] = stats;
    ++array->size;
    return 0;
}
