// Define a class for each algorithm (hash function or block cipher)
class Algorithm {
public:
    std::string name;
    void* handle; // Library handle

    Algorithm(const std::string& name, void* handle) : name(name), handle(handle) {}

    virtual ~Algorithm() {}

    virtual bool initialize() = 0;
    virtual bool isAvailable() = 0;
    virtual int execute(const std::string& input, std::string& output) = 0;
};

// Implement a factory function to create instances of algorithms
std::unique_ptr<Algorithm> createAlgorithm(const std::string& name, void* handle) {
    if (name == "SHA256") {
        return std::make_unique<SHA256>(handle);
    } else if (name == "AES-256") {
        return std::make_unique<AES_256>(handle);
    }
    // Add more algorithms here
}

// Function to modify file extension
void modifyFileExtension(const std::string& filename, const std::string& digits, const std::string& extension) {
    size_t pos = filename.rfind('.');
    if (pos != std::string::npos) {
        std::cout << filename.substr(0, pos + 1) << digits << '.' << extension << std::endl;
    } else {
        std::cout << filename << digits << '.' << extension << std::endl;
    }
}

// Function to run a command in the background
int runCommandInBackground(const std::string& command) {
    pid_t pid = fork();
    if (pid == -1) {
        return 0; // Fork failed
    } else if (pid == 0) {
        execl(command.c_str(), command.c_str(), nullptr);
        exit(0); // Should not reach here unless exec fails
    }
    return 1;
}

// Main function to demonstrate usage
int main() {
    std::vector<std::unique_ptr<Algorithm>> algorithms;

    // Dynamically load and manage algorithms
    void* handle = dlopen("libcrypto.so", RTLD_LAZY);
    if (handle) {
        algorithms.push_back(createAlgorithm("SHA256", handle));
        algorithms.push_back(createAlgorithm("AES-256", handle));
    }

    for (auto& algo : algorithms) {
        if (algo->initialize() && algo->isAvailable()) {
            std::string output;
            int result = algo->execute("input data", output);
            if (result == 0) {
                std::cout << "Execution successful: " << output << std::endl;
            } else {
                std::cerr << "Execution failed" << std::endl;
            }
        }
    }

    // Modify file extension
    modifyFileExtension("example.txt", "123", "new");

    // Run command in background
    if (!runCommandInBackground("ls -l")) {
        std::cerr << "Failed to run command in background" << std::endl;
    }

    return 0;
}
