#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int id;
    float power_level;
} TX_POWER_LEVEL_STATS;

typedef struct Node {
    TX_POWER_LEVEL_STATS data;
    struct Node* next;
} Node;

Node* head = NULL;

void add_power_stats(int id, float power_level) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_node->data.id = id;
    new_node->data.power_level = power_level;
    new_node->next = head;
    head = new_node;
}

void remove_power_stats(int id) {
    Node* current = head;
    Node* previous = NULL;

    while (current != NULL && current->data.id != id) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        printf("No power stats found with ID %d\n", id);
        return;
    }

    if (previous == NULL) {
        head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
}

void display_power_stats() {
    Node* current = head;
    while (current != NULL) {
        printf("ID: %d, Power Level: %.2f\n", current->data.id, current->data.power_level);
        current = current->next;
    }
}

int main() {
    add_power_stats(1, 50.5);
    add_power_stats(2, 60.3);
    display_power_stats();
    remove_power_stats(1);
    display_power_stats();
    return 0;
}
