// Implementation of DistributedFileSystemClient
DistributedFileSystemClient::DistributedFileSystemClient(DistributedMetadataService* metadata, ExternalDataLogger* logger)
    : metadataService(metadata), dataLogger(logger) {
    // Initialize worker threads
    for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
        workerThreads.emplace_back(&DistributedFileSystemClient::workerThreadFunction, this);
    }
}

DistributedFileSystemClient::~DistributedFileSystemClient() {
    shutdown();
    for (auto& thread : workerThreads) {
        if (thread.joinable()) {
            thread.join();
        }
    }
}

