using System;
using System.Collections.Concurrent;
using System.Data.SqlClient;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;

[Route("api/[controller]")]
public class UpdateController : ControllerBase
{
    private readonly ConcurrentDictionary<string, DateTime> _lockCache = new();
    private readonly string _databaseConnectionString = "your_database_connection_string";
    private readonly HttpClient _httpClient;

    public UpdateController(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [HttpPost("realtime")]
    public async Task<IActionResult> ProcessRealTimeUpdate([FromBody] RealTimeUpdateRequest request)
    {
        if (IsDuplicateRequest(request.RequestId))
            return StatusCode(200, "Duplicate request received. Skipping.");

        try
        {
            await LockResourceAsync(request.ResourceId);

            using (var connection = new SqlConnection(_databaseConnectionString))
            {
                await connection.OpenAsync();
                var transaction = connection.BeginTransaction();

                // Process data from external sources and update database with optimistic locking
                await UpdateDatabaseWithOptimisticLocking(connection, transaction, request);

                transaction.Commit();
            }

            return StatusCode(200, "Update processed successfully.");
        }
        catch (Exception ex)
        {
            _lockCache.TryRemove(request.ResourceId, out _);
            await LogErrorAsync(ex, request.RequestId);
            throw;
        }
    }

    private bool IsDuplicateRequest(string requestId)
    {
        if (_lockCache.TryGetValue(requestId, out var lastProcessed))
        {
            return DateTime.UtcNow - lastProcessed < TimeSpan.FromSeconds(10); // Adjust time window as needed
        }
        _lockCache.TryAdd(requestId, DateTime.UtcNow);
        return false;
    }

    private async Task LockResourceAsync(string resourceId)
    {
        while (!_lockCache.TryAdd(resourceId, DateTime.UtcNow))
        {
            await Task.Delay(100); // Retry every 100ms
        }
    }

    private async Task UpdateDatabaseWithOptimisticLocking(SqlConnection connection, SqlTransaction transaction, RealTimeUpdateRequest request)
    {
        var command = new SqlCommand("UPDATE YourTable SET Column = @Value WHERE Id = @Id AND Version = @Version", connection, transaction);
        command.Parameters.AddWithValue("@Value", request.Value);
        command.Parameters.AddWithValue("@Id", request.Id);
        command.Parameters.AddWithValue("@Version", request.Version);

        if (await command.ExecuteNonQueryAsync() == 0)
            throw new DbUpdateConcurrencyException("Concurrent update conflict detected.");
    }

    private async Task LogErrorAsync(Exception ex, string requestId)
    {
        // Implement logging logic here
    }
}

public class RealTimeUpdateRequest
{
    public string RequestId { get; set; }
    public string ResourceId { get; set; }
    public int Version { get; set; }
    public string Value { get; set; }
}
```

