    private readonly IDistributedCache _cache;

    public CustomUserStore(IDistributedCache cache, UserManager<ApplicationUser> userManager)
        : base(new DbContextOptionsBuilder<ApplicationDbContext>().UseInMemoryDatabase("CustomUserStore").Options, new PasswordHasher<ApplicationUser>(), 
              new ApplicationSignInManager<ApplicationUser>(userManager), null, null, null)
    {
        _cache = cache;
    }

    protected override async Task<IdentityResult> CreateAsync(ApplicationUser user, CancellationToken cancellationToken = default)
    {
        // Custom create logic
        return await base.CreateAsync(user, cancellationToken);
    }

    protected override async Task<IdentityResult> UpdateAsync(ApplicationUser user, CancellationToken cancellationToken = default)
    {
        // Custom update logic
        return await base.UpdateAsync(user, cancellationToken);
    }

    public override async Task<ApplicationUser> FindByNameAsync(string normalizedUserName, CancellationToken cancellationToken = default)
    {
        var cachedUser = await _cache.GetStringAsync($"user:{normalizedUserName}");
        if (cachedUser != null)
        {
            return JsonConvert.DeserializeObject<ApplicationUser>(cachedUser);
        }

        var user = await base.FindByNameAsync(normalizedUserName, cancellationToken);
        if (user != null)
        {
            await _cache.SetStringAsync($"user:{normalizedUserName}", JsonConvert.SerializeObject(user), new DistributedCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(30)
            });
        }

        return user;
    }
}

