using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;

public class DataSource
{
    public string SourceType { get; set; }
    public string ApiEndpoint { get; set; }
    public string AuthenticationToken { get; set; }
    public Dictionary<string, string> QueryParameters { get; set; }
}

public interface IDataProcessor
{
    Task ProcessDataAsync(DataSource dataSource);
}

public class DataProcessor : IDataProcessor
{
    private readonly HttpClient _httpClient;
    private static readonly HashSet<string> AllowedEndpoints = new HashSet<string>
    {
        "https://api.example.com/data1",
        "https://api.example.com/data2"
    };

    public DataProcessor(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task ProcessDataAsync(DataSource dataSource)
    {
        if (dataSource == null || string.IsNullOrEmpty(dataSource.SourceType) ||
            string.IsNullOrEmpty(dataSource.ApiEndpoint))
        {
            Console.WriteLine("Missing required properties in data source.");
            return;
        }

        if (!AllowedEndpoints.Contains(dataSource.ApiEndpoint))
        {
            Console.WriteLine($"Invalid API endpoint: {dataSource.ApiEndpoint}");
            return;
        }

        var requestUrl = $"{dataSource.ApiEndpoint}?";
        if (dataSource.QueryParameters != null && dataSource.QueryParameters.Any())
        {
            requestUrl += string.Join("&", dataSource.QueryParameters.Select(kvp => $"{kvp.Key}={kvp.Value}"));
        }
        else
        {
            Console.WriteLine("Missing query parameters, using defaults.");
        }

        try
        {
            var response = await _httpClient.GetAsync(requestUrl);
            if (response.IsSuccessStatusCode)
            {
                var data = await response.Content.ReadAsStringAsync();
                // Process the data and update display here
                Console.WriteLine($"Data processed for {dataSource.SourceType}: {data}");
            }
            else
            {
                Console.WriteLine($"Failed to retrieve data from {dataSource.ApiEndpoint}, status code: {response.StatusCode}");
            }
        }
        catch (HttpRequestException ex)
        {
            Console.WriteLine($"Request exception for {dataSource.ApiEndpoint}: {ex.Message}");
        }
    }
}

public class FetchAndProcessData
{
    private readonly IDataProcessor _dataProcessor;

    public FetchAndProcessData(IDataProcessor dataProcessor)
    {
        _dataProcessor = dataProcessor;
    }

    public async Task FetchAndProcessDataAsync(DataSource[] dataSources)
    {
        var tasks = dataSources.Select(dataSource => _dataProcessor.ProcessDataAsync(dataSource)).ToArray();
        await Task.WhenAll(tasks);
    }
}

// Usage
var httpClient = new HttpClient();
var dataSource1 = new DataSource { SourceType = "SourceA", ApiEndpoint = "https://api.example.com/data1" };
var dataSource2 = new DataSource { SourceType = "SourceB", ApiEndpoint = "https://api.example.com/data2" };

var dataProcessor = new DataProcessor(httpClient);
var fetchAndProcessData = new FetchAndProcessData(dataProcessor);

await fetchAndProcessData.FetchAndProcessDataAsync(new[] { dataSource1, dataSource2 });
