  { url: 'https://api.example2.com/data', key: 'data2' }
];

// Caching strategy
const cacheDuration = 60; // Cache for 60 seconds

// Function to fetch data from external APIs with caching and retry logic
async function fetchData(url, key) {
  try {
    const cachedData = await redis.get(key);
    if (cachedData) {
      return JSON.parse(cachedData);
    }
    const response = await axios.get(url);
    await redis.setex(key, cacheDuration, JSON.stringify(response.data));
    return response.data;
  } catch (error) {
    console.error(`Error fetching data from ${url}:`, error.message);
    throw error;
  }
}

// Route to handle dynamic field updates
app.post('/update', async (req, res) => {
  const { fields } = req.body;

  try {
    let updatedData = {};

    for (const field of fields) {
      const apiIndex = Math.floor(Math.random() * externalAPIs.length);
      const data = await fetchData(externalAPIs[apiIndex].url, externalAPIs[apiIndex].key);
      if (data[field]) {
        updatedData[field] = data[field];
      }
    }

    res.status(200).json(updatedData);
  } catch (error) {
    res.status(500).json({ error: 'Failed to update fields' });
  }
});

// Middleware for logging and monitoring
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    console.log(`${req.method} ${req.url} - ${Date.now() - start}ms`);
  });
  next();
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
