    client: Client,
    token: Mutex<String>,
}

impl OAuth2Client {
    async fn new() -> Result<Self, Error> {
        let client = Client::new();
        let token = Mutex::new(String::new());
        Ok(OAuth2Client { client, token })
    }

    async fn get_token(&self) -> Result<String, Error> {
        // Implement OAuth2 token refresh logic here
        unimplemented!()
    }

    async fn make_request(
        &self,
        url: &str,
        method: reqwest::Method,
        headers: Option<header::HeaderMap>,
        body: Option<reqwest::Body>,
    ) -> Result<Response, Error> {
        let token = self.get_token().await?;
        let mut request = self.client.request(method, url);
        request.header("Authorization", format!("Bearer {}", token));
        if let Some(headers) = headers {
            for (key, value) in headers.iter() {
                request.header(key, value);
            }
        }
        if let Some(body) = body {
            request.body(body);
        }
        request.send().await
    }

    async fn get(&self, url: &str, headers: Option<header::HeaderMap>) -> Result<Response, Error> {
        self.make_request(url, reqwest::Method::GET, headers, None).await
    }

    async fn post(
        &self,
        url: &str,
        headers: Option<header::HeaderMap>,
        body: Option<reqwest::Body>,
    ) -> Result<Response, Error> {
        self.make_request(url, reqwest::Method::POST, headers, body).await
    }
}

