// src/metrics.rs
use std::time::{Instant, Duration};
use sysinfo::{System, SystemExt};

pub struct BuildMetrics {
    start_time: Instant,
    memory_usage: u64,
}

impl BuildMetrics {
    pub fn new() -> Self {
        BuildMetrics {
            start_time: Instant::now(),
            memory_usage: 0,
        }
    }

    pub fn update_memory_usage(&mut self) {
        let mut sys = System::new_all();
        std::thread::sleep(Duration::from_millis(100));
        sys.refresh_all();
        self.memory_usage = sys.total_memory() - sys.free_memory();
    }

    pub fn get_duration(&self) -> Duration {
        Instant::now().duration_since(self.start_time)
    }
}

// src/concurrency.rs
use std::sync::{Arc, Mutex};
use tokio::sync::mpsc;

pub struct ConcurrencyManager {
    workers: usize,
    queue: mpsc::Sender<BuildTask>,
}

impl ConcurrencyManager {
    pub fn new(workers: usize) -> Self {
        let (sender, receiver) = mpsc::channel(workers);
        for _ in 0..workers {
            tokio::spawn(self.worker(receiver.clone()));
        }
        ConcurrencyManager { workers, queue: sender }
    }

    async fn worker(&self, receiver: mpsc::Receiver<BuildTask>) {
        while let Some(task) = receiver.recv().await {
            task.execute();
        }
    }

    pub fn submit_task(&self, task: BuildTask) {
        self.queue.send(task).unwrap();
    }
}

pub struct BuildTask {
    name: String,
    func: Box<dyn FnOnce()>,
}

impl BuildTask {
    pub fn new(name: String, func: impl FnOnce() + 'static) -> Self {
        BuildTask {
            name,
            func: Box::new(func),
        }
    }

    pub fn execute(&self) {
        info!("Executing task: {}", self.name);
        (self.func)();
        info!("Completed task: {}", self.name);
    }
}

// src/error_recovery.rs
use std::error::Error;

pub struct ErrorRecovery {
    critical_tasks: Vec<String>,
}

impl ErrorRecovery {
    pub fn new(critical_tasks: Vec<String>) -> Self {
        ErrorRecovery { critical_tasks }
    }

