    use tokio::sync::mpsc;

    pub struct ResourceManager {
        pool: Arc<Mutex<Vec<Resource>>>,
        queue: mpsc::Sender<BuildTask>,
    }

    impl ResourceManager {
        pub fn new(initial_resources: Vec<Resource>) -> Self {
            let (sender, receiver) = mpsc::channel(initial_resources.len());
            ResourceManager {
                pool: Arc::new(Mutex::new(initial_resources)),
                queue: sender,
            }
        }

        async fn worker(&self, receiver: mpsc::Receiver<BuildTask>) {
            while let Some(task) = receiver.recv().await {
                task.execute();
            }
        }

        pub fn submit_task(&self, task: BuildTask) {
            self.queue.send(task).unwrap();
        }

        pub fn acquire_resource(&self) -> Option<Resource> {
            let mut pool = self.pool.lock().unwrap();
            pool.pop()
        }

        pub fn release_resource(&self, resource: Resource) {
            let mut pool = self.pool.lock().unwrap();
            pool.push(resource);
        }
    }

    pub struct Resource {
        id: String,
        capacity: u64,
    }
}

