['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int id;
    pthread_mutex_t lock;
    int priority;
} Semaphore;

Semaphore* create_semaphore(int max_concurrent_sessions) {
    Semaphore *sem = (Semaphore*)malloc(max_concurrent_sessions * sizeof(Semaphore));
    for (int i = 0; i < max_concurrent_sessions; i++) {
        sem[i].id = i;
        pthread_mutex_init(&sem[i].lock, NULL);
        sem[i].priority = 0;
    }
    return sem;
}

void acquire_semaphore(Semaphore *sem, int priority) {
    for (int i = 0; i < max_concurrent_sessions; i++) {
        if (sem[i].priority <= priority) {
            pthread_mutex_lock(&sem[i].lock);
            sem[i].priority = priority;
            break;
        }
    }
}

void release_semaphore(Semaphore *sem, int id) {
    for (int i = 0; i < max_concurrent_sessions; i++) {
        if (sem[i].id == id) {
            pthread_mutex_unlock(&sem[i].lock);
            sem[i].priority = 0;
            break;
        }
    }
}

void destroy_semaphore(Semaphore *sem, int max_concurrent_sessions) {
    for (int i = 0; i < max_concurrent_sessions; i++) {
        pthread_mutex_destroy(&sem[i].lock);
    }
    free(sem);
}
```

This code snippet demonstrates a basic implementation of a semaphore-based concurrency control mechanism in C. It includes functions to create, acquire, release, and destroy semaphores. The semaphore structure allows each session to have its own lock with a priority level, which can be used to prioritize high-priority sessions. This is a simplified version of the semaphore mechanism that you would need to expand upon for a full-featured `SecureSessionManager` library.']

