# realtimedataaggregator/pipeline.py

import threading
from queue import Queue

class DataPipeline:
    def __init__(self, source_adapters, transformers, validators):
        self.source_adapters = source_adapters
        self.transformers = transformers
        self.validators = validators
        self.input_queue = Queue()
        self.output_queue = Queue()

    def start(self):
        threading.Thread(target=self.process_data).start()

    def process_data(self):
        while True:
            data = self.input_queue.get()
            if data is None:
                break

            for adapter in self.source_adapters:
                parsed_data = adapter.parse_data(data)
                filtered_data = adapter.filter_data(parsed_data)

            for transformer in self.transformers:
                transformed_data = transformer.apply(filtered_data)

            for validator in self.validators:
                if not validator.validate(transformed_data):
                    continue

            self.output_queue.put(transformed_data)
