class IoTSystem {
private:
    DataProcessor processor;
    NetworkHandler networkHandler;
    ErrorLogger errorLogger;
    BackpressureHandler backpressureHandler;
    Monitor monitor;

    std::queue<SensorData> dataQueue;
    std::mutex queueMutex;
    std::condition_variable dataCondition;
    std::atomic<bool> running{true};
    std::vector<std::thread> threads;

public:
    IoTSystem(int numThreads) {
        for (int i = 0; i < numThreads; ++i) {
            threads.emplace_back([this]() {
                while (running) {
                    std::unique_lock<std::mutex> lock(queueMutex);
                    dataCondition.wait(lock, [this] { return !dataQueue.empty() || !running; });
                    if (!running && dataQueue.empty()) break;

                    SensorData data = std::move(dataQueue.front());
                    dataQueue.pop();
                    lock.unlock();

                    processor.process(data);

                    monitor.updateMetrics("processed_data", 1);
                }
            });
        }
    }

    ~IoTSystem() {
        running = false;
        dataCondition.notify_all();
        for (auto& thread : threads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void addData(const SensorData& data) {
        std::unique_lock<std::mutex> lock(queueMutex);
        dataQueue.push(data);
        dataCondition.notify_one();

        if (!backpressureHandler.handleBackpressure()) {
            errorLogger.logError("Backpressure detected");
            // Handle backpressure gracefully
        }
    }

    void adjustThreads(int newNumThreads) {
        std::vector<std::thread> newThreads;
        for (int i = 0; i < newNumThreads; ++i) {
            newThreads.emplace_back([this]() {
                while (running) {
                    std::unique_lock<std::mutex> lock(queueMutex);
                    dataCondition.wait(lock, [this] { return !dataQueue.empty() || !running; });
                    if (!running && dataQueue.empty()) break;

                    SensorData data = std::move(dataQueue.front());
                    dataQueue.pop();
                    lock.unlock();

                    processor.process(data);

                    monitor.updateMetrics("processed_data", 1);
                }
            });
        }

        for (auto& thread : threads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
        threads = std::move(newThreads);
    }
};

int main() {
    IoTSystem system(4);

    // Simulate adding data
    for (int i = 0; i < 10000; ++i) {
        SensorData data; // Initialize sensor data
        system.addData(data);
    }

    // Adjust number of threads dynamically
    system.adjustThreads(8);

    return 0;
}
