mod rate_limiter {
    use std::collections::HashMap;
    use std::sync::{Arc, Mutex};
    use std::time::{Instant, Duration};

    pub struct RateLimiter {
        limits: Arc<Mutex<HashMap<String, (u32, Instant)>>>,
    }

    impl RateLimiter {
        pub fn new() -> Self {
            RateLimiter {
                limits: Arc::new(Mutex::new(HashMap::new())),
            }
        }

        pub fn allow_request(&self, user_id: &str) -> bool {
            let mut limits = self.limits.lock().unwrap();
            if !limits.contains_key(user_id) || Instant::now() > limits[user_id].1 + Duration::from_secs(1) {
                limits.insert(user_id.to_string(), (0, Instant::now()));
            }
            if limits[user_id].0 < 10 {
                limits.get_mut(user_id).unwrap().0 += 1;
                true
            } else {
                false
            }
        }
    }
