type AuthMicroservice struct {
	httpServer *http.Server
	config     Config
}

func NewAuthMicroservice(config Config) *AuthMicroservice {
	return &AuthMicroservice{
		config: config,
	}
}

func (s *AuthMicroservice) Start() error {
	s.httpServer = &http.Server{
		Addr:    fmt.Sprintf(":%d", s.config.Port),
		Handler: s.router(),
	}

	log.Println("Starting Auth Microservice on port:", s.config.Port)
	return s.httpServer.ListenAndServe()
}

func (s *AuthMicroservice) Stop() error {
	log.Println("Stopping Auth Microservice")
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	return s.httpServer.Shutdown(ctx)
}

func (s *AuthMicroservice) router() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("/login/google", s.loginGoogle)
	mux.HandleFunc("/login/facebook", s.loginFacebook)
	mux.HandleFunc("/login/linkedin", s.loginLinkedIn)
	return mux
}

