public interface IRateLimiter
{
    bool AllowRequest();
}

public class RateLimiter : IRateLimiter
{
    private readonly int _maxRequestsPerHour;
    private readonly Timer _timer;
    private int _requestCount;

    public RateLimiter(int maxRequestsPerHour)
    {
        _maxRequestsPerHour = maxRequestsPerHour;
        _requestCount = 0;
        _timer = new Timer(ResetRequestCount, null, TimeSpan.FromHours(1), Timeout.InfiniteTimeSpan);
    }

    private void ResetRequestCount(object state)
    {
        _requestCount = 0;
    }

    public bool AllowRequest()
    {
        if (_requestCount >= _maxRequestsPerHour)
            return false;

        Interlocked.Increment(ref _requestCount);
        return true;
    }
}
