using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class EncryptionModule
{
    private readonly HttpClient _httpClient = new HttpClient();
    private readonly CryptoVault _cryptoVault;

    public EncryptionModule(CryptoVault cryptoVault)
    {
        _cryptoVault = cryptoVault;
    }

    public async Task<string> LoadAndDecryptDataAsync(string url, CancellationToken cancellationToken)
    {
        var encryptedData = await FetchEncryptedDataFromUrl(url, cancellationToken);
        var key = _cryptoVault.GetKey();
        var iv = _cryptoVault.GetIV();

        return DecryptData(encryptedData, key, iv);
    }

    private async Task<byte[]> FetchEncryptedDataFromUrl(string url, CancellationToken cancellationToken)
    {
        using (var response = await _httpClient.GetAsync(url, HttpCompletionOption.ResponseHeadersRead, cancellationToken))
        {
            response.EnsureSuccessStatusCode();
            var contentStream = await response.Content.ReadAsStreamAsync(cancellationToken);
            return await contentStream.ReadAllBytesAsync(cancellationToken);
        }
    }

    private string DecryptData(byte[] encryptedData, byte[] key, byte[] iv)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            aes.Mode = CipherMode.GCM;

            var decryptor = aes.CreateDecryptor(key, iv);

            using (var memoryStream = new MemoryStream(encryptedData))
            {
                using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
                {
                    using (var reader = new StreamReader(cryptoStream))
                    {
                        return await reader.ReadToEndAsync();
                    }
                }
            }
        }
    }
}

public class CryptoVault
{
    private readonly byte[] _key;
    private readonly byte[] _iv;

    public CryptoVault()
    {
        // Initialize key and IV securely from a secure vault or generate them randomly.
        _key = GenerateKey();
        _iv = GenerateIV();
    }

    public byte[] GetKey() => _key;
    public byte[] GetIV() => _iv;

    private static byte[] GenerateKey()
    {
        using (var rng = new RNGCryptoServiceProvider())
        {
            var key = new byte[32]; // AES-256 key size
            rng.GetBytes(key);
            return key;
        }
    }

    private static byte[] GenerateIV()
    {
        using (var rng = new RNGCryptoServiceProvider())
        {
            var iv = new byte[12]; // GCM IV size
            rng.GetBytes(iv);
            return iv;
        }
    }
}
