use tokio::{net::TcpListener, sync::mpsc};
use std::{env, process};

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let addr = env::var("LISTEN_ADDR").unwrap_or_else(|_| "127.0.0.1:8080".to_string());
    let listener = TcpListener::bind(&addr).await?;
    println!("Listening on {}", addr);

    // Setup message routing and handling
    let (tx, mut rx) = mpsc::channel(32);
    tokio::spawn(async move {
        while let Some((mut socket, addr)) = listener.accept().await {
            tokio::spawn(async move {
                match handle_client(socket).await {
                    Ok(_) => println!("Client {} disconnected", addr),
                    Err(e) => eprintln!("Error handling client {}: {}", addr, e),
                }
            });
        }
    });

    // Handle control messages for subscription and publication
    while let Some(message) = rx.recv().await {
        match message {
            Message::Subscribe { service_type, topic } => handle_subscription(service_type, topic).await,
            Message::Publish { service_type, data } => handle_publication(service_type, data).await,
        }
    }

    Ok(())
}

