// AdvancedLoggingFramework.cpp
#include "AdvancedLoggingFramework.h"

void AdvancedLoggingFramework::start() {
    isRunning = true;
    for (int i = 0; i < consumerCount; ++i) {
        consumerThreads.emplace_back(&AdvancedLoggingFramework::consumerThread, this, i);
    }
    producerThread();
}

void AdvancedLoggingFramework::stop() {
    isRunning = false;
    dataReady.notify_all();
    for (auto& thread : consumerThreads) {
        if (thread.joinable()) {
            thread.join();
        }
    }
}

void AdvancedLoggingFramework::log(const std::string& message) {
    std::lock_guard<std::mutex> lock(queueMutex);
    logQueue.push(LogEntry{message});
    dataReady.notify_one();
}

