}

void AdvancedLoggingFramework::producerThread() {
    while (isRunning) {
        LogEntry newLog = generateNewLog(); // Assume this function generates a new log entry
        std::lock_guard<std::mutex> lock(queueMutex);
        logQueue.push(newLog);
        dataReady.notify_one();
    }
}

void AdvancedLoggingFramework::consumerThread(int id) {
    while (isRunning) {
        std::unique_lock<std::mutex> lock(queueMutex);
        dataReady.wait(lock, [this] { return !logQueue.empty() || !isRunning; });
        if (!isRunning && logQueue.empty()) {
            break;
        }
        LogEntry logEntry = logQueue.front();
        logQueue.pop();
        lock.unlock();

        processLogEntries(logEntry);
    }
}

