public class TransactionProcessingService {

    private ExecutorService executorService = Executors.newFixedThreadPool(10);
    private PaymentApiClient paymentApiClient;

    public TransactionProcessingService(PaymentApiClient paymentApiClient) {
        this.paymentApiClient = paymentApiClient;
    }

    public void processBatch(TransactionPacket[] transactions) {
        for (TransactionPacket transaction : transactions) {
            Future<?> future = executorService.submit(() -> processTransaction(transaction));
            // Optionally handle the Future to manage results or exceptions
        }
    }

    private void processTransaction(TransactionPacket transaction) {
        try {
            if (!paymentApiClient.validateTransaction(transaction)) {
                logError("Validation failed for transaction: " + transaction);
                return;
            }

            boolean paymentSuccessful = paymentApiClient.processPayment(transaction);
            if (paymentSuccessful) {
                // Handle successful payment
                logInfo("Processed transaction successfully: " + transaction);
            } else {
                logError("Payment processing failed for transaction: " + transaction);
            }
        } catch (Exception e) {
            logError("An error occurred while processing transaction: " + transaction, e);
        }
    }

    private void logInfo(String message) {
        // Log to a monitoring system or console
    }

    private void logError(String message, Exception exception) {
        // Log detailed error information
    }

    private void logError(String message) {
        // Log general error information
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }
}
