['Here is a basic implementation of a hash table with separate chaining in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define TABLE_SIZE 100

typedef struct Node {
    char* key;
    int value;
    struct Node* next;
} Node;

Node* create_node(char* key, int value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->key = strdup(key);
    new_node->value = value;
    new_node->next = NULL;
    return new_node;
}

void insert(Node** table, char* key, int value) {
    int index = hash_function(key);
    Node* new_node = create_node(key, value);

    if (table[index] == NULL) {
        table[index] = new_node;
    } else {
        Node* current = table[index];
        while (current->next != NULL) {
            if (strcmp(current->key, key) == 0) {
                current->value = value;
                free(new_node->key);
                free(new_node);
                return;
            }
            current = current->next;
        }
        if (strcmp(current->key, key) == 0) {
            current->value = value;
            free(new_node->key);
            free(new_node);
            return;
        }
        current->next = new_node;
    }
}

int get(Node** table, char* key) {
    int index = hash_function(key);

    if (table[index] == NULL) {
        return -1; // Key not found
    } else {
        Node* current = table[index];
        while (current != NULL) {
            if (strcmp(current->key, key) == 0) {
                return current->value;
            }
            current = current->next;
        }
    }

    return -1; // Key not found
}

void delete(Node** table, char* key) {
    int index = hash_function(key);

    if (table[index] != NULL) {
        Node* current = table[index];
        Node* prev = NULL;

        while (current != NULL) {
            if (strcmp(current->key, key) == 0) {
                if (prev == NULL) {
                    table[index] = current->next;
                } else {
                    prev->next = current->next;
                }
                free(current->key);
                free(current);
                return;
            }
            prev = current;
            current = current->next;
        }
    }
}

void print_table(Node** table) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        Node* current = table[i];
        while (current != NULL) {
            printf("%s: %d\n", current->key, current->value);
            current = current->next;
        }
    }
}

int hash_function(char* key) {
    // Simple hash function for demonstration purposes
    int sum = 0;
    for (int i = 0; key[i] != '\0'; i++) {
        sum += (int)key[i];
    }
    return sum % TABLE_SIZE;
}
