class FileNamer {
public:
    static std::string generateSafeUniqueFileName(const std::string& baseName, const std::vector<std::string>& extensions) {
        if (extensions.empty()) {
            throw std::invalid_argument("No supported file extensions provided");
        }

        std::string cleanBaseName = sanitizeFilename(baseName);
        std::string extension = getValidExtension(cleanBaseName, extensions);

        return constructFileName(cleanBaseName, generateSequence(), generateIdentifier(), extension);
    }

private:
    static std::string sanitizeFilename(const std::string& baseName) {
        // Remove invalid characters and trim
        std::string sanitized;
        for (char c : baseName) {
            if (isalnum(c)) {
                sanitized += c;
            }
        }
        return sanitized;
    }

    static std::string getValidExtension(const std::string& cleanBaseName, const std::vector<std::string>& extensions) {
        size_t dotPos = cleanBaseName.find('.');
        if (dotPos != std::string::npos && isSupportedExtension(cleanBaseName.substr(dotPos), extensions)) {
            return cleanBaseName.substr(dotPos);
        } else {
            std::cout << "Warning: Unsupported file extension. Using default." << std::endl;
            return extensions.front();
        }
    }

    static bool isSupportedExtension(const std::string& extension, const std::vector<std::string>& supportedExtensions) {
        for (const auto& ext : supportedExtensions) {
            if (ext == extension) {
                return true;
            }
        }
        return false;
    }

    static int generateSequence() {
        // Implement logic to generate a numeric sequence
        return rand();
    }

    static std::string generateIdentifier() {
        time_t now = time(nullptr);
        char buffer[10];
        strftime(buffer, sizeof(buffer), "%Y%m%d%H%M%S", localtime(&now));
        return std::string(buffer) + "-" + std::to_string(rand());
    }

    static std::string constructFileName(const std::string& baseName, int sequence, const std::string& identifier, const std::string& extension) {
        // Implement logic to construct the final filename
        return baseName + "_" + std::to_string(sequence) + "_" + identifier + extension;
    }
};

int main() {
    DynamicArrayManager manager;
    TX_POWER_LEVEL_STATS entry = {1, 10.5};
    manager.addEntry(entry);

    std::vector<std::string> extensions = {"txt", "csv"};
    try {
        std::string fileName = FileNamer::generateSafeUniqueFileName("data", extensions);
        std::cout << "Generated file name: " << fileName << std::endl;
    } catch (const std::invalid_argument& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
