typedef struct {
    TX_POWER_LEVEL_STATS *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

void init_dynamic_array(DynamicArray *array) {
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void free_dynamic_array(DynamicArray *array) {
    if (array->data != NULL) {
        free(array->data);
        array->data = NULL;
        array->size = 0;
        array->capacity = 0;
    }
    pthread_mutex_destroy(&array->mutex);
}

int append_to_array(DynamicArray *array, TX_POWER_LEVEL_STATS item) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity == 0 ? 1 : array->capacity * 2;
        TX_POWER_LEVEL_STATS *new_data = realloc(array->data, new_capacity * sizeof(TX_POWER_LEVEL_STATS));
        if (new_data == NULL) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size++] = item;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void append_slash_if_needed(char *str, size_t max_size) {
    if (strlen(str) < max_size - 1) {
        str[strlen(str)] = '/';
    }
