// Define NFAPI_CRC_INDICATION_PDU_T structure as per API documentation

typedef struct NFAPI_CRC_INDICATION_PDU_TAG {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

// Define linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define linked list structure
typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t mutex;
} LinkedList;

// Initialize the linked list
void init_list(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

// Add a new element to the linked list
void add_element(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        // Handle memory allocation failure
        perror("Memory allocation failed");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    new_node->data = data;
    new_node->next = NULL;
    if (list->tail != NULL) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

// Remove an element from the linked list
void remove_element(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (current->data == data) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            if (list->tail == current) {
                list->tail = prev;
            }
            free(current);
            list->size--;
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to fetch data from RESTful API and populate linked list
void* fetch_data(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    CURL* curl = curl_easy_init();
    if(curl) {
        CURLcode res;
        for(int i = 0; i < 3; i++) { // Retry up to 3 times
            res = curl_easy_perform(curl);
            if(res != CURLE_OK) {
                fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
                sleep(i + 1); // Backoff strategy
            } else {
                break;
            }
        }
        curl_easy_cleanup(curl);
    }
    return NULL;
}

// Example usage of the library
int main() {
    LinkedList list;
    init_list(&list);

    NFAPI_CRC_INDICATION_PDU_T data;
    // Populate data structure as per API documentation

    add_element(&list, data);

    remove_element(&list, data);

    pthread_t thread;
    if(pthread_create(&thread, NULL, fetch_data, &list) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }
    pthread_join(thread, NULL);

    // Clean up
    pthread_mutex_destroy(&list.mutex);
    Node* current = list.head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    return EXIT_SUCCESS;
}
