private:
    std::unordered_map<std::string, std::shared_ptr<void>> cache;
    std::mutex mutex_;
    std::condition_variable cv_;

public:
    void updateConfiguration(const std::string& key, const std::shared_ptr<void>& config) {
        std::lock_guard<std::mutex> lock(mutex_);
        cache[key] = config;
        cv_.notify_all();
    }

    std::shared_ptr<void> getConfiguration(const std::string& key) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this, &key] { return cache.find(key) != cache.end(); });
        return cache[key];
    }
};

