#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_CONCURRENT_REQUESTS 50000
#define MAX_DNS_PROVIDERS 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T pdus[MAX_CONCURRENT_REQUESTS];
int pdu_index = 0;

pthread_mutex_t lock;
pthread_cond_t cond;

void* generate_pdus(void* arg) {
    while (1) {
        pthread_mutex_lock(&lock);
        if (pdu_index >= MAX_CONCURRENT_REQUESTS) {
            pthread_cond_wait(&cond, &lock);
        }
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand();
        pdu.CRC_INDICATION_REL8_TAG = (rand() % 2) == 0 ? 1 : 0;
        pdus[pdu_index++] = pdu;
        pthread_mutex_unlock(&lock);
    }
}

int main() {
    pthread_t threads[MAX_CONCURRENT_REQUESTS];
    pthread_mutex_init(&lock, NULL);
    pthread_cond_init(&cond, NULL);

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        pthread_create(&threads[i], NULL, generate_pdus, NULL);
    }

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&lock);
    pthread_cond_destroy(&cond);

    return 0;
}
