// Define a simple linked list for managing PDUs
typedef struct PduNode {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct PduNode* next;
} PduNode;

PduNode* head = NULL;
pthread_mutex_t lock;

// Function to generate random CRCFLAG
int generateRandomCrcFlag() {
    return rand() % 2; // Randomly set to either 0 or 1
}

// Asynchronous function to populate list of PDUs
void* populatePDUs(void* arg) {
    int N = *(int*)arg; // Number of PDUs to generate

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&lock);
        PduNode* newNode = (PduNode*)malloc(sizeof(PduNode));
        newNode->pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
        newNode->pdu.RNTI = rand() % 65536;
        newNode->pdu.CRC_INDICATION_REL8_TAG = generateRandomCrcFlag();
        newNode->next = head;
        head = newNode;
        pthread_mutex_unlock(&lock);
    }

    return NULL;
}

// Function to simulate DNS provider API integration
void integrateDNSProvider() {
    // Placeholder for actual implementation
    printf("Integrating with DNS provider...\n");
}

// Main function to demonstrate the asynchronous PDU population
int main() {
    srand(time(NULL));
    pthread_t thread1, thread2;
    int N = 50000; // Number of PDUs to generate

    if (pthread_mutex_init(&lock, NULL) != 0) {
        printf("Mutex initialization failed\n");
        return 1;
    }

    if (pthread_create(&thread1, NULL, populatePDUs, &N) != 0) {
        printf("Thread creation failed\n");
        return 1;
    }

    if (pthread_create(&thread2, NULL, populatePDUs, &N) != 0) {
        printf("Thread creation failed\n");
        return 1;
    }

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    integrateDNSProvider();

    // Cleanup
    while (head != NULL) {
        PduNode* temp = head;
        head = head->next;
        free(temp);
    }

    pthread_mutex_destroy(&lock);

    return 0;
}
