["```javascript
const express = require('express');
const { Worker, isMainThread, parentPort } = require('worker_threads');
const axios = require('axios');
const redis = require('redis');
const fs = require('fs');
const zlib = require('zlib');
const pino = require('pino');

const app = express();
app.use(express.json());

const logger = pino({
  level: 'info',
  transport: {
    target: 'pino-pretty'
  }
});

const redisClient = redis.createClient();

const workerPoolSize = Math.min(200, os.cpus().length); // Dynamic worker pool
let workers = [];

for (let i = 0; i < workerPoolSize; i++) {
  const worker = new Worker('./worker.js');
  workers.push(worker);
}

app.post('/process', async (req, res) => {
  try {
    const commands = req.body.commands;
    if (!commands || !Array.isArray(commands)) {
      return res.status(400).send('Invalid command batch');
    }

    const batchSize = Math.min(50, commands.length);
    for (let i = 0; i < batchSize; i++) {
      const command = commands[i];
      const worker = workers.shift();
      if (worker) {
        worker.postMessage({ command });
        worker.on('message', (result) => {
          res.write(JSON.stringify(result) + '\n');
          workers.push(worker);
        });
      } else {
        // Handle case when no worker is available
        return res.status(503).send('Service unavailable');
      }
    }
  } catch (error) {
    logger.error(error);
    res.status(500).send('Internal Server Error');
  }
});

app.listen(3000, () => {
  logger.info('Microservice is running on port 3000');
});
