['```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <atomic>
#include <mutex>
#include <condition_variable>

class StateManager {
public:
    void addState(const std::string& state);
    bool removeState(const std::string& state);
    bool stateExists(const std::string& state) const;
    size_t getStateCount() const;

private:
    std::vector<std::string> states_;
    mutable std::mutex mutex_;
};

void StateManager::addState(const std::string& state) {
    std::lock_guard<std::mutex> lock(mutex_);
    states_.push_back(state);
}

bool StateManager::removeState(const std::string& state) {
    std::lock_guard<std::mutex> lock(mutex_);
    auto it = std::find(states_.begin(), states_.end(), state);
    if (it != states_.end()) {
        states_.erase(it);
        return true;
    }
    return false;
}

bool StateManager::stateExists(const std::string& state) const {
    std::lock_guard<std::mutex> lock(mutex_);
    return std::find(states_.begin(), states_.end(), state) != states_.end();
}

size_t StateManager::getStateCount() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return states_.size();
}
