use std::env;
use std::fs::{self, File};
use std::io::{self, Write};
use std::path::Path;
use std::sync::{Arc, Mutex};
use tokio::task;

#[derive(Clone)]
struct FileHasher {
    cache: Arc<Mutex<HashMap<String, String>>>,
}

impl FileHasher {
    fn new() -> Self {
        FileHasher {
            cache: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    async fn calculate_hash(&self, file_path: &Path) -> io::Result<String> {
        let mut hasher = md5::Md5::new();
        if let Some(hash) = self.cache.lock().unwrap().get(file_path.to_str().unwrap()) {
            return Ok(hash.clone());
        }
        let mut file = File::open(file_path)?;
        let mut buffer = [0; 4096];
        loop {
            let bytes_read = file.read(&mut buffer)?;
            if bytes_read == 0 {
                break;
            }
            hasher.update(&buffer[..bytes_read]);
        }
        let hash = format!("{:x}", hasher.finalize());
        self.cache.lock().unwrap().insert(file_path.to_str().unwrap().to_string(), hash.clone());
        Ok(hash)
    }

    async fn verify_hash(&self, file_path: &Path, expected_hash: &str) -> io::Result<bool> {
        let calculated_hash = self.calculate_hash(file_path).await?;
        Ok(calculated_hash == expected_hash)
    }
}

#[tokio::main]
async fn main() -> io::Result<()> {
    let hasher = FileHasher::new();
    let file_path = Path::new("example.txt");
    let expected_hash = "expected_md5_hash";

    if !hasher.verify_hash(file_path, expected_hash).await? {
        println!("File hash does not match.");
    } else {
        println!("File hash is valid.");
    }

    Ok(())
}

fn create_directory_and_set_env_var(directory_name: &str) -> io::Result<()> {
    let env_var_name = "MY_DIRECTORY";
    if let Some(path_str) = env::var(env_var_name).ok() {
        if Path::new(&path_str).exists() {
            println!("Directory already exists at {}", path_str);
            return Ok(());
        }
    }

    let path = Path::new(directory_name);
    fs::create_dir_all(&path)?;
    env::set_var(env_var_name, path.display().to_string());

    println!("Created directory and set environment variable to: {}", path.display());

    Ok(())
}
