class SerializationManager {
public:
    using Format = std::string;

    static std::shared_ptr<SerializationManager> getInstance() {
        static std::shared_ptr<SerializationManager> instance = std::make_shared<SerializationManager>();
        return instance;
    }

    bool serialize(const CUSTOMER_TRANSACTION_RECORDS& record, const Format& format, std::string& output) {
        if (serializers_.find(format) == serializers_.end()) {
            return false; // Unsupported format
        }
        return serializers_[format]->serialize(record, output);
    }

    bool deserialize(const std::string& input, const Format& format, CUSTOMER_TRANSACTION_RECORDS& record) {
        if (deserializers_.find(format) == deserializers_.end()) {
            return false; // Unsupported format
        }
        return deserializers_[format]->deserialize(input, record);
    }

private:
    SerializationManager() {}

    std::unordered_map<Format, std::shared_ptr<Serializer>> serializers_;
    std::unordered_map<Format, std::shared_ptr<Deserializer>> deserializers_;

    class Serializer {
    public:
        virtual ~Serializer() {}
        virtual bool serialize(const CUSTOMER_TRANSACTION_RECORDS& record, std::string& output) = 0;
    };

    class Deserializer {
    public:
