import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class ProductInventoryManager {
    private static final ConcurrentHashMap<String, Product> productCache = new ConcurrentHashMap<>();
    private static final Lock lock = new ReentrantLock();

    public static void updateProduct(Product product) {
        try {
            lock.lock();
            productCache.put(product.getId(), product);
        } finally {
            lock.unlock();
        }
    }

    public static Product getProduct(String id) {
        return productCache.get(id);
    }

    public static void main(String[] args) {
        // Example usage
        Product newProduct = new Product("123", "Laptop", 100);
        updateProduct(newProduct);

        Product retrievedProduct = getProduct("123");
        System.out.println(retrievedProduct);
    }
}

class Product {
    private String id;
    private String name;
    private int quantity;

    public Product(String id, String name, int quantity) {
        this.id = id;
