#define MAX_THREADS 100
#define MAX_CONNECTIONS 50

PGconn *connections[MAX_CONNECTIONS];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_connections() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        connections[i] = PQconnectdb("host=localhost dbname=mydb user=postgres password=mypassword");
        if (PQstatus(connections[i]) != CONNECTION_OK) {
            fprintf(stderr, "Connection to database failed: %s", PQerrorMessage(connections[i]));
            exit(1);
        }
    }
}

void *process_request(void *arg) {
    // Simulate request processing
    int id = *(int *)arg;
    pthread_mutex_lock(&lock);
    PGconn *conn = connections[id % MAX_CONNECTIONS];
    char query[256];
    sprintf(query, "SELECT generate_random_value();");
    PGresult *res = PQexec(conn, query);
    if (PQresultStatus(res) != PGRES_TUPLES_OK) {
        fprintf(stderr, "Database error: %s", PQerrorMessage(conn));
    } else {
        printf("Request %d: %s\n", id, PQgetvalue(res, 0, 0));
    }
    PQclear(res);
    pthread_mutex_unlock(&lock);
    return NULL;
}

int main() {
    initialize_connections();
    int ids[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        ids[i] = i;
        pthread_t thread;
        pthread_create(&thread, NULL, process_request, &ids[i]);
        pthread_join(thread, NULL);
    }
    return 0;
}
