#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>
#include <sys/time.h>

#define MAX_THREADS 1000
#define NUM_ACQUISITIONS 10000

typedef struct {
    int value;
    sem_t *sem;
} Semaphore;

Semaphore* create_semaphore(int initial_value) {
    Semaphore *semaphore = (Semaphore*)malloc(sizeof(Semaphore));
    semaphore->value = initial_value;
    sem_init(semaphore->sem, 0, initial_value);
    return semaphore;
}

void destroy_semaphore(Semaphore *semaphore) {
    sem_destroy(semaphore->sem);
    free(semaphore);
}

int acquire_semaphore(Semaphore *semaphore) {
    return sem_wait(semaphore->sem);
}

int release_semaphore(Semaphore *semaphore) {
    return sem_post(semaphore->sem);
}

void* thread_task(void *arg) {
    Semaphore *sem = (Semaphore*)arg;
    for (int i = 0; i < NUM_ACQUISITIONS; i++) {
        acquire_semaphore(sem);
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 1; // 1 microsecond
        nanosleep(&delay, NULL);
        release_semaphore(sem);
    }
    return NULL;
}

int main() {
    Semaphore *semaphore = create_semaphore(5);
    pthread_t threads[MAX_THREADS];

    struct timeval start_time, end_time;
    gettimeofday(&start_time, NULL);

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, thread_task, semaphore);
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    gettimeofday(&end_time, NULL);
    long seconds = end_time.tv_sec - start_time.tv_sec;
    long microseconds = end_time.tv_usec - start_time.tv_usec;
    printf("Total time taken: %ld.%06ld seconds\n", seconds, microseconds);

    destroy_semaphore(semaphore);
    return 0;
}
```

This code snippet provides a basic implementation of a semaphore system in C. It includes the creation and destruction of semaphores, as well as functions to acquire and release the semaphore. The `thread_task` function simulates the behavior of threads attempting to acquire the semaphore multiple times with a small delay between each attempt. The `main` function initializes the semaphore, creates multiple threads, and measures the total time taken for all acquisitions. This is a simplified version and does not include advanced features like persistence in an external database or comprehensive error handling and logging mechanisms.']

