TX_POWER_LEVEL_STATS power_stats[MAX_POWER_STATS];
int current_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
redisContext *redis_conn;

void connect_to_redis() {
    redis_conn = redisConnect("127.0.0.1", 6379);
    if (redis_conn->err) {
        fprintf(stderr, "Redis connection error: %s\n", redis_conn->errstr);
        exit(1);
    }
}

void add_power_stats(int timestamp, int cell_identity, int power_level) {
    pthread_mutex_lock(&lock);
    if (current_count < MAX_POWER_STATS) {
        power_stats[current_count].timestamp = timestamp;
        power_stats[current_count].cell_identity = cell_identity;
        power_stats[current_count].power_level = power_level;
        current_count++;
    }
    pthread_mutex_unlock(&lock);

    char key[20];
    snprintf(key, sizeof(key), "ci:%d", cell_identity);
    redisReply *reply = (redisReply *)redisCommand(redis_conn, "SET %s %d", key, power_level);
    freeReplyObject(reply);
}

TX_POWER_LEVEL_STATS* get_latest_power_stats(int cell_identity) {
    char key[20];
    snprintf(key, sizeof(key), "ci:%d", cell_identity);
    redisReply *reply = (redisReply *)redisCommand(redis_conn, "GET %s", key);
    if (!reply || reply->type == REDIS_REPLY_NIL) {
        freeReplyObject(reply);
        return NULL;
    }

    int power_level = atoi(reply->str);
    freeReplyObject(reply);

    pthread_mutex_lock(&lock);
    for (int i = current_count - 1; i >= 0; i--) {
        if (power_stats[i].cell_identity == cell_identity) {
            return &power_stats[i];
        }
    }
    pthread_mutex_unlock(&lock);

    return NULL;
}

void* cache_update_thread(void *arg) {
    while (1) {
        // Update cache logic here
        sleep(60);  // Example: update every minute
    }
    return NULL;
}
