// Define a base class for streaming protocols
class StreamingProtocol {
public:
    virtual ~StreamingProtocol() {}
    virtual void connect(const std::string& config) = 0;
    virtual void disconnect() = 0;
    virtual void send(const std::string& data) = 0;
    virtual void receive(std::string& data) = 0;
};

// Define a factory to create instances of streaming protocols
class StreamingProtocolFactory {
public:
    static std::unique_ptr<StreamingProtocol> createProtocol(const std::string& protocolType, const std::string& config);
};

// Implement concrete classes for each streaming protocol
