    virtual void ingest(const std::string& data) = 0;
};

// Define an analytics service interface
class AnalyticsService {
public:
    virtual ~AnalyticsService() {}
    virtual void process(const std::string& data) = 0;
};

// Define a configuration class to manage user settings
class Configuration {
public:
