    DataIngestionPlatform* ingestionPlatform_;
    AnalyticsService* analyticsService_;
    std::thread processingThread_;
    std::mutex processingMutex_;
    std::condition_variable processingCondition_;
};

// Implement the factory to create instances of streaming protocols
std::unique_ptr<StreamingProtocol> StreamingProtocolFactory::createProtocol(const std::string& protocolType, const std::string& config) {
    if (protocolType == "Kafka") return std::make_unique<KafkaProtocol>();
    else if (protocolType == "MQTT") return std::make_unique<MQTTProtocol>();
    // Add other protocols as needed
