}

// Implement the SensorDataLibrary methods
void SensorDataLibrary::start() {
    processingThread_ = std::thread([this]() {
        while (true) {
            std::unique_lock<std::mutex> lock(processingMutex_);
            processingCondition_.wait(lock, [this]() { return !protocol_->receive(); });
            if (!protocol_->receive()) continue;
            lock.unlock();
            process(protocol_->receive());
        }
    });
}

void SensorDataLibrary::stop() {
    processingThread_.join();
}

void SensorDataLibrary::process(const std::string& data) {
    ingestionPlatform_->ingest(data);
    analyticsService_->process(data);
}
