void addElement(DynamicArray *arr, TX_POWER_LEVEL_STATS item) {
    if (arr->size >= arr->capacity) {
        arr->capacity = (arr->capacity == 0) ? 1 : arr->capacity * 2;
        arr->data = realloc(arr->data, arr->capacity * sizeof(TX_POWER_LEVEL_STATS));
    }
    arr->data[arr->size++] = item;
