#include <iostream>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <memory>
#include <thread>
#include <chrono>

// External identity provider interface
class IdentityProvider {
public:
    virtual std::string refreshToken(const std::string& token) = 0;
};

// User session context
struct SessionContext {
    std::string userId;
    std::string authToken;
    std::time_t lastAccessTime;

    SessionContext(std::string uid, std::string atoken)
        : userId(uid), authToken(atoken), lastAccessTime(time(nullptr)) {}
};

// Session manager module
class SessionManager {
private:
    IdentityProvider& identityProvider;
    std::unordered_map<std::string, std::shared_ptr<SessionContext>> sessions;
    mutable std::mutex sessionsMutex;
    std::condition_variable sessionUpdateCond;

public:
    explicit SessionManager(IdentityProvider& provider) : identityProvider(provider) {}

    // Create or refresh a user session
    void createOrRefreshSession(const std::string& userId, const std::string& authToken) {
        std::lock_guard<std::mutex> lock(sessionsMutex);
        if (sessions.find(userId) == sessions.end()) {
            sessions[userId] = std::make_shared<SessionContext>(userId, authToken);
        } else {
            sessions[userId]->authToken = identityProvider.refreshToken(authToken);
            sessions[userId]->lastAccessTime = time(nullptr);
        }
    }

    // Retrieve a session by user ID
    std::shared_ptr<SessionContext> getSession(const std::string& userId) {
        std::lock_guard<std::mutex> lock(sessionsMutex);
        if (sessions.find(userId) != sessions.end()) {
            return sessions[userId];
        }
        return nullptr;
    }

    // Clean up stale sessions
    void cleanUpStaleSessions() {
        while (true) {
            std::unique_lock<std::mutex> lock(sessionsMutex);
            sessionUpdateCond.wait_for(lock, std::chrono::minutes(1), [this] {
                for (const auto& entry : sessions) {
                    if (time(nullptr) - entry.second->lastAccessTime > 30 * 60) { // 30 minutes
                        return true;
                    }
                }
                return false;
            });

            for (auto it = sessions.begin(); it != sessions.end();) {
                if (time(nullptr) - it->second->lastAccessTime > 30 * 60) {
                    it = sessions.erase(it);
                } else {
                    ++it;
                }
            }
        }
    }

    // Start session cleanup thread
    void startSessionCleanupThread() {
        std::thread([this]() {
            while (true) {
                cleanUpStaleSessions();
                std::this_thread::sleep_for(std::chrono::minutes(1));
            }
        }).detach();
    }
};

int main() {
