#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *ue_id;
    int qos_params;
    // Additional session attributes
} UESessionInfo;

typedef struct Node {
    UESessionInfo data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t mutex;
} SessionList;

// Initialize the session list
void init_session_list(SessionList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

// Add or update a session in the list
int add_or_update_session(SessionList *list, UESessionInfo new_session) {
    pthread_mutex_lock(&list->mutex);
    Node *current = list->head;
    while (current != NULL) {
        if (strcmp(current->data.ue_id, new_session.ue_id) == 0) {
            // Update existing session
            current->data.qos_params = new_session.qos_params;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
        current = current->next;
    }
    // Add new session
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory allocation failed
    }
    new_node->data = new_session;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Remove a session from the list
int remove_session(SessionList *list, char *ue_id) {
    pthread_mutex_lock(&list->mutex);
    Node *current = list->head;
    Node *prev = NULL;
    while (current != NULL) {
        if (strcmp(current->data.ue_id, ue_id) == 0) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return -1; // Session not found
}

// Clean up and destroy the session list
void destroy_session_list(SessionList *list) {
    pthread_mutex_lock(&list->mutex);
    Node *current = list->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
```

