typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DynamicQueueNode {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct DynamicQueueNode *next;
} DynamicQueueNode;

typedef struct DynamicQueue {
    DynamicQueueNode *front;
    DynamicQueueNode *rear;
    pthread_mutex_t mutex;
    int size;
} DynamicQueue;

DynamicQueue* dynamic_queue_create() {
    DynamicQueue *queue = (DynamicQueue*)malloc(sizeof(DynamicQueue));
    if (queue == NULL) {
        return NULL;
    }
    queue->front = queue->rear = NULL;
    pthread_mutex_init(&queue->mutex, NULL);
    queue->size = 0;
    return queue;
}

void dynamic_queue_destroy(DynamicQueue *queue) {
    while (queue->front != NULL) {
        DynamicQueueNode *temp = queue->front;
        queue->front = queue->front->next;
        free(temp->data);
        free(temp);
    }
    pthread_mutex_destroy(&queue->mutex);
    free(queue);
}

int dynamic_queue_enqueue(DynamicQueue *queue, NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&queue->mutex);
    DynamicQueueNode *new_node = (DynamicQueueNode*)malloc(sizeof(DynamicQueueNode));
    if (new_node == NULL) {
        pthread_mutex_unlock(&queue->mutex);
        return -1;
    }
    new_node->data = data;
    new_node->next = NULL;
    if (queue->rear != NULL) {
        queue->rear->next = new_node;
    } else {
        queue->front = new_node;
    }
    queue->rear = new_node;
    queue->size++;
    pthread_mutex_unlock(&queue->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* dynamic_queue_dequeue(DynamicQueue *queue) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->front == NULL) {
        pthread_mutex_unlock(&queue->mutex);
        return NULL;
    }
    DynamicQueueNode *temp = queue->front;
    NFAPI_CRC_INDICATION_PDU_T *data = temp->data;
    queue->front = queue->front->next;
    if (queue->front == NULL) {
        queue->rear = NULL;
    }
    free(temp);
    queue->size--;
    pthread_mutex_unlock(&queue->mutex);
    return data;
}

int dynamic_queue_size(DynamicQueue *queue) {
    return queue->size;
}
