// Define a modular JavaScript library for dynamic script loading and execution

class ModuleLoader {
  constructor(cdnUrl) {
    this.cdnUrl = cdnUrl;
    this.modules = {};
    this.dependencies = {};
    this.errorHandler = console.error;
    this.debugEnabled = false;
  }

  addModule(name, src, dependencies = []) {
    if (this.modules[name]) return;
    this.modules[name] = { src, dependencies };
    for (const dep of dependencies) {
      if (!this.dependencies[dep]) this.dependencies[dep] = [];
      this.dependencies[dep].push(name);
    }
  }

  loadModule(name) {
    const module = this.modules[name];
    if (!module) return;
    if (module.loading) return;

    for (const dep of module.dependencies) {
      if (!this.modules[dep]) {
        console.warn(`Dependency ${dep} not found.`);
        continue;
      }
      if (!this.modules[dep].loaded && !this.modules[dep].loading) {
        this.loadModule(dep);
      }
    }

    const script = document.createElement('script');
    script.src = `${this.cdnUrl}/${module.src}`;
    script.onload = () => {
      this.modules[name].loaded = true;
      if (this.debugEnabled) console.log(`Loaded ${name}`);
      for (const dep of this.dependencies[name] || []) {
        this.loadModule(dep);
      }
    };
    script.onerror = (error) => {
      this.errorHandler(`Failed to load ${name}:`, error);
    };
    document.head.appendChild(script);
  }

  setErrorHandler(handler) {
    this.errorHandler = handler;
  }

  enableDebug() {
    this.debugEnabled = true;
  }
}

// Usage example
const loader = new ModuleLoader('https://cdn.example.com/modules');
loader.addModule('math', 'math.js');
loader.addModule('science', 'science.js', ['math']);
loader.loadModule('science');

// Additional features can be added to handle conditional loading, local validation,
// graceful degradation, and internationalization as per requirements.
