class ServiceInterface {
public:
    virtual ~ServiceInterface() = default;
    virtual void checkHealth() const = 0;
};

class NetworkHealthMonitor {
public:
    NetworkHealthMonitor() : running_(false) {}

    void addService(std::unique_ptr<ServiceInterface> service) {
        services_.push_back(std::move(service));
    }

    void startMonitoring() {
        if (running_) return;
        running_ = true;
        monitorThread_ = std::thread([this]() {
            while (running_) {
                for (const auto& service : services_) {
                    service->checkHealth();
                }
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
        });
    }

    void stopMonitoring() {
        running_ = false;
        if (monitorThread_.joinable()) {
            monitorThread_.join();
        }
    }

private:
    std::vector<std::unique_ptr<ServiceInterface>> services_;
    std::thread monitorThread_;
    std::atomic<bool> running_;
};

class DatabaseService : public ServiceInterface {
public:
    void checkHealth() const override {
        // Implement health check for database
        std::cout << "Database service health check" << std::endl;
    }
};

class APIService : public ServiceInterface {
public:
    void checkHealth() const override {
        // Implement health check for API
        std::cout << "API service health check" << std::endl;
    }
};

int main() {
