            CryptoAlgorithm* algo = get_algorithm_by_name(config->algorithms[i].name);
            if (algo != NULL && !algo->is_available()) {
                algo->initialize();
            }
        }

        // Sleep or poll for configuration changes
        sleep(60);  // Adjust interval as needed
    }

    return 0;
}

void* framework_monitor(void* arg) {
    while (1) {
        FrameworkConfig* config = load_config_from_service();
        if (config != NULL) {
