        DataSource(name="JSONDataSource", url="http://example.com/jsondata", schema={"key": "type"}, retry_policy={"max_retries": 3, "backoff_factor": 2}),
        DataSource(name="XMLDataSource", url="http://example.com/xmldata", schema={"tag": "type"}, retry_policy={"max_retries": 5, "backoff_factor": 4})
    ]

    for source in sources:
        data = retry_with_backoff(lambda: fetch_data(source))
        if validate_data(data, source.schema):
            print(f"Data from {source.name} is valid")
        else:
            print(f"Data from {source.name} is invalid")

if __name__ == "__main__":
    main()
```

