    // Parse command line arguments and set options in args

    if (args.directory == NULL || (args.count_words && args.summarize_sizes)) {
        fprintf(stderr, "Invalid usage.\n");
        return 1;
    }

    // Initialize logging system with timestamping and categorization

    DIR *dir;
    struct dirent *ent;
    int file_count = 0;

    if ((dir = opendir(args.directory)) != NULL) {
        while ((ent = readdir(dir)) != NULL && file_count < MAX_FILES) {
            if (strcmp(ent->d_name, ".") != 0 && strcmp(ent->d_name, "..") != 0) {
                // Process each file in a thread
                pthread_t thread;
                pthread_create(&thread, NULL, process_file, ent);
                pthread_join(thread, NULL);
                file_count++;
            }
        }
        closedir(dir);
    } else {
        perror("Error opening directory");
        return 1;
    }

    // Output results and clean up

    return 0;
}
