#include <iostream>
#include <unordered_map>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <future>
#include <chrono>

class Cache {
public:
    struct CacheItem {
        std::string data;
        std::time_t lastAccessed;
    };

private:
    std::unordered_map<std::string, CacheItem> cache;
    std::mutex mutex;
    std::condition_variable condVar;
    std::queue<std::future<void>> futures;

public:
    void put(const std::string& key, const std::string& data) {
        std::lock_guard<std::mutex> lock(mutex);
        cache[key] = {data, std::time(nullptr)};
    }

    std::string get(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = cache.find(key);
        if (it != cache.end()) {
            it->second.lastAccessed = std::time(nullptr);
            return it->second.data;
        }
        return "";
    }

    void remove(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex);
        cache.erase(key);
    }

    void startBackgroundTasks() {
        for (size_t i = 0; i < numThreads; ++i) {
            std::thread([this]() {
                while (true) {
                    std::future<void> future;
                    {
                        std::unique_lock<std::mutex> lock(mutex);
                        condVar.wait(lock, [this]() { return !futures.empty(); });
                        future = std::move(futures.front());
                        futures.pop();
                    }
                    future.get();
                }
            }).detach();
        }
    }

    void addTask(std::future<void>&& task) {
        {
            std::lock_guard<std::mutex> lock(mutex);
            futures.push(std::move(task));
        }
        condVar.notify_one();
    }

private:
    size_t numThreads = 4;
};

int main() {
    Cache cache;
    cache.startBackgroundTasks();

    // Simulate read and write operations
    auto future1 = std::async(std::launch::async, [&cache]() {
        cache.put("key1", "value1");
    });

    auto future2 = std::async(std::launch::async, [&cache]() {
        std::cout << "Value: " << cache.get("key1") << std::endl;
    });

    future1.wait();
    future2.wait();

    return 0;
}
