} log_level;

void log_message(log_level level, const char* message) {
    time_t current_time = time(NULL);
    struct tm* local_time = localtime(&current_time);
    printf("[%s] %s\n", asctime(local_time), message);
}

size_t write_callback(void* contents, size_t size, size_t nmemb, void* userp) {
    // Handle API response
    return size * nmemb;
}

int persist_record(record rec) {
    CURL* curl;
    CURLcode res;

    curl = curl_easy_init();
    if(curl) {
        char url[256];
        sprintf(url, "http://api.example.com/store?offset=%ld&key=%d", rec.offset, rec.key);

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            log_message(ERROR, "Failed to persist record: %s\n", curl_easy_strerror(res));
            return -1;
        }

        curl_easy_cleanup(curl);
    }
    return 0;
}

int persistRecords(record* records, int count, long range_start, long range_end, int retry_limit, int base_delay) {
    for(int i = 0; i < count; i++) {
        if(records[i].offset == 0 || records[i].key <= 0) {
            log_message(ERROR, "Invalid record encountered at index %d\n", i);
            return -1;
        }

        int retry_count = 0;
        while(retry_count <= retry_limit) {
            if(persist_record(records[i]) == 0) {
                break;
            }
            retry_count++;
            if(retry_count < retry_limit) {
                sleep(base_delay * pow(2, retry_count));
            }
        }

        if(retry_count > retry_limit) {
            log_message(ERROR, "Failed to persist record after %d retries\n", retry_limit);
            return -1;
        }
    }
    return 0;
}

int main() {
    int count = 10;
    long range_start = 0;
    long range_end = 1000;
    int retry_limit = 5;
    int base_delay = 1;

    record* records = (record*)malloc(count * sizeof(record));
    if(records == NULL) {
        log_message(ERROR, "Failed to allocate memory for records\n");
        return -1;
    }

    srand(time(NULL));
    for(int i = 0; i < count; i++) {
        records[i].offset = rand() % (range_end - range_start + 1) + range_start;
        records[i].key = rand() % (range_end - range_start + 1) + range_start;
    }

    if(persistRecords(records, count, range_start, range_end, retry_limit, base_delay) != 0) {
        log_message(ERROR, "Failed to persist all records\n");
        free(records);
        return -1;
    }

    free(records);
    return 0;
}
