#define MAX_CLIENTS 100
#define BUFFER_SIZE 256

typedef struct {
    char key[BUFFER_SIZE];
    char value[BUFFER_SIZE];
    int version;
} KeyValue;

KeyValue data[MAX_CLIENTS * 100]; // Assuming each client can store 100 entries
int data_count = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* handle_client(void* arg) {
    int client_id = *(int*)arg;
    char buffer[BUFFER_SIZE];

    // Simulate client operations
    while (1) {
        pthread_mutex_lock(&lock);
        if (data_count == 0) {
            pthread_cond_wait(&cond, &lock);
        }
        for (int i = 0; i < data_count; i++) {
            sprintf(buffer, "Key: %s, Value: %s", data[i].key, data[i].value);
            printf("Client %d read entry: %s\n", client_id, buffer);
        }
        pthread_mutex_unlock(&lock);
        sleep(1); // Simulate processing time
    }

    return NULL;
}

int main() {
    pthread_t clients[MAX_CLIENTS];
    int client_ids[MAX_CLIENTS];

    for (int i = 0; i < MAX_CLIENTS; i++) {
        client_ids[i] = i;
        pthread_create(&clients[i], NULL, handle_client, &client_ids[i]);
    }

    // Simulate data insertion
    pthread_mutex_lock(&lock);
    strcpy(data[data_count].key, "key1");
    strcpy(data[data_count].value, "value1");
    data[data_count].version = 0;
    data_count++;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&lock);

    sleep(10); // Allow clients to process

    for (int i = 0; i < MAX_CLIENTS; i++) {
        pthread_join(clients[i], NULL);
    }

    return 0;
}
