#include <atomic>
#include <future>
#include <chrono>

class PreferenceManager {
public:
    void addPreference(const std::string& deviceId, const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (preferences_.find(deviceId) == preferences_.end()) {
            preferences_[deviceId] = {};
        }
        preferences_[deviceId][key] = value;
    }

    void updatePreference(const std::string& deviceId, const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (preferences_.find(deviceId) != preferences_.end()) {
            preferences_[deviceId][key] = value;
        }
    }

    void deletePreference(const std::string& deviceId, const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (preferences_.find(deviceId) != preferences_.end()) {
            preferences_[deviceId].erase(key);
        }
    }

private:
    std::unordered_map<std::string, std::unordered_map<std::string, std::string>> preferences_;
    std::mutex mutex_;
};

class CloudService {
public:
    void syncPreferences(const PreferenceManager& preferenceManager) {
