namespace ImageMetadataExtractor {

class ImageFile {
public:
    virtual ~ImageFile() = default;
    virtual std::string getBitsPerSample() const = 0;
    virtual std::string getSamplesPerPixel() const = 0;
    virtual std::string getCompressionType() const = 0;
};

class TiffImage : public ImageFile {
public:
    TiffImage(const std::string& path) {
        if (!(tif = TIFFOpen(path.c_str(), "r"))) {
            throw std::runtime_error("Failed to open TIFF file: " + path);
        }
    }

    ~TiffImage() override {
        TIFFClose(tif);
    }

    std::string getBitsPerSample() const override {
        uint16 bitsPerSample;
        if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bitsPerSample)) {
            return std::to_string(bitsPerSample);
        }
        return "N/A";
    }

    std::string getSamplesPerPixel() const override {
        uint16 samplesPerPixel;
        if (TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel)) {
            return std::to_string(samplesPerPixel);
        }
        return "N/A";
    }

    std::string getCompressionType() const override {
        uint16 compression;
        if (TIFFGetField(tif, TIFFTAG_COMPRESSION, &compression)) {
            switch (compression) {
                case COMPRESSION_NONE:
                    return "None";
                case COMPRESSION_LZW:
                    return "LZW";
                case COMPRESSION_PACKBITS:
                    return "PackBits";
                default:
                    return "Unknown";
            }
        }
        return "N/A";
    }

private:
    TIFF* tif;
};

class ImageMetadataExtractor {
public:
    static std::shared_ptr<ImageFile> createImageFile(const std::string& path) {
        const std::string extension = path.substr(path.find_last_of(".") + 1);
        if (extension == "tif" || extension == "tiff") {
            return std::make_shared<TiffImage>(path);
        }
        throw std::runtime_error("Unsupported image format: " + extension);
    }

    static void extractMetadata(const std::string& path, const std::string& xpath) {
        try {
            auto imageFile = createImageFile(path);
            std::cout << "Bits per sample: " << imageFile->getBitsPerSample() << std::endl;
            std::cout << "Samples per pixel: " << imageFile->getSamplesPerPixel() << std::endl;
            std::cout << "Compression type: " << imageFile->getCompressionType() << std::endl;

            // Parse XML metadata and extract using XPath
            boost::property_tree::ptree pt;
            read_xml(path, pt);
            auto xpathResult = pt.get_child_optional(xpath);
            if (xpathResult) {
                std::cout << "XPath result: " << xpathResult->data() << std::endl;
            } else {
                std::cout << "XPath not found" << std::endl;
            }
        } catch (const std::exception& e) {
            std::cerr << "Error extracting metadata from " << path << ": " << e.what() << std::endl;
        }
    }
};

} // namespace ImageMetadataExtractor

int main() {
    try {
        ImageMetadataExtractor::extractMetadata("example.tiff", "//xpath/expression");
    } catch (const std::exception& e) {
        std::cerr << "Error in main: " << e.what() << std::endl;
    }
    return 0;
}
```

