import hashlib
import os
import asyncio
from typing import Optional, Callable
import logging

class FileHasher:
    def __init__(self, log_function: Callable[[str], None]):
        self.log_function = log_function

    async def _hash_file_async(self, file_path: str) -> str:
        hash_md5 = hashlib.md5()
        try:
            with open(file_path, "rb") as f:
                for chunk in iter(lambda: f.read(4096), b""):
                    hash_md5.update(chunk)
            return hash_md5.hexdigest()
        except FileNotFoundError:
            self.log_function(f"Error: File not found {file_path}")
            raise
        except Exception as e:
            self.log_function(f"Error: Failed to read file {file_path}: {e}")
            raise

    def hash_file_sync(self, file_path: str) -> str:
        try:
            with open(file_path, "rb") as f:
                hash_md5 = hashlib.md5()
                for chunk in iter(lambda: f.read(4096), b""):
                    hash_md5.update(chunk)
                return hash_md5.hexdigest()
        except FileNotFoundError:
            self.log_function(f"Error: File not found {file_path}")
            raise
        except Exception as e:
            self.log_function(f"Error: Failed to read file {file_path}: {e}")
            raise

    async def validate_hash_async(self, file_path: str, expected_hash: str) -> bool:
        try:
            computed_hash = await self._hash_file_async(file_path)
            return computed_hash == expected_hash
        except Exception as e:
            self.log_function(f"Error during hash validation: {e}")
            raise

    def validate_hash_sync(self, file_path: str, expected_hash: str) -> bool:
        try:
            computed_hash = self.hash_file_sync(file_path)
            return computed_hash == expected_hash
        except Exception as e:
            self.log_function(f"Error during hash validation: {e}")
            raise

    async def _log_task_async(self, task_name: str):
        try:
            await asyncio.sleep(1)  # Simulate logging delay
            self.log_function(f"{task_name} completed successfully")
        except Exception as e:
            self.log_function(f"Error logging {task_name}: {e}")

    def log_task_sync(self, task_name: str):
        try:
            asyncio.run(self._log_task_async(task_name))
        except Exception as e:
            self.log_function(f"Error during log operation: {e}")
