// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for a node in the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the structure for the linked list
typedef struct LinkedList {
    Node* head;
    pthread_mutex_t mutex; // Mutex for thread-safe operations
} LinkedList;

// Function to initialize the linked list
void init_list(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

// Function to insert a new element into the linked list
int insert_element(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Allocation failure
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

// Function to validate an element in the linked list
int validate_element(LinkedList* list, RNTI rnti) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            // Perform validation logic here
            pthread_mutex_unlock(&list->mutex);
            return 1; // Validation successful
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return 0; // Element not found
}

// Function to export the linked list to a file
int export_list(LinkedList* list, const char* filename) {
    pthread_mutex_lock(&list->mutex);
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // File I/O failure
    }
    Node* current = list->head;
    while (current != NULL) {
        fprintf(file, "%d %d %d\n", current->data.rx_ue_info_tag, current->data.rnti, current->data.crcflag);
        current = current->next;
    }
    fclose(file);
    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

// Function to free the linked list
void free_list(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_destroy(&list->mutex);
    pthread_mutex_unlock(&list->mutex);
}
