class FsaManager {
private:
    std::vector<State> states;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void addState(const State& state) {
        std::lock_guard<std::mutex> lock(mtx);
        states.push_back(state);
        cv.notify_one();
    }

    void removeState(int id) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this, id] { return find_if(states.begin(), states.end(), [id](const State& s) { return s.id == id; }) != states.end(); });
        auto it = find_if(states.begin(), states.end(), [id](const State& s) { return s.id == id; });
        if (it != states.end()) {
            states.erase(it);
        }
    }

    std::vector<State> getStates() {
        std::lock_guard<std::mutex> lock(mtx);
        return states;
    }
};

int main() {
    FsaManager manager;

    // Adding states
    manager.addState(State(1, "Initial State"));
    manager.addState(State(2, "Intermediate State"));

    // Retrieving states
    std::vector<State> currentStates = manager.getStates();
    for (const auto& state : currentStates) {
        std::cout << "State ID: " << state.id << ", Data: " << state.data << std::endl;
    }

    // Removing a state
    manager.removeState(1);

    return 0;
}
```

This code snippet demonstrates a simple implementation of an FSA state manager using C++. It includes basic functionalities to add, remove, and retrieve states. The use of `std::mutex` ensures thread safety during state operations, while `std::condition_variable` is used for synchronization between threads. This example can be expanded with additional features such as error handling, logging, and concurrency control mechanisms to meet the requirements of a high-performance library.']

