// Include necessary headers
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define constants
#define MAX_SENSORS 100
#define READINGS_PER_DAY 1000

// Define data structures
typedef struct SensorData {
    float readings[READINGS_PER_DAY];
    int count;
} SensorData;

typedef struct TemperatureLibrary {
    SensorData sensors[MAX_SENSORS];
    pthread_mutex_t lock;
    int logging_level;
    void (*log_callback)(const char* message);
} TemperatureLibrary;

// Function prototypes
void initialize_library(TemperatureLibrary* lib, int logging_level, void (*log_cb)(const char*));
int add_reading(TemperatureLibrary* lib, int sensor_id, float reading);
SensorData* get_sensor_data(TemperatureLibrary* lib, int sensor_id);
void log_message(const char* message);

// Initialize the library
void initialize_library(TemperatureLibrary* lib, int logging_level, void (*log_cb)(const char*)) {
    lib->logging_level = logging_level;
    lib->log_callback = log_cb;
    pthread_mutex_init(&lib->lock, NULL);
    for (int i = 0; i < MAX_SENSORS; i++) {
        lib->sensors[i].count = 0;
    }
}

// Add a temperature reading
int add_reading(TemperatureLibrary* lib, int sensor_id, float reading) {
    if (sensor_id < 0 || sensor_id >= MAX_SENSORS) return -1;
    pthread_mutex_lock(&lib->lock);
    SensorData* data = &lib->sensors[sensor_id];
    if (data->count >= READINGS_PER_DAY) {
        pthread_mutex_unlock(&lib->lock);
        return -2; // Too many readings
    }
    data->readings[data->count++] = reading;
    log_message("Reading added");
    pthread_mutex_unlock(&lib->lock);
    return 0;
}

// Get sensor data
SensorData* get_sensor_data(TemperatureLibrary* lib, int sensor_id) {
    if (sensor_id < 0 || sensor_id >= MAX_SENSORS) return NULL;
    SensorData* data = &lib->sensors[sensor_id];
    return data;
}

// Log a message with conditional logging based on level
void log_message(const char* message) {
    if (log_callback != NULL) {
        (*log_callback)(message);
    }
}
