@RestController
@RequestMapping("/api/v1/inventory")
public class InventoryController {

    @Autowired
    private InventoryItemRepository inventoryItemRepository;

    @Autowired
    private CacheManager cacheManager;

    @GetMapping("/{id}")
    public ResponseEntity<InventoryItem> getInventoryItem(@PathVariable Long id) {
        String cacheKey = "inventory:" + id;
        InventoryItem item = (InventoryItem) cacheManager.getCache("inventoryCache").get(cacheKey).get();
        if (item == null) {
            Optional<InventoryItem> optionalItem = inventoryItemRepository.findById(id);
            item = optionalItem.orElseGet(() -> new InventoryItem());
            cacheManager.getCache("inventoryCache").put(cacheKey, item);
        }
        return ResponseEntity.ok(item);
    }

    @PostMapping
    public ResponseEntity<InventoryItem> createInventoryItem(@RequestBody InventoryItem item) {
        InventoryItem savedItem = inventoryItemRepository.save(item);
        cacheManager.getCache("inventoryCache").put("inventory:" + savedItem.getId(), savedItem);
        return ResponseEntity.status(HttpStatus.CREATED).body(savedItem);
    }

    @PutMapping("/{id}")
    public ResponseEntity<InventoryItem> updateInventoryItem(@PathVariable Long id, @RequestBody InventoryItem newItem) {
        Optional<InventoryItem> existingItem = inventoryItemRepository.findById(id);
        if (existingItem.isPresent()) {
            InventoryItem updatedItem = existingItem.get();
            updatedItem.setName(newItem.getName());
            updatedItem.setDescription(newItem.getDescription());
            updatedItem.setPrice(newItem.getPrice());
            updatedItem.setStockQuantity(newItem.getStockQuantity());
            updatedItem.setCategoryId(newItem.getCategoryId());
            InventoryItem savedItem = inventoryItemRepository.save(updatedItem);
            cacheManager.getCache("inventoryCache").put("inventory:" + id, savedItem);
            return ResponseEntity.ok(savedItem);
        }
        return ResponseEntity.notFound().build();
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteInventoryItem(@PathVariable Long id) {
        if (inventoryItemRepository.existsById(id)) {
            inventoryItemRepository.deleteById(id);
            cacheManager.getCache("inventoryCache").evict("inventory:" + id);
            return ResponseEntity.noContent().build();
        }
        return ResponseEntity.notFound().build();
    }
}

