logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class FileService:
    def __init__(self, config_file):
        self.config_file = config_file
        self.buckets = self.load_buckets()

    def load_buckets(self):
        with open(self.config_file, 'r') as file:
            buckets = [line.strip() for line in file.readlines()]
        return buckets

    def compute_md5(self, bucket, key):
        try:
            s3 = boto3.client('s3')
            response = s3.get_object(Bucket=bucket, Key=key)
            hash_obj = hashlib.md5()
            for chunk in iter(lambda: response['Body'].read(4096), b''):
                hash_obj.update(chunk)
            return hash_obj.hexdigest()
        except (NoCredentialsError, PartialCredentialsError) as e:
            logger.error(f"Authentication error: {e}")
            raise
        except Exception as e:
            logger.error(f"Error computing MD5 for {bucket}/{key}: {e}")
            raise

    def process_files_concurrently(self):
        with ThreadPoolExecutor() as executor:
            futures = {executor.submit(self.compute_md5, bucket, key): (bucket, key) for bucket in self.buckets}
            for future in as_completed(futures):
                bucket, key = futures[future]
                try:
                    md5_hash = future.result()
                    # Persist MD5 hash in distributed database here
