// Global dependencies for the batchUploadAndInsert function
DistributedLogger distributedLogger;
KeyValueStore keyValueStore;
CommandExecutor commandExecutor;
ExternalLogger externalLogger;

// Atomic flag to control shutdown
std::atomic<bool> isShuttingDown(false);

// Function to handle log insertion
void insertLog(const FileURL& url, const LogEntry& data) {
    if (!keyValueStore.insert(url, data)) {
        distributedLogger.log("Failed to insert log for URL: " + url);
    }
}

// Function to handle file uploads
void uploadFile(const FileURL& url, const std::string& format) {
    // Simulate file upload logic
    externalLogger.logCommandOutput(url, "Upload completed");
}

// Function to execute commands asynchronously
void executeCommandAsync(const FileURL& url, std::function<void()> callback) {
    commandExecutor.execute(url, callback);
}

// Main function for batch insertion and file uploads
void batchUploadAndInsert(const std::vector<FileURL>& urls, const LogEntry& logData, bool isAsynchronous = true) {
    if (urls.empty()) {
        distributedLogger.log("Empty batch provided");
        return;
    }

    std::mutex mutex;
    std::condition_variable cv;
    int completedTasks = 0;

    for (const auto& url : urls) {
        if (!isShuttingDown) {
            ++completedTasks;

            // Insert log entry
            insertLog(url, logData);

            // Upload file
            if (isAsynchronous) {
                executeCommandAsync(url, [url]() {
                    uploadFile(url, "default_format");
                });
            } else {
                uploadFile(url, "default_format");
            }

            std::lock_guard<std::mutex> lock(mutex);
            cv.notify_one();
        }
    }

    // Wait for all tasks to complete
    while (completedTasks > 0) {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [completedTasks]() { return completedTasks == 0; });
        --completedTasks;
    }
}

// Graceful shutdown function
void gracefulShutdown() {
    isShuttingDown.store(true);
}
