#include <iostream>
#include <fstream>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <vector>
#include <unordered_map>
#include <chrono>

enum class LogLevel { DEBUG, INFO, WARN, ERROR, FATAL };

class Logger {
private:
    static std::unique_ptr<Logger> instance;
    std::queue<std::string> logQueue;
    std::mutex queueMutex;
    std::condition_variable cv;
    std::atomic<bool> running{true};
    std::vector<std::thread> workers;

    Logger() {
        for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
            workers.emplace_back([this]() {
                while (running) {
                    std::unique_lock<std::mutex> lock(queueMutex);
                    cv.wait(lock, [this] { return !logQueue.empty() || !running; });
                    if (!running && logQueue.empty()) break;
                    auto log = logQueue.front();
                    logQueue.pop();
                    lock.unlock();
                    processLog(log);
                }
            });
        }
    }

public:
    static Logger& getInstance() {
        if (!instance) instance.reset(new Logger());
        return *instance;
    }

    void log(const std::string& message, LogLevel level = LogLevel::INFO) {
        // Add timestamp and log level to the message
        std::ostringstream oss;
        oss << "[" << getTimestamp() << "] [" << toString(level) << "] " << message;
        auto logMessage = oss.str();

        // Enqueue the log message for asynchronous processing
        std::unique_lock<std::mutex> lock(queueMutex);
        logQueue.push(logMessage);
        cv.notify_one();
    }

    void stop() {
        running = false;
        cv.notify_all();
        for (auto& worker : workers) worker.join();
    }

private:
    static std::string getTimestamp() {
        auto now = std::chrono::system_clock::now();
        auto in_time_t = std::chrono::system_clock::to_time_t(now);
        std::ostringstream oss;
        oss << std::put_time(std::localtime(&in_time_t), "%Y-%m-%d %X");
        return oss.str();
    }

    static std::string toString(LogLevel level) {
        switch (level) {
            case LogLevel::DEBUG: return "DEBUG";
            case LogLevel::INFO:  return "INFO";
            case LogLevel::WARN:  return "WARN";
            case LogLevel::ERROR: return "ERROR";
            case LogLevel::FATAL: return "FATAL";
        }
        return "UNKNOWN";
    }

    void processLog(const std::string& logMessage) {
        // Implement backend storage logic here
        // Example: write to file, send to external API, etc.
        std::cout << logMessage << std::endl; // Placeholder for actual implementation
    }
};

std::unique_ptr<Logger> Logger::instance = nullptr;

int main() {
    Logger& logger = Logger::getInstance();
    logger.log("Application started", LogLevel::INFO);

    // Simulate logging from different threads
    std::thread t1([&logger]() {
        for (int i = 0; i < 100; ++i) {
            logger.log("Thread 1 log entry " + std::to_string(i), LogLevel::DEBUG);
        }
    });

    std::thread t2([&logger]() {
        for (int i = 0; i < 100; ++i) {
            logger.log("Thread 2 log entry " + std::to_string(i), LogLevel::INFO);
        }
    });

    t1.join();
    t2.join();

    logger.stop();
    return 0;
}
