const retry = require('async-retry');

class PaymentGatewayKit {
  constructor(config) {
    this.config = config;
    this.fraudDetectionUrl = config.fraudDetectionUrl;
    this.paymentProcessorUrl = config.paymentProcessorUrl;
    this.notificationServiceUrl = config.notificationServiceUrl;
    this.rateLimiter = rateLimit({
      windowMs: 1 * 60 * 1000, // 1 minute
      max: 100, // limit each IP to 100 requests per windowMs
    });
  }

  async createTransaction(payload) {
    return this.processRequest('create', payload);
  }

  async updateTransaction(payload) {
    return this.processRequest('update', payload);
  }

  async refundTransaction(payload) {
    return this.processRequest('refund', payload);
  }

  async cancelTransaction(payload) {
    return this.processRequest('cancel', payload);
  }

  async processRequest(action, payload) {
    const { transactionId, amount, currency, payerInfo, paymentMethod } = payload;
    if (!this.validatePayload(payload)) throw new Error('Invalid payload');

    let response;
    try {
      await this.rateLimiter();
      await retry(async bail => {
        response = await axios.post(`${this.paymentProcessorUrl}/${action}`, payload);
      });
      const fraudDetectionResult = await this.fraudDetectionService(payload);
      if (fraudDetectionResult.isFraudulent) throw new Error('Fraudulent transaction');
    } catch (error) {
      this.logError(error);
      bail(error);
    }

    await this.notificationService(action, response.data);

    return response.data;
  }

  validatePayload(payload) {
    // Add validation logic here
    return true;
  }

  async fraudDetectionService(payload) {
    const { data } = await axios.post(this.fraudDetectionUrl, payload);
    return data;
  }

  async notificationService(action, result) {
    const message = `Transaction ${action} with ID ${result.transactionId}: ${JSON.stringify(result)}`;
    await axios.post(this.notificationServiceUrl, { message });
  }

  logError(error) {
    // Log error using an external service (ELK Stack or AWS CloudWatch)
  }
}

module.exports = PaymentGatewayKit;
