class DeviceStatusManager:
    def __init__(self):
        self.device_store = {}
        self.redis_cache = RedisClient()

    def get_device_status(self, device_id):
        return self.device_store.get(device_id)

    def update_device_status(self, device_id, status):
        if device_id not in self.device_store:
            self.device_store[device_id] = {'version': 1}

        version = self.device_store[device_id]['version'] + 1
        self.device_store[device_id] = {'status': status, 'version': version}
        self.redis_cache.set(device_id, status)

    def delete_device_status(self, device_id):
