```javascript
const express = require('express');
const fs = require('fs');
const path = require('path');
const axios = require('axios');

const app = express();
app.use(express.json());

const config = {
    directories: ['/path/to/directories'],
    fileExtensions: ['.txt', '.csv'],
    concurrencyLimit: 100,
    performanceThresholds: {}
};

let activeTasks = 0;
let taskQueue = [];

function processFile(filePath) {
    if (activeTasks >= config.concurrencyLimit) {
        return new Promise((resolve, reject) => {
            taskQueue.push({ filePath, resolve, reject });
        });
    }

    const startTime = Date.now();
    fs.readFile(filePath, 'utf8', async (err, data) => {
        if (err) {
            console.error(`Error reading file ${filePath}:`, err);
            return;
        }

        try {
            const metadata = await validateMetadata(data);
            if (!metadata.valid) {
                console.warn(`Invalid metadata for file ${filePath}`);
                return;
            }

            // Process the file
            console.log(`Processing file ${filePath}`);
            activeTasks++;
            const endTime = Date.now();
            const duration = endTime - startTime;

            if (duration > config.performanceThresholds[getFileType(filePath)]) {
                console.warn(`File processing exceeded threshold: ${duration}ms`);
            }

            // Resolve all tasks waiting for concurrency
            while (taskQueue.length > 0 && activeTasks < config.concurrencyLimit) {
                const { filePath, resolve } = taskQueue.shift();
                processFile(filePath).then(resolve);
            }
        } catch (error) {
            console.error(`Error processing file ${filePath}:`, error);
        } finally {
            activeTasks--;
        }
    });
}

async function validateMetadata(metadata) {
    try {
        const response = await axios.get('https://metadata-service.com/validate', { params: { metadata } });
        return response.data;
    } catch (error) {
        console.error(`Error validating metadata:`, error);
        return { valid: false };
    }
}

function getFileType(filePath) {
    const extname = path.extname(filePath).toLowerCase();
    for (const ext of config.fileExtensions) {
        if (ext === extname) {
            return ext;
        }
    }
    return null;
}

app.post('/process', async (req, res) => {
    try {
        const { directories, fileExtensions, concurrencyLimit, performanceThresholds } = req.body;
        Object.assign(config, { directories, fileExtensions, concurrencyLimit, performanceThresholds });
        taskQueue = [];
        activeTasks = 0;

        config.directories.forEach(dir => {
            fs.readdirSync(dir).forEach(file => {
                const filePath = path.join(dir, file);
                if (fs.lstatSync(filePath).isFile()) {
                    processFile(filePath);
                }
            });
        });

        res.status(200).json({ message: 'Processing started' });
    } catch (error) {
        console.error('Error starting processing:', error);
        res.status(500).json({ error: 'Failed to start processing' });
    }
});

app.listen(3000, () => {
    console.log('Service listening on port 3000');
});
```

