import java.io.IOException;
import java.util.Random;
import java.util.concurrent.TimeUnit;

public class ServiceSimulator {
    private static final String SERVICE_URL = "http://localhost:3000/process";
    private static final Random RANDOM = new Random();
    private static boolean serviceRunning = true;

    public static void main(String[] args) throws IOException, InterruptedException {
        while (true) {
            int delay = RANDOM.nextInt(60) * 1000; // Random delay between 0 and 59 seconds
            System.out.println("Waiting for " + delay / 1000 + " seconds before next restart...");
            TimeUnit.SECONDS.sleep(delay);

            if (!serviceRunning) {
                startService();
            }

            int stopDelay = RANDOM.nextInt(60) * 1000; // Random delay between 0 and 59 seconds
            System.out.println("Waiting for " + stopDelay / 1000 + " seconds before next stop...");
            TimeUnit.SECONDS.sleep(stopDelay);

            if (serviceRunning) {
                stopService();
            }
        }
    }

    private static void startService() {
        try {
            ProcessBuilder pb = new ProcessBuilder("node", "/path/to/your/nodejs/service.js");
            pb.redirectErrorStream(true);
            Process process = pb.start();

            serviceRunning = true;
            System.out.println("Node.js service started");

            // Simulate sending messages to a messaging system
            sendServiceStatus(process);
        } catch (IOException e) {
            System.err.println("Failed to start Node.js service: " + e.getMessage());
        }
    }

    private static void stopService() {
        try {
            if (serviceRunning) {
                Process process = Runtime.getRuntime().exec("pkill -f nodejs");
                process.waitFor();
                serviceRunning = false;
                System.out.println("Node.js service stopped");
            }
        } catch (IOException | InterruptedException e) {
            System.err.println("Failed to stop Node.js service: " + e.getMessage());
        }
    }

    private static void sendServiceStatus(Process process) throws IOException, InterruptedException {
        while (!process.isAlive()) {
            Thread.sleep(100);
        }

        // Simulate sending messages
        Runtime.getRuntime().exec("echo 'Service is running' | nc localhost 5672");
        Runtime.getRuntime().exec("echo 'Service is stopped' | nc localhost 5672");
    }
}
```

