import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.apache.kafka.clients.consumer.ConsumerRecords;
import com.fasterxml.jackson.databind.ObjectMapper;

public class LogProcessingSystem {
    private ExecutorService consumerExecutor;
    private ObjectMapper objectMapper = new ObjectMapper();

    public LogProcessingSystem(int numberOfConsumers) {
        this.consumerExecutor = Executors.newFixedThreadPool(numberOfConsumers);
    }

    public void start() {
        // Start Kafka consumer threads
        for (int i = 0; i < numberOfConsumers; i++) {
            int id = i;
            consumerExecutor.submit(() -> consumeLogs(id));
        }
    }

    private void consumeLogs(int consumerId) {
        // Kafka consumer logic here
        while (true) {
            ConsumerRecords<String, String> records = kafkaConsumer.poll(Duration.ofMillis(100));
            for (ConsumerRecord<String, String> record : records) {
                LogEntry logEntry = objectMapper.readValue(record.value(), LogEntry.class);
                processLogEntry(logEntry, consumerId);
            }
        }
    }

    private void processLogEntry(LogEntry logEntry, int consumerId) {
        // Process the log entry
        if (logEntry.getStream().equals("kafka")) {
            kafkaProcessor.process(logEntry);
        } else if (logEntry.getStream().equals("http")) {
            httpProcessor.process(logEntry);
        } else if (logEntry.getStream().equals("grpc")) {
            grpcProcessor.process(logEntry);
        }
    }

    public void stop() {
        consumerExecutor.shutdown();
    }

    // Assume these classes and methods are defined elsewhere
    private KafkaConsumer<String, String> kafkaConsumer;
    private LogProcessor kafkaProcessor;
    private HttpProcessor httpProcessor;
    private GrpcProcessor grpcProcessor;

    private static class LogEntry {
        private String stream;
        private String content;

        // Getters and setters
    }
}
