        if (apiEndpoint == null)
        {
            Console.WriteLine("Invalid API endpoint provided.");
            return;
        }

        try
        {
            var data = await GetDataFromCacheOrFetchAsync(apiEndpoint, sourceType);
            DisplayData(data);
        }
        catch (Exception ex)
        {
            HandleError(ex);
        }
