    private string GetValidApiEndpoint(string sourceType)
    {
        if (_apiEndpoints.Contains(sourceType))
        {
            return sourceType;
        }
        else
        {
            Console.WriteLine($"Warning: Source type {sourceType} is not supported. Using default.");
            return _apiEndpoints[0];
        }
    }

    private async Task<byte[]> GetDataFromCacheOrFetchAsync(string apiEndpoint, string sourceType)
    {
        if (_cacheExpiryTimes.ContainsKey(apiEndpoint) && DateTime.Now < _cacheExpiryTimes[apiEndpoint])
        {
            return _dataCache[apiEndpoint];
        }
        else
        {
            var data = await FetchDataAsync(apiEndpoint);
            _cacheExpiryTimes[apiEndpoint] = DateTime.Now.AddMinutes(10); // Example expiry time
            _dataCache[apiEndpoint] = data;
            return data;
        }
