const redis = require('redis');
const RateLimit = require('rate-limit');

const app = express();
app.use(express.json());
app.use(cors());

// Redis client setup
const redisClient = redis.createClient({
  host: 'localhost',
  port: 6379,
});

redisClient.on('error', (err) => {
  console.error('Redis error:', err);
});

// Rate limiting middleware
const limiter = new RateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
});

app.use(limiter);

// External API keys and tokens
const externalAPIToken = process.env.EXTERNAL_API_TOKEN;
const anotherExternalAPIToken = process.env.ANOTHER_EXTERNAL_API_TOKEN;

// Function to fetch data from an external API with caching
async function fetchDataFromAPI(url, key) {
  const cachedData = await redisClient.get(key);
  if (cachedData) {
    return JSON.parse(cachedData);
  }

  try {
    const response = await axios.get(url, {
      headers: {
        Authorization: `Bearer ${externalAPIToken}`,
      },
    });
    await redisClient.setex(key, 3600, JSON.stringify(response.data)); // Cache for 1 hour
    return response.data;
  } catch (error) {
    console.error('Error fetching data from API:', error);
    throw error;
  }
}

// Route to validate and retrieve real-time data
app.get('/data/:field', async (req, res) => {
  const field = req.params.field;
  const url = `https://api.example.com/data/${field}`;
  const cacheKey = `data:${field}`;

  try {
    const data = await fetchDataFromAPI(url, cacheKey);
    res.json(data);
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch data' });
  }
});

