import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class UserActivityAggregator {

    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final ConcurrentHashMap<String, Session> sessions = new ConcurrentHashMap<>();

    public void processLog(String userId, long timestamp) {
        executor.submit(() -> {
            synchronized (sessions) {
                sessions.computeIfAbsent(userId, u -> new Session()).addActivity(timestamp);
            }
        });
    }

    public double getAverageSessionDuration(String userId) {
        Session session = sessions.get(userId);
        if (session == null || session.getSessionCount() < 2) {
            return 0;
        }
        long totalDuration = session.getTotalDuration();
        int validSessions = (int) Math.max(1, totalDuration / 600); // exclude sessions shorter than 10 minutes
        return (double) validSessions * 10; // Convert back to minutes for average duration
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }

    private static class Session {
        private final long[] timestamps;
        private int count;

        public Session() {
            timestamps = new long[1024]; // Initial capacity
            count = 0;
        }

        public void addActivity(long timestamp) {
            if (count == timestamps.length) {
                timestamps = java.util.Arrays.copyOf(timestamps, timestamps.length * 2);
            }
            timestamps[count++] = timestamp;
        }

        public long getTotalDuration() {
            long totalDuration = 0;
            for (int i = 1; i < count; i++) {
                totalDuration += timestamps[i] - timestamps[i - 1];
            }
            return totalDuration;
        }

        public int getSessionCount() {
            return count;
        }
    }
}
