import io.grpc.netty.shaded.io.netty.channel.nio.NioEventLoopGroup;
import io.grpc.netty.shaded.io.netty.channel.socket.nio.NioServerSocketChannel;

public class SecureTLSGrpcServer {

    private Server server;

    public void start() throws Exception {
        EventLoopGroup bossGroup = new NioEventLoopGroup(1);
        EventLoopGroup workerGroup = new NioEventLoopGroup();
        try {
            server = ServerBuilder.forPort(8443)
                    .addService(new MyServiceImpl())
                    .useTransportSecurity(new File("server.crt"), new File("server.key"))
                    .bossGroup(bossGroup)
                    .workerGroup(workerGroup)
                    .build()
                    .start();
            Runtime.getRuntime().addShutdownHook(new Thread(() -> {
                try {
                    SecureTLSGrpcServer.this.stop();
                } catch (InterruptedException e) {
                    e.printStackTrace(System.err);
                }
            }));
            server.awaitTermination();
        } finally {
            bossGroup.shutdownGracefully();
            workerGroup.shutdownGracefully();
        }
    }

    private void stop() throws InterruptedException {
        if (server != null) {
            server.shutdown().awaitTermination(30, TimeUnit.SECONDS);
        }
    }

    public static void main(String[] args) throws Exception {
        final SecureTLSGrpcServer server = new SecureTLSGrpcServer();
        server.start();
    }
}
