// Define the external data stores
trait DataStore {
    fn store(&self, key: &str, value: &[u8]) -> Result<(), String>;
    fn retrieve(&self, key: &str) -> Result<Vec<u8>, String>;
}

struct LocalFileSystem;
impl DataStore for LocalFileSystem {
