["```sql
CREATE PROCEDURE GetEmployeeDetails
    @SupervisorID INT = NULL,
    @Department VARCHAR(255) = NULL,
    @JobTitle VARCHAR(255) = NULL,
    @PageNumber INT,
    @PageSize INT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SQL NVARCHAR(MAX);

    SET @SQL = '
        SELECT TOP (@PageSize)
            e.EmployeeID, 
            e.Name, 
            e.City, 
            e.Address,
            api.Data1,
            api.Data2
        FROM Employees e WITH (NOLOCK)
        LEFT JOIN (
            SELECT EmployeeID, Data1, Data2
            FROM ExternalAPIs WITH (NOLOCK)
            WHERE EmployeeID = @EmployeeID
        ) api ON e.EmployeeID = api.EmployeeID
        WHERE 1=1';

    IF @SupervisorID IS NOT NULL
        SET @SQL = @SQL + ' AND e.SupervisorID = @SupervisorID';

    IF @Department IS NOT NULL
        SET @SQL = @SQL + ' AND e.Department = @Department';

    IF @JobTitle IS NOT NULL
        SET @SQL = @SQL + ' AND e.JobTitle = @JobTitle';

    SET @SQL = @SQL + '
        ORDER BY e.EmployeeID OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY';

    EXEC sp_executesql @SQL, 
                      N'@SupervisorID INT, @Department VARCHAR(255), @JobTitle VARCHAR(255), @PageNumber INT, @PageSize INT', 
                      @SupervisorID, @Department, @JobTitle, @PageNumber, @PageSize;
END
