    let service = Service::new();
    let cdn_manager = CDNAssetManager;
    let storage_manager = ObjectStorageAssetManager;

    // Initialize server with compression and static asset serving
    let https = HttpsConnector::new();
    let addr = ([127, 0, 0, 1], 3000).into();
    let make_svc = hyper::service::make_service_fn(move |_conn| {
        let service = service.clone();
        let cdn_manager = cdn_manager.clone();
        let storage_manager = storage_manager.clone();
        async move {
            Ok::<_, std::io::Error>(hyper::service::service_fn(move |req| {
                let service = service.clone();
                let cdn_manager = cdn_manager.clone();
                let storage_manager = storage_manager.clone();
                async move {
                    let asset_id = req.uri().path().trim_start_matches('/');
                    if asset_id.is_empty() {
                        return Ok(Response::new(Body::from("Welcome to the service!")));
                    }
                    // Fetch asset from CDN or Object Storage
                    if let Ok(asset) = cdn_manager.fetch_asset(asset_id).await {
                        Ok(Response::new(Body::from(asset)))
                    } else if let Ok(asset) = storage_manager.fetch_asset(asset_id).await {
                        Ok(Response::new(Body::from(asset)))
                    } else {
                        Ok(Response::builder()
                            .status(hyper::StatusCode::NOT_FOUND)
                            .body(Body::from("Asset not found"))
                            .unwrap())
                    }
                }
            }))
        }
    });

    let server = Server::bind(&addr).serve(make_svc.with_graceful_shutdown(shutdown_signal()));
    println!("Listening on http://{}", addr);

    if let Err(e) = server.await {
        eprintln!("Server error: {}", e);
    }

    Ok(())
}

async fn shutdown_signal() -> Result<(), std::io::Error> {
    tokio::signal::ctrl_c().await?;
    Ok(())
}
