#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>

class DataStreamProcessor {
public:
    void addData(const std::string& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        dataQueue_.push(data);
        condition_.notify_one();
    }

    std::vector<std::string> getProcessedData() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (dataQueue_.empty()) {
            condition_.wait(lock);
        }
        std::vector<std::string> processedData = std::move(dataQueue_);
        return processedData;
    }

private:
    std::queue<std::string> dataQueue_;
    std::mutex mutex_;
    std::condition_variable condition_;
};

int main() {
    DataStreamProcessor processor;

    // Simulate data streaming
    for (int i = 0; i < 10; ++i) {
        processor.addData("Data " + std::to_string(i));
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }

    // Process and print data
    auto processedData = processor.getProcessedData();
    for (const auto& data : processedData) {
        std::cout << data << std::endl;
    }

    return 0;
}
