// app.js
const express = require('express');
const bodyParser = require('body-parser');
const crypto = require('crypto');
const argon2 = require('argon2');
const mongoose = require('mongoose');
const redis = require('redis');
const fs = require('fs');
const multer = require('multer');

const app = express();
app.use(bodyParser.json());

// MongoDB connection
mongoose.connect('mongodb://localhost/user_profiles', { useNewUrlParser: true, useUnifiedTopology: true });

// Redis client
const redisClient = redis.createClient();

// Multer setup for file uploads
const storage = multer.memoryStorage();
const upload = multer({ storage: storage });

// User model
const User = mongoose.model('User', new mongoose.Schema({
  id: String,
  name: String,
  email: String,
  passwordHash: String,
  profilePictureMd5: String,
  profilePictureEncrypted: Buffer,
}));

// Argon2 hashing function
async function hashPassword(password) {
  return await argon2.hash(password);
}

// MD5 hash generation for profile picture URLs
function generateProfilePictureMd5(url) {
  return crypto.createHash('md5').update(url).digest('hex');
}

// AES-256-CBC encryption for profile pictures
function encryptProfilePicture(buffer, key) {
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(key), iv);
  let encrypted = cipher.update(buffer);
  encrypted = Buffer.concat([encrypted, cipher.final()]);
  return { iv: iv.toString('hex'), encryptedData: encrypted.toString('hex') };
}

// Route to handle user actions
app.post('/user', upload.single('profile_picture'), async (req, res) => {
  const { id, name, email, password, action } = req.body;
  const profilePictureBuffer = req.file ? Buffer.from(req.file.buffer, 'binary') : null;

  try {
    if (action === 'create' || action === 'update') {
      let user = await User.findOne({ id });
      if (!user) {
        user = new User();
      }
      user.id = id;
      user.name = name;
      user.email = email;
      user.passwordHash = await hashPassword(password);
      user.profilePictureMd5 = generateProfilePictureMd5(req.body.profile_picture_url || '');
      user.profilePictureEncrypted = encryptProfilePicture(profilePictureBuffer, 'your-secret-key');
      await user.save();
    } else if (action === 'delete') {
      await User.findOneAndDelete({ id });
    }
    res.status(200).send('User action processed successfully.');
  } catch (error) {
    console.error(error);
    res.status(500).send('Error processing user action.');
  }
});

// Route to handle file uploads
app.post('/upload', upload.single('file'), async (req, res) => {
  const fileBuffer = req.file.buffer;
  // Handle file upload logic here
  res.status(200).send('File uploaded successfully.');
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
