#include <iostream>
#include <websocketpp/config/asio_no_tls.hpp>
#include <websocketpp/server.hpp>
#include "kafka/kafka_producer.h"
#include "rest/rest_client.h"
#include "database/database_connection.h"
#include "trading/trading_platform_interface.h"
#include "data_model/data_model_manager.h"

typedef websocketpp::server<websocketpp::config::asio> web_server;

class FinancialMarketDataProcessor {
private:
    web_server ws_server;
    kafka_producer kafka_prod;
    rest_client rest_cli;
    database_connection db_conn;
    trading_platform_interface trading_plat;
    data_model_manager data_mgr;

public:
    void init() {
        // Initialize WebSocket server
        ws_server.init_asio();
        ws_server.set_message_handler(std::bind(&FinancialMarketDataProcessor::handle_message, this, std::placeholders::_1, std::placeholders::_2));

        // Initialize Kafka producer
        kafka_prod.initialize();

        // Initialize REST client
        rest_cli.initialize();

        // Connect to database
        db_conn.connect();

        // Initialize trading platform interface
        trading_plat.initialize();

        // Load data model manager
        data_mgr.load_models();
    }

    void handle_message(web_server::connection_hdl hdl, web_server::message_ptr msg) {
        // Process incoming WebSocket message
        std::string payload = msg->get_payload();
        process_data(payload);
    }

    void process_data(const std::string& data) {
        // Parse and validate data
        auto parsed_data = parse_and_validate(data);

        if (parsed_data) {
            // Insert into database
            db_conn.insert(parsed_data);

            // Publish to Kafka
            kafka_prod.publish(parsed_data);

            // Send to trading platform
            trading_plat.send(parsed_data);
        }
    }

    void run_web_server(uint16_t port) {
        ws_server.listen(port);
        ws_server.start_accept();
        ws_server.run();
    }
};

int main() {
    FinancialMarketDataProcessor processor;
    processor.init();
    processor.run_web_server(9002);
    return 0;
}
