public class DockerService : IDockerService
{
    private readonly IKubernetes _kubernetesClient;
    private readonly ILogger<DockerService> _logger;
    private readonly HttpClient _httpClient;

    public DockerService(IKubernetes kubernetesClient, ILogger<DockerService> logger)
    {
        _kubernetesClient = kubernetesClient;
        _logger = logger;
        _httpClient = new HttpClient();
    }

    public async Task DeployContainer(string imageName, int port)
    {
        try
        {
            var containerSpec = new V1PodSpec
            {
                Containers = new List<V1Container>
                {
                    new V1Container
                    {
                        Name = "container",
                        Image = imageName,
                        Resources = new V1ResourceRequirements
                        {
                            Requests = new Dictionary<string, string> { { "cpu", "50m" }, { "memory", "64Mi" } },
                            Limits = new Dictionary<string, string> { { "cpu", "250m" }, { "memory", "128Mi" } }
                        },
                        Ports = new List<V1ContainerPort>
                        {
                            new V1ContainerPort { ContainerPort = port }
                        }
                    }
                }
            };

            var pod = new V1Pod
            {
                ApiVersion = "v1",
                Kind = "Pod",
                Metadata = new V1ObjectMeta { Name = $"container-{Guid.NewGuid()}" },
                Spec = containerSpec
            };

            await _kubernetesClient.CoreV1Api.CreateNamespacedPodAsync("default", pod);
            _logger.LogInformation($"Container deployed successfully with image: {imageName}");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to deploy container with image: {imageName}");
        }
    }

    public async Task ScaleContainers(string serviceName, int replicas)
    {
        try
        {
            var deployment = await _kubernetesClient.AppsV1Api.ReadNamespacedDeploymentAsync(serviceName, "default");
            deployment.Spec.Replicas = replicas;
            await _kubernetesClient.AppsV1Api.ReplaceNamespacedDeploymentAsync(deployment.Name, "default", deployment);
            _logger.LogInformation($"Scaled {serviceName} to {replicas} replicas");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to scale {serviceName}");
        }
    }
}

