    return KafkaConsumer(*topics, bootstrap_servers=bootstrap_servers, group_id=group_id)

# Create a Kafka producer to send messages to a topic
def create_kafka_producer(bootstrap_servers='localhost:9092'):
    return KafkaProducer(bootstrap_servers=bootstrap_servers)

# Define a decorator for handling retries with exponential backoff
def retry_on_failure(retries=3, delay=1):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempt = 0
            while attempt < retries:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    time.sleep(delay * (2 ** attempt))
                    attempt += 1
            raise Exception("Failed after maximum number of retries")
        return wrapper
    return decorator

# Define a function for secure API key management with MFA
