using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Logging;

public class DataProcessingService : IDataProcessingService
{
    private readonly ILogger<DataProcessingService> _logger;
    private readonly IAuthenticationApiClient _authenticationApi;
    private readonly string _databaseConnectionString;

    public DataProcessingService(ILogger<DataProcessingService> logger, IAuthenticationApiClient authenticationApi, string databaseConnectionString)
    {
        _logger = logger;
        _authenticationApi = authenticationApi;
        _databaseConnectionString = databaseConnectionString;
    }

    public async Task ProcessLargeByteArrayAsync(byte[] data, int offset, int pageSize, CancellationToken cancellationToken)
    {
        try
        {
            var token = await _authenticationApi.GetAccessTokenAsync(cancellationToken);
            if (token == null)
                throw new UnauthorizedAccessException("Failed to authenticate user.");

            using (var connection = new SqlConnection(_databaseConnectionString))
            {
                connection.AccessToken = token;
                connection.Open();

                using (var command = connection.CreateCommand())
                {
                    command.CommandText = "usp_ProcessData";
                    command.CommandType = CommandType.StoredProcedure;

                    var dataParameter = command.CreateParameter();
                    dataParameter.ParameterName = "@Data";
                    dataParameter.Value = new SqlBytes(data, offset, pageSize);
                    dataParameter.DbType = DbType.Binary;
                    dataParameter.Size = -1; // Use -1 to indicate variable length
                    command.Parameters.Add(dataParameter);

                    using (var reader = await command.ExecuteReaderAsync(cancellationToken))
                    {
                        while (await reader.ReadAsync(cancellationToken))
                        {
                            // Process each row as needed
                        }
                    }
                }
            }
        }
        catch (SqlException ex)
        {
            _logger.LogError(ex, "Error processing data.");
            if (!ex.IsTransient())
                throw;
            await RetryProcessLargeByteArrayAsync(data, offset, pageSize, cancellationToken);
        }
    }

    private async Task RetryProcessLargeByteArrayAsync(byte[] data, int offset, int pageSize, CancellationToken cancellationToken)
    {
        const int maxRetries = 3;
        for (int attempt = 1; attempt <= maxRetries; attempt++)
        {
            try
            {
                await ProcessLargeByteArrayAsync(data, offset, pageSize, cancellationToken);
                return;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Attempt {attempt} failed. Retrying...");
                await Task.Delay(100 * attempt, cancellationToken); // Exponential backoff
            }
        }

        throw new InvalidOperationException("Max retries exceeded.");
    }
}

public interface IDataProcessingService
{
    Task ProcessLargeByteArrayAsync(byte[] data, int offset, int pageSize, CancellationToken cancellationToken);
}
