    private static final String HISTORICAL_TRENDS_API = "https://api.cloudprovider.com/historical-trends";

    public void fetchAndProcessData() {
        ExecutorService executorService = Executors.newFixedThreadPool(10);
        CompletionService<Void> completionService = new ExecutorCompletionService<>(executorService);

        // Fetch real-time stock prices
        completionService.submit(() -> {
            try (CloseableHttpClient httpClient = HttpClients.createDefault()) {
                HttpGet request = new HttpGet(STREAM_PRICES_API);
                try (CloseableHttpResponse response = httpClient.execute(request)) {
                    HttpEntity entity = response.getEntity();
                    if (entity != null) {
                        String result = EntityUtils.toString(entity);
                        // Process real-time data
                        JsonNode rootNode = jsonMapper.readTree(result);
                        processRealTimeData(rootNode);
                    }
                }
            } catch (IOException e) {
                handleException(e, "Error fetching stream prices");
            }
            return null;
        });

        // Fetch historical trends
        completionService.submit(() -> {
            try (CloseableHttpClient httpClient = HttpClients.createDefault()) {
                HttpGet request = new HttpGet(HISTORICAL_TRENDS_API);
                try (CloseableHttpResponse response = httpClient.execute(request)) {
                    HttpEntity entity = response.getEntity();
                    if (entity != null) {
                        String result = EntityUtils.toString(entity);
                        // Process historical data
                        JsonNode rootNode = jsonMapper.readTree(result);
                        processHistoricalData(rootNode);
                    }
                }
            } catch (IOException e) {
                handleException(e, "Error fetching historical trends");
            }
            return null;
        });

        // Handle completion of tasks
        for (int i = 0; i < 2; i++) {
            try {
                Future<Void> future = completionService.take();
                future.get();
            } catch (InterruptedException | ExecutionException e) {
                handleException(e, "Error processing data");
            }
        }

        executorService.shutdown();
    }

    private void processRealTimeData(JsonNode rootNode) {
