using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class DecryptionService
{
    private readonly ILogger<DecryptionService> _logger;
    private readonly ICryptoTransform _cryptoTransform;

    public DecryptionService(ILogger<DecryptionService> logger, byte[] key, byte[] iv)
    {
        _logger = logger;
        var aesAlg = Aes.Create();
        aesAlg.Key = key;
        aesAlg.IV = iv;
        aesAlg.Mode = CipherMode.CBC;
        aesAlg.Padding = PaddingMode.PKCS7;
        _cryptoTransform = aesAlg.CreateDecryptor();
    }

    public async Task<byte[]> DecryptAsync(byte[] encryptedData)
    {
        try
        {
            using (var memoryStream = new MemoryStream(encryptedData))
            using (var cryptoStream = new CryptoStream(memoryStream, _cryptoTransform, CryptoStreamMode.Read))
            using (var resultStream = new MemoryStream())
            {
                await cryptoStream.CopyToAsync(resultStream);
                return resultStream.ToArray();
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Decryption failed");
            throw;
        }
    }
}
