#[derive(Debug)]
enum DroneCommand {
    Status,
    Recharge,
    Route(String),
    Monitor,
    Emergency,
    Reschedule,
    Audit,
}

struct DroneManager {
    drones: HashMap<String, Drone>,
    api_client: APIClient,
    queue: mpsc::Sender<DroneCommand>,
}

impl DroneManager {
    async fn new(api_client: APIClient) -> Self {
        let (tx, rx) = mpsc::channel(100);
        let manager = DroneManager {
            drones: HashMap::new(),
            api_client,
            queue: tx,
        };
        tokio::spawn(manager.run(rx));
        manager
    }

    async fn run(&self, mut rx: mpsc::Receiver<DroneCommand>) {
        while let Some(command) = rx.recv().await {
            match command {
                DroneCommand::Status => self.handle_status(),
                DroneCommand::Recharge => self.handle_recharge(),
                DroneCommand::Route(destination) => self.handle_route(&destination),
                DroneCommand::Monitor => self.handle_monitor(),
                DroneCommand::Emergency => self.handle_emergency(),
                DroneCommand::Reschedule => self.handle_reschedule(),
                DroneCommand::Audit => self.handle_audit(),
            }
        }
    }

    fn handle_status(&self) {
