# Import necessary libraries
from kubernetes import client, config
from concurrent.futures import ThreadPoolExecutor
import logging

# Initialize Kubernetes client
config.load_kube_config()
k8s_client = client.CoreV1Api()

# Function to deploy a containerized microservice
def deploy_microservice(namespace, manifest):
    try:
        # Create deployment object from manifest
        deployment = client.V1Deployment(body=manifest)
        # Apply the deployment
        k8s_client.create_namespaced_deployment(namespace, deployment)
        logging.info(f"Microservice deployed successfully in {namespace}")
    except Exception as e:
        logging.error(f"Failed to deploy microservice: {e}")

# Function to scale a microservice
def scale_microservice(namespace, name, replicas):
    try:
        # Get the current deployment
        deployment = k8s_client.read_namespaced_deployment(name, namespace)
        # Update the number of replicas
        deployment.spec.replicas = replicas
        # Apply the updated deployment
        k8s_client.patch_namespaced_deployment(name, namespace, deployment)
        logging.info(f"Microservice scaled to {replicas} replicas in {namespace}")
    except Exception as e:
        logging.error(f"Failed to scale microservice: {e}")

# Function to rollback a microservice
def rollback_microservice(namespace, name):
    try:
        # Get the rollout history
        history = k8s_client.list_namespaced_deployment_rollout_status(name, namespace)
        # Rollback to the previous version
        k8s_client.rollback_namespaced_deployment(name, namespace)
        logging.info(f"Microservice rolled back to previous version in {namespace}")
    except Exception as e:
        logging.error(f"Failed to rollback microservice: {e}")

# Function to handle errors gracefully
def error_handler(exception):
    logging.error(f"Error occurred: {exception}")
    return None

# Example usage with ThreadPoolExecutor
if __name__ == "__main__":
    # Define the namespace and deployment manifest
    namespace = "default"
    deployment_manifest = {
        "apiVersion": "apps/v1",
        "kind": "Deployment",
        "metadata": {
            "name": "my-microservice"
        },
        "spec": {
            "replicas": 3,
            "selector": {
                "matchLabels": {
                    "app": "my-app"
                }
            },
            "template": {
                "metadata": {
                    "labels": {
                        "app": "my-app"
                    }
                },
                "spec": {
                    "containers": [
                        {
                            "name": "my-container",
                            "image": "my-image:latest"
                        }
                    ]
                }
            }
        }
    }

    # Deploy the microservice
    with ThreadPoolExecutor(max_workers=2) as executor:
        future = executor.submit(deploy_microservice, namespace, deployment_manifest)
        result = future.result()

    # Scale the microservice
    scale_future = executor.submit(scale_microservice, namespace, "my-microservice", 5)

    # Rollback the microservice
    rollback_future = executor.submit(rollback_microservice, namespace, "my-microservice")

    # Handle errors gracefully
    future.add_done_callback(error_handler)
