import abc
from abc import ABC, abstractmethod
import time
import redis
import memcache
import boto3
from botocore.exceptions import ClientError

class CacheEntry(ABC):
    @abstractmethod
    def __init__(self, key: str, value: any, expiration_time: int):
        pass

    @abstractmethod
    def get_value(self) -> any:
        pass

    @abstractmethod
    def update_value(self, new_value: any) -> None:
        pass

class RedisCacheEntry(CacheEntry):
    def __init__(self, key: str, value: any, expiration_time: int):
        self.key = key
        self.value = value
        self.expiration_time = expiration_time

    def get_value(self) -> any:
        return redis_client.get(self.key)

    def update_value(self, new_value: any) -> None:
        redis_client.setex(self.key, self.expiration_time, new_value)

class MemcachedCacheEntry(CacheEntry):
    def __init__(self, key: str, value: any, expiration_time: int):
        self.key = key
        self.value = value
        self.expiration_time = expiration_time

    def get_value(self) -> any:
        return memcache_client.get(self.key)

    def update_value(self, new_value: any) -> None:
        memcache_client.setex(self.key, self.expiration_time, new_value)

class DynamoDBCacheEntry(CacheEntry):
    def __init__(self, key: str, value: any, expiration_time: int):
        self.dynamodb = boto3.resource('dynamodb')
        self.table = self.dynamodb.Table('cache_table')
        self.key = key
        self.value = value
        self.expiration_time = expiration_time

    def get_value(self) -> any:
        response = self.table.get_item(Key={'key': self.key})
        item = response.get('Item', {})
        if 'expiration' in item and time.time() < item['expiration']:
            return item['value']
        else:
            raise KeyError(f"Key {self.key} not found or expired")

    def update_value(self, new_value: any) -> None:
        try:
            self.table.update_item(
                Key={'key': self.key},
                UpdateExpression='SET value = :val, expiration = :exp',
                ExpressionAttributeValues={
                    ':val': new_value,
                    ':exp': time.time() + self.expiration_time
                }
            )
        except ClientError as e:
            raise KeyError(f"Failed to update key {self.key}: {e}")

class CacheManager:
    def __init__(self, cache_entries: dict):
        self.cache_entries = cache_entries

    def get(self, key: str) -> any:
        entry = self.cache_entries.get(key)
        if entry:
            return entry.get_value()

    def set(self, key: str, value: any, expiration_time: int) -> None:
        entry = self.cache_entries[key]
        entry.update_value(value)

# Example usage
redis_client = redis.StrictRedis(host='localhost', port=6379, db=0)
memcache_client = memcache.Client(['127.0.0.1:11211'], debug=0)

cache_entries = {
    'key1': RedisCacheEntry('key1', 'value1', 3600),
    'key2': MemcachedCacheEntry('key2', 'value2', 7200),
    'key3': DynamoDBCacheEntry('key3', 'value3', 4800)
}

cache_manager = CacheManager(cache_entries)

# Get value
print(cache_manager.get('key1'))  # Output: 'value1'

# Set new value
cache_manager.set('key1', 'new_value1', 3600)
print(cache_manager.get('key1'))  # Output: 'new_value1'
```']

