using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.EntityFrameworkCore;
using StackExchange.Redis;

public class ConnectionStatusUpdate
{
    public int Id { get; set; }
    public string UeId { get; set; }
    public bool IsConnected { get; set; }
    public DateTime LastUpdated { get; set; }
}

public interface IConnectionStatusRepository
{
    Task AddOrUpdate(ConnectionStatusUpdate update);
    Task PurgeExpiredUpdates();
}

public class ConnectionStatusRepository : IConnectionStatusRepository
{
    private readonly DbContext _context;
    private readonly IDistributedCache _cache;

    public ConnectionStatusRepository(DbContext context, IDistributedCache cache)
    {
        _context = context;
        _cache = cache;
    }

    public async Task AddOrUpdate(ConnectionStatusUpdate update)
    {
        var existingUpdate = await _context.ConnectionStatusUpdates.FindAsync(update.Id);
        if (existingUpdate == null)
        {
            _context.ConnectionStatusUpdates.Add(update);
        }
        else
        {
            existingUpdate.IsConnected = update.IsConnected;
            existingUpdate.LastUpdated = DateTime.UtcNow;
        }
        await _context.SaveChangesAsync();

        // Cache the update for quick retrieval
        var cacheKey = $"ConnectionStatus:{update.UeId}";
        await _cache.SetStringAsync(cacheKey, JsonConvert.SerializeObject(update));
    }

    public async Task PurgeExpiredUpdates()
    {
        var cutoffTime = DateTime.UtcNow.AddMinutes(-30); // Example: Expire updates older than 30 minutes
        var expiredUpdates = await _context.ConnectionStatusUpdates.Where(u => u.LastUpdated < cutoffTime).ToListAsync();
        _context.ConnectionStatusUpdates.RemoveRange(expiredUpdates);
        await _context.SaveChangesAsync();

        // Purge cached updates
        foreach (var update in expiredUpdates)
        {
            var cacheKey = $"ConnectionStatus:{update.UeId}";
            await _cache.RemoveAsync(cacheKey);
        }
    }
}

public class ConnectionStatusService : IHostedService, IDisposable
{
    private readonly IServiceScopeFactory _scopeFactory;
    private readonly IDistributedCache _cache;

    public ConnectionStatusService(IServiceScopeFactory scopeFactory, IDistributedCache cache)
    {
        _scopeFactory = scopeFactory;
        _cache = cache;
    }

    public Task StartAsync(CancellationToken cancellationToken)
    {
        return Task.Run(async () =>
        {
            while (!cancellationToken.IsCancellationRequested)
            {
                using (var scope = _scopeFactory.CreateScope())
                {
                    var repository = scope.ServiceProvider.GetRequiredService<IConnectionStatusRepository>();
                    await repository.PurgeExpiredUpdates();
                }
                await Task.Delay(TimeSpan.FromMinutes(10), cancellationToken); // Purge every 10 minutes
            }
        }, cancellationToken);
    }

    public Task StopAsync(CancellationToken cancellationToken)
    {
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        // Cleanup if necessary
    }
}

public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        services.AddDbContext<ConnectionStatusContext>(options =>
            options.UseSqlServer(Configuration.GetConnectionString("DefaultConnection")));

        services.AddStackExchangeRedisCache(options =>
