// Define the TX_POWER_LEVEL_STATS structure
typedef struct {
    int ci_id;
    float power_level;
} TX_POWER_LEVEL_STATS;

// Define a node for the dynamic array
typedef struct Node {
    TX_POWER_LEVEL_STATS data;
    struct Node* next;
} Node;

// Define the dynamic array
typedef struct DynamicArray {
    Node* head;
    Node* tail;
    int count;
    pthread_mutex_t mutex;
} DynamicArray;

// Initialize the dynamic array
DynamicArray* init_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->head = array->tail = NULL;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

// Add or update an element in the dynamic array
void add_or_update_element(DynamicArray* array, TX_POWER_LEVEL_STATS data) {
    pthread_mutex_lock(&array->mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&array->mutex);
        return;
    }
    new_node->data = data;
    new_node->next = NULL;

    if (array->head == NULL) {
        array->head = array->tail = new_node;
    } else {
        array->tail->next = new_node;
        array->tail = new_node;
    }
    array->count++;
    pthread_mutex_unlock(&array->mutex);
}

// Retrieve an element from the dynamic array
TX_POWER_LEVEL_STATS* get_element(DynamicArray* array, int ci_id) {
    Node* current = array->head;
    while (current != NULL) {
        if (current->data.ci_id == ci_id) {
            return &current->data;
        }
        current = current->next;
    }
    return NULL;
}

// Free the dynamic array
void free_dynamic_array(DynamicArray* array) {
    Node* current = array->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

// Define a function to simulate real-time data updates
void* update_data(void* arg) {
    DynamicArray* array = (DynamicArray*)arg;
    // Simulate real-time updates
    for (int i = 0; i < 1000; i++) {
        TX_POWER_LEVEL_STATS data = {i, (float)i * 1.2};
        add_or_update_element(array, data);
        usleep(100); // Simulate delay in API response
    }
    return NULL;
}

// Define a function to simulate database synchronization
void* sync_to_database(void* arg) {
    DynamicArray* array = (DynamicArray*)arg;
    // Simulate database synchronization
    while (1) {
        pthread_mutex_lock(&array->mutex);
        Node* current = array->head;
        while (current != NULL) {
            printf("Updating CI ID: %d, Power Level: %.2f\n", current->data.ci_id, current->data.power_level);
            current = current->next;
        }
        pthread_mutex_unlock(&array->mutex);
        sleep(10); // Simulate synchronization interval
    }
    return NULL;
}

int main() {
    DynamicArray* array = init_dynamic_array();
    if (!array) {
        fprintf(stderr, "Failed to initialize dynamic array\n");
        return 1;
    }

    pthread_t update_thread, sync_thread;

    if (pthread_create(&update_thread, NULL, update_data, array) != 0) {
        fprintf(stderr, "Failed to create update thread\n");
        free_dynamic_array(array);
        return 1;
    }

    if (pthread_create(&sync_thread, NULL, sync_to_database, array) != 0) {
        fprintf(stderr, "Failed to create sync thread\n");
        pthread_join(update_thread, NULL);
        free_dynamic_array(array);
        return 1;
    }

    pthread_join(update_thread, NULL);
    pthread_join(sync_thread, NULL);

    free_dynamic_array(array);
    return 0;
}
