class DataSchema:
    def __init__(self, version):
        self.version = version

    def validate_data(self, data):
        try:
            validate(instance=data, schema=self.get_schema())
        except ValidationError as e:
            print(f"Data validation failed: {e}")
            return False
        return True

    def get_schema(self):
        if self.version == 1:
            # Define schema for version 1
            return {
                "type": "object",
                "properties": {
                    "field1": {"type": "string"},
                    "field2": {"type": "number"}
                },
                "required": ["field1"]
            }
        elif self.version == 2:
            # Define schema for version 2
            return {
                "type": "object",
                "properties": {
                    "field1": {"type": "string"},
                    "field2": {"type": "number"},
                    "new_field": {"type": "boolean"}
                },
                "required": ["field1"]
            }
        else:
            raise ValueError("Unsupported schema version")

