#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_ENTRIES 100000
#define LOG_RETENTION_DAYS 30

typedef struct {
    time_t timestamp;
    char session_id[128];
    char event_type[64];
    char metadata[512];
} LogEntry;

LogEntry log_entries[MAX_LOG_ENTRIES];
int log_count = 0;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t log_full_cond = PTHREAD_COND_INITIALIZER;

void* event_broker(void* arg) {
    // Simulate event broker interaction
    while (1) {
        pthread_mutex_lock(&log_mutex);
        while (log_count == MAX_LOG_ENTRIES) {
            pthread_cond_wait(&log_full_cond, &log_mutex);
        }
        // Publish log entry to event broker
        printf("Publishing log entry: %s\n", log_entries[log_count].metadata);
        log_count++;
        pthread_mutex_unlock(&log_mutex);
    }
}

void* database_writer(void* arg) {
    // Simulate database interaction
    while (1) {
        pthread_mutex_lock(&log_mutex);
        if (log_count > 0) {
            // Write log entry to distributed database
            printf("Writing log entry to database: %s\n", log_entries[log_count - 1].metadata);
            log_count--;
            pthread_cond_signal(&log_full_cond);
        }
        pthread_mutex_unlock(&log_mutex);
    }
}

void* log_cleaner(void* arg) {
    while (1) {
        sleep(LOG_RETENTION_DAYS * 86400); // Sleep for retention period
        pthread_mutex_lock(&log_mutex);
        int current_time = time(NULL);
        int entries_to_delete = 0;
        for (int i = 0; i < log_count; i++) {
            if (current_time - log_entries[i].timestamp > LOG_RETENTION_DAYS * 86400) {
                entries_to_delete++;
            }
        }
        for (int i = 0; i < entries_to_delete; i++) {
            memmove(&log_entries[i], &log_entries[i + 1], sizeof(LogEntry));
        }
        log_count -= entries_to_delete;
        pthread_mutex_unlock(&log_mutex);
    }
}

int main() {
    pthread_t event_broker_thread, database_writer_thread, log_cleaner_thread;

    pthread_create(&event_broker_thread, NULL, event_broker, NULL);
    pthread_create(&database_writer_thread, NULL, database_writer, NULL);
    pthread_create(&log_cleaner_thread, NULL, log_cleaner, NULL);

    // Simulate log generation
    for (int i = 0; i < MAX_LOG_ENTRIES; i++) {
        LogEntry entry;
        time(&entry.timestamp);
        snprintf(entry.session_id, sizeof(entry.session_id), "session%d", i);
        snprintf(entry.event_type, sizeof(entry.event_type), "event%d", i);
        snprintf(entry.metadata, sizeof(entry.metadata), "metadata%d", i);

        pthread_mutex_lock(&log_mutex);
        if (log_count < MAX_LOG_ENTRIES) {
            log_entries[log_count++] = entry;
            pthread_cond_signal(&log_full_cond);
        }
        pthread_mutex_unlock(&log_mutex);
    }

    pthread_join(event_broker_thread, NULL);
    pthread_join(database_writer_thread, NULL);
    pthread_join(log_cleaner_thread, NULL);

    return 0;
}
