#include <time.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_LOG_ENTRIES 10000
#define LOG_ENTRY_SIZE 256

typedef struct {
    time_t timestamp;
    char session_id[32];
    char event_type[64];
    char metadata[128];
} LogEntry;

typedef struct {
    LogEntry logs[MAX_LOG_ENTRIES];
    int count;
    pthread_mutex_t lock;
} LogBuffer;

LogBuffer log_buffer = {0};

void init_log_buffer() {
    pthread_mutex_init(&log_buffer.lock, NULL);
}

void add_log_entry(const char* session_id, const char* event_type, const char* metadata) {
    pthread_mutex_lock(&log_buffer.lock);
    if (log_buffer.count < MAX_LOG_ENTRIES) {
        LogEntry entry = {0};
        time_t now = time(NULL);
        snprintf(entry.session_id, sizeof(entry.session_id), "%s", session_id);
        snprintf(entry.event_type, sizeof(entry.event_type), "%s", event_type);
        snprintf(entry.metadata, sizeof(entry.metadata), "%s", metadata);
        entry.timestamp = now;
        log_buffer.logs[log_buffer.count++] = entry;
    }
    pthread_mutex_unlock(&log_buffer.lock);
}

void* cleanup_old_logs(void* arg) {
    while (1) {
        sleep(86400); // Sleep for 24 hours
        pthread_mutex_lock(&log_buffer.lock);
        int current_time = time(NULL);
        for (int i = 0; i < log_buffer.count; ) {
            if (current_time - log_buffer.logs[i].timestamp > 86400) { // Remove logs older than 24 hours
                for (int j = i; j < log_buffer.count - 1; j++) {
                    log_buffer.logs[j] = log_buffer.logs[j + 1];
                }
                log_buffer.count--;
            } else {
                break;
            }
        }
        pthread_mutex_unlock(&log_buffer.lock);
    }
    return NULL;
}

int main() {
    init_log_buffer();
    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, cleanup_old_logs, NULL);

    // Simulate adding log entries
    add_log_entry("session123", "ERROR", "File not found");
    add_log_entry("session456", "INFO", "User logged in");

    pthread_join(cleanup_thread, NULL);
    return 0;
}
```

This code block demonstrates a basic implementation of a log buffer with concurrency handling using mutexes. It includes a function to add log entries and a background thread to clean up old logs based on a configurable retention policy. The `main` function simulates adding log entries to demonstrate the system's functionality.']

