public class DataIngestionPipeline {
    private MessageQueue messageQueue;
    private List<DataSource> dataSources;
    private Set<String> activeTransactions;
    private Timer validationTimer;
    private long freshnessThreshold;

    public DataIngestionPipeline(MessageQueue messageQueue, List<DataSource> dataSources, long freshnessThreshold) {
        this.messageQueue = messageQueue;
        this.dataSources = dataSources;
        this.activeTransactions = new HashSet<>();
        this.freshnessThreshold = freshnessThreshold;
        this.validationTimer = new Timer();
    }

    public void start() {
        for (DataSource dataSource : dataSources) {
            dataSource.registerListener(this::onDataPacketReceived);
        }
        validationTimer.scheduleAtFixedRate(new StalePacketValidator(), 0, 60 * 1000); // Validate every minute
    }

    private void onDataPacketReceived(DataPacket packet) {
        if (isDuplicate(packet)) return;
        activeTransactions.add(packet.getTransactionId());
        messageQueue.sendMessage(packet);
    }

    private boolean isDuplicate(DataPacket packet) {
        return activeTransactions.contains(packet.getTransactionId());
    }

    private class StalePacketValidator extends TimerTask {
        @Override
        public void run() {
            for (DataPacket packet : messageQueue.getAllMessages()) {
                if (System.currentTimeMillis() - packet.getTimestamp() > freshnessThreshold) {
                    // Log and re-ingest stale packet
                    System.out.println("Re-ingesting stale packet: " + packet.getTransactionId());
                    onDataPacketReceived(packet);
                }
            }
        }
    }
}
```

