public class BatchFileUploaderDataSource implements DataSource {
    private Listener listener;
    private ScheduledExecutorService scheduler;

    public BatchFileUploaderDataSource(Listener listener, Path directoryPath) {
        this.listener = listener;
        this.scheduler = Executors.newSingleThreadScheduledExecutor();
        scheduleFileProcessing(directoryPath);
    }

    @Override
    public void registerListener(Listener listener) {
        // Already set in constructor
    }

    private void scheduleFileProcessing(Path directoryPath) {
        scheduler.scheduleAtFixedRate(() -> processFilesInDirectory(directoryPath), 0, 1, TimeUnit.MINUTES);
    }

    private void processFilesInDirectory(Path directoryPath) {
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(directoryPath)) {
            for (Path file : stream) {
                if (!Files.isDirectory(file)) {
                    List<DataPacket> packets = parseBatchFile(file);
                    for (DataPacket packet : packets) {
                        listener.onDataPacketReceived(packet);
                    }
                    // Move or delete the file after processing
                    Files.move(file, file.resolveSibling("processed_" + file.getFileName()));
                }
            }
        } catch (IOException e) {
            // Handle errors
        }
    }
}
