#include <time.h>

// Define error levels
#define LOG_ERROR 1
#define LOG_WARNING 2

// Function to log messages securely
void secure_log(int level, const char *message, ...) {
    va_list args;
    time_t current_time = time(NULL);
    char timestamp[20];

    // Format the current timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time));

    // Open log file in append mode (ensure it's secure)
    FILE *log_file = fopen("encryption.log", "a+");
    if (!log_file) {
        return; // Log failure can be handled based on requirements
    }

    // Start formatting the message with timestamp and level
    fprintf(log_file, "[%s] [%d] ", timestamp, level);

    // Use va_start and va_end to handle variable arguments
    va_start(args, message);
    vfprintf(log_file, message, args);
    va_end(args);

    // Add a newline character at the end of each log entry
    fprintf(log_file, "\n");

    // Close the log file
    fclose(log_file);
}

// Example usage
int main() {
    secure_log(LOG_ERROR, "Failed to retrieve encryption key: %s", "Rate limit exceeded");
    return 0;
}
