#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* dynamic_array_create(size_t initial_capacity) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    array->elements = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void dynamic_array_destroy(DynamicArray *array) {
    free(array->elements);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int dynamic_array_add(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        array->elements = realloc(array->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        array->capacity = new_capacity;
    }
    array->elements[array->count++] = element;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

// Asynchronous handling function
typedef struct {
    int (*callback)(void *, void *);
    void *data;
    void *result;
} AsyncHandle;

void* async_handle(void *arg) {
    AsyncHandle *handle = (AsyncHandle *)arg;
    handle->result = handle->callback(handle->data);
    return NULL;
}

int execute_async(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T element, int (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    if (dynamic_array_add(array, element) != 0) {
        return -1; // Allocation failed
    }

    pthread_t thread;
    AsyncHandle handle = {callback, &element, NULL};
    if (pthread_create(&thread, NULL, async_handle, &handle) != 0) {
        dynamic_array_remove_last(array); // Remove the element if thread creation fails
        return -1; // Thread creation failed
    }

    pthread_join(thread, NULL);
    return 0;
}

// Example callback function for demonstration
int example_callback(NFAPI_CRC_INDICATION_PDU_T pdu) {
    printf("Processing PDU with RNTI: %d\n", pdu.RNTI);
    return 0; // Return value can be used as needed
}
