using json = nlohmann::json;
namespace pq = pqxx;

class TelemetryProcessor {
public:
    TelemetryProcessor(const std::string& db_config) : db_config_(db_config), running_(false) {}

    void start() {
        running_ = true;
        consumer_thread_ = std::thread(&TelemetryProcessor::consumeMessages, this);
    }

    void stop() {
        running_ = false;
        condition_.notify_all();
        if (consumer_thread_.joinable()) {
            consumer_thread_.join();
        }
    }

    void addMessage(const json& message) {
        std::lock_guard<std::mutex> lock(mutex_);
        messages_.push(message);
        condition_.notify_one();
    }

private:
    void consumeMessages() {
        while (running_) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this] { return !messages_.empty() || !running_; });
            if (!running_) break;

            json message = messages_.front();
            messages_.pop();

            lock.unlock();
            processMessage(message);
        }
    }

    void processMessage(const json& message) {
        // Validate and parse the message
        if (validateMessage(message)) {
            // Persist to database
            storeToDatabase(message);
        } else {
            std::cerr << "Invalid message: " << message.dump() << std::endl;
        }
    }

    bool validateMessage(const json& message) {
        // Implement validation logic here
        return true;
    }

    void storeToDatabase(const json& message) {
        pqxx::connection C(db_config_);
        if (C.is_open()) {
            std::string sql = "INSERT INTO telemetry_data VALUES (" +
                              std::to_string(message["sensor_reading"]) + ", " +
                              std::to_string(message["battery_level"]) + ", " +
                              C.esc(message["location"].dump()) + ")";
            pqxx::work W(C);
            W.exec(sql);
            W.commit();
        } else {
            std::cerr << "Database connection failed." << std::endl;
        }
    }

    std::string db_config_;
    bool running_;
    std::thread consumer_thread_;
    std::mutex mutex_;
    std::condition_variable condition_;
    std::queue<json> messages_;
};

// Example usage
int main() {
    TelemetryProcessor processor("dbname=mydb user=me password=mypassword host=localhost port=5432");
    processor.start();

    // Simulate message ingestion
    json message = {{"sensor_reading", 10}, {"battery_level", 80}, {"location", [latitude: 40.7128, longitude: -74.0060]}};
    processor.addMessage(message);

    // Stop the processor after some time
    std::this_thread::sleep_for(std::chrono::seconds(10));
    processor.stop();

    return 0;
}
