    std::mutex mtx;
    std::condition_variable cv;
    bool running;

public:
    MessageQueue() : running(true) {}

    void startProcessing(TelemetryProcessor& processor, DatabaseManager& dbManager) {
        std::thread([this, &processor, &dbManager]() {
            while (running) {
                std::unique_lock<std::mutex> lock(mtx);
