import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class LogProcessingService {
    private ExecutorService executorService;
    private LoggingServiceAPI loggingServiceAPI;
    private int severityThreshold;

    public LogProcessingService(LoggingServiceAPI loggingServiceAPI, int severityThreshold) {
        this.loggingServiceAPI = loggingServiceAPI;
        this.severityThreshold = severityThreshold;
        this.executorService = Executors.newCachedThreadPool();
    }

    public void addLogSource(LogSource logSource) {
        executorService.submit(() -> processLogs(logSource));
    }

    private void processLogs(LogSource logSource) {
        try {
            for (LogEntry entry : logSource.getLogs()) {
                if (entry.getSeverity() >= severityThreshold) {
                    loggingServiceAPI.transmitLog(entry);
                }
            }
        } catch (Exception e) {
            handleException(e, logSource);
        }
    }

    private void handleException(Exception e, LogSource logSource) {
        // Implement error handling strategy
        System.err.println("Error processing logs from " + logSource.getName() + ": " + e.getMessage());
        // Fallback mechanism if necessary
    }

    public void stop() throws InterruptedException {
        executorService.shutdown();
        if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
            executorService.shutdownNow();
        }
    }

    interface LogSource {
        String getName();
        Iterable<LogEntry> getLogs();
    }

    static class LogEntry {
        private int severity;
        private String message;

        public LogEntry(int severity, String message) {
            this.severity = severity;
            this.message = message;
        }

        public int getSeverity() {
            return severity;
        }

        public String getMessage() {
            return message;
        }
    }

    interface LoggingServiceAPI {
        void transmitLog(LogEntry log);
    }
}
