            await _semaphore.WaitAsync();
            try
            {
                // Logic to register the user and handle lockout settings
                bool isUserAdded = await AddUserToDatabase(username);
                if (isUserAdded)
                {
                    _userLockoutStatus.TryAdd(username, false);
                }
                return isUserAdded;
            }
            finally
            {
                _semaphore.Release();
            }
        }

        public async Task<bool> LockOutUser(string username)
        {
            await _semaphore.WaitAsync();
            try
            {
                bool lockoutApplied = await SetLockoutStatus(username, true);
                return lockoutApplied;
            }
            finally
            {
                _semaphore.Release();
            }
        }

        public async Task<bool> UnLockUser(string username)
        {
            await _semaphore.WaitAsync();
            try
            {
                bool unlockApplied = await SetLockoutStatus(username, false);
                return unlockApplied;
            }
            finally
            {
                _semaphore.Release();
            }
