            return true;
        }

        private async Task<bool> SetLockoutStatus(string username, bool isLockedOut)
        {
            if (_userLockoutStatus.TryGetValue(username, out var currentStatus))
            {
                _userLockoutStatus.TryUpdate(username, isLockedOut, currentStatus);
                await LogActivity($"User {username} is now locked out: {isLockedOut}");
                return true;
            }
            return false;
        }

