import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

public class ResilientSemaphore {

    private static final int MAX_CONCURRENT_THREADS = 1000;
    private static final int MAX_ACQUISITION_ATTEMPTS_PER_THREAD = 10000;
    private static final long DELAY_MICROSECONDS = 1L;
    private static final String DB_URL = "jdbc:mysql://localhost:3306/semaphore";
    private static final String USER = "username";
    private static final String PASS = "password";

    private Connection dbConnection;
    private ConcurrentHashMap<Integer, AtomicInteger> semaphoreCounts;

    public ResilientSemaphore() {
        try {
            dbConnection = DriverManager.getConnection(DB_URL, USER, PASS);
            semaphoreCounts = new ConcurrentHashMap<>();
            initializeDatabase();
        } catch (SQLException e) {
            throw new RuntimeException("Failed to connect to the database", e);
        }
    }

    private void initializeDatabase() throws SQLException {
        String createTableSql = "CREATE TABLE IF NOT EXISTS semaphores (" +
                "id INT PRIMARY KEY, " +
                "count INT NOT NULL)" +
                "ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci";

        try (PreparedStatement stmt = dbConnection.prepareStatement(createTableSql)) {
            stmt.executeUpdate();
        }

        for (int i = 1; i <= MAX_CONCURRENT_THREADS; i++) {
            String insertSql = "INSERT INTO semaphores (id, count) VALUES (?, ?) ON DUPLICATE KEY UPDATE count=VALUES(count)";
            try (PreparedStatement stmt = dbConnection.prepareStatement(insertSql)) {
                stmt.setInt(1, i);
                stmt.setInt(2, MAX_ACQUISITION_ATTEMPTS_PER_THREAD);
                stmt.executeUpdate();
            }
        }
    }

    public boolean acquire(int threadId) throws InterruptedException {
        long startTime = System.nanoTime();
        while (System.nanoTime() - startTime < TimeUnit.SECONDS.toNanos(60)) {
            int currentCount;
            do {
                currentCount = semaphoreCounts.getOrDefault(threadId, new AtomicInteger()).get();
                if (currentCount <= 0) {
                    return false; // Semaphore limit reached
                }
            } while (!semaphoreCounts.getOrDefault(threadId, new AtomicInteger()).compareAndSet(currentCount, currentCount - 1));

            try {
                Thread.sleep(DELAY_MICROSECONDS);
                updateDatabase(semaphoreCounts, threadId);
                return true;
            } catch (InterruptedException e) {
                semaphoreCounts.getOrDefault(threadId, new AtomicInteger()).incrementAndGet();
                throw e;
            }
        }
        return false; // Timeout
    }

    private void updateDatabase(ConcurrentHashMap<Integer, AtomicInteger> semaphoreCounts, int threadId) throws SQLException {
        String updateSql = "UPDATE semaphores SET count=? WHERE id=?";
        try (PreparedStatement stmt = dbConnection.prepareStatement(updateSql)) {
            stmt.setInt(1, semaphoreCounts.getOrDefault(threadId, new AtomicInteger()).get());
            stmt.setInt(2, threadId);
            stmt.executeUpdate();
        }
    }

    public void release(int threadId) throws SQLException {
        int currentCount;
        do {
            currentCount = semaphoreCounts.getOrDefault(threadId, new AtomicInteger()).get();
        } while (!semaphoreCounts.getOrDefault(threadId, new AtomicInteger()).compareAndSet(currentCount, currentCount + 1));

        updateDatabase(semaphoreCounts, threadId);
    }

    public static void main(String[] args) {
        ResilientSemaphore semaphore = new ResilientSemaphore();

        Runnable task = () -> {
            try {
                boolean acquired = semaphore.acquire(Thread.currentThread().getId());
                if (acquired) {
                    System.out.println("Thread " + Thread.currentThread().getId() + " acquired semaphore");
                    // Perform critical section operations
                    semaphore.release(Thread.currentThread().getId());
                    System.out.println("Thread " + Thread.currentThread().getId() + " released semaphore");
                }
            } catch (InterruptedException e) {
                System.out.println("Thread " + Thread.currentThread().getId() + " interrupted");
            }
        };

        for (int i = 0; i < MAX_CONCURRENT_THREADS; i++) {
            new Thread(task).start();
        }
    }
}
