class DynamicLogProcessor {
  constructor() {
    this.factoryRegistry = {};
    this.processors = [];
  }

  // Register a factory function for a specific data format or protocol
  registerFactory(format, factoryFunction) {
    this.factoryRegistry[format] = factoryFunction;
  }

  // Create a log processor based on the data format
  createProcessor(data) {
    const { format } = data;
    if (this.factoryRegistry[format]) {
      return this.factoryRegistry[format](data);
    }
    throw new Error(`No processor available for format: ${format}`);
  }

  // Add a processor to the list
  addProcessor(processor) {
    this.processors.push(processor);
  }

  // Process log data asynchronously
  async processLogData(data) {
    const processor = this.createProcessor(data);
    await processor.process();
  }
}

// Example usage
const dlp = new DynamicLogProcessor();

// Register a factory for JSON logs
dlp.registerFactory('json', (data) => new JsonLogProcessor(data));

// Register a factory for CSV logs
dlp.registerFactory('csv', (data) => new CsvLogProcessor(data));

// Add processors to the list
dlp.addProcessor(new LogEnricher());
dlp.addProcessor(new AnomalyDetector());

// Process some log data
const jsonData = { format: 'json', payload: '{ "message": "Hello, world!" }' };
const csvData = { format: 'csv', payload: 'timestamp,message\n1633072800,Hello, world!' };

dlp.processLogData(jsonData).then(() => console.log('JSON log processed'));
dlp.processLogData(csvData).then(() => console.log('CSV log processed'));
```

