#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_SESSIONS 100
#define BUFFER_SIZE 4096

typedef struct {
    int session_id;
    int client_socket;
    pthread_t thread_id;
} NetworkSession;

NetworkSession sessions[MAX_SESSIONS];
int session_count = 0;
pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;

void *handle_client(void *arg) {
    NetworkSession *session = (NetworkSession *)arg;
    char buffer[BUFFER_SIZE];

    while (1) {
        int bytes_received = recv(session->client_socket, buffer, BUFFER_SIZE - 1, 0);
        if (bytes_received <= 0) {
            break;
        }
        buffer[bytes_received] = '\0';
        printf("Received from session %d: %s", session->session_id, buffer);

        // Process network interface statistics here
    }

    close(session->client_socket);
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        if (sessions[i].thread_id == pthread_self()) {
            sessions[i] = sessions[--session_count];
            break;
        }
    }
    pthread_mutex_unlock(&session_lock);

    return NULL;
}

void start_session(int client_socket) {
    if (session_count >= MAX_SESSIONS) {
        printf("Maximum number of sessions reached.\n");
        return;
    }

    NetworkSession *new_session = &sessions[session_count++];
    new_session->session_id = session_count;
    new_session->client_socket = client_socket;
    pthread_create(&new_session->thread_id, NULL, handle_client, (void *)new_session);
}

int main() {
    int server_socket, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    if ((server_socket = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(8080);

    if (bind(server_socket, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    if (listen(server_socket, MAX_SESSIONS) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port 8080\n");

    while (1) {
        if ((new_socket = accept(server_socket, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }

        start_session(new_socket);
    }

    return 0;
}
```

This code sets up a basic server that listens for incoming network interface statistics requests. It creates a new thread for each client connection to handle concurrent sessions efficiently. The server can be scaled by adding more threads or using a process-based model depending on the requirements.

Please note that this is a simplified example and does not include advanced features like error handling, logging, memory management, or telemetry service integration. You should expand upon this foundation to meet the full requirements of your network monitoring system.']

