// Main function
int main(int argc, char* argv[]) {
    if (argc < 2) {
        displayHelp();
        return EXIT_FAILURE;
    }

    // Parse command line arguments
    int countWordsFlag = 0;
    long long fileSizeSum = 0;
    const char* delimiter = "\n";
    const char* output_file = NULL;
    int threads = 4;
    int format = 0; // Plain text by default
    regex_t pattern;
    int rangeOption = 0;
    double metricValue = 0.0;
    int helpFlag = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            helpFlag = 1;
        } else if (strcmp(argv[i], "-c") == 0) {
            countWordsFlag = 1;
        } else if (strcmp(argv[i], "-s") == 0) {
            fileSizeSum += summarizeFileSizes(".");
        } else if (strncmp(argv[i], "-d", 2) == 0) {
            delimiter = argv[i] + 3;
        } else if (strcmp(argv[i], "-o") == 0) {
            output_file = argv[++i];
        } else if (strncmp(argv[i], "-t", 2) == 0) {
            threads = atoi(argv[i] + 3);
        } else if (strncmp(argv[i], "-f", 2) == 0) {
            format = atoi(argv[i] + 3); // Assuming format codes are integers
        } else if (strncmp(argv[i], "-p", 2) == 0) {
            regcomp(&pattern, argv[i] + 3, REG_EXTENDED | REG_NOSUB);
        } else if (strcmp(argv[i], "-r") == 0) {
            rangeOption = atoi(argv[++i]);
            metricValue = atof(argv[++i]);
        } else if (strncmp(argv[i], "-m", 2) == 0) {
            metricValue = atof(argv[++i]);
        }
    }

    if (helpFlag || countWordsFlag) {
        displayHelp();
        return EXIT_SUCCESS;
    }

    // Process directories in parallel
    pthread_t* threadsArray = malloc(threads * sizeof(pthread_t));
    int threadIndex = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") != 0 && strcmp(argv[i], "-c") != 0) {
            pthread_create(&threadsArray[threadIndex++], NULL, processDirectory, argv[i]);
            if (threadIndex == threads) {
                for (int j = 0; j < threadIndex; j++) {
                    pthread_join(threadsArray[j], NULL);
                }
                threadIndex = 0;
            }
        }
    }

    // Join any remaining threads
    for (int i = 0; i < threadIndex; i++) {
        pthread_join(threadsArray[i], NULL);
    }

    free(threadsArray);

    return EXIT_SUCCESS;
}

// Function to process a directory
void* processDirectory(void* arg) {
    const char* directory = (const char*)arg;
    DIR* dir = opendir(directory);
    if (dir == NULL) {
        perror("opendir");
        pthread_exit(NULL);
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) {
            // Process the file
            // Example: Count words or summarize file size
        }
    }

    closedir(dir);
    pthread_exit(NULL);
}

// Function to display help
void displayHelp() {
    printf("Usage: %s [options] directory...\n", argv[0]);
    printf("\nOptions:\n");
    printf("  --help          Display this usage summary\n");
    printf("  -c               Count the total number of words across all files in the directory\n");
    printf("  -s               Summarize file sizes, excluding directories\n");
    printf("  -d delimiter     Specify a custom delimiter for line splitting (default is newline)\n");
    printf("  -o output_file   Redirect output to a specified file instead of standard output\n");
    printf("  -t threads       Specify the number of threads for parallel processing (default is 4)\n");
    printf("  -f format        Output results in a specified format (0: plain text, 1: JSON, 2: CSV)\n");
    printf("  -p pattern       Filter files based on a regular expression pattern\n");
    printf("  -r range         Process files within a specified range\n");
    printf("  -m metric        Calculate additional metrics like average word length or frequency of specific words\n");
}

// Function to count words in a directory
int countWords(const char* directory) {
    DIR* dir = opendir(directory);
    if (dir == NULL) {
        perror("opendir");
        return -1;
    }

    struct dirent* entry;
    int wordCount = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) {
            // Open and count words in the file
            FILE* file = fopen(entry->d_name, "r");
            if (file == NULL) {
                perror("fopen");
                continue;
            }

            char buffer[1024];
            while (fgets(buffer, sizeof(buffer), file) != NULL) {
                wordCount += strwordcount(buffer);
            }

            fclose(file);
        }
    }

    closedir(dir);
    return wordCount;
}

// Helper function to count words in a string
int strwordcount(const char* str) {
    int count = 0;
    while (*str) {
        if (isalpha(*str)) {
            count++;
            while (isalpha(*str)) str++;
        } else {
            str++;
        }
    }
    return count;
}

// Function to summarize file sizes
long long summarizeFileSizes(const char* directory) {
    DIR* dir = opendir(directory);
    if (dir == NULL) {
        perror("opendir");
        return -1;
    }

    struct dirent* entry;
    long long totalSize = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) {
            // Get file size
            struct stat st;
            if (stat(entry->d_name, &st) == 0) {
                totalSize += st.st_size;
            }
        } else if (entry->d_type == DT_DIR && strcmp(entry->d_name, ".") != 0 && strcmp(entry->d_name, "..") != 0) {
            // Recursively process subdirectories
            totalSize += summarizeFileSizes(entry->d_name);
        }
    }

    closedir(dir);
    return totalSize;
}

// Function to write output
void writeOutput(const char* data, const char* output_file, int format) {
    FILE* file = fopen(output_file, "w");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    switch (format) {
        case 0: // Plain text
            fprintf(file, "%s", data);
            break;
        case 1: // JSON
            fprintf(file, "{\"data\": \"%s\"}", data);
            break;
        case 2: // CSV
            fprintf(file, "Data,%s\n", data);
            break;
    }

    fclose(file);
}
