#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_SENSORS 10000
#define READINGS_PER_SENSOR 5000

typedef struct {
    int sensor_id;
    double temperature;
    double humidity;
} Reading;

typedef struct {
    Reading* readings;
    size_t count;
} DataStream;

typedef struct {
    sem_t* semaphore;
    pthread_mutex_t* mutex;
} MutexAndSemaphorePair;

MutexAndSemaphorePair* create_ms_pair() {
    MutexAndSemaphorePair* ms_pair = malloc(sizeof(MutexAndSemaphorePair));
    ms_pair->semaphore = malloc(sizeof(sem_t));
    ms_pair->mutex = malloc(sizeof(pthread_mutex_t));

    sem_init(ms_pair->semaphore, 0, 1);
    pthread_mutex_init(ms_pair->mutex, NULL);

    return ms_pair;
}

void destroy_ms_pair(MutexAndSemaphorePair* ms_pair) {
    sem_destroy(ms_pair->semaphore);
    pthread_mutex_destroy(ms_pair->mutex);
    free(ms_pair->semaphore);
    free(ms_pair->mutex);
    free(ms_pair);
}

void add_reading(DataStream* stream, Reading reading) {
    pthread_mutex_lock(stream->ms_pair->mutex);
    sem_wait(stream->ms_pair->semaphore);

    if (stream->count >= MAX_SENSORS * READINGS_PER_SENSOR) {
        // Handle memory overflow or garbage collection
    }

    stream->readings[stream->count] = reading;
    stream->count++;

    sem_post(stream->ms_pair->semaphore);
    pthread_mutex_unlock(stream->ms_pair->mutex);
}

Reading get_reading(DataStream* stream, int index) {
    Reading reading;

    pthread_mutex_lock(stream->ms_pair->mutex);
    sem_wait(stream->ms_pair->semaphore);

    if (index < 0 || index >= stream->count) {
        // Handle invalid index
    }

    reading = stream->readings[index];

    sem_post(stream->ms_pair->semaphore);
    pthread_mutex_unlock(stream->ms_pair->mutex);

    return reading;
}

void* sensor_thread(void* arg) {
    DataStream* stream = (DataStream*)arg;

    for (int i = 0; i < READINGS_PER_SENSOR; i++) {
        Reading reading = { /* populate reading data */ };
        add_reading(stream, reading);
    }

    return NULL;
}

int main() {
    DataStream stream;
    MutexAndSemaphorePair* ms_pair = create_ms_pair();

    stream.readings = malloc(MAX_SENSORS * READINGS_PER_SENSOR * sizeof(Reading));
    stream.count = 0;
    stream.ms_pair = ms_pair;

    pthread_t threads[MAX_SENSORS];

    for (int i = 0; i < MAX_SENSORS; i++) {
        pthread_create(&threads[i], NULL, sensor_thread, &stream);
    }

    for (int i = 0; i < MAX_SENSORS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up resources

    destroy_ms_pair(ms_pair);
    free(stream.readings);

    return 0;
