#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>
#include <curl/curl.h>
#include <redis/redis.h>

#define MAX_CONNECTIONS 100
#define MAX_TASKS 500

typedef struct {
    CURL *curl;
    char *data;
} Task;

Task tasks[MAX_TASKS];
sem_t task_semaphore;

void* worker_thread(void *arg) {
    int thread_id = *(int*)arg;
    while (1) {
        sem_wait(&task_semaphore);
        for (int i = 0; i < MAX_TASKS; i++) {
            if (tasks[i].curl != NULL) {
                CURLcode res = curl_easy_perform(tasks[i].curl);
                if (res != CURLE_OK) {
                    fprintf(stderr, "Curl error: %s\n", curl_easy_strerror(res));
                }
                free(tasks[i].data);
                tasks[i].curl = NULL;
            }
        }
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    sem_init(&task_semaphore, 0, 1);

    pthread_t threads[MAX_CONNECTIONS];
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        pthread_create(&threads[i], NULL, worker_thread, &i);
    }

    // Main loop to fetch and process tasks
    while (1) {
        sem_wait(&task_semaphore);
        for (int i = 0; i < MAX_TASKS; i++) {
            if (tasks[i].curl == NULL) {
                CURL *curl = curl_easy_init();
                if (curl) {
                    // Setup the task
                    tasks[i].curl = curl;
                    curl_easy_setopt(curl, CURLOPT_URL, "http://api.example.com/data");
                    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
                    sem_post(&task_semaphore);
                }
            }
        }
    }

    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&task_semaphore);

    return 0;
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    Task *task = (Task*)userp;
    task->data = realloc(task->data, task->size + realsize + 1);
    if (task->data == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        return 0;
    }
    memcpy(&(task->data[task->size]), contents, realsize);
    task->size += realsize;
    task->data[realsize] = 0;
    return realsize;
}
```

This code provides a basic structure for the C program described in the question. It includes a worker thread that fetches data from APIs and processes it using asynchronous I/O with libcurl. The main loop continuously assigns tasks to available threads. Real-time progress updates and notifications for completed tasks can be added as needed.']

