class FileSynchronizer {
public:
    void addFileForUpload(const std::string& filePath) {
        std::lock_guard<std::mutex> lock(mutex_);
        uploadQueue_.push(filePath);
        conditionVariable_.notify_one();
    }

    void start() {
        std::thread([this]() {
            while (true) {
                std::unique_lock<std::mutex> lock(mutex_);
                conditionVariable_.wait(lock, [this] { return !uploadQueue_.empty(); });
                std::string filePath = uploadQueue_.front();
                uploadQueue_.pop();
                lock.unlock();

                // Simulate asynchronous file upload
                std::async(std::launch::async, [this, filePath]() {
                    uploadFile(filePath);
                });
            }
        }).detach();
    }

private:
    void uploadFile(const std::string& filePath) {
        // Logic to upload file asynchronously
        std::cout << "Uploading file: " << filePath << std::endl;
        // Simulate upload time
        std::this_thread::sleep_for(std::chrono::seconds(2));
        std::cout << "File uploaded: " << filePath << std::endl;
    }

    std::queue<std::string> uploadQueue_;
    std::mutex mutex_;
    std::condition_variable conditionVariable_;
};

int main() {
    FileSynchronizer synchronizer;
    synchronizer.addFileForUpload("file1.txt");
    synchronizer.addFileForUpload("file2.txt");

    // Start the synchronization process
    synchronizer.start();

    return 0;
}
