import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.tags.Tag;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cloud.gateway.route.RouteLocator;
import org.springframework.cloud.gateway.route.builder.RouteLocatorBuilder;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.*;

@RestController
@Tag(name = "API Gateway", description = "Gateway for routing requests among multiple backend services")
public class ApiGatewayController {

    @Autowired
    private RouteLocator routeLocator;

    @GetMapping("/api/route/{service}")
    @Operation(summary = "Route request to a specific backend service", description = "Dynamically routes requests based on custom headers and health checks")
    public String routeRequest(@PathVariable String service, @RequestHeader("X-Service-Type") String serviceType) {
        // Logic to dynamically select the route based on service and service type
        return routeLocator.getRoutes().stream()
                .filter(route -> route.getId().equals(service + "-" + serviceType))
                .findFirst()
                .map(route -> "Routing request to: " + route.getId())
                .orElse("Service not available");
    }
}

@Configuration
public class GatewayConfig {

    @Bean
    public RouteLocator customRouteLocator(RouteLocatorBuilder builder) {
        return builder.routes()
            .route("service-a-json", r -> r.path("/api/serviceA/**")
                    .and().header("X-Service-Type", "json")
                    .uri("lb://service-a-json"))
            .route("service-b-xml", r -> r.path("/api/serviceB/**")
                    .and().header("X-Service-Type", "xml")
                    .uri("lb://service-b-xml"))
            .build();
    }
}
