class PDUPoolManager {
public:
    PDUPoolManager(size_t poolSize) : poolSize_(poolSize), nextIndex_(0) {}

    NFAPI_CRC_INDICATION_PDU_T* allocatePDU(uint32_t rxTag, uint16_t rnti) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (availablePDUs_.empty()) {
            std::cerr << "No available PDUs in the pool." << std::endl;
            return nullptr;
        }
        NFAPI_CRC_INDICATION_PDU_T* pdu = availablePDUs_.front();
        availablePDUs_.pop();

        // Initialize new PDU
        pdu->RX_UE_INFORMATION_TAG = rxTag;
        pdu->RNTI = rnti;
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = true; // Example initialization

        return pdu;
    }

    void deallocatePDU(NFAPI_CRC_INDICATION_PDU_T* pdu) {
        std::unique_lock<std::mutex> lock(mutex_);
        availablePDUs_.push(pdu);
    }

private:
