use std::sync::{Arc, Mutex};
use tokio::task;
use tokio::time::{self, Duration};
use md5::{Md5, Digest};

struct FileIntegrityService {
    cache: Arc<Mutex<HashMap<String, String>>>,
    hashing_service_url: String,
}

impl FileIntegrityService {
    fn new(hashing_service_url: String) -> Self {
        FileIntegrityService {
            cache: Arc::new(Mutex::new(HashMap::new())),
            hashing_service_url,
        }
    }

    async fn calculate_md5(&self, file_path: &str) -> Result<String, Box<dyn std::error::Error>> {
        if let Some(hash) = self.get_cached_hash(file_path).await? {
            return Ok(hash);
        }

        let hash = self.calculate_md5_hash(file_path).await?;
        self.cache_hash(file_path, &hash).await?;
        Ok(hash)
    }

    async fn get_cached_hash(&self, file_path: &str) -> Result<Option<String>, Box<dyn std::error::Error>> {
        let cache = self.cache.lock().unwrap();
        Ok(cache.get(file_path).cloned())
    }

    async fn calculate_md5_hash(&self, file_path: &str) -> Result<String, Box<dyn std::error::Error>> {
        // Simulate hash calculation
        time::sleep(Duration::from_secs(1)).await;
        Ok(format!("MD5-{}", file_path))
    }

    async fn cache_hash(&self, file_path: &str, hash: &str) -> Result<(), Box<dyn std::error::Error>> {
        let mut cache = self.cache.lock().unwrap();
        cache.insert(file_path.to_string(), hash.to_string());
        Ok(())
    }
}

#[tokio::main]
async fn main() {
    let service = FileIntegrityService::new("http://hashing-service.com".to_string());
    if let Ok(hash) = service.calculate_md5("/path/to/file.txt").await {
        println!("MD5 hash: {}", hash);
    } else {
        eprintln!("Failed to calculate MD5 hash");
    }
}
