#include <stdlib.h>
#include <string.h>

typedef struct {
    int power_level;
    char *region_name;
} TX_POWER_LEVEL_STATS;

typedef struct DynamicArray {
    TX_POWER_LEVEL_STATS **data;
    size_t size;
    size_t capacity;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->data[i]->region_name);
        free(array->data[i]);
    }
    free(array->data);
    free(array);
}

int add_to_dynamic_array(DynamicArray *array, TX_POWER_LEVEL_STATS *stats) {
    if (array->size >= array->capacity) {
        size_t new_capacity = (array->capacity == 0) ? 1 : array->capacity * 2;
        TX_POWER_LEVEL_STATS **new_data = realloc(array->data, new_capacity * sizeof(TX_POWER_LEVEL_STATS *));
        if (!new_data) return -1;
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size] = stats;
    ++array->size;
    return 0;
}

TX_POWER_LEVEL_STATS* get_from_dynamic_array(DynamicArray *array, size_t index) {
    if (index >= array->size) return NULL;
    return array->data[index];
}

void remove_from_dynamic_array(DynamicArray *array, size_t index) {
    if (index >= array->size) return;
    free(array->data[index]->region_name);
    free(array->data[index]);
    for (size_t i = index; i < array->size - 1; ++i) {
        array->data[i] = array->data[i + 1];
    }
    --array->size;
}

DynamicArray* copy_dynamic_array(const DynamicArray *source) {
    DynamicArray *copy = malloc(sizeof(DynamicArray));
    if (!copy) return NULL;
    copy->size = source->size;
    copy->capacity = source->capacity;
    copy->data = malloc(copy->capacity * sizeof(TX_POWER_LEVEL_STATS *));
    if (!copy->data) {
        free(copy);
        return NULL;
    }
    for (size_t i = 0; i < copy->size; ++i) {
        TX_POWER_LEVEL_STATS *new_stats = malloc(sizeof(TX_POWER_LEVEL_STATS));
        new_stats->power_level = source->data[i]->power_level;
        new_stats->region_name = strdup(source->data[i]->region_name);
        copy->data[i] = new_stats;
    }
    return copy;
}
