#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

// Define a simple structure to hold IP addresses
typedef struct {
    char ip[INET_ADDRSTRLEN];
} IPAddress;

// Function to perform DNS resolution for a given hostname
int resolveDNS(const char *hostname, IPAddress *ip) {
    struct addrinfo hints;
    struct addrinfo *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // Use IPv4 addresses
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1;
    }

    p = res;
    while (p != NULL) {
        void *addr;
        char *ipstr;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // convert the IP to a string and print it:
        ipstr = inet_ntop(p->ai_family, addr, ip->ip, INET_ADDRSTRLEN);
        if (ipstr == NULL) {
            perror("inet_ntop");
            freeaddrinfo(res); // free the linked list
            return -1;
        }
        break; // exit loop after first address found
    }

    freeaddrinfo(res); // free the linked list

    return 0;
}

int main() {
    IPAddress ip;
    const char *hostname = "example.com";

    if (resolveDNS(hostname, &ip) == 0) {
        printf("IP Address: %s\n", ip.ip);
    } else {
        printf("Failed to resolve DNS for %s\n", hostname);
    }

    return 0;
}
