DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->data = (TX_POWER_LEVEL_STATS*)malloc(INITIAL_CAPACITY * sizeof(TX_POWER_LEVEL_STATS));
    array->size = 0;
    array->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    free(array->data);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void add_stats(DynamicArray *array, TX_POWER_LEVEL_STATS stats) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * GROWTH_FACTOR;
        array->data = (TX_POWER_LEVEL_STATS*)realloc(array->data, new_capacity * sizeof(TX_POWER_LEVEL_STATS));
        array->capacity = new_capacity;
    }
    array->data[array->size++] = stats;
    pthread_mutex_unlock(&array->lock);
}

