#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_TX_POWER_LEVEL_STATS 1024

typedef struct {
    int power_level;
    char *timestamp;
} TX_POWER_LEVEL_STATS;

TX_POWER_LEVEL_STATS tx_power_stats[MAX_TX_POWER_LEVEL_STATS];
int stats_count = 0;

pthread_mutex_t stats_lock = PTHREAD_MUTEX_INITIALIZER;

void add_tx_power_stat(int power_level, const char *timestamp) {
    pthread_mutex_lock(&stats_lock);
    if (stats_count < MAX_TX_POWER_LEVEL_STATS) {
        tx_power_stats[stats_count].power_level = power_level;
        tx_power_stats[stats_count].timestamp = strdup(timestamp);
        stats_count++;
    }
    pthread_mutex_unlock(&stats_lock);
}

void remove_tx_power_stat(int index) {
    pthread_mutex_lock(&stats_lock);
    if (index >= 0 && index < stats_count) {
        free(tx_power_stats[index].timestamp);
        for (; index < stats_count - 1; index++) {
            tx_power_stats[index] = tx_power_stats[index + 1];
        }
        stats_count--;
    }
    pthread_mutex_unlock(&stats_lock);
}

void clear_tx_power_stats() {
    pthread_mutex_lock(&stats_lock);
    for (int i = 0; i < stats_count; i++) {
        free(tx_power_stats[i].timestamp);
    }
    stats_count = 0;
    pthread_mutex_unlock(&stats_lock);
}
