#define MAX_UPDATES_PER_MINUTE 50000000
#define CACHE_SIZE 1000

typedef struct {
    int timestamp;
    int ci;
    float power_level;
} TX_POWER_LEVEL_STATS;

TX_POWER_LEVEL_STATS* cache[CACHE_SIZE];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
sqlite3* db;
int db_update_count = 0;

void* database_worker(void* arg) {
    while (1) {
        pthread_mutex_lock(&lock);
        if (db_update_count > 0) {
            sqlite3_exec(db, "BEGIN TRANSACTION;", NULL, NULL, NULL);
            for (int i = 0; i < db_update_count; i++) {
                TX_POWER_LEVEL_STATS* stats = cache[i];
                char query[256];
                snprintf(query, sizeof(query), "INSERT OR REPLACE INTO power_stats (timestamp, ci, power_level) VALUES (%d, %d, %f);", 
                         stats->timestamp, stats->ci, stats->power_level);
                sqlite3_exec(db, query, NULL, NULL, NULL);
            }
            sqlite3_exec(db, "COMMIT;", NULL, NULL, NULL);
            db_update_count = 0;
        }
        pthread_mutex_unlock(&lock);
        sleep(1);
    }
}

void add_power_stats(TX_POWER_LEVEL_STATS* stats) {
    if (db_update_count < MAX_UPDATES_PER_MINUTE) {
        pthread_mutex_lock(&lock);
        cache[db_update_count++] = stats;
        pthread_mutex_unlock(&lock);
    } else {
        printf("Database update limit reached. Please try again later.\n");
    }
}

void* real_time_api_worker(void* arg) {
