    pthread_t db_thread, api_thread, cache_thread;
    sqlite3_open("power_stats.db", &db);

    pthread_create(&db_thread, NULL, database_worker, NULL);
    pthread_create(&api_thread, NULL, real_time_api_worker, NULL);
    pthread_create(&cache_thread, NULL, cache_worker, NULL);

    // Main program loop
    while (1) {
        TX_POWER_LEVEL_STATS stats = {time(NULL), 12345, 70.5};
