typedef struct {
    int power_level;
    // other fields
} TX_POWER_LEVEL_STATS;

typedef struct {
    TX_POWER_LEVEL_STATS *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* dynamic_array_create(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->capacity = initial_capacity;
    array->size = 0;
    array->data = (TX_POWER_LEVEL_STATS*)calloc(initial_capacity, sizeof(TX_POWER_LEVEL_STATS));
    if (!array->data) {
        free(array);
        return NULL;
    }
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void dynamic_array_free(DynamicArray* array) {
    free(array->data);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int dynamic_array_push(DynamicArray* array, const TX_POWER_LEVEL_STATS *stats) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        TX_POWER_LEVEL_STATS *new_data = (TX_POWER_LEVEL_STATS*)realloc(array->data, new_capacity * sizeof(TX_POWER_LEVEL_STATS));
        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size++] = *stats;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int dynamic_array_get(const DynamicArray* array, size_t index, TX_POWER_LEVEL_STATS *result) {
    if (index >= array->size) return -1;
    pthread_mutex_lock(&array->lock);
    *result = array->data[index];
    pthread_mutex_unlock(&array->lock);
    return 0;
}
