// Thread-safe operations with locks
pthread_mutex_t array_mutex;
TX_POWER_LEVEL_STATS** array = NULL;
int count = 0;

void add_power_level_stats(TX_POWER_LEVEL_STATS* stats) {
    pthread_mutex_lock(&array_mutex);
    TX_POWER_LEVEL_STATS** new_array = (TX_POWER_LEVEL_STATS**)realloc(array, (count + 1) * sizeof(TX_POWER_LEVEL_STATS*));
    if (new_array == NULL) {
        pthread_mutex_unlock(&array_mutex);
        return;
    }
    array = new_array;
    array[count] = stats;
    count++;
    pthread_mutex_unlock(&array_mutex);
}

void remove_power_level_stats(int index) {
    pthread_mutex_lock(&array_mutex);
    for (int i = index; i < count - 1; i++) {
        array[i] = array[i + 1];
    }
