#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_REGIONS 100

typedef struct {
    int power_level;
    time_t timestamp;
} TX_POWER_LEVEL_STATS;

typedef struct {
    TX_POWER_LEVEL_STATS *stats_array;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

typedef struct {
    DynamicArray regional_arrays[MAX_REGIONS];
    pthread_mutex_t region_locks[MAX_REGIONS];
} RegionalDatabase;

RegionalDatabase *init_database() {
    RegionalDatabase *db = (RegionalDatabase *)malloc(sizeof(RegionalDatabase));
    if (!db) return NULL;

    for (int i = 0; i < MAX_REGIONS; i++) {
        db->regional_arrays[i].stats_array = NULL;
        db->regional_arrays[i].count = 0;
        pthread_mutex_init(&db->region_locks[i], NULL);
        pthread_mutex_init(&db->regional_arrays[i].lock, NULL);
    }

    return db;
}

void destroy_database(RegionalDatabase *db) {
    for (int i = 0; i < MAX_REGIONS; i++) {
        free(db->regional_arrays[i].stats_array);
        pthread_mutex_destroy(&db->region_locks[i]);
        pthread_mutex_destroy(&db->regional_arrays[i].lock);
    }
    free(db);
}

void add_stats_to_region(RegionalDatabase *db, int region_id, TX_POWER_LEVEL_STATS stats) {
    pthread_mutex_lock(&db->region_locks[region_id]);
    DynamicArray *array = &db->regional_arrays[region_id];

    array->stats_array = realloc(array->stats_array, (array->count + 1) * sizeof(TX_POWER_LEVEL_STATS));
    if (!array->stats_array) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&db->region_locks[region_id]);
        return;
    }

    array->stats_array[array->count++] = stats;

    pthread_mutex_unlock(&db->region_locks[region_id]);
}

void update_stats_in_region(RegionalDatabase *db, int region_id, size_t index, TX_POWER_LEVEL_STATS new_stats) {
    pthread_mutex_lock(&db->region_locks[region_id]);
    DynamicArray *array = &db->regional_arrays[region_id];

    if (index >= array->count) {
        fprintf(stderr, "Index out of bounds\n");
        pthread_mutex_unlock(&db->region_locks[region_id]);
        return;
    }

    array->stats_array[index] = new_stats;

    pthread_mutex_unlock(&db->region_locks[region_id]);
}

TX_POWER_LEVEL_STATS *get_stats_from_region(RegionalDatabase *db, int region_id, size_t index) {
    pthread_mutex_lock(&db->region_locks[region_id]);
    DynamicArray *array = &db->regional_arrays[region_id];

    if (index >= array->count) {
        fprintf(stderr, "Index out of bounds\n");
        pthread_mutex_unlock(&db->region_locks[region_id]);
        return NULL;
    }

    TX_POWER_LEVEL_STATS *stats = &array->stats_array[index];
    pthread_mutex_unlock(&db->region_locks[region_id]);

    return stats;
}

void remove_stats_from_region(RegionalDatabase *db, int region_id, size_t index) {
    pthread_mutex_lock(&db->region_locks[region_id]);
    DynamicArray *array = &db->regional_arrays[region_id];

    if (index >= array->count) {
        fprintf(stderr, "Index out of bounds\n");
        pthread_mutex_unlock(&db->region_locks[region_id]);
        return;
    }

    for (size_t i = index; i < array->count - 1; i++) {
        array->stats_array[i] = array->stats_array[i + 1];
    }

    array->count--;
    pthread_mutex_unlock(&db->region_locks[region_id]);
}
```

