// Define a simple hash function for caching
unsigned long hash(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % 1000; // Simplified for example
}

// Define a cache entry structure
typedef struct CacheEntry {
    char ci[20];
    TX_POWER_LEVEL_STATS stats;
    time_t last_updated;
} CacheEntry;

// Global variables for caching and synchronization
CacheEntry cache[1000];
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to update the cache
void update_cache(const char *ci, const TX_POWER_LEVEL_STATS *stats) {
    pthread_mutex_lock(&cache_lock);
    unsigned long index = hash(ci);
    cache[index].last_updated = time(NULL);
    strcpy(cache[index].ci, ci);
    memcpy(&cache[index].stats, stats, sizeof(TX_POWER_LEVEL_STATS));
    pthread_mutex_unlock(&cache_lock);
}

// Function to get the latest stats from the cache
TX_POWER_LEVEL_STATS *get_latest_stats(const char *ci) {
    TX_POWER_LEVEL_STATS *result = NULL;
    pthread_mutex_lock(&cache_lock);
    unsigned long index = hash(ci);
    if (strcmp(cache[index].ci, ci) == 0 && time(NULL) - cache[index].last_updated < 60) { // Cache entry is valid for 1 minute
        result = &cache[index].stats;
    }
    pthread_mutex_unlock(&cache_lock);
    return result;
}

