typedef struct {
    int id;
    pthread_t thread_id;
} Worker;

Worker workers[MAX_THREADS];
int num_workers = 0;
int task_queue_size = 0;
int task_queue[MAX_THREADS];

void* worker_function(void* arg) {
    int id = *(int*)arg;
    while (1) {
        // Get a task from the queue
        pthread_mutex_lock(&task_queue_mutex);
        if (task_queue_size > 0) {
            int task_id = task_queue[0];
            for (int i = 0; i < task_queue_size - 1; i++) {
                task_queue[i] = task_queue[i + 1];
            }
            task_queue_size--;
        } else {
            pthread_mutex_unlock(&task_queue_mutex);
            break;
        }
        pthread_mutex_unlock(&task_queue_mutex);

        // Process the task
        process_task(task_id);
    }
    return NULL;
}

void add_task(int task_id) {
    pthread_mutex_lock(&task_queue_mutex);
    task_queue[task_queue_size++] = task_id;
    pthread_mutex_unlock(&task_queue_mutex);
}

int main(int argc, char* argv[]) {
    // Parse command line arguments
    parse_arguments(argc, argv);

    // Initialize worker threads
    for (int i = 0; i < num_workers; i++) {
        workers[i].id = i;
        pthread_create(&workers[i].thread_id, NULL, worker_function, &workers[i].id);
    }

    // Add tasks to the queue
    for (int i = 0; i < task_queue_size; i++) {
        add_task(i);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_workers; i++) {
        pthread_join(workers[i].thread_id, NULL);
    }

    return 0;
}
