import threading
from collections import deque
import time

class WebSocketFrame:
    def __init__(self, frame_id, opcode, payload):
        self.frame_id = frame_id
        self.opcode = opcode
        self.payload = payload

class DynamicQueue:
    def __init__(self, max_size=10000):
        self.max_size = max_size
        self.queue = deque()
        self.lock = threading.Lock()

    def enqueue(self, frame):
        with self.lock:
            if len(self.queue) >= self.max_size:
                self.resize_queue(2 * self.max_size)
            self.queue.append(frame)

    def dequeue(self):
        with self.lock:
            return self.queue.popleft() if self.queue else None

    def resize_queue(self, new_size):
        with self.lock:
            while len(self.queue) > new_size // 2:
                self.queue.popleft()
            self.max_size = new_size

class WebSocketClient:
    def __init__(self, api_url):
        self.api_url = api_url
        self.session = requests.Session()
        self.reconnect_interval = 5  # seconds
        self.resend_interval = 10  # seconds

    def connect(self):
        while True:
            try:
                self.session.get(self.api_url)
                break
            except requests.RequestException as e:
                print(f"Connection failed: {e}. Retrying in {self.reconnect_interval} seconds...")
                time.sleep(self.reconnect_interval)

    def send_frame(self, frame):
        while True:
            try:
                response = self.session.post(self.api_url, json=frame.__dict__)
                if response.status_code == 200:
                    return
                else:
                    raise Exception(f"Failed to send frame: {response.text}")
            except requests.RequestException as e:
                print(f"Send failed: {e}. Retrying in {self.resend_interval} seconds...")
                time.sleep(self.resend_interval)

# Example usage
queue = DynamicQueue()
client = WebSocketClient("https://example.com/api/websocket")
frame = WebSocketFrame(1, 0x01, "Hello, World!")
queue.enqueue(frame)
client.connect()
while True:
    frame = queue.dequeue()
    if frame:
        client.send_frame(frame)
```

