#define MAX_DEVICES 1000
#define RETRY_LIMIT 5

typedef struct {
    int device_id;
    char current_status[256];
    char reason_code[256];
    time_t timestamp;
} DEVICE_STATUS_UPDATE_T;

typedef struct {
    DEVICE_STATUS_UPDATE_T devices[MAX_DEVICES];
    int device_count;
    pthread_mutex_t lock;
} BATCH_UPDATE_CONTEXT_T;

void* update_device_status(void* arg) {
    BATCH_UPDATE_CONTEXT_T* context = (BATCH_UPDATE_CONTEXT_T*)arg;
    CURL* curl;
    CURLcode res;

    for (int i = 0; i < context->device_count; ++i) {
        pthread_mutex_lock(&context->lock);
        DEVICE_STATUS_UPDATE_T device = context->devices[i];
        pthread_mutex_unlock(&context->lock);

        char url[256];
        snprintf(url, sizeof(url), "https://api.example.com/devices/%d/status", device.device_id);

        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if(curl) {
            struct curl_slist *headers = NULL;
            headers = curl_slist_append(headers, "Content-Type: application/json");
            headers = curl_slist_append(headers, "Authorization: Bearer YOUR_ACCESS_TOKEN");

            char data[1024];
            snprintf(data, sizeof(data), "{\"status\":\"%s\", \"reason_code\":\"%s\", \"timestamp\":\"%ld\"}",
                     device.current_status, device.reason_code, device.timestamp);

            curl_easy_setopt(curl, CURLOPT_URL, url);
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, data);
            curl_easy_setopt(curl, CURLOPT_VERBOSE, 1L);

            int retry_count = RETRY_LIMIT;
            while (retry_count > 0) {
                res = curl_easy_perform(curl);
                if(res == CURLE_OK) {
                    break;
                } else {
                    printf("Failed to update device status for device ID %d. Retrying...\n", device.device_id);
                    retry_count--;
                    sleep(1 << (RETRY_LIMIT - retry_count)); // Exponential backoff
                }
            }

            if(res != CURLE_OK) {
                fprintf(stderr, "Error: %s\n", curl_easy_strerror(res));
            }

            curl_slist_free_all(headers);
            curl_easy_cleanup(curl);
        }
        curl_global_cleanup();
    }

    return NULL;
}

int batchUpdateDeviceStatuses(BATCH_UPDATE_CONTEXT_T* context) {
    pthread_t threads[context->device_count];
    int rc;

    if (pthread_mutex_init(&context->lock, NULL) != 0) {
        perror("Mutex initialization failed");
        return -1;
    }

    for(int i = 0; i < context->device_count; ++i) {
        if ((rc = pthread_create(&threads[i], NULL, update_device_status, (void*)context)) != 0) {
            perror("Thread creation failed");
            return -1;
        }
    }

    for(int i = 0; i < context->device_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&context->lock);

    return 0;
}
