#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define NFAPI_CRC_INDICATION_PDU_T struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
};

#define MAX_THREADS 10

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    NFAPI_CRC_INDICATION_PDU_T *data;
    int size;
    int capacity;
} UE_Info_Manager;

UE_Info_Manager ue_manager;

void initialize_UE_Info_Manager(int capacity) {
    memset(&ue_manager, 0, sizeof(UE_Info_Manager));
    ue_manager.capacity = capacity;
    ue_manager.data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&ue_manager.lock, NULL);
    pthread_cond_init(&ue_manager.cond, NULL);
}

void destroy_UE_Info_Manager() {
    pthread_mutex_destroy(&ue_manager.lock);
    pthread_cond_destroy(&ue_manager.cond);
    free(ue_manager.data);
}

void add_UE_Info(NFAPI_CRC_INDICATION_PDU_T *info) {
    pthread_mutex_lock(&ue_manager.lock);
    if (ue_manager.size >= ue_manager.capacity) {
        int new_capacity = ue_manager.capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(ue_manager.data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&ue_manager.lock);
            return; // Handle memory allocation failure
        }
        ue_manager.capacity = new_capacity;
        ue_manager.data = new_data;
    }
    memcpy(&ue_manager.data[ue_manager.size], info, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    ue_manager.size++;
    pthread_cond_signal(&ue_manager.cond);
    pthread_mutex_unlock(&ue_manager.lock);
}

void *update_thread(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T new_info;
    while (1) {
        pthread_mutex_lock(&ue_manager.lock);
        while (ue_manager.size == 0) {
            pthread_cond_wait(&ue_manager.cond, &ue_manager.lock);
        }
        memcpy(&new_info, &ue_manager.data[0], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memmove(ue_manager.data, &ue_manager.data[1], --ue_manager.size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pthread_mutex_unlock(&ue_manager.lock);

        // Simulate external data source update
        sleep(1);
    }
    return NULL;
}

int main() {
    initialize_UE_Info_Manager(100);

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, update_thread, NULL);
    }

    // Simulate adding new UE info
    NFAPI_CRC_INDICATION_PDU_T info;
    info.RX_UE_INFORMATION_TAG = 1;
    info.RNTI = 2;
    info.CRC_INDICATION_REL8_TAG = 3;
    add_UE_Info(&info);

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_UE_Info_Manager();
    return 0;
}
