APICreds api_creds;

int process_file(const char *filename, FileStats *stats) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    int line_count = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        line_count++;
    }
    fclose(file);

    stats->filename = strdup(filename);
    stats->line_count = line_count;
    return 0;
}

void* thread_process(void *arg) {
    int thread_id = *(int*)arg;
    // Implement thread-specific logic for processing files
    pthread_exit(NULL);
}

void process_directory(const char *directory, FileStats **stats, int *total_lines, int *num_files) {
    DIR *dir;
    struct dirent *entry;

    dir = opendir(directory);
    if (!dir) {
        perror("Failed to open directory");
        return;
    }

    pthread_t threads[MAX_THREADS];
    int thread_ids[MAX_THREADS];
    int num_threads = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && strstr(entry->d_name, ".txt") != NULL) {
            stats[*num_files] = (FileStats*)malloc(sizeof(FileStats));
            process_file(entry->d_name, &stats[*num_files]);
            (*total_lines) += stats[*num_files]->line_count;
            (*num_files)++;

            if (num_threads < MAX_THREADS) {
                thread_ids[num_threads] = num_threads;
                pthread_create(&threads[num_threads], NULL, thread_process, &thread_ids[num_threads]);
                num_threads++;
            }
        }
    }

    closedir(dir);
}

