    for (int i = 0; i < num_files; i++) {
        if (num_threads < MAX_THREADS) {
            thread_ids[num_threads] = i;
            pthread_create(&threads[num_threads], NULL, api_request, &thread_ids[num_threads]);
            num_threads++;
        }
    }

    // Wait for all threads to finish
}

