#include <iostream>
#include <mutex>
#include <unordered_map>
#include <vector>
#include <condition_variable>

struct USER_ACTIVITY_LOG {
    std::string session_id;
    std::string user_id;
    std::string activity_type;
    time_t timestamp;
    std::map<std::string, std::string> metadata;
};

class ActivityLogManager {
public:
    void addActivity(const USER_ACTIVITY_LOG& log) {
        std::lock_guard<std::mutex> lock(mutex_);
        logs_[log.session_id] = log;
        // Queue the request to distributed NoSQL database
        queueRequest("INSERT", log);
    }

    bool updateActivity(const std::string& session_id, const USER_ACTIVITY_LOG& updated_log) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (logs_.find(session_id) != logs_.end()) {
            logs_[session_id] = updated_log;
            // Queue the request to distributed NoSQL database
            queueRequest("UPDATE", updated_log);
            return true;
        }
        return false;
    }

    std::vector<USER_ACTIVITY_LOG> getActivitiesByUserId(const std::string& user_id) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<USER_ACTIVITY_LOG> activities;
        for (const auto& log : logs_) {
            if (log.second.user_id == user_id) {
                activities.push_back(log.second);
            }
        }
        // Queue the request to RESTful API
        queueRequest("QUERY_USER", {user_id});
        return activities;
    }

private:
    std::mutex mutex_;
    std::unordered_map<std::string, USER_ACTIVITY_LOG> logs_;
    std::condition_variable cv_;
    int max_queue_size_ = 1000;
    int request_count_ = 0;

    void queueRequest(const std::string& operation, const USER_ACTIVITY_LOG& log) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (request_count_ >= max_queue_size_) {
            cv_.wait(lock);
        }
        // Simulate queuing the request
        std::cout << "Queuing " << operation << " for session_id: " << log.session_id << std::endl;
        ++request_count_;
    }

    void processRequests() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return request_count_ > 0; });
            // Process the request from the queue
            --request_count_;
            cv_.notify_all();
        }
    }

    static ActivityLogManager* instance_;
};

ActivityLogManager* ActivityLogManager::instance_ = nullptr;

ActivityLogManager& getInstance() {
    if (instance_ == nullptr) {
        instance_ = new ActivityLogManager();
    }
    return *instance_;
}

int main() {
    auto manager = getInstance();
    USER_ACTIVITY_LOG log1 = {"session1", "user1", "login", time(nullptr), {{"ip", "192.168.1.1"}};
    manager.addActivity(log1);

    USER_ACTIVITY_LOG updated_log = {"session1", "user1", "logout", time(nullptr), {}};
    manager.updateActivity("session1", updated_log);

    auto activities = manager.getActivitiesByUserId("user1");
    for (const auto& activity : activities) {
        std::cout << "Session ID: " << activity.session_id
                  << ", User ID: " << activity.user_id
                  << ", Activity Type: " << activity.activity_type
                  << ", Timestamp: " << ctime(&activity.timestamp)
                  << std::endl;
    }

    return 0;
}
