    void (*deallocator)(void *);
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = (TX_POWER_LEVEL_STATS*)malloc(initial_capacity * sizeof(TX_POWER_LEVEL_STATS));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->capacity = initial_capacity;
    da->size = 0;
    da->allocator = realloc;
    da->deallocator = free;

    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    if (da->array) da->deallocator(da->array);
    da->deallocator(da);
}

int add_power_level_stats(DynamicArray *da, TX_POWER_LEVEL_STATS stats) {
    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity ? da->capacity * 2 : 1;
        void *new_array = da->allocator(&da->array, new_capacity * sizeof(TX_POWER_LEVEL_STATS));
        if (!new_array) return -1;

        da->capacity = new_capacity;
    }

    da->array[da->size++] = stats;
    return 0;
}

TX_POWER_LEVEL_STATS* get_power_level_stats(DynamicArray *da, size_t index) {
    if (index >= da->size) return NULL;
    return &da->array[index];
}
