Microservice* create_microservice(const char* name, int port) {
    Microservice* ms = (Microservice*)malloc(sizeof(Microservice));
    if (ms == NULL) {
        fprintf(stderr, "Failed to allocate memory for microservice\n");
        exit(EXIT_FAILURE);
    }
    ms->name = strdup(name);
    ms->port = port;
    return ms;
}

// Function to free the allocated memory of a microservice
