    if (ms != NULL) {
        free(ms->name);
        free(ms);
    }
}

// Main function to demonstrate creating and freeing a microservice
int main() {
    // Create a new microservice
    Microservice* myService = create_microservice("MyHTTP2Microservice", 8080);

    // Print microservice details
    printf("Microservice Name: %s\n", myService->name);
    printf("Microservice Port: %d\n", myService->port);

    // Free the allocated memory
    free_microservice(myService);

    return 0;
}
