# Import necessary libraries
from flask import Flask, request, jsonify
import redis
import time

app = Flask(__name__)
redis_client = redis.StrictRedis(host='localhost', port=6379, db=0)

# Function to handle user profile creation and updates
@app.route('/profile', methods=['POST'])
def create_or_update_profile():
    user_id = request.json['user_id']
    profile_data = request.json['profile_data']

    # Implement optimistic concurrency control using Redis transactions
    while True:
        try:
            with redis_client.pipeline() as pipe:
                pipe.watch('profile:' + user_id)
                current_profile = pipe.get('profile:' + user_id) or '{}'
                current_profile = json.loads(current_profile)

                if 'version' in current_profile and profile_data['version'] <= current_profile['version']:
                    raise Exception("Stale data")

                # Update the profile and increment version
                profile_data['version'] = current_profile.get('version', 0) + 1
                pipe.multi()
                pipe.set('profile:' + user_id, json.dumps(profile_data))
                pipe.execute()
            break
        except redis.WatchError:
            continue

    return jsonify({'status': 'success'})

# Function to handle user profile retrieval
@app.route('/profile/<user_id>', methods=['GET'])
def get_profile(user_id):
    profile = redis_client.get('profile:' + user_id)
    if profile:
        return jsonify(json.loads(profile))
    else:
        return jsonify({'error': 'Profile not found'}), 404

# Function to handle batch processing of write operations
@app.route('/batch', methods=['POST'])
def batch_operations():
    operations = request.json['operations']

    for operation in operations:
        if operation['type'] == 'create_or_update':
            create_or_update_profile(operation['data'])
        elif operation['type'] == 'delete':
            delete_profile(operation['user_id'])

    return jsonify({'status': 'success'})

# Function to handle user profile deletion
@app.route('/profile/<user_id>', methods=['DELETE'])
def delete_profile(user_id):
    redis_client.delete('profile:' + user_id)
    return jsonify({'status': 'success'})

# Run the Flask application
if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=True)
```

This code snippet provides a basic implementation of a RESTful API for managing user profiles using Flask and Redis. It includes functions to handle user profile creation, updates, retrieval, batch processing, and deletion. The use of Redis transactions ensures optimistic concurrency control, while batch processing helps in optimizing write operations.']

