// Define a dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct DynamicList {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    size_t capacity;
} DynamicList;

// Initialize the dynamic list
void initDynamicList(DynamicList* list, size_t initialCapacity) {
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = 0;
    list->capacity = initialCapacity;
}

// Add an item to the dynamic list
void addToList(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T item) {
    if (list->size == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        list->data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->capacity = newCapacity;
    }
    list->data[list->size++] = item;
}

// Free the dynamic list
void freeDynamicList(DynamicList* list) {
    free(list->data);
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
}

// Example usage of the dynamic list
int main() {
    DynamicList crcIndicationPduList;
    initDynamicList(&crcIndicationPduList, 10);

    NFAPI_CRC_INDICATION_PDU_T pduItem = {12345, 6789, 0};
    addToList(&crcIndicationPduList, pduItem);

    // Add more items as needed

    freeDynamicList(&crcIndicationPduList);
    return 0;
}
