#define MAX_POWER_LEVEL_STATS 1000

typedef struct {
    int power_level;
    char region[50];
} TX_POWER_LEVEL_STATS;

typedef struct {
    TX_POWER_LEVEL_STATS stats[MAX_POWER_LEVEL_STATS];
    int count;
    pthread_mutex_t mutex;
} PowerLevelStatsManager;

PowerLevelStatsManager* create_power_level_stats_manager() {
    PowerLevelStatsManager* manager = (PowerLevelStatsManager*)malloc(sizeof(PowerLevelStatsManager));
    if (manager == NULL) {
        fprintf(stderr, "Failed to allocate memory for power level stats manager.\n");
        return NULL;
    }
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroy_power_level_stats_manager(PowerLevelStatsManager* manager) {
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int add_power_level_stat(PowerLevelStatsManager* manager, TX_POWER_LEVEL_STATS stat) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count >= MAX_POWER_LEVEL_STATS) {
        fprintf(stderr, "Power level stats array is full.\n");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }
    manager->stats[manager->count] = stat;
    manager->count++;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int get_power_level_stat_by_region(PowerLevelStatsManager* manager, char* region, TX_POWER_LEVEL_STATS** stats, int* count) {
    pthread_mutex_lock(&manager->mutex);
    *count = 0;
    for (int i = 0; i < manager->count; i++) {
        if (strcmp(manager->stats[i].region, region) == 0) {
            (*stats)[(*count)] = manager->stats[i];
            (*count)++;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int update_power_level_stat(PowerLevelStatsManager* manager, TX_POWER_LEVEL_STATS newStat) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->count; i++) {
        if (strcmp(manager->stats[i].region, newStat.region) == 0 && manager->stats[i].power_level == newStat.power_level) {
            manager->stats[i] = newStat;
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    fprintf(stderr, "Power level stat not found for update.\n");
    return -1;
}
