// Define the structure for API response data
typedef struct {
    char *data;
    size_t size;
} api_response;

// Function to fetch data from an API asynchronously
void* fetch_data(void* arg) {
    // Simulate API request using libcurl
    CURL *curl;
    CURLcode res;
    api_response *response = (api_response*)malloc(sizeof(api_response));
    response->data = NULL;
    response->size = 0;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "https://api.example.com/data");
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, &write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void*)response);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    return response;
}

// Callback function to handle API response data
size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    api_response *response = (api_response*)userdata;
    size_t realsize = size * nmemb;

    char *new_data = realloc(response->data, response->size + realsize + 1);
    if(new_data == NULL) {
        free(response->data);
        return 0; // out of memory!
    }

    memcpy(&(new_data[response->size]), ptr, realsize);
    new_data[response->size + realsize] = '\0';

    response->data = new_data;
    response->size += realsize;

    return realsize;
}

// Function to process the fetched data
void process_data(api_response *response) {
    // Implement data processing logic here
    printf("Processing data: %s\n", response->data);
    free(response->data);
}

int main() {
    pthread_t thread_id;
    api_response *response;

    // Create a new thread to fetch data asynchronously
    if(pthread_create(&thread_id, NULL, fetch_data, (void*)&response) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    // Wait for the thread to finish and get the response
    pthread_join(thread_id, (void**)&response);

    // Process the fetched data
    process_data(response);

    return 0;
}
```

