// Define the LOGICAL_SWITCH_STATE structure
struct LOGICAL_SWITCH_STATE {
    std::string id;
    std::vector<std::string> vnfs;
    Metrics metrics; // Assume Metrics is a predefined struct for operational states
};

// Define the CachePolicy enum for cache eviction policies
enum class CachePolicy { LRU, MRU, TTL };

// Define the ThreadPool class with configurable concurrency
class ThreadPool {
public:
    explicit ThreadPool(size_t maxThreads) : stop(false) {
        for(size_t i = 0; i < maxThreads; ++i) {
            workers.emplace_back([this] {
                while(true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(queue_mutex);
                        condition.wait(lock, [this] { return stop || !tasks.empty(); });
                        if(stop && tasks.empty())
                            return;
                        task = std::move(tasks.front());
                        tasks.pop();
                    }
                    task();
                }
            });
        }
    }

    template<class F, class... Args>
    void enqueue(F&& f, Args&&... args) {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            if(stop)
                throw std::runtime_error("enqueue on stopped ThreadPool");
            tasks.emplace([f, args...] { (f(args), ...); });
        }
        condition.notify_one();
    }

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        condition.notify_all();
        for(std::thread &worker: workers)
            worker.join();
    }
private:
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::mutex queue_mutex;
    std::condition_variable condition;
    bool stop;
};

