class DEVICE_EVENT_LOGS {
    // Define the structure of DEVICE_EVENT_LOGS
};

class EventLogManager {
public:
    EventLogManager(size_t maxEvents, size_t cacheSize);
    ~EventLogManager();

    void addLog(const DEVICE_EVENT_LOGS& log);
    std::vector<DEVICE_EVENT_LOGS> getLogs() const;

private:
    mutable std::mutex logsMutex;
    std::condition_variable newLogCond;
    std::vector<DEVICE_EVENT_LOGS> logs;
    size_t maxEvents;
};

EventLogManager::EventLogManager(size_t maxEvents, size_t cacheSize)
    : maxEvents(maxEvents), logs() {}

EventLogManager::~EventLogManager() {}

void EventLogManager::addLog(const DEVICE_EVENT_LOGS& log) {
    std::unique_lock<std::mutex> lock(logsMutex);
    if (logs.size() >= maxEvents) {
        newLogCond.wait(lock, [this]() { return logs.size() < maxEvents; });
    }
    logs.push_back(log);
}

std::vector<DEVICE_EVENT_LOGS> EventLogManager::getLogs() const {
    std::lock_guard<std::mutex> lock(logsMutex);
    return logs;
}
```

