public class UserProfileManager
{
    private static readonly Logger logger = LogManager.GetCurrentClassLogger();

    public T LoadUserProfile<T>(string filePath) where T : new()
    {
        try
        {
            if (!File.Exists(filePath))
            {
                logger.Error("File does not exist: {0}", filePath);
                return new T();
            }

            using (FileStream fileStream = File.OpenRead(filePath))
            {
                BinaryFormatter formatter = new BinaryFormatter();
                T userProfile = (T)formatter.Deserialize(fileStream);
                logger.Info("UserProfile loaded successfully.");
                return userProfile;
            }
        }
        catch (Exception ex)
        {
            logger.Error(ex, "Error loading UserProfile from file: {0}", filePath);
            throw;
        }
    }
}
