#include "nfapi_crc_indication.h"

void nfapi_crc_indication_list_init(NFAPI_CRC_INDICATION_LIST_T *list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
}

int nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST_T *list, const NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_NODE_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_NODE_T));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Allocation failure
    }

    new_node->data = *data;
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        list->tail->next = new_node;
    }
    list->tail = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int nfapi_crc_indication_list_remove_by_rnti(NFAPI_CRC_INDICATION_LIST_T *list, RNTI rnti, NFAPI_CRC_INDICATION_PDU_T *removed_data) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_NODE_T *current = list->head;
    NFAPI_CRC_INDICATION_NODE_T *previous = NULL;

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            if (current->next == NULL) {
                list->tail = previous;
            }

            *removed_data = current->data;
            free(current);
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Node not found
}

void nfapi_crc_indication_list_clear(NFAPI_CRC_INDICATION_LIST_T *list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_NODE_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_NODE_T *next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
}

size_t nfapi_crc_indication_list_size(const NFAPI_CRC_INDICATION_LIST_T *list) {
    return list->count;
}
