import hashlib
import os
from concurrent.futures import ThreadPoolExecutor

def md5_hash(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as file:
        for chunk in iter(lambda: file.read(4096), b""):
            hasher.update(chunk)
    return hasher.hexdigest()

def batch_md5_hashes(file_paths):
    results = {}
    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = {executor.submit(md5_hash, path): path for path in file_paths}
        for future in futures.as_completed(futures):
            try:
                path = futures[future]
                hash_value = future.result()
                results[path] = hash_value
            except Exception as e:
                print(f"Error processing {path}: {e}")
    return results

def main():
    file_paths = ['file1.txt', 'file2.txt', 'file3.txt']  # Replace with actual file paths
    hashes = batch_md5_hashes(file_paths)
    for path, hash_value in hashes.items():
        print(f"{path}: {hash_value}")

if __name__ == "__main__":
    main()
