// NetworkPacket.h
#ifndef NETWORK_PACKET_H
#define NETWORK_PACKET_H

#include <string>
#include <chrono>

struct NetworkPacket {
    std::chrono::time_point<std::chrono::system_clock> timestamp;
    std::string sourceIP;
    std::string destinationIP;
    int protocolType;
    size_t payloadSize;
    int packetID;

    // Constructors, getters, and setters
};

#endif

// DistributedDoublyLinkedList.h
#ifndef DISTRIBUTED_DOUBLY_LINKED_LIST_H
#define DISTRIBUTED_DOUBLY_LINKED_LIST_H

#include <mutex>
#include <condition_variable>
#include <atomic>
#include "NetworkPacket.h"

class DistributedDoublyLinkedList {
public:
    void addPacket(const NetworkPacket& packet);
    void removeStalePackets(int ageThreshold);
    std::vector<NetworkPacket> getFilteredPackets(const std::function<bool(const NetworkPacket&)>& filter);

private:
    struct Node {
        NetworkPacket data;
        Node* next;
        Node* prev;
        std::atomic<bool> markedForDeletion;

        Node(const NetworkPacket& packet) : data(packet), next(nullptr), prev(nullptr), markedForDeletion(false) {}
    };

    Node* head;
    Node* tail;
    std::mutex mutex;
    std::condition_variable cv;
    std::atomic<int> size;

    void garbageCollect();
};

#endif

// NetworkMonitorAPI.h
#ifndef NETWORK_MONITOR_API_H
#define NETWORK_MONITOR_API_H

#include <functional>

class NetworkMonitorAPI {
public:
    virtual void subscribeToPackets(const std::function<void(const NetworkPacket&)>& callback) = 0;
    virtual void filterPacketsBySourceIP(const std::string& ip, const std::function<bool(const NetworkPacket&)>& callback) = 0;
    virtual void filterPacketsByProtocolType(int protocolType, const std::function<bool(const NetworkPacket&)>& callback) = 0;

    virtual ~NetworkMonitorAPI() {}
};

#endif

// DistributedDoublyLinkedList.cpp
#include "DistributedDoublyLinkedList.h"

void DistributedDoublyLinkedList::addPacket(const NetworkPacket& packet) {
    std::lock_guard<std::mutex> lock(mutex);
    Node* newNode = new Node(packet);
    if (head == nullptr) {
        head = tail = newNode;
    } else {
        tail->next = newNode;
        newNode->prev = tail;
        tail = newNode;
    }
    size.fetch_add(1);
}

void DistributedDoublyLinkedList::removeStalePackets(int ageThreshold) {
    std::lock_guard<std::mutex> lock(mutex);
    auto now = std::chrono::system_clock::now();
    Node* current = head;
    while (current != nullptr) {
        if (std::chrono::duration_cast<std::chrono::seconds>(now - current->data.timestamp).count() > ageThreshold && !current->markedForDeletion.load()) {
            current->markedForDeletion.store(true);
            cv.notify_all();
        }
        current = current->next;
    }
}

std::vector<NetworkPacket> DistributedDoublyLinkedList::getFilteredPackets(const std::function<bool(const NetworkPacket&)>& filter) {
    std::lock_guard<std::mutex> lock(mutex);
    std::vector<NetworkPacket> filteredPackets;
    Node* current = head;
    while (current != nullptr) {
        if (!current->markedForDeletion.load() && filter(current->data)) {
            filteredPackets.push_back(current->data);
        }
        current = current->next;
    }
    return filteredPackets;
}

void DistributedDoublyLinkedList::garbageCollect() {
    std::unique_lock<std::mutex> lock(mutex, std::defer_lock);
    cv.wait(lock, [this] { return !head || !std::atomic_load(&size); });
    Node* current = head;
    while (current != nullptr) {
        if (current->markedForDeletion.load()) {
            Node* next = current->next;
            delete current;
            current = next;
        } else {
            lock.unlock();
            cv.notify_all();
            std::this_thread::yield();
            lock.lock();
        }
    }
    head = tail = nullptr;
}

// NetworkMonitorAPIImplementation.cpp
#include "NetworkMonitorAPI.h"

class NetworkMonitorAPIImplementation : public NetworkMonitorAPI {
public:
    void subscribeToPackets(const std::function<void(const NetworkPacket&)>& callback) override {
        // Implement subscription logic here
    }

    void filterPacketsBySourceIP(const std::string& ip, const std::function<bool(const NetworkPacket&)>& callback) override {
        // Implement source IP filtering logic here
    }

    void filterPacketsByProtocolType(int protocolType, const std::function<bool(const NetworkPacket&)>& callback) override {
        // Implement protocol type filtering logic here
    }
};

// main.cpp
#include "DistributedDoublyLinkedList.h"
#include "NetworkMonitorAPIImplementation.h"

int main() {
    DistributedDoublyLinkedList packetList;
    NetworkMonitorAPIImplementation networkAPI;

    // Example usage
