typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CrcQueueNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct CrcQueueNode* next;
} CrcQueueNode;

typedef struct CrcQueue {
    CrcQueueNode* front;
    CrcQueueNode* rear;
    pthread_mutex_t lock;
    size_t size;
} CrcQueue;

CrcQueue* createCrcQueue() {
    CrcQueue* queue = (CrcQueue*)malloc(sizeof(CrcQueue));
    if (!queue) return NULL;
    queue->front = queue->rear = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    queue->size = 0;
    return queue;
}

void destroyCrcQueue(CrcQueue* queue) {
    CrcQueueNode* current = queue->front;
    while (current != NULL) {
        CrcQueueNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

bool enqueue(CrcQueue* queue, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&queue->lock);
    CrcQueueNode* newNode = (CrcQueueNode*)malloc(sizeof(CrcQueueNode));
    if (!newNode) {
        pthread_mutex_unlock(&queue->lock);
        return false;
    }
    newNode->data = data;
    newNode->next = NULL;

    if (queue->rear == NULL) {
        queue->front = queue->rear = newNode;
    } else {
        queue->rear->next = newNode;
        queue->rear = newNode;
    }
    queue->size++;
    pthread_mutex_unlock(&queue->lock);
    return true;
}

bool dequeue(CrcQueue* queue, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&queue->lock);
    if (queue->front == NULL) {
        pthread_mutex_unlock(&queue->lock);
        return false;
    }
    CrcQueueNode* temp = queue->front;
    *data = temp->data;
    queue->front = temp->next;

    if (queue->front == NULL) {
        queue->rear = NULL;
    }
    free(temp);
    queue->size--;
    pthread_mutex_unlock(&queue->lock);
    return true;
}

size_t getCrcQueueSize(CrcQueue* queue) {
    size_t size;
    pthread_mutex_lock(&queue->lock);
    size = queue->size;
    pthread_mutex_unlock(&queue->lock);
    return size;
}
