#include <chrono>
#include <algorithm>

// Forward declarations
class SensorData;
class EventBus;

// Singleton for EventBus
class EventBus {
public:
    static EventBus& getInstance() {
        static EventBus instance;
        return instance;
    }

    void publish(const std::string& topic, const SensorData& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        subscribers_[topic].push(data);
        cv_.notify_one();
    }

    void subscribe(const std::string& topic, std::function<void(const SensorData&)> callback) {
        std::lock_guard<std::mutex> lock(mutex_);
        callbacks_[topic].emplace_back(callback);
    }

private:
    EventBus() {}

    std::mutex mutex_;
    std::condition_variable cv_;
    std::unordered_map<std::string, std::queue<SensorData>> subscribers_;
    std::unordered_map<std::string, std::vector<std::function<void(const SensorData&)>>> callbacks_;
};

// Class representing sensor data
class SensorData {
public:
    SensorData(int id, double value, std::chrono::milliseconds timestamp)
        : id_(id), value_(value), timestamp_(timestamp) {}

    int getId() const { return id_; }
    double getValue() const { return value_; }
    std::chrono::milliseconds getTimestamp() const { return timestamp_; }

private:
    int id_;
    double value_;
    std::chrono::milliseconds timestamp_;
};

// Class for sensor data processor
class SensorDataProcessor {
public:
    void process(const SensorData& data) {
        // Process the sensor data here
        std::cout << "Processing sensor data from ID: " << data.getId() << ", Value: " << data.getValue()
                  << ", Timestamp: " << data.getTimestamp().count() << " ms" << std::endl;
    }
};

// Class for managing asynchronous sensor data streams
class SensorDataStreamManager {
public:
    void addSensor(int id, double value, std::chrono::milliseconds timestamp) {
        EventBus::getInstance().publish("sensor_data", SensorData(id, value, timestamp));
    }

private:
    SensorDataProcessor processor_;

    // Worker thread function to process incoming sensor data
    void worker() {
        while (true) {
            std::string topic;
            SensorData data;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                cv_.wait(lock, []{ return !EventBus::getInstance().subscribers_.empty(); });
                topic = EventBus::getInstance().subscribers_.begin()->first;
                data = EventBus::getInstance().subscribers_[topic].front();
                EventBus::getInstance().subscribers_[topic].pop();
            }
            processor_.process(data);
        }
    }

    std::mutex mutex_;
    std::condition_variable cv_;

    // Start worker threads
    void startThreads(size_t num_threads) {
        for (size_t i = 0; i < num_threads; ++i) {
            threads_.emplace_back(&SensorDataStreamManager::worker, this);
        }
    }

    ~SensorDataStreamManager() {
        // Join all worker threads
        for (auto& thread : threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

private:
    std::vector<std::thread> threads_;
};

int main() {
    SensorDataStreamManager manager;
    manager.startThreads(10);

    // Simulate sensor data stream
    for (int i = 0; i < 15000; ++i) {
        manager.addSensor(i, static_cast<double>(i), std::chrono::milliseconds(i));
        std::this_thread::sleep_for(std::chrono::milliseconds(1));
    }

    return 0;
}
