#include <curl/curl.h>

typedef struct {
    int timestamp;
    int ci;
    float power_level;
} TX_POWER_LEVEL_STATS;

typedef struct {
    TX_POWER_LEVEL_STATS *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* dynamic_array_create(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->data = (TX_POWER_LEVEL_STATS*)malloc(initial_capacity * sizeof(TX_POWER_LEVEL_STATS));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void dynamic_array_destroy(DynamicArray *array) {
    free(array->data);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int dynamic_array_add(DynamicArray *array, TX_POWER_LEVEL_STATS item) {
    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        TX_POWER_LEVEL_STATS *new_data = (TX_POWER_LEVEL_STATS*)realloc(array->data, new_capacity * sizeof(TX_POWER_LEVEL_STATS));
        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size++] = item;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

TX_POWER_LEVEL_STATS* dynamic_array_get(DynamicArray *array, int ci) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].ci == ci) {
            pthread_mutex_lock(&array->lock);
            TX_POWER_LEVEL_STATS *item = &array->data[i];
            pthread_mutex_unlock(&array->lock);
            return item;
        }
    }
    return NULL;
}

// Database operations
void db_update(DynamicArray *array, TX_POWER_LEVEL_STATS item) {
    sqlite3 *db;
    char *zErrMsg = 0;
    int rc;

    rc = sqlite3_open("tx_power_stats.db", &db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return;
    }

    // Insert or update the record
    char sql[256];
    sprintf(sql, "INSERT OR REPLACE INTO power_stats VALUES (%d, %d, %.2f)", item.timestamp, item.ci, item.power_level);

    rc = sqlite3_exec(db, sql, 0, 0, &zErrMsg);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", zErrMsg);
        sqlite3_free(zErrMsg);
    }

    sqlite3_close(db);
}

// Third-party API operations
void api_update(DynamicArray *array, TX_POWER_LEVEL_STATS item) {
    CURL *curl;
    CURLcode res;

    curl = curl_easy_init();
    if(curl) {
        char url[256];
        sprintf(url, "https://api.example.com/power_stats?ci=%d&power=%.2f", item.ci, item.power_level);

        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "{}"); // Empty JSON payload

        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }
}

// Cache operations
void cache_update(DynamicArray *array, TX_POWER_LEVEL_STATS item) {
