#include <iostream>
#include <vector>
#include <string>
#include <mutex>
#include <thread>
#include <queue>
#include <condition_variable>

class CacheManager {
private:
    std::unordered_map<std::string, std::string> cache;
    std::mutex mutex;
    std::condition_variable cv;
    int capacity;

public:
    CacheManager(int cap) : capacity(cap) {}

    void put(const std::string& key, const std::string& value) {
        std::unique_lock<std::mutex> lock(mutex);
        if (cache.size() >= capacity) {
            cv.wait(lock, [this] { return !cache.empty(); });
        }
        cache[key] = value;
        lock.unlock();
        cv.notify_all();
    }

    std::string get(const std::string& key) {
        std::unique_lock<std::mutex> lock(mutex);
        if (cache.find(key) != cache.end()) {
            std::string value = cache[key];
            cache.erase(key);
            cache[key] = value; // Move to the end
            return value;
        }
        return "";
    }

    void remove(const std::string& key) {
        std::unique_lock<std::mutex> lock(mutex);
        if (cache.find(key) != cache.end()) {
            cache.erase(key);
        }
        lock.unlock();
        cv.notify_all();
    }
};

class CacheSystem {
private:
    CacheManager manager;
    int N;

public:
    CacheSystem(int n, int capacity) : manager(capacity), N(n) {}

    void handleRequest(const std::string& request) {
        if (request.find("put") != std::string::npos) {
            // Parse key and value from request
            std::string key = parseKey(request);
            std::string value = parseValue(request);
            manager.put(key, value);
        } else if (request.find("get") != std::string::npos) {
            // Parse key from request
            std::string key = parseKey(request);
            std::string value = manager.get(key);
            std::cout << "GET: " << key << " -> " << value << std::endl;
        } else if (request.find("remove") != std::string::npos) {
            // Parse key from request
            std::string key = parseKey(request);
            manager.remove(key);
        }
    }

private:
    std::string parseKey(const std::string& request) {
        // Implement parsing logic for key
        return "key";
    }

    std::string parseValue(const std::string& request) {
        // Implement parsing logic for value
        return "value";
    }
};

int main() {
    int N = 5;
    CacheSystem system(N, 10);
    std::vector<std::thread> threads;

    for (int i = 0; i < N; ++i) {
        threads.emplace_back([&system] {
            while (true) {
                // Simulate request
                std::string request = "put key" + std::to_string(i) + " value" + std::to_string(i);
                system.handleRequest(request);
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
            }
        });
    }

    for (auto& thread : threads) {
