        if let Some(hash) = self.cache.read().await.get(&path) {
            return Ok(hash.clone());
        }

        let result = self.sender.send(HashRequest::HashFile(path)).await?;
        match result {
            // Handle the response from the worker
            _ => unimplemented!(),
        }
    }

    async fn pause(&self) {
        // Implement pause logic
    }

    async fn resume(&self) {
        // Implement resume logic
    }

    async fn cancel(&self) {
        // Implement cancel logic
    }

    async fn worker(mut receiver: mpsc::Receiver<HashRequest>) {
        while let Some(request) = receiver.recv().await {
            match request {
                HashRequest::HashFile(path) => Self::handle_hash_request(path).await,
                HashRequest::Pause => Self::pause_worker(),
                HashRequest::Resume => Self::resume_worker(),
                HashRequest::Cancel => break,
            }
        }
    }

    async fn handle_hash_request(path: PathBuf) {
        if let Ok(contents) = fs::read(&path) {
            let mut hasher = Md5::new();
            hasher.update(&contents);
            let hash = format!("{:x}", hasher.finalize());

            let mut cache = CACHE.write().await;
            cache.insert(path, hash.clone());
        }
    }

    fn pause_worker() {
        // Implement worker pause logic
    }

    fn resume_worker() {
        // Implement worker resume logic
    }
}

