// Define module-level data structures and variables
typedef struct {
    // Array of TX_POWER_LEVEL_STATS records
    TX_POWER_LEVEL_STATS *records;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} TX_POWER_MODULE;

TX_POWER_MODULE tx_power_module;

// Function to initialize the module
void init_tx_power_module() {
    tx_power_module.records = NULL;
    tx_power_module.count = 0;
    tx_power_module.capacity = 16;
    pthread_mutex_init(&tx_power_module.mutex, NULL);
}

// Function to add a new record to the module
int add_record(time_t timestamp, int ci, int power_level) {
    // Thread-safe locking
    pthread_mutex_lock(&tx_power_module.mutex);

    // Resize array if necessary
    if (tx_power_module.count >= tx_power_module.capacity) {
        size_t new_capacity = tx_power_module.capacity * 2;
        TX_POWER_LEVEL_STATS *new_records = realloc(tx_power_module.records, new_capacity * sizeof(TX_POWER_LEVEL_STATS));
        if (!new_records) {
            pthread_mutex_unlock(&tx_power_module.mutex);
            return -1; // Memory allocation failed
        }
        tx_power_module.records = new_records;
        tx_power_module.capacity = new_capacity;
    }

    // Add the new record
    TX_POWER_LEVEL_STATS record = {timestamp, ci, power_level};
    tx_power_module.records[tx_power_module.count++] = record;

    pthread_mutex_unlock(&tx_power_module.mutex);
    return 0; // Success
}

// Function to update a record in the module
int update_record(int ci, int new_power_level) {
    // Thread-safe locking
    pthread_mutex_lock(&tx_power_module.mutex);

    for (size_t i = 0; i < tx_power_module.count; ++i) {
        if (tx_power_module.records[i].ci == ci) {
            tx_power_module.records[i].power_level = new_power_level;
            pthread_mutex_unlock(&tx_power_module.mutex);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&tx_power_module.mutex);
    return -1; // Record not found
}

// Function to retrieve a record from the module
TX_POWER_LEVEL_STATS *get_record(int ci) {
    // Thread-safe locking
    pthread_mutex_lock(&tx_power_module.mutex);

    for (size_t i = 0; i < tx_power_module.count; ++i) {
        if (tx_power_module.records[i].ci == ci) {
            pthread_mutex_unlock(&tx_power_module.mutex);
            return &tx_power_module.records[i];
        }
    }

    pthread_mutex_unlock(&tx_power_module.mutex);
    return NULL; // Record not found
}

