typedef struct dynamic_array_node {
    TX_POWER_LEVEL_STATS *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DYNAMIC_ARRAY_NODE;

DYNAMIC_ARRAY_NODE* create_dynamic_array() {
    DYNAMIC_ARRAY_NODE *node = (DYNAMIC_ARRAY_NODE *)malloc(sizeof(DYNAMIC_ARRAY_NODE));
    node->capacity = 10;
    node->size = 0;
    node->data = (TX_POWER_LEVEL_STATS *)malloc(node->capacity * sizeof(TX_POWER_LEVEL_STATS));
    pthread_mutex_init(&node->mutex, NULL);
    return node;
}

void destroy_dynamic_array(DYNAMIC_ARRAY_NODE *node) {
    free(node->data);
    pthread_mutex_destroy(&node->mutex);
    free(node);
}

void add_tx_power_level_stats(DYNAMIC_ARRAY_NODE *node, TX_POWER_LEVEL_STATS stats) {
    pthread_mutex_lock(&node->mutex);
    if (node->size == node->capacity) {
        node->capacity *= 2;
        node->data = realloc(node->data, node->capacity * sizeof(TX_POWER_LEVEL_STATS));
    }
    node->data[node->size++] = stats;
    pthread_mutex_unlock(&node->mutex);
}

TX_POWER_LEVEL_STATS* get_tx_power_level_stats(DYNAMIC_ARRAY_NODE *node, size_t index) {
    if (index >= node->size) return NULL;
    pthread_mutex_lock(&node->mutex);
    TX_POWER_LEVEL_STATS *stats = &node->data[index];
    pthread_mutex_unlock(&node->mutex);
    return stats;
}

