    array->records = (TX_POWER_LEVEL_STATS*)calloc(initial_capacity, sizeof(TX_POWER_LEVEL_STATS));
    if (!array->records) {
        free(array);
        return NULL;
    }
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array) {
        free(array->records);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

int add_record(DynamicArray* array, TX_POWER_LEVEL_STATS record) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        TX_POWER_LEVEL_STATS* new_records = (TX_POWER_LEVEL_STATS*)realloc(array->records, new_capacity * sizeof(TX_POWER_LEVEL_STATS));
        if (!new_records) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->records = new_records;
        array->capacity = new_capacity;
    }
    array->records[array->size++] = record;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int update_record(DynamicArray* array, int ci, TX_POWER_LEVEL_STATS new_record) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->records[i].ci == ci) {
            array->records[i] = new_record;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1;
}

TX_POWER_LEVEL_STATS* get_record(DynamicArray* array, int ci) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->records[i].ci == ci) {
            TX_POWER_LEVEL_STATS* record = &array->records[i];
            pthread_mutex_unlock(&array->lock);
            return record;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return NULL;
}
