from confluent_kafka import Producer, Consumer, KafkaException
import requests
import json

def kafka_producer():
    producer = Producer({'bootstrap.servers': 'localhost:9092'})
    return producer

def kafka_consumer(topic):
    consumer = Consumer({
        'bootstrap.servers': 'localhost:9092',
        'group.id': 'analytics-group',
        'auto.offset.reset': 'earliest'
    })
    consumer.subscribe([topic])
    return consumer

def fetch_metadata(event_id, metadata_url):
    response = requests.get(f"{metadata_url}/{event_id}")
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception("Failed to fetch metadata")

def process_event(producer, event, metadata_url):
    try:
        metadata = fetch_metadata(event['id'], metadata_url)
        enriched_event = {**event, **metadata}
        producer.produce('enriched-events', json.dumps(enriched_event).encode('utf-8'))
    except Exception as e:
        print(f"Error processing event: {e}")

def main():
    producer = kafka_producer()
    consumer = kafka_consumer('raw-events')
    metadata_url = 'https://example.com/api/metadata'

    try:
        while True:
            msg = consumer.poll(timeout=1.0)
            if msg is None:
                continue

            if msg.error():
                if msg.error().code() == KafkaException._PARTITION_EOF:
                    print(f"End of partition reached {msg.topic()} [{msg.partition()}] at offset {msg.offset()}")
                elif msg.error():
                    raise KafkaException(msg.error())
            else:
                event = json.loads(msg.value().decode('utf-8'))
                process_event(producer, event, metadata_url)
    except KeyboardInterrupt:
        pass
    finally:
        consumer.close()
        producer.flush()

if __name__ == "__main__":
    main()
