#define MAX_STATS 1000000

typedef struct {
    time_t timestamp;
    int cell_id;
    float power_level;
    int sqi;
} TX_POWER_LEVEL_STATS;

TX_POWER_LEVEL_STATS stats[MAX_STATS];
int current_index = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_entry(TX_POWER_LEVEL_STATS new_stat) {
    pthread_mutex_lock(&lock);
    if (current_index < MAX_STATS) {
        stats[current_index++] = new_stat;
    }
    pthread_mutex_unlock(&lock);
}

TX_POWER_LEVEL_STATS* get_entry(int index) {
    pthread_mutex_lock(&lock);
    TX_POWER_LEVEL_STATS* entry = (index >= 0 && index < current_index) ? &stats[index] : NULL;
    pthread_mutex_unlock(&lock);
    return entry;
}

void update_entry(int index, TX_POWER_LEVEL_STATS new_stat) {
    pthread_mutex_lock(&lock);
    if (index >= 0 && index < current_index) {
        stats[index] = new_stat;
    }
    pthread_mutex_unlock(&lock);
