typedef struct {
    time_t timestamp;
    int ci;
    float power_level;
    int sqi;
} TX_POWER_LEVEL_STATS;

typedef struct {
    TX_POWER_LEVEL_STATS *data;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->data = NULL;
    array->count = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    free(array->data);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_entry(DynamicArray *array, TX_POWER_LEVEL_STATS entry) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity == 0 ? 1 : array->capacity * 2;
        TX_POWER_LEVEL_STATS *new_data = (TX_POWER_LEVEL_STATS*)realloc(array->data, new_capacity * sizeof(TX_POWER_LEVEL_STATS));
        if (!new_data) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->count++] = entry;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

TX_POWER_LEVEL_STATS get_entry(DynamicArray *array, size_t index) {
    pthread_mutex_lock(&array->mutex);
    if (index >= array->count) {
        TX_POWER_LEVEL_STATS default_entry = {0};
        pthread_mutex_unlock(&array->mutex);
        return default_entry; // Invalid index
    }
    TX_POWER_LEVEL_STATS entry = array->data[index];
    pthread_mutex_unlock(&array->mutex);
    return entry;
}

void update_entry(DynamicArray *array, size_t index, TX_POWER_LEVEL_STATS new_entry) {
    pthread_mutex_lock(&array->mutex);
    if (index < array->count) {
        array->data[index] = new_entry;
    }
    pthread_mutex_unlock(&array->mutex);
}

// Add more functions as needed for deletion, batch processing, and persistence to database/REST API
