    int start_index = *(int*)arg;
    free(arg);

    for (int i = 0; i < 100000; ++i) {
        pthread_mutex_lock(&mutex);
        if (total_structures >= MAX_STRUCTURES) {
            pthread_mutex_unlock(&mutex);
            break;
        }
        int index = total_structures++;
        pthread_mutex_unlock(&mutex);

        nfaapi_structures[index].RX_UE_INFORMATION_TAG = i % 100;
        nfaapi_structures[index].RNTI = i % 500;
        nfaapi_structures[index].CRC_INDICATION_REL8_TAG = (i % 2) == 0 ? 1 : 0;
    }

    return NULL;
}

