    pthread_t threads[num_threads];
    int thread_args[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        thread_args[i] = i * (MAX_STRUCTURES / num_threads);
        if (pthread_create(&threads[i], NULL, generate_structures, &thread_args[i]) != 0) {
            perror("Failed to create thread");
            return 1;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            return 1;
        }
    }

    if (argc > 2 && strcmp(argv[1], "-cs") == 0) {
        printf("CSV Statistics:\n");
        // Add code to print CSV statistics here
    }

    if (argc > 3 && argv[1][0] == '-' && argv[1][1] == 'o') {
        FILE* output_file = fopen(argv[2], "w");
        if (output_file == NULL) {
            perror("Failed to open output file");
