// Function prototypes for the library
Config* load_config(const char *source);
void merge_configs(Config **configs, int num_configs, Config **merged_config);
void update_config(Config *config, const char *new_value);
void save_config(Config *config, const char *destination);

int main() {
    // Example usage of the library
    Config *static_config = load_config("static.json");
    Config *dynamic_config = load_config("dynamic.yaml");

    Config *merged_config = NULL;
    merge_configs(&static_config, &dynamic_config, 2, &merged_config);

    update_config(merged_config, "API_KEY", "new_api_key");
    save_config(merged_config, "merged_config.json");

    free(static_config);
    free(dynamic_config);
    free(merged_config);

    return 0;
}

// Function to load configuration from a source
Config* load_config(const char *source) {
    Config *config = (Config *)malloc(sizeof(Config));
    config->key = strdup(source);
    config->value = "default_value";
    return config;
}

// Function to merge configurations
void merge_configs(Config **configs, int num_configs, Config **merged_config) {
    *merged_config = configs[0];
    for (int i = 1; i < num_configs; i++) {
        if (strcmp(configs[i]->key, (*merged_config)->key) == 0) {
            free((*merged_config)->value);
            (*merged_config)->value = strdup(configs[i]->value);
        }
    }
}

// Function to update configuration
void update_config(Config *config, const char *new_value) {
    free(config->value);
    config->value = strdup(new_value);
}

// Function to save configuration to a destination
void save_config(Config *config, const char *destination) {
    printf("Saving %s to %s\n", config->key, destination);
}
