#include <pthread.h>

typedef enum {
    LTE_CCCH_TYPE_A,
    LTE_CCCH_TYPE_B,
    // Add more types as needed
} LTE_CCCH_Type;

typedef struct {
    void* nas_pdu;
    size_t nas_pdu_size;
    LTE_CCCH_Type type;
    int priority;
    long timestamp;
} LTE_CCCH_Message;

typedef struct LTE_CCCH_Collection {
    LTE_CCCH_Message** messages;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} LTE_CCCH_Collection;

LTE_CCCH_Collection* lte_ccch_create() {
    LTE_CCCH_Collection* collection = (LTE_CCCH_Collection*)malloc(sizeof(LTE_CCCH_Collection));
    if (!collection) {
        return NULL;
    }
    memset(collection, 0, sizeof(LTE_CCCH_Collection));
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void lte_ccch_destroy(LTE_CCCH_Collection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->messages[i]->nas_pdu);
        free(collection->messages[i]);
    }
    free(collection->messages);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int lte_ccch_add_message(LTE_CCCH_Collection* collection, LTE_CCCH_Message* message) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 16;
        LTE_CCCH_Message** new_messages = (LTE_CCCH_Message**)realloc(collection->messages, new_capacity * sizeof(LTE_CCCH_Message*));
        if (!new_messages) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->messages = new_messages;
        collection->capacity = new_capacity;
    }
    collection->messages[collection->count++] = message;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

// Add more functions as needed (e.g., remove, filter, get_by_criteria)
