class DataSource {
public:
    std::string id;
    std::shared_ptr<void> payload;

    DataSource(std::string _id, std::shared_ptr<void> _payload) : id(_id), payload(_payload) {}
};

class StreamingDataLib {
private:
    std::unordered_map<std::string, DataSource*> dataSources;
    std::mutex dataSourceMutex;
    std::condition_variable dataSourceCondVar;

public:
    void addDataSource(const std::string& id, const std::shared_ptr<void>& payload) {
        std::lock_guard<std::mutex> lock(dataSourceMutex);
        if (dataSources.find(id) != dataSources.end()) {
            throw std::runtime_error("Data source already exists");
        }
        dataSources[id] = new DataSource(id, payload);
        dataSourceCondVar.notify_one();
    }

    void updateDataSource(const std::string& id, const std::shared_ptr<void>& payload) {
        std::lock_guard<std::mutex> lock(dataSourceMutex);
        if (dataSources.find(id) == dataSources.end()) {
            throw std::runtime_error("Data source does not exist");
        }
        delete dataSources[id];
        dataSources[id] = new DataSource(id, payload);
    }

    void removeDataSource(const std::string& id) {
        std::lock_guard<std::mutex> lock(dataSourceMutex);
        if (dataSources.find(id) == dataSources.end()) {
            throw std::runtime_error("Data source does not exist");
        }
        delete dataSources[id];
        dataSources.erase(id);
    }

    DataSource* getDataSource(const std::string& id) const {
        std::lock_guard<std::mutex> lock(dataSourceMutex);
        auto it = dataSources.find(id);
        if (it == dataSources.end()) {
            throw std::runtime_error("Data source does not exist");
        }
        return it->second;
    }

    size_t getDataSourceCount() const {
        std::lock_guard<std::mutex> lock(dataSourceMutex);
        return dataSources.size();
    }
};

int main() {
    StreamingDataLib lib;

    // Example usage
    auto payload = std::make_shared<int>(42);
    lib.addDataSource("source1", payload);

    try {
        auto dataSource = lib.getDataSource("source1");
        std::cout << "Payload: " << *static_cast<int*>(dataSource->payload.get()) << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    lib.removeDataSource("source1");

    return 0;
}
