// Concrete implementation of a data source
class DataSouceImpl : public DataSource {
public:
    DataSouceImpl(std::string id, std::unique_ptr<DataValidationService> validationService)
        : id(id), validationService(std::move(validationService)) {}

    ~DataSouceImpl() override = default;

    std::string getId() const override { return id; }

    void setData(const std::string& payload) override {
        if (validationService->validate(payload)) {
            this->payload = payload;
        } else {
            throw std::runtime_error("Invalid data payload");
        }
    }

    std::string getData() const override { return payload; }

private:
    std::string id;
    std::unique_ptr<DataValidationService> validationService;
    std::string payload;
};

// Interface for tracing spans
class TracingSpan {
public:
    virtual ~TracingSpan() = default;
    virtual std::string getId() const = 0;
    virtual void setTraceId(const std::string& traceId) = 0;
    virtual std::string getTraceId() const = 0;
};

// Concrete implementation of a tracing span
class TracingSpanImpl : public TracingSpan {
public:
    TracingSpanImpl(std::string id, std::unique_ptr<TracingSystem> tracingSystem)
        : id(id), tracingSystem(std::move(tracingSystem)) {}

    ~TracingSpanImpl() override = default;

    std::string getId() const override { return id; }

    void setTraceId(const std::string& traceId) override {
        this->traceId = traceId;
        if (tracingSystem) {
            tracingSystem->record(traceId);
        }
    }

    std::string getTraceId() const override { return traceId; }

private:
    std::string id;
    std::unique_ptr<TracingSystem> tracingSystem;
    std::string traceId;
};

// Interface for data validation services
