        // Simple check for non-empty payload
        return !payload.empty();
    }
};

// Interface for tracing systems
class TracingSystem {
public:
    virtual ~TracingSystem() = default;
    virtual void record(const std::string& traceId) const = 0;
};

// Mock implementation of a tracing system (e.g., Jaeger)
