public:
    StreamingDataLibrary() = default;

    ~StreamingDataLibrary() {
        // Cleanup resources
    }

    void addDataSource(std::unique_ptr<DataSource> dataSource) {
        std::lock_guard<std::mutex> lock(mutex);
        dataSources[dataSource->getId()] = std::move(dataSource);
    }

    void updateDataSource(const std::string& id, const std::string& payload) {
        std::lock_guard<std::mutex> lock(mutex);
        if (dataSources.find(id) != dataSources.end()) {
            dataSources[id]->setData(payload);
        } else {
            throw std::runtime_error("Data source not found");
        }
    }

    void removeDataSource(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex);
        if (dataSources.find(id) != dataSources.end()) {
            dataSources.erase(id);
        } else {
            throw std::runtime_error("Data source not found");
        }
    }

    void addTracingSpan(std::unique_ptr<TracingSpan> tracingSpan) {
        std::lock_guard<std::mutex> lock(mutex);
        tracingSpans[tracingSpan->getId()] = std::move(tracingSpan);
    }

    void updateTracingSpan(const std::string& id, const std::string& traceId) {
        std::lock_guard<std::mutex> lock(mutex);
        if (tracingSpans.find(id) != tracingSpans.end()) {
            tracingSpans[id]->setTraceId(traceId);
        } else {
            throw std::runtime_error("Tracing span not found");
        }
    }

    void removeTracingSpan(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex);
        if (tracingSpans.find(id) != tracingSpans.end()) {
            tracingSpans.erase(id);
        } else {
            throw std::runtime_error("Tracing span not found");
        }
    }

private:
    std::mutex mutex;
    std::unordered_map<std::string, std::unique_ptr<DataSource>> dataSources;
    std::unordered_map<std::string, std::unique_ptr<TracingSpan>> tracingSpans;
};

int main() {
    // Example usage
