#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <functional>
#include <future>
#include <chrono>
#include <atomic>

class SandeshClient {
public:
    SandeshClient(const std::vector<std::string>& servers, int timeout)
        : servers_(servers), timeout_(timeout), shutdown_(false) {}

    void start() {
        for (size_t i = 0; i < num_threads_; ++i) {
            threads_.emplace_back(&SandeshClient::worker, this);
        }
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            shutdown_ = true;
        }
        cv_.notify_all();
        for (std::thread& thread : threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    template<typename F, typename... Args>
    auto enqueue(F&& f, Args&&... args) -> std::future<typename std::result_of<F(Args...)>::type> {
        using return_type = typename std::result_of<F(Args...)>::type;

        auto task = std::make_shared<std::packaged_task<return_type()>>(
            std::bind(std::forward<F>(f), std::forward<Args>(args)...)
        );

        std::future<return_type> res = task->get_future();
        {
            std::unique_lock<std::mutex> lock(mutex_);
            if (shutdown_) {
                throw std::runtime_error("enqueue on stopped SandeshClient");
            }
            tasks_.emplace([task]() { (*task)(); });
        }
        cv_.notify_one();
        return res;
    }

private:
    void worker() {
        while (true) {
            std::function<void()> task;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                cv_.wait(lock, [this] { return shutdown_ || !tasks_.empty(); });
                if (shutdown_ && tasks_.empty()) {
                    return;
                }
                task = std::move(tasks_.front());
                tasks_.pop();
            }
            task();
        }
    }

    std::vector<std::string> servers_;
    int timeout_;
    bool shutdown_;
    std::queue<std::function<void()>> tasks_;
    std::vector<std::thread> threads_;
    std::mutex mutex_;
    std::condition_variable cv_;
    size_t num_threads_ = std::thread::hardware_concurrency();
};

int main() {
    SandeshClient client({"http://server1", "http://server2"}, 5000);
    client.start();

    // Example usage of enqueue
    auto future_result = client.enqueue([]() {
        return 42;
    });

    std::cout << "Result: " << future_result.get() << std::endl;

    client.stop();
    return 0;
}
```

