class RandomNumberGenerator {
private:
    std::mt19937 rng;
    std::uniform_int_distribution<int> distribution;

public:
    RandomNumberGenerator(int min, int max) : rng(std::random_device()()), distribution(min, max) {}

    int generate() {
        return distribution(rng);
    }
};

class RNGService {
protected:
    virtual int generateRandomNumber() = 0;
public:
    virtual ~RNGService() {}
    virtual std::string getProviderName() const = 0;
};

class ServiceA : public RNGService {
private:
    RandomNumberGenerator rng;

public:
    ServiceA() : rng(1, 100) {}

    int generateRandomNumber() override {
        return rng.generate();
    }

    std::string getProviderName() const override {
        return "ServiceA";
    }
};

class ServiceB : public RNGService {
private:
    RandomNumberGenerator rng;

public:
    ServiceB() : rng(1, 200) {}

    int generateRandomNumber() override {
        return rng.generate();
    }

    std::string getProviderName() const override {
        return "ServiceB";
    }
};

class RNGManager {
private:
    std::vector<RNGService*> services;
    std::mutex lock;
    std::condition_variable cv;
    bool stop;

public:
    RNGManager() : stop(false) {}

    void addService(RNGService* service) {
        std::lock_guard<std::mutex> guard(lock);
        services.push_back(service);
    }

    int generateRandomNumber() {
        std::unique_lock<std::mutex> lock(this->lock);
        cv.wait(lock, [this] { return !services.empty(); });
        RNGService* selectedService = services.front();
        services.erase(services.begin());
        return selectedService->generateRandomNumber();
    }

    void start() {
        std::thread([this]() {
            while (!stop) {
                int randomNumber = generateRandomNumber();
                std::cout << "Generated Number: " << randomNumber << std::endl;
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
            }
        }).detach();
    }

    void stopManager() {
        {
            std::lock_guard<std::mutex> guard(lock);
            stop = true;
        }
        cv.notify_all();
    }
};

int main() {
