import java.util.concurrent.*;
import javax.net.ssl.*;

public class StateManager {
    private final ExecutorService executorService;
    private final Cache<String, Object> cache;
    private final ExternalDataSource dataSource1;
    private final ExternalDataSource dataSource2;

    public StateManager(int concurrencyLevel, int cacheSize) {
        this.executorService = Executors.newFixedThreadPool(concurrencyLevel);
        this.cache = Caffeine.newBuilder()
                .maximumSize(cacheSize)
                .expireAfterWrite(5, TimeUnit.MINUTES)
                .build();
        this.dataSource1 = new ExternalDataSource("dataSource1Config");
        this.dataSource2 = new ExternalDataSource("dataSource2Config");
    }

    public Object loadStateObject(String name) throws IOException, ClassNotFoundException {
        if (name.length() > 255) {
            throw new IllegalArgumentException("Name exceeds the maximum length of 255 characters.");
        }
        return cache.get(name, key -> {
            try {
                ObjectInputStream ois = dataSource1.getObjectInputStream();
                Object stateObject = ois.readObject();
                ois.close();
                return stateObject;
            } catch (IOException | ClassNotFoundException e) {
                // Log error and retry logic
                throw new RuntimeException("Failed to load state object", e);
            }
        });
    }

    public void evictStateObject(String name) {
        cache.invalidate(name);
    }

    public void shutdown() {
        executorService.shutdown();
    }
}
