// Import necessary libraries
const axios = require('axios');
const fs = require('fs').promises;
const path = require('path');

class ConfigManager {
    constructor(serviceUrl, localDirs) {
        this.serviceUrl = serviceUrl;
        this.localDirs = localDirs;
        this.configCache = {};
        this.locks = {};
    }

    async fetchServiceConfig() {
        try {
            const response = await axios.get(this.serviceUrl);
            return response.data;
        } catch (error) {
            console.error('Failed to fetch service config:', error);
            return null;
        }
    }

    async readLocalConfigs() {
        let localConfig = {};
        for (const dir of this.localDirs) {
            const files = await fs.readdir(dir);
            for (const file of files) {
                if (path.extname(file) === '.json') {
                    const filePath = path.join(dir, file);
                    const data = await fs.readFile(filePath, 'utf8');
                    localConfig = { ...localConfig, ...JSON.parse(data) };
                }
            }
        }
        return localConfig;
    }

    async mergeConfigs(serviceConfig, localConfig) {
        const mergedConfig = { ...serviceConfig };
        for (const key in localConfig) {
            if (mergedConfig[key] === undefined || typeof mergedConfig[key] !== 'object') {
                mergedConfig[key] = localConfig[key];
            } else {
                mergedConfig[key] = this.mergeConfigs(mergedConfig[key], localConfig[key]);
            }
        }
        return mergedConfig;
    }

    async getConfiguration() {
        const serviceConfig = await this.fetchServiceConfig();
        if (!serviceConfig) {
            return null;
        }
        let localConfig = await this.readLocalConfigs();
        if (this.configCache.timestamp && Date.now() - this.configCache.timestamp < 60000) {
            return this.configCache.config;
        }
        const mergedConfig = this.mergeConfigs(serviceConfig, localConfig);
        this.configCache.config = mergedConfig;
        this.configCache.timestamp = Date.now();
        return mergedConfig;
    }

    async updateConfiguration(configUpdates) {
        try {
            await axios.post(this.serviceUrl, configUpdates);
            delete this.configCache.config; // Invalidate cache
        } catch (error) {
            console.error('Failed to update service config:', error);
        }
    }
}

// Usage example:
const configManager = new ConfigManager('http://configservice.com/api/config', ['/path/to/local/dir1', '/path/to/local/dir2']);
configManager.getConfiguration().then(console.log);
```

