// C++ command execution framework for distributed system
#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <functional>

class CommandManager {
public:
  void addCommand(const std::function<void()>& command) {
    std::lock_guard<std::mutex> lock(mutex_);
    commands_.push_back(command);
    condition_.notify_one();
  }

  void executeCommands(int concurrencyLevel) {
    for (int i = 0; i < concurrencyLevel; ++i) {
      std::thread([this]() {
        while (true) {
          std::function<void()> command;
          {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this] { return !commands_.empty(); });
            command = commands_.back();
            commands_.pop_back();
          }
          command();
        }
      }).detach();
    }
  }

private:
  std::mutex mutex_;
  std::condition_variable condition_;
  std::vector<std::function<void()>> commands_;
};

int main() {
  CommandManager manager;
  manager.addCommand([]() { std::cout << "Executing command 1" << std::endl; });
  manager.addCommand([]() { std::cout << "Executing command 2" << std::endl; });

  manager.executeCommands(2);

  return 0;
}
