['```sql
CREATE OR ALTER PROCEDURE GetEmployeeDetails(
    @SupervisorID INT = NULL,
    @Department VARCHAR(100) = NULL,
    @JobTitle VARCHAR(100) = NULL,
    @MetadataField NVARCHAR(MAX) = NULL,
    @PageNumber INT = 1,
    @PageSize INT = 500
)
AS
BEGIN
    DECLARE @SQL NVARCHAR(MAX);
    SET @SQL = '
        SELECT TOP (@PageSize)
            e.EmployeeID, 
            e.Name, 
            e.City, 
            e.Address
        FROM Employees e WITH (INDEX(EmployeeIndex))
        WHERE 1=1
    ';

    IF @SupervisorID IS NOT NULL
        SET @SQL += ' AND e.SupervisorID = @SupervisorID';

    IF @Department IS NOT NULL
        SET @SQL += ' AND e.Department = @Department';

    IF @JobTitle IS NOT NULL
        SET @SQL += ' AND e.JobTitle = @JobTitle';

    IF @MetadataField IS NOT NULL
        SET @SQL += ' AND EXISTS (SELECT 1 FROM Metadata m WHERE m.EmployeeID = e.EmployeeID AND JSON_VALUE(m.Metadata, '$.' + @MetadataField + "') IS NOT NULL)";

    SET @SQL += '
        ORDER BY e.EmployeeID OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY
    ';

    EXEC sp_executesql @SQL,
                      N'@SupervisorID INT, @Department VARCHAR(100), @JobTitle VARCHAR(100), @MetadataField NVARCHAR(MAX), @PageNumber INT, @PageSize INT',
                      @SupervisorID, @Department, @JobTitle, @MetadataField, @PageNumber, @PageSize;
END
```

This code block defines a stored procedure `GetEmployeeDetails` that retrieves employee details based on the provided filters (`@SupervisorID`, `@Department`, `@JobTitle`, and `@MetadataField`). It uses pagination to fetch up to 500 records per page starting from a specified page number. The procedure dynamically constructs the SQL query using `sp_executesql` to handle dynamic parameters and index hints for efficient querying.']

