use actix_web::{web, App, HttpResponse, HttpServer, Responder};
use reqwest::Client;
use tokio::sync::Mutex;

struct AppState {
    client: Client,
    cache: Mutex<std::collections::HashMap<String, String>>,
}

async fn index(data: web::Data<AppState>) -> impl Responder {
    let item = data.cache.lock().await.get("key");
    match item {
        Some(value) => HttpResponse::Ok().body(*value),
        None => {
            let response = data.client.get("http://example.com").send().await.unwrap();
            let content = response.text().await.unwrap();
            data.cache.lock().await.insert("key".to_string(), content.clone());
            HttpResponse::Ok().body(content)
        }
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .app_data(web::Data::new(AppState {
                client: Client::new(),
                cache: Mutex::new(std::collections::HashMap::new()),
            }))
            .route("/", web::get().to(index))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
