const fs = require('fs');
const crypto = require('crypto');

function updateConfigFile(configFilePath, envSettings) {
  try {
    // Read the existing configuration file
    let configFile = fs.readFileSync(configFilePath, 'utf8');
    let configObject = JSON.parse(configFile);

    // Update the configuration object with environment-specific settings
    for (let key in envSettings) {
      if (envSettings.hasOwnProperty(key)) {
        let value = envSettings[key];
        if (typeof value === 'string' && value.startsWith('ENC(')) {
          // Decrypt sensitive values
          value = crypto.createDecipheriv('aes-256-cbc', Buffer.from(value.split('|')[1], 'hex'), Buffer.from(value.split('|')[2], 'hex')).update(Buffer.from(value.split('|')[3], 'hex'), 'hex', 'utf8') + crypto.createDecipheriv('aes-256-cbc', Buffer.from(value.split('|')[1], 'hex'), Buffer.from(value.split('|')[2], 'hex')).final('utf8');
        }
        configObject[key] = value;
      }
    }

    // Write the updated configuration back to the file
    fs.writeFileSync(configFilePath, JSON.stringify(configObject, null, 2));
    console.log('Configuration file updated successfully.');
  } catch (error) {
    console.error('Error updating configuration file:', error);
  }
}

// Example usage
const envSettings = {
  DB_PASSWORD: 'ENC(123456|key1|iv1|ciphertext1)',
  API_KEY: 'abcde12345'
};
updateConfigFile('./config.json', envSettings);
```

This script updates a configuration file by replacing environment-specific settings with actual values from a provided JSON object. It reads the existing configuration file, parses it into an object, and then updates the object with the new environment settings. If the setting value starts with 'ENC(', it decrypts the sensitive value using AES-256-CBC encryption before updating the configuration. Finally, it writes the updated configuration back to the file. The script includes error handling to catch any issues that may occur during the file operations or decryption process."]

