    public DataIngestionPipeline(int poolSize, int queueCapacity) {
        this.executorService = Executors.newFixedThreadPool(poolSize);
        this.messageQueue = new ArrayBlockingQueue<>(queueCapacity);
    }

    public void start() {
        // Start the RESTful API client
        executorService.submit(new RestApiClient(messageQueue));

        // Start the WebSocket server
        executorService.submit(new WebSocketServer(messageQueue));

        // Start the batch file uploader
        executorService.submit(new BatchFileUploader(messageQueue));
    }

    private static class RestApiClient implements Runnable {
        private BlockingQueue<String> messageQueue;

        public RestApiClient(BlockingQueue<String> messageQueue) {
            this.messageQueue = messageQueue;
        }

        @Override
        public void run() {
            // Secure RESTful API client logic with mutual TLS and retry mechanisms
            while (true) {
                try {
                    String data = fetchRestData();
                    if (!messageQueue.offer(data, 100, TimeUnit.MILLISECONDS)) {
                        System.out.println("Failed to offer data into queue");
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        private String fetchRestData() {
            // Implementation of RESTful API data fetching logic
            return "REST Data";
        }
    }

    private static class WebSocketServer implements Runnable {
        private BlockingQueue<String> messageQueue;

        public WebSocketServer(BlockingQueue<String> messageQueue) {
            this.messageQueue = messageQueue;
        }

        @Override
        public void run() {
            // WebSocket server logic, considering latency and throughput trade-offs
            while (true) {
                try {
                    String data = receiveWebSocketData();
                    if (!messageQueue.offer(data, 100, TimeUnit.MILLISECONDS)) {
                        System.out.println("Failed to offer data into queue");
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        private String receiveWebSocketData() {
            // Implementation of WebSocket data receiving logic
            return "WebSocket Data";
        }
    }

    private static class BatchFileUploader implements Runnable {
        private BlockingQueue<String> messageQueue;

        public BatchFileUploader(BlockingQueue<String> messageQueue) {
            this.messageQueue = messageQueue;
        }

        @Override
        public void run() {
            // Batch file uploader logic, handling concurrent ingestions
            while (true) {
                try {
                    String data = readBatchFile();
                    if (!messageQueue.offer(data, 100, TimeUnit.MILLISECONDS)) {
                        System.out.println("Failed to offer data into queue");
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        private String readBatchFile() {
            // Implementation of batch file reading logic
            return "Batch File Data";
        }
    }

    public void stop() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    public static void main(String[] args) {
        DataIngestionPipeline pipeline = new DataIngestionPipeline(10, 1000);
        pipeline.start();

        // Simulate system shutdown
        try {
            TimeUnit.HOURS.sleep(1);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        pipeline.stop();
    }
}
