#include <xmlpp/xml_document.h>
#include <xmlpp/node_element.h>

class DynamicXMLProcessor {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::queue<std::shared_ptr<xmlpp::Document>> xmlQueue;
    bool stopProcessing;

public:
    DynamicXMLProcessor() : stopProcessing(false) {}

    ~DynamicXMLProcessor() {
        stopProcessing = true;
        cv.notify_all();
    }

    void UpdatePreferencesAsync(std::istream& xmlStream) {
        std::shared_ptr<xmlpp::Document> doc = std::make_shared<xmlpp::Document>();
        try {
            doc->read_from_stream(xmlStream);
        } catch (const xmlpp::exception& e) {
            std::cerr << "Failed to parse XML: " << e.what() << std::endl;
            return;
        }

        {
            std::lock_guard<std::mutex> lock(mtx);
            xmlQueue.push(doc);
        }
        cv.notify_one();
    }

    void worker() {
        while (true) {
            std::shared_ptr<xmlpp::Document> doc;
            {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait(lock, [this] { return !xmlQueue.empty() || stopProcessing; });
                if (stopProcessing && xmlQueue.empty()) {
                    break;
                }
                doc = xmlQueue.front();
                xmlQueue.pop();
            }

            // Process the XML document
            std::cout << "Processing document: " << doc->get_root_node()->get_name() << std::endl;
        }
    }

    void startProcessing() {
        for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
            std::thread([this] { worker(); }).detach();
        }
    }
};

int main() {
    DynamicXMLProcessor processor;
    processor.startProcessing();

    // Simulate processing an XML file
    std::ifstream xmlFile("preferences.xml");
    if (xmlFile.is_open()) {
        processor.UpdatePreferencesAsync(xmlFile);
    } else {
        std::cerr << "Failed to open XML file" << std::endl;
    }

    return 0;
}
