#include <iostream>
#include <string>
#include <unordered_map>
#include <fstream>
#include <json/json.h>
#include <yaml-cpp/yaml.h>
#include <libconfig.h++>

class ConfigManager {
public:
    void loadConfig(const std::string& filePath, const std::string& format) {
        if (format == "json") {
            Json::Value root;
            Json::Reader reader;
            std::ifstream file(filePath);
            if (!reader.parse(file, root)) {
                throw std::runtime_error("Failed to parse JSON config");
            }
            loadConfigFromJson(root);
        } else if (format == "yaml") {
            YAML::Node config = YAML::LoadFile(filePath);
            loadConfigFromYaml(config);
        } else if (format == "ini") {
            libconfig::Config cfg;
            try {
                cfg.readFile(filePath.c_str());
            } catch(libconfig::FileIOException &fioex) {
                std::cerr << "I/O error while reading config file: " << fioex.what() << std::endl;
            } catch(libconfig::ParseException &pex) {
                std::cerr << "Parse error at " << pex.getFile() << ":" << pex.getLine()
                          << " - " << pex.getError() << std::endl;
            }
            loadConfigFromIni(cfg);
        } else {
            throw std::runtime_error("Unsupported config format");
        }
    }

private:
    void loadConfigFromJson(const Json::Value& root) {
        for (const auto& item : root) {
            configs_[item.key()] = item.asString();
        }
    }

    void loadConfigFromYaml(const YAML::Node& config) {
        for (const auto& item : config.items()) {
            configs_[item.first.as<std::string>()] = item.second.as<std::string>();
        }
    }

    void loadConfigFromIni(const libconfig::Config& cfg) {
        try {
            const libconfig::Setting& root = cfg.getRoot();
            for (int i = 0; i < root.getLength(); ++i) {
                const libconfig::Setting& section = root[i];
                std::string sectionName = section.getName();
                for (int j = 0; j < section.getLength(); ++j) {
                    const libconfig::Setting& item = section[j];
                    configs_[sectionName + "." + item.getName()] = item.getValue<std::string>();
                }
            }
        } catch(libconfig::SettingNotFoundException &nfex) {
            std::cerr << "No such setting: " << nfex.getPath() << std::endl;
        }
    }

    std::unordered_map<std::string, std::string> configs_;
};

int main() {
    ConfigManager configManager;
    configManager.loadConfig("config.json", "json");
    return 0;
}
