struct ProductInventoryItem {
    std::string id;
    int quantity;
    double price;
};

class InventoryManager {
public:
    void updateInventory(const ProductInventoryItem& item);
    ProductInventoryItem getInventoryItem(const std::string& id);

private:
    std::map<std::string, ProductInventoryItem> inventoryMap;
    std::mutex inventoryMutex;
    std::condition_variable updateCondition;

    void processUpdates() {
        while (true) {
            std::unique_lock<std::mutex> lock(updateMutex);
            updateCondition.wait(lock, [this] { return !updatesQueue.empty(); });

            auto item = updatesQueue.front();
            updatesQueue.pop();

            lock.unlock();

            updateInventory(item);
        }
    }

    std::queue<ProductInventoryItem> updatesQueue;
    std::mutex updateMutex;
    std::thread updateThread;
};

void InventoryManager::updateInventory(const ProductInventoryItem& item) {
    std::lock_guard<std::mutex> lock(inventoryMutex);
    inventoryMap[item.id] = item;
}

ProductInventoryItem InventoryManager::getInventoryItem(const std::string& id) {
    std::lock_guard<std::mutex> lock(inventoryMutex);
    if (inventoryMap.find(id) != inventoryMap.end()) {
        return inventoryMap[id];
    } else {
        throw std::runtime_error("Product not found");
    }
}

int main() {
    InventoryManager manager;
    manager.updateThread = std::thread(&InventoryManager::processUpdates, &manager);

    // Simulate inventory updates
    ProductInventoryItem item1 = {"item1", 100, 25.99};
    ProductInventoryItem item2 = {"item2", 200, 45.99};

    manager.updateInventory(item1);
    manager.updateInventory(item2);

    // Simulate getting inventory
    try {
        auto item = manager.getInventoryItem("item1");
        std::cout << "Item ID: " << item.id << ", Quantity: " << item.quantity << ", Price: $" << item.price << std::endl;
    } catch (const std::runtime_error& e) {
        std::cerr << e.what() << std::endl;
    }

    manager.updateThread.join();
    return 0;
}
