#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_CELLS 1000
#define MAX_POWER_LEVEL 127

typedef struct {
    time_t timestamp;
    int ci;
    int power_level;
} TX_POWER_LEVEL_STATS;

TX_POWER_LEVEL_STATS dynamic_array[MAX_CELLS];
int cell_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
sem_t semaphore;

void add_entry(int ci, int power_level) {
    pthread_mutex_lock(&mutex);
    if (cell_count < MAX_CELLS) {
        dynamic_array[cell_count].timestamp = time(NULL);
        dynamic_array[cell_count].ci = ci;
        dynamic_array[cell_count].power_level = power_level;
        cell_count++;
        sem_post(&semaphore);
    } else {
        fprintf(stderr, "Dynamic array is full\n");
    }
    pthread_mutex_unlock(&mutex);
}

void update_entry(int ci, int power_level) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < cell_count; i++) {
        if (dynamic_array[i].ci == ci) {
            dynamic_array[i].timestamp = time(NULL);
            dynamic_array[i].power_level = power_level;
            sem_post(&semaphore);
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    fprintf(stderr, "CI not found\n");
    pthread_mutex_unlock(&mutex);
}

TX_POWER_LEVEL_STATS* get_entry(int ci) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < cell_count; i++) {
        if (dynamic_array[i].ci == ci) {
            sem_post(&semaphore);
            pthread_mutex_unlock(&mutex);
            return &dynamic_array[i];
        }
    }
    sem_post(&semaphore);
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void initialize_library() {
    sem_init(&semaphore, 0, 1);
}

void cleanup_library() {
    sem_destroy(&semaphore);
}
