#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>

// Define a simple financial data structure
struct FinancialData {
    std::string instrument;
    double price;
    long timestamp;
};

// Interface for processing financial data
class FinancialDataProcessor {
public:
    virtual ~FinancialDataProcessor() = default;
    virtual void process(const FinancialData& data) = 0;
};

// Concrete implementation of the processor that outputs data to console
class ConsoleProcessor : public FinancialDataProcessor {
public:
    void process(const FinancialData& data) override {
        std::cout << "Processing financial data: Instrument=" << data.instrument
                  << ", Price=" << data.price << ", Timestamp=" << data.timestamp << std::endl;
    }
};

// Thread-safe container for financial data
class DataQueue {
private:
    std::vector<FinancialData> queue_;
    std::mutex mutex_;
    std::condition_variable cond_;

public:
    void enqueue(const FinancialData& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push_back(data);
        cond_.notify_one();
    }

    bool dequeue(FinancialData& data) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (cond_.wait_for(lock, std::chrono::seconds(1), [this]{ return !queue_.empty(); })) {
            data = queue_.back();
            queue_.pop_back();
            return true;
        }
        return false;
    }
};

// Worker thread for processing financial data
class DataProcessorThread {
private:
    FinancialDataProcessor& processor_;
    DataQueue& queue_;

public:
    DataProcessorThread(FinancialDataProcessor& processor, DataQueue& queue)
        : processor_(processor), queue_(queue) {}

    void run() {
        while (true) {
            FinancialData data;
            if (queue_.dequeue(data)) {
                processor_.process(data);
            }
        }
    }
};

int main() {
    ConsoleProcessor processor;
    DataQueue queue;

    std::vector<std::thread> threads;
    for (size_t i = 0; i < 4; ++i) { // Create 4 worker threads
        threads.emplace_back(DataProcessorThread(processor, queue));
    }

    // Simulate data ingestion from different sources
    FinancialData data1{"AAPL", 150.75, std::chrono::system_clock::now().time_since_epoch().count()};
    FinancialData data2{"GOOGL", 2800.25, std::chrono::system_clock::now().time_since_epoch().count()};
    queue.enqueue(data1);
    queue.enqueue(data2);

    for (auto& thread : threads) {
        if (thread.joinable()) {
            thread.join();
        }
    }

    return 0;
}
