import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DataProcessingPipeline {

    private ExecutorService executorService;
    private ExternalDataSourceManager dataSourceManager;
    private DataTransformer transformer;
    private DataAggregator aggregator;
    private ErrorHandling errorHandler;

    public DataProcessingPipeline(int threadPoolSize) {
        this.executorService = Executors.newFixedThreadPool(threadPoolSize);
        this.dataSourceManager = new ExternalDataSourceManager();
        this.transformer = new DataTransformer();
        this.aggregator = new DataAggregator();
        this.errorHandler = new ErrorHandling();
    }

    public void start() {
        // Start all data source listeners
        dataSourceManager.registerListener(data -> executorService.submit(() -> processData(data)));

        // Schedule periodic aggregation tasks
        executorService.scheduleAtFixedRate(aggregator::aggregateData, 0, 5, TimeUnit.MINUTES);

        // Handle shutdown gracefully
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            try {
                executorService.shutdown();
                if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                    executorService.shutdownNow();
                }
            } catch (InterruptedException e) {
                executorService.shutdownNow();
            }
        }));
    }

    private void processData(Object data) {
        try {
            Object transformedData = transformer.transform(data);
            errorHandler.handle(transformedData, aggregator::storeData);
        } catch (Exception e) {
            errorHandler.handleError(e);
        }
    }

    // Additional methods for configuration and management
}

class ExternalDataSourceManager {
    public void registerListener(Consumer<Object> listener) {
        // Logic to register a listener for data stream from various sources
    }
}

class DataTransformer {
    public Object transform(Object data) {
        // Logic to transform raw data into a unified format
        return data;
    }
}

class DataAggregator {
    public void aggregateData() {
        // Logic to aggregate transformed data
    }

    public void storeData(Object data) {
        // Logic to store aggregated data in the target system
    }
}

class ErrorHandling {
    public void handle(Object data, Runnable onSuccess) {
        try {
            onSuccess.run();
        } catch (Exception e) {
            handleError(e);
        }
    }

    public void handleError(Exception e) {
        // Logic to handle errors and retries or failover mechanisms
    }
}
```

