import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class BatchFileDeletionManager {

    private static final String[] EXCLUDE_FILE_TYPES = {".tmp", ".log"};
    private static final int DELETION_LIMIT_PER_DIRECTORY = 1000;
    private static final long FILE_AGE_THRESHOLD = 7;
    private static final long MODIFIED_TIME_THRESHOLD = 24;

    private ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public void startBatchFileDeletion() {
        String[] directories = {"dir1", "dir2", "dir3"};
        for (String directory : directories) {
            executorService.submit(() -> deleteFilesInDirectory(directory));
        }
    }

    private void deleteFilesInDirectory(String directoryPath) {
        Path directory = Paths.get(directoryPath);
        try {
            Files.walk(directory)
                 .filter(Files::isRegularFile)
                 .forEach(this::deleteIfEligible);
        } catch (Exception e) {
            // Handle exception
        }
    }

    private void deleteIfEligible(Path filePath) {
        File file = filePath.toFile();
        if (isOlderThanThreshold(file) && !isRecentlyModified(file)) {
            try {
                Files.delete(filePath);
            } catch (Exception e) {
                // Handle exception
            }
        }
    }

    private boolean isOlderThanThreshold(File file) {
        LocalDateTime lastModified = file.toPath().getBasicFileAttributes().lastModifiedTime().toInstant().atZone(java.time.ZoneId.systemDefault()).toLocalDateTime();
        return ChronoUnit.DAYS.between(lastModified, LocalDateTime.now()) > FILE_AGE_THRESHOLD;
    }

    private boolean isRecentlyModified(File file) {
        LocalDateTime lastModified = file.toPath().getBasicFileAttributes().lastModifiedTime().toInstant().atZone(java.time.ZoneId.systemDefault()).toLocalDateTime();
        return ChronoUnit.HOURS.between(lastModified, LocalDateTime.now()) < MODIFIED_TIME_THRESHOLD;
    }

    private void enforceResourceUsagePolicies() {
        // Logic to enforce resource usage policies
    }

    private void implementCircuitBreakersAndBulkheads() {
        // Logic to implement circuit breakers and bulkheads
    }

    public static void main(String[] args) {
        BatchFileDeletionManager manager = new BatchFileDeletionManager();
        manager.startBatchFileDeletion();
    }
}
