from flask import Flask, request, jsonify
import requests
import redis
from functools import wraps

app = Flask(__name__)
redis_client = redis.StrictRedis(host='localhost', port=6379, db=0)

# Example of a rate limiting decorator
def rate_limit(limit: int):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if redis_client.incr('hits') > limit:
                return jsonify({"error": "Rate limit exceeded"}), 429
            redis_client.expire('hits', 60)  # Reset the counter after a minute
            return func(*args, **kwargs)
        return wrapper
    return decorator

@app.route('/api/data', methods=['GET'])
@rate_limit(1000)  # Example rate limit
def get_data():
    try:
        response = requests.get('https://external-api.com/data')
        response.raise_for_status()
        data = response.json()
        return jsonify(data)
    except requests.RequestException as e:
        return jsonify({"error": str(e)}), 502

if __name__ == '__main__':
    app.run(debug=True, threaded=True, processes=4)
```

