import org.springframework.cloud.gateway.route.RouteLocator;
import org.springframework.cloud.gateway.route.builder.RouteLocatorBuilder;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class GatewayConfig {

    @Bean
    public RouteLocator customRouteLocator(RouteLocatorBuilder builder) {
        return builder.routes()
            .route("payment_processor", r -> r.path("/api/payment/**")
                .uri("lb://payment-service")
                .filters(f -> f.stripPrefix(1))
                .predicate(p -> p.header("Authorization", "Bearer .*"))
                .filter(f -> f.rewritePath("/api/payment/(?<segment>.*$)", "/${segment}")))
            .route("logging_service", r -> r.path("/api/logs/**")
                .uri("lb://logging-service")
                .filters(f -> f.stripPrefix(1))
                .predicate(p -> p.header("Authorization", "Bearer .*"))
                .filter(f -> f.rewritePath("/api/logs/(?<segment>.*$)", "/${segment}")))
            .build();
    }
}
