// Java Library Code Placeholder

// Serializable interface
public interface Serializable {
    byte[] serialize();
}

// Deserializable interface
public interface Deserializable<T> {
    T deserialize(byte[] data);
}

// Serializer class
public class Serializer {
    private Map<Class<?>, Serializable> serializers = new ConcurrentHashMap<>();

    public void register(Class<?> clazz, Serializable serializer) {
        // Register a serializer for a specific class
        if (serializers.containsKey(clazz)) {
            throw new IllegalArgumentException("Serializer already registered for " + clazz);
        }
        serializers.put(clazz, serializer);
    }

    public byte[] serialize(Object object) throws Exception {
        Class<?> clazz = object.getClass();
        Serializable serializer = serializers.get(clazz);
        if (serializer == null) {
            throw new IllegalArgumentException("No serializer registered for " + clazz);
        }
        return serializer.serialize(object);
    }
}

// Deserializer class
public class Deserializer {
    private Map<Class<?>, Deserializable<?>> deserializers = new ConcurrentHashMap<>();

    public <T> void register(Class<T> clazz, Deserializable<T> deserializer) {
        // Register a deserializer for a specific class
        if (deserializers.containsKey(clazz)) {
            throw new IllegalArgumentException("Deserializer already registered for " + clazz);
        }
        deserializers.put(clazz, deserializer);
    }

    public <T> T deserialize(byte[] data, Class<T> clazz) throws Exception {
        Deserializable<T> deserializer = (Deserializable<T>) deserializers.get(clazz);
        if (deserializer == null) {
            throw new IllegalArgumentException("No deserializer registered for " + clazz);
        }
        return deserializer.deserialize(data);
    }
}

