// Include necessary headers
#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>

// Define constants
const int MAX_UPDATE_RATE = 200000; // Maximum updates per minute

// Define data structures
struct ProductInventoryItem {
    std::string id;
    int quantity;
};

// Thread pool implementation for handling concurrent inventory updates
class ThreadPool {
private:
    std::vector<std::thread> workers;
    std::queue<ProductInventoryItem> updateQueue;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool stop;

public:
    ThreadPool(size_t threads) : stop(false) {
        for (size_t i = 0; i < threads; ++i)
            workers.emplace_back([this] {
                for (;;) {
                    ProductInventoryItem task;
                    {
                        std::unique_lock<std::mutex> lock(this->queueMutex);
                        this->condition.wait(lock, [this] { return this->stop || !this->updateQueue.empty(); });
                        if (this->stop && this->updateQueue.empty())
                            return;
                        task = std::move(this->updateQueue.front());
                        this->updateQueue.pop();
                    }
                    processUpdate(task);
                }
            });
    }

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread &worker : workers)
            worker.join();
    }

    void enqueue(ProductInventoryItem task) {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            updateQueue.push(task);
        }
        condition.notify_one();
    }

private:
    void processUpdate(const ProductInventoryItem& item) {
