typedef struct {
    int power_level;
    char api_source[50];
} TX_POWER_LEVEL_STATS;

typedef struct {
    TX_POWER_LEVEL_STATS *stats_array;
    size_t count;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->stats_array = NULL;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    if (array->stats_array != NULL) {
        free(array->stats_array);
    }
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

void add_stats_to_array(DynamicArray *array, TX_POWER_LEVEL_STATS stats) {
    pthread_mutex_lock(&array->mutex);
    array->count++;
    array->stats_array = (TX_POWER_LEVEL_STATS*)realloc(array->stats_array, array->count * sizeof(TX_POWER_LEVEL_STATS));
    array->stats_array[array->count - 1] = stats;
    pthread_mutex_unlock(&array->mutex);
}

void* thread_function(void *arg) {
    DynamicArray *array = (DynamicArray*)arg;
    TX_POWER_LEVEL_STATS new_stats = { .power_level = rand() % 100, .api_source = "API_X" };
    add_stats_to_array(array, new_stats);
    return NULL;
}

int main() {
    DynamicArray *array = create_dynamic_array();

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_function, array);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Number of stats added: %zu\n", array->count);

    destroy_dynamic_array(array);
    return 0;
}
