    std::string data;
};

class EventLogManager {
public:
    EventLogManager() : running(true) {}

    ~EventLogManager() {
        stop();
    }

    void start() {
        ingestionThread = std::thread(&EventLogManager::ingestEvents, this);
        storageThread = std::thread(&EventLogManager::storeEvents, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            running = false;
        }
        cv.notify_all();
        ingestionThread.join();
        storageThread.join();
    }

    void ingestEvent(const Event& event) {
        {
            std::unique_lock<std::mutex> lock(mutex);
            eventQueue.push(event);
        }
        cv.notify_one();
    }

private:
    bool running;
    std::thread ingestionThread;
    std::thread storageThread;
    std::queue<Event> eventQueue;
    std::mutex mutex;
    std::condition_variable cv;

    void ingestEvents() {
        while (true) {
            Event event;
            {
                std::unique_lock<std::mutex> lock(mutex);
                cv.wait(lock, [this] { return !eventQueue.empty() || !running; });
                if (!running && eventQueue.empty()) break;
                event = eventQueue.front();
                eventQueue.pop();
            }
            processEvent(event);
        }
    }

    void storeEvents() {
        while (true) {
            Event event;
            {
                std::unique_lock<std::mutex> lock(mutex);
                cv.wait(lock, [this] { return !eventQueue.empty() || !running; });
                if (!running && eventQueue.empty()) break;
                event = eventQueue.front();
                eventQueue.pop();
            }
            storeEvent(event);
        }
    }

    void processEvent(const Event& event) {
        // Implement event processing logic here
        std::cout << "Processing event from: " << event.source << std::endl;
    }

    void storeEvent(const Event& event) {
        // Implement storage logic here, including encryption and handling different storage backends
        encryptAndStore(event);
    }

    void encryptAndStore(const Event& event) {
        // Encrypt the data using OpenSSL
        char encryptedData[1024];
        int encryptedLen = encryptData(event.data.c_str(), static_cast<int>(event.data.length()), encryptedData, sizeof(encryptedData));
        if (encryptedLen > 0) {
            // Store the encrypted data in a file or a database
            std::ofstream outfile("log.txt", std::ios::app);
            outfile.write(encryptedData, encryptedLen);
            outfile.close();
        } else {
            std::cerr << "Encryption failed" << std::endl;
        }
    }

    int encryptData(const char* data, int len, char* output, size_t max_output_length) {
        // Placeholder for encryption logic using OpenSSL
        SSL_library_init();
        SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
        if (!ctx) return -1;

        SSL* ssl = SSL_new(ctx);
        if (!ssl) {
            SSL_CTX_free(ctx);
            return -1;
        }

        BIO* bio_out = BIO_new(BIO_s_mem());
        SSL_set_bio(ssl, NULL, bio_out);

        int result = SSL_write(ssl, data, len);
        if (result <= 0) {
            BIO_free_all(bio_out);
            SSL_free(ssl);
            SSL_CTX_free(ctx);
            return -1;
        }

        BUF_MEM* buf_ptr;
        BIO_get_mem_ptr(bio_out, &buf_ptr);
        int encrypted_len = buf_ptr->length;
        if (encrypted_len > max_output_length) {
            BIO_free_all(bio_out);
            SSL_free(ssl);
            SSL_CTX_free(ctx);
            return -1;
        }

        memcpy(output, buf_ptr->data, encrypted_len);
        BIO_free_all(bio_out);
        SSL_free(ssl);
        SSL_CTX_free(ctx);

        return encrypted_len;
    }
};

