import hashlib
import os
from concurrent.futures import ThreadPoolExecutor

class FileHasher:
    def __init__(self, max_workers=10):
        self.max_workers = max_workers
        self.executor = ThreadPoolExecutor(max_workers=max_workers)

    def calculate_md5_sync(self, file_path):
        with open(file_path, 'rb') as f:
            return hashlib.md5(f.read()).hexdigest()

    def calculate_md5_async(self, file_path):
        future = self.executor.submit(self.calculate_md5_sync, file_path)
        return future

    def validate_hash(self, file_path, expected_hash, async_mode=False):
        if async_mode:
            future = self.calculate_md5_async(file_path)
            actual_hash = future.result()
        else:
            actual_hash = self.calculate_md5_sync(file_path)

        if actual_hash == expected_hash:
            print(f"File '{file_path}' hash is valid.")
        else:
            print(f"File '{file_path}' hash is invalid. Expected: {expected_hash}, Actual: {actual_hash}")

    def shutdown(self):
        self.executor.shutdown()
```

