auto DeviceStatusManager::callWithRetry(Func&& func, Args&&... args) -> std::invoke_result_t<Func, Args...> {
    int retryCount = 0;
    while (retryCount < 5) { // Maximum retries
        try {
            return std::forward<Func>(func)(std::forward<Args>(args)...);
        } catch (...) {
            ++retryCount;
            if (retryCount == 5) {
                handleAPIFailure();
                throw; // Re-throw after max retries
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(100 * retryCount)); // Exponential backoff
        }
    }
    return func(args...); // Fallback if max retries fail
}

