        perror("Failed to allocate memory for PDUs");
        return NULL;
    }

    CURL *curl;
    CURLcode res;

    for (int i = 0; i < num_pdus; ++i) {
        pdus[i].RNTI = generateRandomRNTI();

        // Fetch RNTI data from external database or API
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if(curl) {
            struct MemoryStruct chunk;
            chunk.memory = malloc(1);  /* will be grown as needed by the realloc above */
            chunk.size = 0;    /* no data at this point */

            curl_easy_setopt(curl, CURLOPT_URL, "http://example.com/api/rnti");
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
            curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

            // Retry logic with exponential backoff
            int retry_count = 0;
            while(retry_count < MAX_RETRIES) {
                res = curl_easy_perform(curl);
                if(res != CURLE_OK) {
                    fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
                    sleep(BACKOFF_BASE * (1 << retry_count));
                    ++retry_count;
                } else {
                    break; // Success
                }
            }

            if(res == CURLE_OK) {
                parseRNTIData(&pdus[i], chunk.memory);
                free(chunk.memory);
            } else {
                fprintf(stderr, "Failed to fetch RNTI data after %d retries\n", MAX_RETRIES);
                pdus[i].CRCFLAG = 0; // Set default CRC flag on failure
            }

            curl_easy_cleanup(curl);
        }
        curl_global_cleanup();
    }

    return pdus;
}

