#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/md5.h>

#define MAX_RNTI_RETRIES 10

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
    unsigned char MD5_HASH[MD5_DIGEST_LENGTH];
} NFAPI_CRC_INDICATION_PDU_T;

void generateNfarlcPdus(int numPDUs, NFAPI_CRC_INDICATION_PDU_T *pdus, int retryPolicy) {
    srand(time(NULL));
    for (int i = 0; i < numPDUs; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = rand();
        pdus[i].CRCFLAG = rand() % 2;

        int retries = 0;
        while (retries < MAX_RNTI_RETRIES) {
            // Attempt to retrieve RNTI from external API
            if (retrieveRntiFromApi(&pdus[i].RNTI)) {
                break; // Successfully retrieved RNTI, exit loop
            }
            retries++;
            // Apply retry policy based on retryPolicy parameter
        }

        if (retries == MAX_RNTI_RETRIES) {
            printf("Failed to retrieve RNTI after %d retries for PDU %d\n", MAX_RNTI_RETRIES, i);
            continue; // Skip processing this PDU if max retries reached
        }

        calculateMd5Hash(pdus[i].RNTI, pdus[i].MD5_HASH);
    }
}

int retrieveRntiFromApi(uint32_t *rnti) {
    // Simulate API call with potential failures
    static int failureCount = 0;
    if (failureCount < 3) {
        *rnti = rand() % UINT32_MAX; // Simulate successful retrieval of RNTI
        return 1; // Success
    } else {
        failureCount++;
        printf("API call failed, retrying...\n");
        return 0; // Failure
    }
}

void calculateMd5Hash(uint32_t rnti, unsigned char *md5Hash) {
    MD5_CTX md5Context;
    MD5_Init(&md5Context);
    MD5_Update(&md5Context, &rnti, sizeof(rnti));
    MD5_Final(md5Hash, &md5Context);
}

int main() {
    const int numPDUs = 100;
    NFAPI_CRC_INDICATION_PDU_T pdus[numPDUs];
    generateNfarlcPdus(numPDUs, pdus, 0); // Use default retry policy

    for (int i = 0; i < numPDUs; i++) {
        printf("PDU %d: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%hhu, MD5_HASH=%s\n",
               i, pdus[i].RX_UE_INFORMATION_TAG, pdus[i].RNTI, pdus[i].CRCFLAG,
               bytesToHex(pdus[i].MD5_HASH));
    }

    return 0;
}

char* bytesToHex(const unsigned char *bytes, size_t length) {
    static char buffer[34]; // 32 hex chars + 1 null terminator
    for (size_t i = 0; i < length; i++) {
        sprintf(buffer + (i * 2), "%02x", bytes[i]);
    }
    return buffer;
}
