NFAPI_CRC_INDICATION_DATA* nfaapi_crc_indication_data_init(size_t max_structs) {
    if (max_structs > MAX_STRUCTS) return NULL;

    NFAPI_CRC_INDICATION_DATA* data = malloc(sizeof(NFAPI_CRC_INDICATION_DATA));
    if (!data) return NULL;

    data->array = calloc(max_structs, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data->array) {
        free(data);
        return NULL;
    }

    data->count = 0;
    pthread_mutex_init(&data->mutex, NULL);

    return data;
}

void nfaapi_crc_indication_data_free(NFAPI_CRC_INDICATION_DATA* data) {
    if (data) {
        free(data->array);
        pthread_mutex_destroy(&data->mutex);
        free(data);
    }
}

int nfaapi_crc_indication_data_populate(NFAPI_CRC_INDICATION_DATA* data, size_t count) {
    pthread_mutex_lock(&data->mutex);

    if (count + data->count > MAX_STRUCTS) {
        pthread_mutex_unlock(&data->mutex);
        return -1;
    }

    for (size_t i = 0; i < count; i++) {
        data->array[data->count + i].RX_UE_INFORMATION_TAG = rand();
        data->array[data->count + i].RNTI = rand() % 65536;
        data->array[data->count + i].CRC_INDICATION_REL8_TAG = rand() % 256;
    }

    data->count += count;

    pthread_mutex_unlock(&data->mutex);
    return 0;
