```c
// NASMessageLibrary.c

#include "NASMessageLibrary.h"
#include <stdlib.h>
#include <string.h>

void NASMessageManager_init(NASMessageManager *manager) {
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&manager->lock, &attr);
    manager->pdu = NULL;
}

void NASMessageManager_destroy(NASMessageManager *manager) {
    pthread_mutex_lock(&manager->lock);
    if (manager->pdu != NULL) {
        free(manager->pdu);
        manager->pdu = NULL;
    }
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

int NASMessageManager_updatePDU(NASMessageManager *manager, const NFAPI_CRC_INDICATION_PDU_T *newPDU) {
    pthread_mutex_lock(&manager->lock);
    if (manager->pdu != NULL) {
        free(manager->pdu);
    }
    manager->pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (manager->pdu == NULL) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failed
    }
    memcpy(manager->pdu, newPDU, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

const NFAPI_CRC_INDICATION_PDU_T* NASMessageManager_getPDU(const NASMessageManager *manager) {
    pthread_mutex_lock(&manager->lock);
    const NFAPI_CRC_INDICATION_PDU_T *pdu = manager->pdu;
    pthread_mutex_unlock(&manager->lock);
    return pdu;
}
