typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct DListNode* prev;
    struct DListNode* next;
} DListNode;

typedef struct DoublyLinkedList {
    DListNode* head;
    DListNode* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* createList() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insertNode(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    DListNode* newNode = (DListNode*)malloc(sizeof(DListNode));
    newNode->data = data;
    newNode->prev = NULL;
    newNode->next = list->head;

    if (list->head != NULL) {
        list->head->prev = newNode;
    } else {
        list->tail = newNode;
    }
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void deleteNode(DoublyLinkedList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    DListNode* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }
            free(current);
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void traverseList(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);
    DListNode* current = list->head;
    while (current != NULL) {
        // Process current node...
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void destroyList(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);
    DListNode* current = list->head;
    while (current != NULL) {
        DListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
