use tokio::sync::{mpsc, RwLock};
use std::collections::HashMap;
use serde::{Serialize, Deserialize};

#[derive(Serialize, Deserialize)]
struct DroneCommand {
    command_type: String,
    data: HashMap<String, String>,
}

struct DroneManager {
    drones: RwLock<HashMap<String, Drone>>,
    queue: mpsc::Sender<DroneCommand>,
}

impl DroneManager {
    async fn new() -> Self {
        DroneManager {
            drones: RwLock::new(HashMap::new()),
            queue: mpsc::channel(1024).1,
        }
    }

    async fn add_drone(&self, drone_id: String, drone: Drone) {
        self.drones.write().await.insert(drone_id, drone);
    }

    async fn dispatch_command(&self, command: DroneCommand) -> Result<(), mpsc::error::SendError<DroneCommand>> {
        self.queue.send(command).await
    }
}

struct Drone {
    id: String,
    battery_level: u8,
    status: String,
}

#[tokio::main]
async fn main() {
    let manager = DroneManager::new().await;

    // Example of adding drones and dispatching commands
    manager.add_drone(
        "drone1".to_string(),
        Drone {
            id: "drone1".to_string(),
            battery_level: 100,
            status: "active".to_string(),
        },
    ).await;

    let command = DroneCommand {
        command_type: "route".to_string(),
        data: HashMap::from([
            ("destination", "New York".to_string()),
            ("weight", "5kg".to_string()),
        ]),
    };

    manager.dispatch_command(command).await.unwrap();
}
