struct ConfigManager {
    config_path: PathBuf,
    client: Client,
    cache: Mutex<Vec<String>>,
}

impl ConfigManager {
    async fn new(root_path: &str) -> Result<Self, Box<dyn std::error::Error>> {
        let mut config_path = PathBuf::from(root_path);
        config_path.push("config_storage");

        if !config_path.exists() {
            DirBuilder::new()
                .recursive(true)
                .create(&config_path)?;
        }

        env::set_var("CONFIG_PATH", &config_path)?;

        Ok(ConfigManager {
            config_path,
            client: Client::new(),
            cache: Mutex::new(Vec::new()),
        })
    }

    async fn push_changes(&self, changes: &[String]) -> Result<(), Box<dyn std::error::Error>> {
        for change in changes {
            self.client.post("http://cms-api/push")
                .json(&change)
                .send()
                .await?;
        }
        Ok(())
    }

    async fn pull_configs(&self) -> Result<(), Box<dyn std::error::Error>> {
        let response = self.client.get("http://cms-api/pull").send().await?;
        if response.status().is_success() {
            let data: Vec<String> = response.json().await?;
            *self.cache.lock().await = data;
        }
        Ok(())
    }

    async fn handle_requests(&self, requests: &[String]) -> Result<(), Box<dyn std::error::Error>> {
        for request in requests {
            // Handle each request concurrently
            task::spawn(async move {
                // Process the request here
            });
        }
        Ok(())
    }

    fn log_message(&self, message: &str) {
        println!("{} - {}", chrono::Local::now(), message);
    }

    async fn run_health_checks(&self) -> Result<(), Box<dyn std::error::Error>> {
        // Implement health checks here
        Ok(())
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let config_manager = ConfigManager::new("/path/to/root").await?;
    config_manager.push_changes(&["config1", "config2"]).await?;
    config_manager.pull_configs().await?;
    config_manager.handle_requests(&["request1", "request2"]).await?;
    config_manager.log_message("Service started successfully");
    config_manager.run_health_checks().await?;
    Ok(())
}
