    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char MD5_HASH[MD5_DIGEST_LENGTH];
} NFAPI_CRC_INDICATION_PDU_T;

int generateNfarlcPdus(NFAPI_CRC_INDICATION_PDU_T **pdus, int num_pdus) {
    if (num_pdus <= 0) {
        fprintf(stderr, "Error: Invalid number of PDUs\n");
        return -1;
    }

    *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdus == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
