    for (int i = 0; i < num_pdus; i++) {
        (*pdus)[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        (*pdus)[i].RNTI = rand() % 65536;
        (*pdus)[i].CRC_INDICATION_REL8_TAG = rand() % 2;

        MD5_CTX md5_ctx;
        MD5_Init(&md5_ctx);
        MD5_Update(&md5_ctx, &(*pdus)[i].RNTI, sizeof((*pdus)[i].RNTI));
        MD5_Final((*pdus)[i].MD5_HASH, &md5_ctx);
    }

    return 0;
}

