// Function to simulate sending a notification using an external messaging service
void sendNotification(const std::string& sessionId, const std::string& message) {
    // Simulate sending a notification with exponential backoff on failure
    int retries = 0;
    while (true) {
        try {
            // Code to send notification
            std::cout << "Sending notification for session " << sessionId << ": " << message << std::endl;
            break; // Successful, exit loop
        } catch (const std::exception& e) {
            if (++retries >= 5) throw; // Max retries exceeded
            std::this_thread::sleep_for(std::chrono::seconds(1 << retries)); // Exponential backoff
        }
    }
}

