// Define dynamic array structure for TX_POWER_LEVEL_STATS
typedef struct {
    TX_POWER_LEVEL_STATS *data;
    size_t used;
    size_t size;
} DYNAMIC_ARRAY;

// Initialize dynamic array
void init_dynamic_array(DYNAMIC_ARRAY *array) {
    array->used = 0;
    array->size = 16; // Initial size can be adjusted
    array->data = (TX_POWER_LEVEL_STATS *)malloc(array->size * sizeof(TX_POWER_LEVEL_STATS));
}

// Free memory allocated for dynamic array
void free_dynamic_array(DYNAMIC_ARRAY *array) {
    free(array->data);
}

// Append an element to the dynamic array
void append_to_array(DYNAMIC_ARRAY *array, TX_POWER_LEVEL_STATS value) {
    if (array->used == array->size) {
        array->size *= 2;
        array->data = (TX_POWER_LEVEL_STATS *)realloc(array->data, array->size * sizeof(TX_POWER_LEVEL_STATS));
    }
    array->data[array->used++] = value;
}

// Example function to demonstrate library usage
void example_library_usage() {
    DYNAMIC_ARRAY my_array;
    init_dynamic_array(&my_array);

    TX_POWER_LEVEL_STATS entry1 = {1, 25.0};
    TX_POWER_LEVEL_STATS entry2 = {2, 30.5};

    append_to_array(&my_array, entry1);
    append_to_array(&my_array, entry2);

    printf("Dynamic array contains %zu elements:\n", my_array.used);
    for (size_t i = 0; i < my_array.used; ++i) {
        printf("ID: %d, Power Level: %.2f\n", my_array.data[i].id, my_array.data[i].power_level);
