#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define log levels
typedef enum {
    LOG_ERROR,
    LOG_WARNING,
    LOG_INFO,
    LOG_DEBUG,
    LOG_TRACE
} LogLevel;

// Log entry structure
typedef struct {
    LogLevel level;
    char message[256];
} LogEntry;

// Thread-safe buffer for log entries
typedef struct {
    LogEntry *entries;
    int capacity;
    int size;
    pthread_mutex_t mutex;
} LogBuffer;

// Initialize log buffer
void init_log_buffer(LogBuffer *buffer, int capacity) {
    buffer->entries = (LogEntry *)malloc(capacity * sizeof(LogEntry));
    buffer->capacity = capacity;
    buffer->size = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

// Add log entry to buffer
void add_log_entry(LogBuffer *buffer, LogLevel level, const char *message) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->size < buffer->capacity) {
        LogEntry entry = {level, message};
        buffer->entries[buffer->size++] = entry;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Asynchronously log entries
void *log_entries_thread(void *arg) {
    LogBuffer *buffer = (LogBuffer *)arg;
    while (1) {
        if (pthread_mutex_lock(&buffer->mutex)) {
            continue;
        }
        for (int i = 0; i < buffer->size; i++) {
            // Send log entry to external service
            send_log_entry_to_service(buffer->entries[i]);
        }
        buffer->size = 0;
        pthread_mutex_unlock(&buffer->mutex);
    }
    return NULL;
}

// Main function to demonstrate logging
int main() {
    LogBuffer buffer;
    init_log_buffer(&buffer, 100);

    // Start log entries thread
    pthread_t log_thread;
    pthread_create(&log_thread, NULL, log_entries_thread, &buffer);

    // Simulate adding log entries
    add_log_entry(&buffer, LOG_INFO, "Application started");
    add_log_entry(&buffer, LOG_WARNING, "Low disk space");

    // Join the log thread
    pthread_join(log_thread, NULL);

    return 0;
}
```

