use hyper::{Client, Uri};
use hyper_tls::HttpsConnector;
use tokio::sync::Mutex;
use std::time::Duration;

type HttpsClient = Client<HttpsConnector>;

async fn create_https_client() -> HttpsClient {
    let https_connector = HttpsConnector::new();
    Client::builder()
        .timeout(Duration::from_secs(5))
        .build::<_, hyper::Body>(https_connector)
}

async fn make_request(client: &HttpsClient, url: &str) -> Result<String, Box<dyn std::error::Error>> {
    let uri = url.parse::<Uri>()?;
    let response = client.get(uri).await?;
    if response.status().is_success() {
        hyper::body::to_bytes(response.into_body()).await.map(|body| String::from_utf8(body.to_vec()).unwrap())
    } else {
        Err(format!("Request failed with status: {}", response.status()).into())
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let client = create_https_client().await?;
    let url = "https://api.example.com/data";
    let response = make_request(&client, url).await?;
    println!("Response: {}", response);
    Ok(())
}
