#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    int ci;
    int power_level;
} TX_POWER_LEVEL_STATS;

typedef struct {
    TX_POWER_LEVEL_STATS *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->capacity = 10;
    array->count = 0;
    array->data = (TX_POWER_LEVEL_STATS*)malloc(array->capacity * sizeof(TX_POWER_LEVEL_STATS));
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void add_entry(DynamicArray *array, TX_POWER_LEVEL_STATS entry) {
    pthread_mutex_lock(&array->lock);
    if (array->count == array->capacity) {
        array->capacity *= 2;
        array->data = (TX_POWER_LEVEL_STATS*)realloc(array->data, array->capacity * sizeof(TX_POWER_LEVEL_STATS));
    }
    array->data[array->count++] = entry;
    pthread_mutex_unlock(&array->lock);
}

void update_entry(DynamicArray *array, int ci, TX_POWER_LEVEL_STATS entry) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->data[i].ci == ci) {
            array->data[i] = entry;
            break;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

TX_POWER_LEVEL_STATS* get_latest_entry(DynamicArray *array, int ci) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->data[i].ci == ci) {
            return &array->data[i];
        }
    }
    pthread_mutex_unlock(&array->lock);
    return NULL;
}

void destroy_dynamic_array(DynamicArray *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->data);
    free(array);
}
```

