typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* init_and_populate_array(int initial_size, int max_size) {
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        // Log memory allocation failure
        return NULL;
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    int current_size = initial_size;
    int load_factor = 0.75; // 75% load factor for resizing

    while (1) {
        for (int i = 0; i < current_size; i++) {
            array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
            array[i].RNTI = rand() % 2048;
            array[i].CRC_INDICATION_REL8_TAG = rand() % 10;
            pthread_mutex_lock(&mutex);
            array[i].CRCFLAG = (rand() % 2) ? 0 : 1; // Randomly set CRCFLAG
            pthread_mutex_unlock(&mutex);
        }

        if (current_size >= max_size) {
            break;
        }

        int new_size = current_size * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array == NULL) {
            // Log memory reallocation failure
            break;
        }

        array = new_array;
        current_size = new_size;

        if ((double)current_size / max_size < load_factor) {
            continue;
        }

        break;
    }

    pthread_mutex_destroy(&mutex);
    return array;
}

