// main.c

#include "LoggingKit.h"
#include <stdio.h>

void console_log(const char* message, LogLevel level) {
    const char* level_str = "";
    switch (level) {
        case LogLevelError: level_str = "ERROR"; break;
        case LogLevelWarning: level_str = "WARNING"; break;
        case LogLevelInfo: level_str = "INFO"; break;
        case LogLevelDebug: level_str = "DEBUG"; break;
        case LogLevelTrace: level_str = "TRACE"; break;
    }
    printf("[%s] %s\n", level_str, message);
}

int main(int argc, char* argv[]) {
    init_logging(console_log);

    log_message("Application started.", LogLevelInfo);
    log_message("An error occurred.", LogLevelError);

    shutdown_logging();
    return 0;
}
