pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;

void resize_array(int new_size) {
    pthread_mutex_lock(&array_lock);
    if (new_size > max_array_size) {
        nfapi_array = realloc(nfapi_array, new_size * sizeof(NFAPI_STRUCT));
        if (nfapi_array == NULL) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        max_array_size = new_size;
    } else if (new_size < array_size) {
        for (int i = new_size; i < array_size; ++i) {
            nfapi_array[i].NFAPI_CRC_INDICATION_PDU_T = 0;
            nfapi_array[i].rx_ue_info_tag = RX_UE_INFORMATION_TAG_INVALID;
            nfapi_array[i].rnti = 0;
            nfapi_array[i].crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG_INVALID;
