#include <stdbool.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure members here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* createList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroyList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void addNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return; // Handle allocation failure
    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

bool iterateList(LinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    if (!list || !callback) return false;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        callback(current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return true;
}

