    bool CRCFLAG;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct LinkedListNode *next;
} LinkedListNode;

LinkedListNode* head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void* thread_func(void* arg) {
    int rnti = *(int*)arg;
    pthread_mutex_lock(&list_mutex);
    for (LinkedListNode* node = head; node != NULL; node = node->next) {
        if (node->data.RNTI == rnti && node->data.CRCFLAG) {
            // Process data
            printf("Processed RNTI: %d\n", rnti);
            break;
        }
    }
    pthread_mutex_unlock(&list_mutex);
    free(arg);
    return NULL;
}

void add_to_list(int rx_tag, int rnti, bool crcflag) {
    pthread_mutex_lock(&list_mutex);
    LinkedListNode* new_node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    new_node->data.RX_UE_INFORMATION_TAG = rx_tag;
    new_node->data.RNTI = rnti;
    new_node->data.CRCFLAG = crcflag;
    pthread_mutex_init(&new_node->data.mutex, NULL);
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&list_mutex);
}

void* background_cleanup(void* arg) {
    while (true) {
        sleep(60); // Cleanup every minute
        pthread_mutex_lock(&list_mutex);
        LinkedListNode* current = head;
        LinkedListNode* prev = NULL;
        while (current != NULL) {
            if (/* Check if entry is inactive */) {
                if (prev == NULL) {
                    head = current->next;
                } else {
                    prev->next = current->next;
                }
                pthread_mutex_destroy(&current->data.mutex);
                free(current);
                current = prev->next;
            } else {
                prev = current;
                current = current->next;
            }
        }
        pthread_mutex_unlock(&list_mutex);
    }
    return NULL;
}

int main() {
    // Initialize data source and cache
    // Create background cleanup thread

    int rntis[N];
    for (int i = 0; i < N; i++) {
