NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdus(int N, ExternalSystemConfig config) {
    if (N <= 0) {
        fprintf(stderr, "Invalid number of PDUs: %d\n", N);
        return NULL;
    }

    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdus == NULL) {
        fprintf(stderr, "Failed to allocate memory for PDUs\n");
        return NULL;
    }

    // Populate the array with random data
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 100;
        pdus[i].RNTI = rand() % 1024;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        pdus[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG to either 0 or 1
    }

    // Log the creation process (detailed information)
    printf("Created and populated %d PDUs\n", N);

    return pdus;
}

// Function to free the allocated memory for PDUs
void free_pdus(NFAPI_CRC_INDICATION_PDU_T* pdus) {
    if (pdus != NULL) {
        free(pdus);
    }
