async fn process_pdus(N: u32, storage_config: StorageConfig, api_configs: Vec<ApiConfig>, logger: Logger) -> Result<(), Box<dyn std::error::Error>> {
    if N == 0 || N > MAX_PDUS {
        return Err("N must be greater than 0 and less than or equal to the maximum allowed".into());
    }

    let (tx, mut rx) = mpsc::channel(N as usize);

    for _ in 0..N {
        let tx_clone = tx.clone();
        tokio::spawn(async move {
            if let Err(e) = fetch_data_from_api(&api_configs[0].endpoint_url, &api_configs[0].auth_token).await {
                log_event(format!("Failed to fetch data: {}", e), "ERROR".to_string());
            } else {
                tx_clone.send(()).await.unwrap();
            }
        });
    }

    while let Some(_) = rx.next().await {
        if let Err(e) = persist_to_storage(NFAPI_CRC_INDICATION_PDU_T { /* Populate fields */ }, &storage_config.url).await {
            log_event(format!("Failed to persist data: {}", e), "ERROR".to_string());
        } else {
            log_event("Data persisted successfully".to_string(), "INFO".to_string());
        }
    }

    Ok(())
}

