    void start() {
        producerThread = std::thread(&DataIngestionPipeline::producer, this);
        consumerThread = std::thread(&DataIngestionPipeline::consumer, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stopFlag = true;
        }
        condition.notify_all();
        producerThread.join();
        consumerThread.join();
    }

