// Define a sensor data structure
struct SensorData {
    std::string id;
    double temperature;
    double humidity;
    double pressure;
};

// Define a thread-safe queue for data processing
class ThreadSafeQueue {
private:
    mutable std::mutex m_mutex;
    std::queue<SensorData> m_queue;
    std::condition_variable m_condition;

public:
    void push(const SensorData& data) {
        std::lock_guard<std::mutex> lock(m_mutex);
        m_queue.push(data);
        m_condition.notify_one();
    }

    bool pop(SensorData& data, std::unique_lock<std::mutex>& lock) {
        if (m_queue.empty()) {
            return false;
        }
        data = m_queue.front();
        m_queue.pop();
        return true;
    }

    void wait_and_pop(SensorData& data) {
        std::unique_lock<std::mutex> lock(m_mutex);
        m_condition.wait(lock, [this]{ return !m_queue.empty(); });
        data = m_queue.front();
        m_queue.pop();
    }
};

// Define a class for real-time data processing
class DataProcessor {
private:
    ThreadSafeQueue m_queue;
    std::vector<std::thread> m_threads;
    std::mutex m_output_mutex;
    std::condition_variable m_output_condition;

public:
