    }
};

// Define a class for monitoring and logging
class Monitor {
private:
    std::mutex m_log_mutex;
    std::condition_variable m_log_condition;
    std::queue<std::string> m_logs;

public:
    void log(const std::string& message) {
        std::lock_guard<std::mutex> lock(m_log_mutex);
        m_logs.push(message);
        m_log_condition.notify_one();
    }

    void print_logs() {
        while (true) {
            std::unique_lock<std::mutex> lock(m_log_mutex);
            m_log_condition.wait(lock, [this]{ return !m_logs.empty(); });
            std::string message = m_logs.front();
            m_logs.pop();
            lock.unlock();

            // Print the log message
            std::cout << "Log: " << message << std::endl;
        }
    }
};

int main() {
