    FileTransferModule(const std::string& onPremiseStorage, const std::string& cloudStorage) 
        : onPremiseStorage(onPremiseStorage), cloudStorage(cloudStorage), running(false) {}

    void start() {
        running = true;
        transferThread = std::thread(&FileTransferModule::transferLoop, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            running = false;
        }
        condition.notify_all();
        if (transferThread.joinable()) {
            transferThread.join();
        }
    }

    void addFileForTransfer(const std::string& filePath) {
        std::unique_lock<std::mutex> lock(mutex);
        filesToTransfer.push(filePath);
        condition.notify_one();
    }

private:
    void transferLoop() {
        while (running) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !filesToTransfer.empty() || !running; });
            if (!running && filesToTransfer.empty()) {
                break;
            }
            auto filePath = filesToTransfer.front();
            filesToTransfer.pop();

            // Simulate file transfer
            std::cout << "Transferring file: " << filePath << std::endl;
            lock.unlock();
            transferFile(filePath);
            lock.lock();
