using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading.Tasks;

public class RandomValueService : IRandomValueService
{
    private readonly ConcurrentDictionary<string, Queue<long>> _valueQueues;
    private readonly ConcurrentDictionary<string, long> _lastGeneratedValue;
    private readonly ConcurrentDictionary<string, long> _currentSeed;
    private readonly int _cacheSize;
    private const int MaxInt = int.MaxValue;
    private const int MinInt = int.MinValue;

    public RandomValueService(int cacheSize = 1000)
    {
        _valueQueues = new ConcurrentDictionary<string, Queue<long>>();
        _lastGeneratedValue = new ConcurrentDictionary<string, long>();
        _currentSeed = new ConcurrentDictionary<string, long>();
        _cacheSize = cacheSize;
        InitializeCaches();
    }

    public Task<long> GetRandomIntAsync(string key)
    {
        return GetRandomValueAsync(key, MinInt, MaxInt);
    }

    public Task<double> GetRandomFloatAsync(string key)
    {
        return GetRandomValueAsync(key, 0.0, 1.0);
    }

    private async Task<long> GetRandomValueAsync(string key, long min, long max)
    {
        if (!_valueQueues.TryGetValue(key, out var queue))
        {
            queue = new Queue<long>();
            _valueQueues.TryAdd(key, queue);
        }

        while (queue.Count < _cacheSize)
        {
            await GenerateValuesForKeyAsync(key, queue, min, max);
        }

        return queue.Dequeue();
    }

    private async Task GenerateValuesForKeyAsync(string key, Queue<long> queue, long min, long max)
    {
        if (!_lastGeneratedValue.TryGetValue(key, out var lastValue))
        {
            lastValue = _currentSeed[key] % (max - min + 1) + min;
        }
        else
        {
            lastValue++;
            if (lastValue > max)
            {
                lastValue -= max - min + 1;
            }
        }

        _lastGeneratedValue.TryAddOrUpdate(key, lastValue, (_, _) => lastValue);
        var nextSeed = lastValue * 25214903917 + 11;
        _currentSeed.TryAddOrUpdate(key, nextSeed, (_, _) => nextSeed);

        queue.Enqueue(lastValue);
    }

    private void InitializeCaches()
    {
        // Initialize caches with default values
        foreach (var key in new[] { "defaultInt", "defaultFloat" })
        {
            _valueQueues.TryAdd(key, new Queue<long>());
            _lastGeneratedValue.TryAdd(key, 0);
            _currentSeed.TryAdd(key, DateTime.Now.Ticks);
        }
    }
}

public interface IRandomValueService
{
    Task<long> GetRandomIntAsync(string key);
    Task<double> GetRandomFloatAsync(string key);
}
```

This code defines a `RandomValueService` class that implements an in-memory random value generation service. It uses concurrent data structures to ensure thread-safe access and minimize contention. The service supports generating both integer and floating-point values within specified ranges, with configurable seeds for reproducibility. It includes caching mechanisms to reduce the load on the random number generator while maintaining performance. The class also provides methods for asynchronously fetching random values for a given key.

Note that this implementation is simplified and does not include features like external configuration servers, network failure recovery, or advanced monitoring and logging. These would need to be added based on specific requirements and constraints.']

