// LoggingKit.c
#include "LoggingKit.h"
#include <stdio.h>
#include <stdarg.h>
#include <pthread.h>

static LogLevel currentLogLevel = INFO;
static FILE *logFile;

void setLogLevel(LogLevel level) {
    currentLogLevel = level;
}

void logMessage(LogLevel level, const char *format, ...) {
    if (level < currentLogLevel) return;

    va_list args;
    va_start(args, format);

    if (logFile != NULL) {
        vfprintf(logFile, format, args);
        fprintf(logFile, "\n");
    } else {
        vprintf(format, args);
        printf("\n");
    }

    va_end(args);
}

void initLogging(const char *configPath) {
    logFile = fopen(configPath, "a");
    if (logFile == NULL) {
        logMessage(ERROR, "Failed to open log file: %s", configPath);
        return;
    }
    setLogLevel(INFO); // Default log level
}

void shutdownLogging() {
    if (logFile != NULL) {
        fclose(logFile);
    }
}
