#define MAX_POWER_LEVEL_STATS 1000

typedef struct {
    int timestamp;
    int ci;
    float power_level;
} TX_POWER_LEVEL_STATS;

TX_POWER_LEVEL_STATS power_stats[MAX_POWER_LEVEL_STATS];
int current_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_power_stat(TX_POWER_LEVEL_STATS new_stat) {
    pthread_mutex_lock(&mutex);
    if (current_count < MAX_POWER_LEVEL_STATS) {
        power_stats[current_count++] = new_stat;
    }
    pthread_mutex_unlock(&mutex);
}

TX_POWER_LEVEL_STATS* get_latest_power_stat(int ci) {
    pthread_mutex_lock(&mutex);
    for (int i = current_count - 1; i >= 0; i--) {
        if (power_stats[i].ci == ci) {
            pthread_mutex_unlock(&mutex);
            return &power_stats[i];
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void update_power_stat(int ci, float new_power_level) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < current_count; i++) {
        if (power_stats[i].ci == ci) {
            power_stats[i].power_level = new_power_level;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}
