#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_TX_POWER_LEVEL_STATS 1024

typedef struct {
    int cell_identity;
    float power_level;
} TX_POWER_LEVEL_STATS;

TX_POWER_LEVEL_STATS tx_power_stats[MAX_TX_POWER_LEVEL_STATS];
int stats_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_tx_power_stat(TX_POWER_LEVEL_STATS *new_stat) {
    pthread_mutex_lock(&mutex);
    if (stats_count < MAX_TX_POWER_LEVEL_STATS) {
        tx_power_stats[stats_count++] = *new_stat;
    } else {
        printf("Error: Maximum number of stats reached.\n");
    }
    pthread_mutex_unlock(&mutex);
}

int update_tx_power_stat(int ci, float new_power_level) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < stats_count; i++) {
        if (tx_power_stats[i].cell_identity == ci) {
            tx_power_stats[i].power_level = new_power_level;
            pthread_mutex_unlock(&mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&mutex);
    printf("Error: Cell identity not found.\n");
    return -1;
}

float get_latest_power_level(int ci) {
    pthread_mutex_lock(&mutex);
    for (int i = stats_count - 1; i >= 0; i--) { // Start from the end to find the latest
        if (tx_power_stats[i].cell_identity == ci) {
            float power_level = tx_power_stats[i].power_level;
            pthread_mutex_unlock(&mutex);
            return power_level;
        }
    }
    pthread_mutex_unlock(&mutex);
    printf("Error: Cell identity not found.\n");
    return -1.0f; // Return an invalid value
}
```

