#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int ci;
    float power_level;
} TX_POWER_LEVEL_STATS;

typedef struct {
    TX_POWER_LEVEL_STATS *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    array->capacity = 10;
    array->size = 0;
    array->data = malloc(array->capacity * sizeof(TX_POWER_LEVEL_STATS));
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    free(array->data);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_entry(DynamicArray *array, TX_POWER_LEVEL_STATS entry) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->data = realloc(array->data, array->capacity * sizeof(TX_POWER_LEVEL_STATS));
    }
    array->data[array->size++] = entry;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int update_entry(DynamicArray *array, int ci, float power_level) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].ci == ci) {
            array->data[i].power_level = power_level;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1;
}

TX_POWER_LEVEL_STATS* get_latest_stats(DynamicArray *array, int ci) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = array->size; i > 0; --i) {
        if (array->data[i-1].ci == ci) {
            TX_POWER_LEVEL_STATS *entry = malloc(sizeof(TX_POWER_LEVEL_STATS));
            *entry = array->data[i-1];
            pthread_mutex_unlock(&array->lock);
            return entry;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return NULL;
}
