```java
package com.microservice.gateway.controller;

import com.microservice.gateway.service.ExternalServiceCaller;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import reactor.core.publisher.Mono;

@RestController
public class GatewayController {

    @Autowired
    private ExternalServiceCaller externalServiceCaller;

    @GetMapping("/api/data")
    public Mono<String> getData(@RequestParam String source) {
        if ("service1".equals(source)) {
            return externalServiceCaller.callExternalService1("http://service1/api/data");
        } else if ("service2".equals(source)) {
            return externalServiceCaller.callExternalService2("http://service2/api/data");
        }
        return Mono.error(new IllegalArgumentException("Invalid source"));
    }
}
