    int CELL_ID;
    int PCI;
    int CELL_RSRP;
    bool RSRP_FLAG;
};

struct ExternalSystemConfig {
    std::string URL;
    std::string AuthToken;
    int MaxRetryLimit;
};

void generateAndPopulatePDUs(int N, const ExternalSystemConfig& config) {
    if (N < 1 || N > 10000) {
        throw std::invalid_argument("Invalid number of PDUs");
    }

    std::vector<NFAPI_CELL_INFO_PDU_T> pdus(N);
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> cellIDDist(1, 65535);
    std::uniform_int_distribution<> pciDist(0, 504);
    std::uniform_int_distribution<> rsrpDist(0, 97);

    for (int i = 0; i < N; ++i) {
        pdus[i].CELL_ID = cellIDDist(gen);
        pdus[i].PCI = pciDist(gen);
        pdus[i].CELL_RSRP = rsrpDist(gen);
        pdus[i].RSRP_FLAG = gen() % 2 == 0;
    }

    auto persistPDUsAsync = [&pdus, &config]() -> std::future<void> {
        return std::async(std::launch::async, [](const std::vector<NFAPI_CELL_INFO_PDU_T>& pdus, const ExternalSystemConfig& config) {
            for (const auto& pdu : pdus) {
                // Simulate asynchronous HTTP request to persist PDU
                try {
                    // Perform the HTTP request here
                    std::cout << "Persisting PDU: Cell ID - " << pdu.CELL_ID << ", PCI - " << pdu.PCI << ", RSRP - " << pdu.CELL_RSRP << ", RSRP_FLAG - " << (pdu.RSRP_FLAG ? "True" : "False") << std::endl;
                } catch (const std::exception& e) {
                    std::cerr << "Error persisting PDU: " << e.what() << std::endl;
                }
            }
        }, pdus, config);
    };

    auto future = persistPDUsAsync();
    // Wait for the async operation to complete
    future.get();
}

int main() {
    ExternalSystemConfig config = {"https://example.com/storage", "auth_token_here", 3};
    generateAndPopulatePDUs(100, config);
    return 0;
}
