// C++ Component

#include <iostream>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include "NFAPI.h"
#include "ExternalAPIWrapper.h"

class NFAPIProcessor {
public:
    void startProcessing(int M, int N) {
        for (int i = 0; i < M; ++i) {
            workers.emplace_back(&NFAPIProcessor::workerThread, this, N);
        }
    }

    void stopProcessing() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            shouldStop = true;
        }
        cv.notify_all();
        for (auto& worker : workers) {
            worker.join();
        }
    }

private:
    void workerThread(int N) {
        while (true) {
            std::queue<NFAPI_CRC_INDICATION_PDU_T> batch;
            {
                std::unique_lock<std::mutex> lock(mutex);
                cv.wait(lock, [this] { return shouldStop || !requests.empty(); });
                if (shouldStop && requests.empty()) break;
                for (int i = 0; i < N && !requests.empty(); ++i) {
                    batch.push(requests.front());
                    requests.pop();
                }
            }

            // Process the batch
            processBatch(batch);
        }
    }

    void processBatch(const std::queue<NFAPI_CRC_INDICATION_PDU_T>& batch) {
        for (const auto& pdu : batch) {
            ExternalAPIWrapper::processPDU(pdu);
        }
    }

    std::mutex mutex;
    std::condition_variable cv;
    bool shouldStop = false;
    std::queue<NFAPI_CRC_INDICATION_PDU_T> requests;
    std::vector<std::thread> workers;
};

