import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class EventProcessor {
    private final int P; // Number of concurrent events
    private final int Q; // Events per batch
    private ExecutorService executorService;

    public EventProcessor(int P, int Q) {
        this.P = P;
        this.Q = Q;
        this.executorService = Executors.newFixedThreadPool(P);
    }

    public void processEvent(String jsonPayload) {
        executorService.submit(() -> {
            // Process event
            try {
                Thread.sleep(100); // Simulate processing time
                System.out.println("Processed: " + jsonPayload);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException ie) {
            executorService.shutdownNow();
        }
    }
}
