        UserId:   payload.UserId,
        Timestamp: payload.Timestamp,
        EventType: payload.EventType,
        LocationX: payload.Location[0],
        LocationY: payload.Location[1],
    })
    if err != nil {
        return nil, err
    }
    return &Response{Success: resp.Success, Message: resp.Message}, nil
}

