#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>

// Function to encrypt data using AES-256-CBC
int encrypt_data(const unsigned char *key, const unsigned char *iv,
                 const unsigned char *plaintext, int plaintext_len,
                 unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        goto err;

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        goto err;
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len))
        goto err;
    ciphertext_len += len;

err:
    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

// Function to decrypt data using AES-256-CBC
int decrypt_data(const unsigned char *key, const unsigned char *iv,
                 const unsigned char *ciphertext, int ciphertext_len,
                 unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int plaintext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        goto err;

    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len))
        goto err;
    plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len))
        goto err;
    plaintext_len += len;

err:
    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;
}

// Example usage
int main() {
    unsigned char key[32] = {0}; // AES-256 key
    unsigned char iv[16] = {0};  // Initialization vector
    unsigned char plaintext[] = "This is a secret message";
    unsigned char ciphertext[128];
    unsigned char decryptedtext[128];

    int len;

    len = encrypt_data(key, iv, plaintext, strlen((char *)plaintext), ciphertext);
    if (len == -1) {
        fprintf(stderr, "Encryption failed\n");
        return 1;
    }

    len = decrypt_data(key, iv, ciphertext, len, decryptedtext);
    if (len == -1) {
        fprintf(stderr, "Decryption failed\n");
        return 1;
    }
    decryptedtext[len] = '\0';

    printf("Encrypted: %s\n", ciphertext);
    printf("Decrypted: %s\n", decryptedtext);

    return 0;
}
