// C Code for Encryption Service

#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <stdio.h>

void generateKey(unsigned char *key, int keyLen) {
    if (RAND_bytes(key, keyLen) != 1) {
        fprintf(stderr, "Error generating random key\n");
        exit(EXIT_FAILURE);
    }
}

void encrypt(const unsigned char *data, size_t dataLen, const unsigned char *key, unsigned char *encryptedData, unsigned char *iv) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new())) {
        fprintf(stderr, "Error creating cipher context\n");
        exit(EXIT_FAILURE);
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Error initializing encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }

    if (1 != EVP_EncryptUpdate(ctx, encryptedData, &len, data, dataLen)) {
        fprintf(stderr, "Error encrypting data\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, encryptedData + len, &len)) {
        fprintf(stderr, "Error finalizing encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }

    ciphertext_len += len;
    encryptedData[ciphertext_len] = '\0';

    EVP_CIPHER_CTX_free(ctx);
}

void decrypt(const unsigned char *encryptedData, size_t dataLen, const unsigned char *key, unsigned char *iv, unsigned char *decryptedData) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int plaintext_len;

    if (!(ctx = EVP_CIPHER_CTX_new())) {
        fprintf(stderr, "Error creating cipher context\n");
        exit(EXIT_FAILURE);
    }

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Error initializing decryption\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }

    if (1 != EVP_DecryptUpdate(ctx, decryptedData, &len, encryptedData, dataLen)) {
        fprintf(stderr, "Error decrypting data\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }
    plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, decryptedData + len, &len)) {
        fprintf(stderr, "Error finalizing decryption\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }

    plaintext_len += len;
    decryptedData[plaintext_len] = '\0';

    EVP_CIPHER_CTX_free(ctx);
}

int main() {
    unsigned char key[32];
    unsigned char iv[16];
    unsigned char data[] = "Hello, World!";
    unsigned char encryptedData[sizeof(data) + 16];
    unsigned char decryptedData[sizeof(data)];

    generateKey(key, sizeof(key));
    generateKey(iv, sizeof(iv));

    encrypt(data, sizeof(data), key, encryptedData, iv);
    decrypt(encryptedData, strlen((char*)encryptedData), key, iv, decryptedData);

    printf("Decrypted data: %s\n", decryptedData);

    return 0;
}
