class IoTDataProcessingPlatform {
public:
    IoTDataProcessingPlatform() {}

    void start() {
        // Start data ingestion threads
        for (int i = 0; i < numIngestThreads_; ++i) {
            ingestThreads_.emplace_back(&IoTDataProcessingPlatform::ingestData, this);
        }

        // Start processing threads
        for (int i = 0; i < numProcessThreads_; ++i) {
            processThreads_.emplace_back(&IoTDataProcessingPlatform::processData, this);
        }
    }

    void stop() {
        // Stop all threads gracefully
        running_ = false;
        ingestCondition_.notify_all();
        processCondition_.notify_all();

        for (auto& thread : ingestThreads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
        for (auto& thread : processThreads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

private:
    void ingestData() {
        while (running_) {
            // Simulate data ingestion
            std::string data = "Sensor data";
            std::unique_lock<std::mutex> lock(ingestMutex_);
            ingestQueue_.push(data);
            ingestCondition_.notify_one();
        }
    }

    void processData() {
        while (running_) {
            std::string data;
            std::unique_lock<std::mutex> lock(processMutex_);
            ingestCondition_.wait(lock, [this] { return !ingestQueue_.empty(); });
            data = ingestQueue_.front();
            ingestQueue_.pop();
            lock.unlock();

            // Simulate data processing
            std::cout << "Processing: " << data << std::endl;
        }
    }

    int numIngestThreads_ = 4;
    int numProcessThreads_ = 4;
    bool running_ = true;

    std::queue<std::string> ingestQueue_;
    std::mutex ingestMutex_;
    std::condition_variable ingestCondition_;

    std::vector<std::thread> ingestThreads_;
    std::vector<std::thread> processThreads_;
};

int main() {
    IoTDataProcessingPlatform platform;
    platform.start();

    // Simulate running for a while
    std::this_thread::sleep_for(std::chrono::seconds(10));

    platform.stop();
    return 0;
}
