const express = require('express');
const http = require('http');
const fs = require('fs');
const path = require('path');
const cluster = require('cluster');
const numCPUs = require('os').cpus().length;
const axios = require('axios');
const workerpool = require('workerpool');

const app = express();
const server = http.createServer(app);
const pool = workerpool.createPool(__dirname + '/workers.js', { minWorkers: 1, maxWorkers: numCPUs });

// Load external APIs
const apis = [
  'https://api.example.com/data1',
  'https://api.example.com/data2'
];

// Caching mechanism with TTL (Time-To-Live)
const cache = {};
const ttl = 30 * 60 * 1000; // 30 minutes

async function fetchData(api) {
  if (cache[api] && Date.now() - cache[api].timestamp < ttl) {
    return cache[api].data;
  }

  try {
    const response = await axios.get(api);
    cache[api] = { data: response.data, timestamp: Date.now() };
    return response.data;
  } catch (error) {
    console.error(`Failed to fetch data from ${api}:`, error.message);
    throw error;
  }
}

// Middleware for routing
app.use(express.json());
app.use('/data', async (req, res) => {
  try {
    const promises = apis.map(fetchData);
    const results = await Promise.all(promises);
    res.send(results);
  } catch (error) {
    res.status(500).send({ error: 'Failed to fetch data' });
  }
});

// Load balancer based on worker performance
function loadBalancer(api) {
  const workers = pool.workers;
  let leastLoadedWorker = null;

  for (const worker of workers) {
    if (!leastLoadedWorker || worker.load < leastLoadedWorker.load) {
      leastLoadedWorker = worker;
    }
  }

  return leastLoadedWorker.proxy;
}

// Message queue integration
const Queue = require('bull');
const myQueue = new Queue('myQueue', 'redis://127.0.0.1:6379');

app.post('/enqueue', async (req, res) => {
  try {
    await myQueue.add(req.body);
    res.send({ message: 'Task enqueued' });
  } catch (error) {
    res.status(500).send({ error: 'Failed to enqueue task' });
  }
});

myQueue.process(async (job, done) => {
  const { api } = job.data;
  try {
    const data = await fetchData(api);
    done(null, data);
  } catch (error) {
    done(error);
  }
});

// Worker pool for JavaScript module execution
const workerPool = require('workerpool');

app.post('/execute', async (req, res) => {
  try {
    const { modulePath } = req.body;
    const result = await pool.exec('executeModule', [modulePath]);
    res.send(result);
  } catch (error) {
    res.status(500).send({ error: 'Failed to execute module' });
  }
});

// Error logging and metrics
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

app.use((err, req, res, next) => {
  logger.error(err.stack);
  res.status(500).send({ error: err.message });
});

// Kubernetes readiness and liveness probes
app.get('/health', (req, res) => {
  res.send({ status: 'ok' });
});

if (cluster.isMaster) {
  console.log(`Master ${process.pid} is running`);

  // Fork workers.
  for (let i = 0; i < numCPUs; i++) {
    cluster.fork();
  }

  cluster.on('exit', (worker, code, signal) => {
    console.log(`worker ${worker.process.pid} died`);
  });
} else {
  server.listen(3000, () => {
    console.log(`Worker ${process.pid} started`);
  });

  // Worker-specific setup
}
