<?php

use OAuth\Common\Consumer\Credentials;
use OAuth\Common\Http\Client\Client;
use OAuth\OAuth2\Service\Facebook;
use OAuth\OAuth2\Service\GitHub;
use Symfony\Component\Cache\FilesystemAdapter;

class UserAuthenticator {
    private $cache;
    private $facebookService;
    private $githubService;

    public function __construct() {
        $this->cache = new FilesystemAdapter('user_data', 3600);

        $credentials = new Credentials(
            'your_facebook_client_id',
            'your_facebook_client_secret',
            'http://example.com/callback'
        );
        $this->facebookService = new Facebook($credentials);

        $credentials = new Credentials(
            'your_github_client_id',
            'your_github_client_secret',
            'http://example.com/callback'
        );
        $this->githubService = new GitHub($credentials);
    }

    public function authenticateUser($provider, $code) {
        try {
            if ($provider === 'facebook') {
                $token = $this->facebookService->getAccessToken('authorization_code', ['code' => $code]);
            } elseif ($provider === 'github') {
                $token = $this->githubService->getAccessToken('authorization_code', ['code' => $code]);
            } else {
                throw new Exception("Unsupported provider");
            }

            $userData = $this->fetchUserData($provider, $token);
            $this->cache->set($userData['id'], $userData, 3600);

            return $userData;
        } catch (\Exception $e) {
            // Log error and throw it again
            error_log("Authentication failed: " . $e->getMessage());
            throw $e;
        }
    }

    private function fetchUserData($provider, $token) {
        try {
            if ($provider === 'facebook') {
                $client = new Client();
                $client->setHeader('Authorization', 'Bearer ' . $token->getAccessToken());
                $response = $client->get('https://graph.facebook.com/me?fields=id,name,email');
                return json_decode($response->getBody(), true);
            } elseif ($provider === 'github') {
                $client = new Client();
                $client->setHeader('Authorization', 'Bearer ' . $token->getAccessToken());
                $response = $client->get('https://api.github.com/user');
                return json_decode($response->getBody(), true);
            }
        } catch (\Exception $e) {
            // Handle and log specific errors
            error_log("Failed to fetch user data from provider: " . $provider);
            throw $e;
        }
    }

    public function getUserData($userId) {
        return $this->cache->get($userId, null);
    }
}

// Usage example:
$authenticator = new UserAuthenticator();
try {
    $userData = $authenticator->authenticateUser('facebook', 'user_code_here');
    echo "Authenticated user: " . json_encode($userData);
} catch (\Exception $e) {
    echo "Authentication failed: " . $e->getMessage();
}
?>
