    int CELL_ID;
    int PCI;
    double CELL_RSRP;
    bool RSRP_FLAG;
    // Other fields
};

// Configuration struct for external system settings
struct ExternalSystemConfig {
    std::string URL;
    std::string AuthDetails;
    int MaxRetryLimit;
    // Other config fields
};

class DeviceManager {
public:
    static DeviceManager& getInstance() {
        static DeviceManager instance;
        return instance;
    }

    void addDeviceStatus(const DEVICE_STATUS_RECORDS& record) {
        std::lock_guard<std::mutex> lock(mutex_);
        deviceStatuses_.push_back(record);
        cv_.notify_one();
    }

    void processPendingUpdates(ExternalSystemConfig config) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (true) {
            cv_.wait(lock, [this] { return !deviceStatuses_.empty(); });
            DEVICE_STATUS_RECORDS record = deviceStatuses_.front();
            deviceStatuses_.pop_front();
            lock.unlock();

            // Process update asynchronously
            std::thread([record, config]() {
                if (!processUpdate(record, config)) {
                    retryQueue_.push({record, config});
                }
            }).detach();
        }
    }

private:
    DeviceManager() {}

    bool processUpdate(const DEVICE_STATUS_RECORDS& record, const ExternalSystemConfig& config) {
        // Implement update logic here
        return true; // Return true if successful
    }

    void retryUpdate(const std::pair<DEVICE_STATUS_RECORDS, ExternalSystemConfig>& data) {
        // Retry update logic here
    }

    std::mutex mutex_;
    std::condition_variable cv_;
    std::vector<DEVICE_STATUS_RECORDS> deviceStatuses_;
    std::queue<std::pair<DEVICE_STATUS_RECORDS, ExternalSystemConfig>> retryQueue_;
};

// Function to generate and populate a vector of NFAPI_CELL_INFO_PDU_T structures
std::vector<NFAPI_CELL_INFO_PDU_T> generateAndPopulatePDUs(int N, const ExternalSystemConfig& config) {
    if (N <= 0 || N > MAX_PDUS_LIMIT) {
        throw std::invalid_argument("Invalid number of PDUs");
    }

    std::vector<NFAPI_CELL_INFO_PDU_T> pdus(N);
