#define MAX_PDUS 50000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_PDUS];
    size_t count;
    pthread_mutex_t mutex;
} PDUList;

PDUList pdu_list;

void initialize_pdu_list() {
    memset(&pdu_list, 0, sizeof(pdu_list));
    pthread_mutex_init(&pdu_list.mutex, NULL);
}

void* process_pdu(void* arg) {
    int index = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T pdu = pdu_list.pdus[index];

    // Simulate processing PDU
    printf("Processing PDU %d: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRC_INDICATION_REL8_TAG=%u\n",
           index, pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG);

    return NULL;
}

void add_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&pdu_list.mutex);
    if (pdu_list.count < MAX_PDUS) {
        pdu_list.pdus[pdu_list.count++] = pdu;
    }
    pthread_mutex_unlock(&pdu_list.mutex);
}

void* process_pdus(void* arg) {
    int num_threads = *(int*)arg;
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; i++) {
        int index = i * MAX_PDUS / num_threads;
        if (index < pdu_list.count) {
            pthread_create(&threads[i], NULL, process_pdu, &index);
        }
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return NULL;
}

void save_pdus_to_disk() {
    int fd = open("pdu_list.dat", O_CREAT | O_WRONLY, 0644);
    if (fd == -1) {
        perror("Failed to open file for writing");
        return;
    }

    ssize_t bytes_written = write(fd, &pdu_list, sizeof(pdu_list));
    if (bytes_written != sizeof(pdu_list)) {
        perror("Failed to write to file");
    } else {
        printf("Saved %zu bytes to disk\n", bytes_written);
    }

    close(fd);
}

void load_pdus_from_disk() {
    int fd = open("pdu_list.dat", O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file for reading");
        return;
    }

    ssize_t bytes_read = read(fd, &pdu_list, sizeof(pdu_list));
    if (bytes_read != sizeof(pdu_list)) {
        perror("Failed to read from file");
    } else {
        printf("Loaded %zu bytes from disk\n", bytes_read);
    }

    close(fd);
}

int main() {
    initialize_pdu_list();

    // Simulate adding PDUs
    for (size_t i = 0; i < MAX_PDUS; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = i;
        pdu.RNTI = i % 1024;
        pdu.CRC_INDICATION_REL8_TAG = rand() % 256;
        add_pdu(pdu);
    }

    // Simulate processing PDUs
    int num_threads = 4;
    pthread_t thread;
    pthread_create(&thread, NULL, process_pdus, &num_threads);
    pthread_join(thread, NULL);

    // Save and load PDU list to/from disk
    save_pdus_to_disk();
    initialize_pdu_list();
    load_pdus_from_disk();

    return 0;
