    TX_POWER_LEVEL_STATS *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    free(array->data);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_entry(DynamicArray *array, TX_POWER_LEVEL_STATS entry) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity == 0 ? 1 : array->capacity * 2;
        TX_POWER_LEVEL_STATS *new_data = realloc(array->data, new_capacity * sizeof(TX_POWER_LEVEL_STATS));
        if (!new_data) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size++] = entry;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int update_entry(DynamicArray *array, int cell_identity, TX_POWER_LEVEL_STATS new_entry) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].cell_identity == cell_identity) {
            array->data[i] = new_entry;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return -1; // Entry not found
}

TX_POWER_LEVEL_STATS get_latest_entry(DynamicArray *array, int cell_identity) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = array->size - 1; i >= 0; --i) {
        if (array->data[i].cell_identity == cell_identity) {
            TX_POWER_LEVEL_STATS result = array->data[i];
            pthread_mutex_unlock(&array->mutex);
            return result;
        }
    }
    TX_POWER_LEVEL_STATS empty_entry = {0};
    pthread_mutex_unlock(&array->mutex);
    return empty_entry; // Entry not found
}
