};

class CellEventLogger {
private:
    std::mutex logMutex;
    std::condition_variable logCondition;
    std::queue<CellEventLogEntry> logQueue;
    bool running;

public:
    CellEventLogger() : running(true) {}

    ~CellEventLogger() {
        stop();
    }

    void start() {
        // Simulate event bus subscription
        std::thread([this]() {
            while (running) {
                // Simulate receiving new log entry
                CellEventLogEntry entry;
                entry.timestamp = std::chrono::system_clock::now();
                entry.cellID = 1; // Example cell ID
                entry.activeResources.push_back({1, 200});
                logQueue.push(entry);

                // Notify the main thread that a new log entry is available
                logCondition.notify_one();

                // Simulate periodic updates every second
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
        }).detach();
    }

    void stop() {
        running = false;
        logCondition.notify_all();
    }

    void addLogEntry(const CellEventLogEntry& entry) {
        std::lock_guard<std::mutex> lock(logMutex);
        logQueue.push(entry);
    }

