        CellEventLogEntry entry = logger.getLogEntryForTimeRange(std::chrono::system_clock::now() - std::chrono::hours(1), std::chrono::system_clock::now());
        std::cout << "Cell ID: " << entry.cellID << ", Timestamp: " << std::chrono::system_clock::to_time_t(entry.timestamp) << std::endl;
    } catch (const std::runtime_error& e) {
        std::cerr << e.what() << std::endl;
    }

    logger.stop();
    return 0;
}
