    bool addSession(const std::string& token, session_t session, time_t expirationTime) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        if (sessionManager.find(token) != sessionManager.end()) {
            return false; // Token already in use
        }
        sessionManager[token] = {session, expirationTime};
        cv.notify_all();
        return true;
    }

    bool validateSession(const std::string& token) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        auto it = sessionManager.find(token);
        if (it == sessionManager.end()) {
            return false; // Token not found
        }
        if (std::chrono::system_clock::now() > it->second.second) {
            sessionManager.erase(it); // Invalidate expired session
            cv.notify_all();
            return false;
        }
        return true;
    }

    void invalidateSession(const std::string& token) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        sessionManager.erase(token);
        cv.notify_all();
    }

