class DynamicCellEventLogger {
public:
    void addLog(const CellEventLogEntry& entry) {
        std::lock_guard<std::mutex> lock(mutex_);
        logs_.push_back(entry);
        condition_.notify_all();
    }

    void updateLog(int cellID, const std::function<void(CellEventLogEntry&)>& updateFunc) {
        std::unique_lock<std::mutex> lock(mutex_);
        for (auto& entry : logs_) {
            if (entry.cellID == cellID) {
                updateFunc(entry);
                condition_.notify_all();
                break;
            }
        }
    }

    std::vector<CellEventLogEntry> getLogsForTimeRange(const std::chrono::system_clock::time_point& start, const std::chrono::system_clock::time_point& end) {
        std::unique_lock<std::mutex> lock(mutex_);
        condition_.wait(lock, [this, start, end]() {
            return !logs_.empty() && logs_.back().timestamp >= start;
        });
        auto it = std::find_if(logs_.begin(), logs_.end(), [start, end](const CellEventLogEntry& entry) {
            return entry.timestamp >= start && entry.timestamp <= end;
        });
        if (it != logs_.end()) {
            std::vector<CellEventLogEntry> result(it, logs_.end());
            return result;
        }
        return {};
    }

    std::vector<CellEventLogEntry> getLogsForCellID(int cellID) {
        std::unique_lock<std::mutex> lock(mutex_);
        condition_.wait(lock, [this, cellID]() {
            return !logs_.empty() && logs_.back().cellID == cellID;
        });
        auto it = std::find_if(logs_.begin(), logs_.end(), [cellID](const CellEventLogEntry& entry) {
            return entry.cellID == cellID;
        });
        if (it != logs_.end()) {
            std::vector<CellEventLogEntry> result(it, logs_.end());
            return result;
        }
        return {};
    }

private:
    std::vector<CellEventLogEntry> logs_;
    std::mutex mutex_;
    std::condition_variable condition_;
};
