#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_PDUS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_PDUS];
    int size;
    pthread_mutex_t lock;
} PDU_POOL_T;

typedef struct {
    int RNTI;
    time_t enqueue_time;
} ENQUEUE_RECORD_T;

typedef struct {
    ENQUEUE_RECORD_T records[MAX_PDUS];
    int index;
    pthread_mutex_t lock;
} ENQUEUE_LOG_T;

PDU_POOL_T pdu_pool = {0};
ENQUEUE_LOG_T enqueue_log = {0};

void init_pdu_pool() {
    for (int i = 0; i < MAX_PDUS; i++) {
        pdu_pool.pdus[i].RX_UE_INFORMATION_TAG = -1;
        pdu_pool.pdus[i].RNTI = -1;
        pdu_pool.pdus[i].CRC_INDICATION_REL8_TAG = -1;
        pdu_pool.pdus[i].CRCFLAG = -1;
    }
}

void init_enqueue_log() {
    enqueue_log.index = 0;
}

int allocate_pdu() {
    pthread_mutex_lock(&pdu_pool.lock);
    for (int i = 0; i < MAX_PDUS; i++) {
        if (pdu_pool.pdus[i].RNTI == -1) {
            int rnti = rand() % 1000; // Simulated RNTI generation
            pdu_pool.pdus[i].RX_UE_INFORMATION_TAG = 123456;
            pdu_pool.pdus[i].RNTI = rnti;
            pdu_pool.pdus[i].CRC_INDICATION_REL8_TAG = 7890;
            pdu_pool.pdus[i].CRCFLAG = rand() % 2;
            pthread_mutex_unlock(&pdu_pool.lock);
            return rnti;
        }
    }
    pthread_mutex_unlock(&pdu_pool.lock);
    return -1; // No available PDUs
}

void enqueue_pdu(int rnti) {
    pthread_mutex_lock(&enqueue_log.lock);
    enqueue_log.records[enqueue_log.index].RNTI = rnti;
    enqueue_log.records[enqueue_log.index].enqueue_time = time(NULL);
    enqueue_log.index = (enqueue_log.index + 1) % MAX_PDUS;
    pthread_mutex_unlock(&enqueue_log.lock);
}

void process_pdu(int rnti) {
    for (int i = 0; i < MAX_PDUS; i++) {
        if (pdu_pool.pdus[i].RNTI == rnti) {
            // Simulated PDU processing
            printf("Processing PDU with RNTI: %d\n", rnti);
            pthread_mutex_lock(&pdu_pool.lock);
            pdu_pool.pdus[i].RNTI = -1; // Free the PDU
            pthread_mutex_unlock(&pdu_pool.lock);
            return;
        }
    }
}

void* message_queue_thread(void* arg) {
    while (1) {
        int rnti = allocate_pdu();
        if (rnti != -1) {
            enqueue_pdu(rnti);
        } else {
            // Handle no available PDUs
        }
    }
    return NULL;
}

int main() {
    init_pdu_pool();
    init_enqueue_log();

    pthread_t message_queue_tid;
    pthread_create(&message_queue_tid, NULL, message_queue_thread, NULL);

    for (int i = 0; i < MAX_PDUS; i++) {
        int rnti = allocate_pdu();
        if (rnti != -1) {
            enqueue_pdu(rnti);
            process_pdu(rnti);
        }
    }

    pthread_join(message_queue_tid, NULL);

    return 0;
}
