#include <condition_variable>
#include <atomic>
#include <random>
#include <chrono>
#include <sstream>

// Define log levels
enum class LogLevel { TRACE, DEBUG, INFO, WARNING, ERROR };

// Log entry structure
struct LogEntry {
    std::string tag;
    int rnti;
    bool crcFlag;
    LogLevel level;
};

class LoggingFramework {
public:
    LoggingFramework(size_t maxQueueSize) : queueMaxSize(maxQueueSize), stop(false) {}

    void addLog(const LogEntry& entry) {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this] { return queue.size() < queueMaxSize; });
        queue.push(entry);
        lock.unlock();
        condition.notify_one();
    }

    void start() {
        worker = std::thread([this]() {
            while (true) {
                LogEntry entry;
                {
                    std::unique_lock<std::mutex> lock(mutex);
                    condition.wait(lock, [this] { return !queue.empty() || stop; });
                    if (stop && queue.empty()) break;
                    entry = queue.front();
                    queue.pop();
                }
                processLog(entry);
            }
        });
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        worker.join();
    }

private:
    void processLog(const LogEntry& entry) {
        // Simulate log processing
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        std::cout << "Processed log: " << entry.tag << ", RNTI: " << entry.rnti << ", CRC: " << (entry.crcFlag ? "true" : "false") << ", Level: " << static_cast<int>(entry.level) << std::endl;
    }

    size_t queueMaxSize;
    std::queue<LogEntry> queue;
    std::thread worker;
    std::mutex mutex;
    std::condition_variable condition;
    std::atomic<bool> stop;
};

int main() {
    LoggingFramework loggingFramework(50000);
    loggingFramework.start();

    // Simulate adding log entries
    for (int i = 0; i < 60000; ++i) {
        LogEntry entry{"RX_UE_INFORMATION_TAG", i, std::rand() % 2 == 0, static_cast<LogLevel>(std::rand() % 5)};
        loggingFramework.addLog(entry);
    }

    loggingFramework.stop();
    return 0;
}
