#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct LinkedNode* next;
} LinkedNode;

typedef struct LinkedList {
    LinkedNode* head;
    pthread_mutex_t mutex;
} LinkedList;

LinkedList* createLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroyLinkedList(LinkedList* list) {
    LinkedNode* current = list->head;
    while (current != NULL) {
        LinkedNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

bool insertElement(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    LinkedNode* newNode = (LinkedNode*)malloc(sizeof(LinkedNode));
    if (!newNode) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

bool deleteElement(LinkedList* list, uint16_t RNTI) {
    pthread_mutex_lock(&list->mutex);
    LinkedNode* current = list->head;
    LinkedNode* prev = NULL;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (prev == NULL) list->head = current->next;
            else prev->next = current->next;
            free(current);
            pthread_mutex_unlock(&list->mutex);
            return true;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return false;
}

int getLinkedListSize(LinkedList* list) {
    int count = 0;
    pthread_mutex_lock(&list->mutex);
    LinkedNode* current = list->head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return count;
}

// Additional functions for bulk operations, persistent storage, etc. would be implemented here
