from confluent_kafka import Producer, Consumer
import requests
import json

def process_event_stream(broker, topic):
    conf = {
        'bootstrap.servers': broker,
        'group.id': 'analytics_group',
        'auto.offset.reset': 'earliest'
    }

    consumer = Consumer(conf)
    consumer.subscribe([topic])

    while True:
        msg = consumer.poll(timeout=1.0)
        if msg is None:
            continue
        if msg.error():
            if msg.error().code() == KafkaError._PARTITION_EOF:
                print(f"End of partition reached {msg.topic()} [{msg.partition()}] at offset {msg.offset()}")
            elif msg.error():
                raise KafkaError(msg.error())

        event_data = json.loads(msg.value())
        enriched_data = enrich_event_with_metadata(event_data)
        process_enriched_data(enriched_data)

def enrich_event_with_metadata(event_data):
    metadata_url = "https://api.example.com/metadata"
    headers = {
        'Authorization': 'Bearer YOUR_TOKEN',
        'Content-Type': 'application/json'
    }
    response = requests.get(metadata_url, params=event_data, headers=headers)
    if response.status_code == 200:
        return {**event_data, **response.json()}
    else:
        raise Exception(f"Failed to fetch metadata: {response.status_code}")

def process_enriched_data(data):
