#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <signal.h>

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    uint64_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} TransactionList;

TransactionList transaction_list = {0};

void init_transaction_list(size_t initial_capacity) {
    transaction_list.data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!transaction_list.data) {
        fprintf(stderr, "Failed to allocate memory for transaction list\n");
        exit(EXIT_FAILURE);
    }
    transaction_list.capacity = initial_capacity;
    transaction_list.size = 0;
    pthread_mutex_init(&transaction_list.lock, NULL);
}

void resize_transaction_list(size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(transaction_list.data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        fprintf(stderr, "Failed to reallocate memory for transaction list\n");
        exit(EXIT_FAILURE);
    }
    transaction_list.data = new_data;
    transaction_list.capacity = new_capacity;
}

void add_transaction(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&transaction_list.lock);
    if (transaction_list.size >= transaction_list.capacity) {
        resize_transaction_list(transaction_list.capacity * 2);
    }
    memcpy(&transaction_list.data[transaction_list.size], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    ++transaction_list.size;
    pthread_mutex_unlock(&transaction_list.lock);
}

void* process_transactions(void* arg) {
    while (1) {
        pthread_mutex_lock(&transaction_list.lock);
        if (transaction_list.size == 0) {
            pthread_cond_wait(/* condition variable for empty list */, &transaction_list.lock);
        }
        NFAPI_CRC_INDICATION_PDU_T pdu = transaction_list.data[0];
        // Process the transaction here
        --transaction_list.size;
        memmove(&transaction_list.data[0], &transaction_list.data[1], transaction_list.size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pthread_mutex_unlock(&transaction_list.lock);
    }
}

int main() {
    init_transaction_list(5000);
    // Add transactions to the list
    pthread_t thread;
    pthread_create(&thread, NULL, process_transactions, NULL);
    // Join the thread when done processing
    pthread_join(thread, NULL);
    return 0;
}
