#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <random>

struct NFAPI_CRC_INDICATION_PDU_T {
    std::string RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
};

class LoggingKit {
public:
    void log(const std::string& message, LogLevel level) {
        if (level >= minLogLevel) {
            std::lock_guard<std::mutex> lock(mutex);
            logs.push_back(message);
        }
    }

    void setMinLogLevel(LogLevel level) {
        minLogLevel = level;
    }

private:
    std::vector<std::string> logs;
    std::mutex mutex;
    LogLevel minLogLevel = LogLevel::INFO;

    enum class LogLevel { TRACE, DEBUG, INFO, WARNING, ERROR };
};

class LogProcessor {
public:
    void startProcessing() {
        processingThread = std::thread(&LogProcessor::processLogs, this);
    }

    void stopProcessing() {
        processingRunning.store(false);
        if (processingThread.joinable()) {
            processingThread.join();
        }
    }

private:
    std::queue<NFAPI_CRC_INDICATION_PDU_T> logQueue;
    std::mutex queueMutex;
    std::condition_variable queueCondVar;
    std::thread processingThread;
    std::atomic<bool> processingRunning{true};

    void processLogs() {
        while (processingRunning) {
            std::unique_lock<std::mutex> lock(queueMutex);
            queueCondVar.wait(lock, [this] { return !logQueue.empty() || !processingRunning; });
            if (!logQueue.empty()) {
                NFAPI_CRC_INDICATION_PDU_T pdu = logQueue.front();
                logQueue.pop();
                lock.unlock();

                // Process log entry
                processLogEntry(pdu);
            }
        }
    }

    void processLogEntry(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        // Log processing logic here
        std::cout << "Processing log: RX_UE_INFORMATION_TAG=" << pdu.RX_UE_INFORMATION_TAG
                  << ", RNTI=" << pdu.RNTI << ", CRCFLAG=" << (pdu.CRCFLAG ? "true" : "false") << std::endl;
    }
};

int main() {
    LoggingKit loggingKit;
    LogProcessor logProcessor;

    // Set minimum log level
    loggingKit.setMinLogLevel(LoggingKit::LogLevel::DEBUG);

    // Start log processing
    logProcessor.startProcessing();

    // Simulate log entries
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1);
    for (int i = 0; i < 200000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = "RX_UE_" + std::to_string(i);
        pdu.RNTI = gen(gen);
        pdu.CRCFLAG = dis(gen) == 1;
        loggingKit.log("Log entry: RX_UE_INFORMATION_TAG=" + pdu.RX_UE_INFORMATION_TAG
                        + ", RNTI=" + std::to_string(pdu.RNTI)
                        + ", CRCFLAG=" + (pdu.CRCFLAG ? "true" : "false"),
                        LoggingKit::LogLevel::INFO);
    }

    // Stop log processing
    logProcessor.stopProcessing();

    return 0;
}
```

