    pthread_mutex_t lock;
} NFAPI_POOL_MODULE;

NFAPI_POOL_MODULE* nfapi_pool_init(int max_connections, int initial_pool_size) {
    NFAPI_POOL_MODULE *module = (NFAPI_POOL_MODULE*)malloc(sizeof(NFAPI_POOL_MODULE));
    module->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_pool_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    module->pool_size = initial_pool_size;
    module->used_count = 0;
    pthread_mutex_init(&module->lock, NULL);
    return module;
}

void nfapi_pool_destroy(NFAPI_POOL_MODULE *module) {
    free(module->pool);
    pthread_mutex_destroy(&module->lock);
    free(module);
}

NFAPI_CRC_INDICATION_PDU_T* nfaapi_get_connection(NFAPI_POOL_MODULE *module, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T *connection = NULL;
    pthread_mutex_lock(&module->lock);
    if (module->used_count < module->pool_size) {
        connection = &module->pool[module->used_count++];
        // Set up RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
        RAND_bytes((unsigned char*)&connection->ue_info, sizeof(RX_UE_INFORMATION_TAG));
        connection->rnti = rnti;
        RAND_bytes((unsigned char*)&connection->crc_indication.crcflag, sizeof(CRC_INDICATION_REL8_TAG));
    }
    pthread_mutex_unlock(&module->lock);
    return connection;
}

void nfaapi_release_connection(NFAPI_POOL_MODULE *module, NFAPI_CRC_INDICATION_PDU_T *connection) {
    pthread_mutex_lock(&module->lock);
    // Find and replace the released connection
    for (int i = 0; i < module->used_count; ++i) {
        if (&module->pool[i] == connection) {
            module->used_count--;
            memmove(&module->pool[i], &module->pool[i+1], (module->used_count - i) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            break;
        }
    }
    pthread_mutex_unlock(&module->lock);
}

