use std::{
    fs,
    io::{self, Write},
    path::Path,
    sync::atomic::{AtomicBool, Ordering},
    time::{Duration, Instant},
};
use tokio::{fs as async_fs, task};
use reqwest::Client;
use serde_json::Value;

#[derive(Debug)]
enum ConfigError {
    Io(io::Error),
    Request(reqwest::Error),
}

impl From<io::Error> for ConfigError {
    fn from(err: io::Error) -> Self {
        ConfigError::Io(err)
    }
}

impl From<reqwest::Error> for ConfigError {
    fn from(err: reqwest::Error) -> Self {
        ConfigError::Request(err)
    }
}

#[derive(Debug)]
struct ConfigManager {
    config_path: PathBuf,
    cms_url: String,
    client: Client,
    lock_file: PathBuf,
    last_pull_time: Instant,
    pull_interval: Duration,
}

impl ConfigManager {
    async fn new(root_path: &str, cms_url: &str) -> Result<Self, ConfigError> {
        let config_path = Path::new(root_path).join("config_storage");
        fs::create_dir_all(&config_path)?;

        let lock_file = config_path.join(".lock");
        if !lock_file.exists() {
            fs::File::create(&lock_file)?;
        }

        Ok(ConfigManager {
            config_path,
            cms_url: cms_url.to_string(),
            client: Client::new(),
            lock_file,
            last_pull_time: Instant::now(),
            pull_interval: Duration::from_secs(60),
        })
    }

    async fn watch_config(&self) -> Result<(), ConfigError> {
        loop {
            task::spawn(async move {
                if let Err(e) = Self::pull_configs(self).await {
                    log_error!("Failed to pull configurations: {:?}", e);
                }
                tokio::time::sleep(self.pull_interval).await;
            });
            task::yield_now().await;
        }
    }

    async fn pull_configs(&self) -> Result<(), ConfigError> {
        if self.last_pull_time.elapsed() < self.pull_interval {
            return Ok(());
        }

        let response = self.client.get(&self.cms_url).send().await?;
        let json: Value = response.json().await?;

        for (key, value) in json.as_object().unwrap() {
            let config_path = self.config_path.join(key);
            fs::write(&config_path, value.to_string())?;
        }

        self.last_pull_time = Instant::now();
        Ok(())
    }

    async fn push_configs(&self) -> Result<(), ConfigError> {
        let mut json = Value::Object(HashMap::new());
        for entry in fs::read_dir(self.config_path)? {
            let entry = entry?;
            let file_name = entry.file_name().to_str().unwrap();
            let config_path = entry.path();
            let config_content = fs::read_to_string(config_path)?;
            json[file_name] = Value::String(config_content);
        }

        self.client.post(&self.cms_url).json(&json).send().await?;
        Ok(())
    }
}

fn log_error!(message: &str) {
    eprintln!("{} - {}", chrono::Local::now(), message);
}
