#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    // Define NFAPI_CRC_INDICATION_PDU_T structure here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    int size;
    int max_size;
    int head;
    int tail;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} NFAPI_CONNECTION_POOL_T;

NFAPI_CONNECTION_POOL_T* create_connection_pool(int initial_size) {
    NFAPI_CONNECTION_POOL_T *pool = (NFAPI_CONNECTION_POOL_T*)malloc(sizeof(NFAPI_CONNECTION_POOL_T));
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->size = 0;
    pool->max_size = initial_size;
    pool->head = 0;
    pool->tail = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond, NULL);
    return pool;
}

void destroy_connection_pool(NFAPI_CONNECTION_POOL_T *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->mutex);
    pthread_cond_destroy(&pool->cond);
    free(pool);
}

int acquire_connection(NFAPI_CONNECTION_POOL_T *pool, NFAPI_CRC_INDICATION_PDU_T **connection) {
    pthread_mutex_lock(&pool->mutex);
    while (pool->size == pool->max_size && pool->head != pool->tail) {
        pthread_cond_wait(&pool->cond, &pool->mutex);
    }
    if (pool->size == pool->max_size && pool->head == pool->tail) {
        pthread_mutex_unlock(&pool->mutex);
        return -1; // Connection pool is full
    }
    *connection = &pool->pool[pool->tail];
    pool->tail = (pool->tail + 1) % pool->max_size;
    pool->size++;
    pthread_cond_signal(&pool->cond);
    pthread_mutex_unlock(&pool->mutex);
    return 0;
}

void release_connection(NFAPI_CONNECTION_POOL_T *pool, NFAPI_CRC_INDICATION_PDU_T *connection) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->head == pool->tail && pool->size > 0) {
        pthread_cond_signal(&pool->cond);
    }
    pool->pool[pool->head] = *connection;
    pool->head = (pool->head + 1) % pool->max_size;
    pool->size--;
    pthread_mutex_unlock(&pool->mutex);
}
```

